INSERT INTO verses (goi, conical, edition_id, version, language_subtag, book, chapter, verse, testament, verse_text) VALUES
(1, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 1, 'OT', 'Í upphafi skapaði Guð himin og jörð.'),
(2, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 2, 'OT', 'Jörðin var auð og tóm, og myrkur var yfir undirdjúpinu, og andi Guðs sveif yfir vötnunum.'),
(3, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 3, 'OT', 'Og Guð sagði: Verði ljós! Og það varð ljós.'),
(4, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 4, 'OT', 'Og Guð sá að ljósið var gott, og Guð greindi ljósið frá myrkrinu.'),
(5, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 5, 'OT', 'Og Guð kallaði ljósið dag, en myrkrið kallaði hann nótt. Og það varð kvöld og það varð morgunn, einn dagur.'),
(6, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 6, 'OT', 'Og Guð sagði: Verði festing mitt á milli vatnanna, og hún greini vötn frá vötnum.'),
(7, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 7, 'OT', 'Og Guð gerði festinguna og greindi vötnin sem voru undir festingunni frá vötnunum sem voru yfir festingunni. Og það varð svo.'),
(8, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 8, 'OT', 'Og Guð kallaði festinguna himin. Og það varð kvöld og það varð morgunn, annar dagur.'),
(9, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 9, 'OT', 'Og Guð sagði: Vötnin undir himninum safnist saman á einn stað, og þurrlendið komi í ljós. Og það varð svo.'),
(10, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 10, 'OT', 'Og Guð kallaði þurrlendið jörð, en safn vatnanna kallaði hann höf. Og Guð sá að það var gott.'),
(11, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 11, 'OT', 'Og Guð sagði: Jörðin gefi af sér gras, jurtir sem bera sæði, og ávaxtatré sem bera ávöxt eftir sinni tegund, með sæði í sér, á jörðinni. Og það varð svo.'),
(12, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 12, 'OT', 'Og jörðin bar gras, jurtir sem bera sæði eftir sinni tegund, og tré sem ber ávöxt með sæði í sér eftir sinni tegund. Og Guð sá að það var gott.'),
(13, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 13, 'OT', 'Og það varð kvöld og það varð morgunn, þriðji dagur.'),
(14, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 14, 'OT', 'Og Guð sagði: Verði ljós á festingu himinsins til að greina dag frá nótt, og þau séu til tákna og til hátíðartíma og til daga og ára.'),
(15, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 15, 'OT', 'Og þau séu ljós á festingu himinsins til að lýsa yfir jörðina. Og það varð svo.'),
(16, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 16, 'OT', 'Og Guð gerði ljósin tvö hin miklu: hið mikla ljós til að ráða deginum og hið litla ljós til að ráða nóttinni, og stjörnurnar.'),
(17, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 17, 'OT', 'Og Guð setti þau á festingu himinsins til að lýsa yfir jörðina,'),
(18, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 18, 'OT', 'og til að ráða yfir deginum og nóttinni og greina ljósið frá myrkrinu. Og Guð sá að það var gott.'),
(19, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 19, 'OT', 'Og það varð kvöld og það varð morgunn, fjórði dagur.'),
(20, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 20, 'OT', 'Og Guð sagði: Vötnin kvikni af kvikindum, lifandi sálum, og fuglar fljúgi yfir jörðina, undir festingu himinsins.'),
(21, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 21, 'OT', 'Og Guð skapaði hin stóru sjávardýr og sérhverja lifandi sál sem hrærist, sem vötnin kviknuðu af eftir tegundum þeirra, og sérhvern fugl með vængi eftir tegund hans. Og Guð sá að það var gott.'),
(22, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 22, 'OT', 'Og Guð blessaði þau og sagði: Verið frjósöm og fjölgið ykkur og fyllið vötnin í höfunum, og fuglunum fjölgi á jörðinni.'),
(23, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 23, 'OT', 'Og það varð kvöld og það varð morgunn, fimmti dagur.'),
(24, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 24, 'OT', 'Og Guð sagði: Jörðin leiði fram lifandi sálir eftir tegundum þeirra, fénað og skriðdýr og villidýr jarðarinnar eftir tegundum þeirra. Og það varð svo.'),
(25, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 25, 'OT', 'Og Guð gerði villidýr jarðarinnar eftir tegundum þeirra og fénaðinn eftir tegundum hans og öll skriðdýr jarðvegarins eftir tegundum þeirra. Og Guð sá að það var gott.'),
(26, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 26, 'OT', 'Og Guð sagði: Gerum manninn í okkar mynd, eftir okkar líkingu, og þeir ráði yfir fiskum sjávarins og fuglum himinsins og fénaðinum og allri jörðinni og öllum skriðdýrum sem skríða á jörðinni.'),
(27, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 27, 'OT', 'Og Guð skapaði manninn í sinni mynd, í mynd Guðs skapaði hann hann, karlkyn og kvenkyn skapaði hann þau.'),
(28, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 28, 'OT', 'Og Guð blessaði þau, og Guð sagði við þau: Verið frjósöm og fjölgið ykkur og fyllið jörðina og leggið hana undir ykkur, og drottnið yfir fiskum sjávarins og fuglum himinsins og öllum lifandi verum sem hrærast á jörðinni.'),
(29, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 29, 'OT', 'Og Guð sagði: Sjá, ég gef ykkur hverja jurt sem ber sæði á allri jörðinni og hvert tré sem ber ávöxt með sæði í sér. Ykkur skal það vera til fæðu.'),
(30, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 30, 'OT', 'Og öllum villidýrum jarðarinnar og öllum fuglum himinsins og öllu sem skríður á jörðinni, sem hefur lifandi sál í sér, gef ég alla græna jurt til fæðu. Og það varð svo.'),
(31, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 1, 31, 'OT', 'Og Guð sá allt sem hann hafði gert, og sjá, það var harla gott. Og það varð kvöld og það varð morgunn, sjötti dagur.'),
(32, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 1, 'OT', 'Og himinn og jörð voru fullgerð og allur her þeirra.'),
(33, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 2, 'OT', 'Og á sjöunda degi lauk Guð verki sínu sem hann hafði gert, og hann hvíldist á sjöunda degi frá öllu verki sínu sem hann hafði gert.'),
(34, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 3, 'OT', 'Og Guð blessaði sjöunda daginn og helgaði hann, því að á honum hvíldist hann frá öllu verki sínu sem Guð hafði skapað til að gera.'),
(35, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 4, 'OT', 'Þetta er ættartala himins og jarðar þegar þau voru sköpuð, á þeim degi er Jahve Guð gerði jörð og himin.'),
(36, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 5, 'OT', 'Og enginn runni akursins var enn á jörðinni, og engin jurt akursins hafði enn sprottið, því að Jahve Guð hafði ekki látið rigna á jörðina, og enginn maður var til að yrkja jörðina.'),
(37, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 6, 'OT', 'En upp steig mistur af jörðinni og vökvaði allt andlit jarðarinnar.'),
(38, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 7, 'OT', 'Þá myndaði Jahve Guð manninn af mold jarðarinnar og blés í nef hans andardrátt lífsins, og maðurinn varð lifandi sál.'),
(39, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 8, 'OT', 'Og Jahve Guð gróðursetti garð í Eden í austri og setti þar manninn sem hann hafði mótað.'),
(40, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 9, 'OT', 'Og Jahve Guð lét upp vaxa af jörðinni hvert tré, girnilegt í útliti og gott til fæðu, og tré lífsins í miðju garðsins og tré þekkingar góðs og ills.'),
(41, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 10, 'OT', 'Og fljót rann út af Eden til að vökva garðinn, og þaðan skiptist það og varð að fjórum höfuðám.'),
(42, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 11, 'OT', 'Nafn hins fyrsta er Písón, hann er sá sem rennur umhverfis allt land Havílu, þar sem gullið er.'),
(43, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 12, 'OT', 'Og gull þess lands er gott, þar er bdelíum og ónyxsteinn.'),
(44, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 13, 'OT', 'Og nafn annarrar árinnar er Gíhon, hún er sú sem rennur umhverfis allt land Kús.'),
(45, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 14, 'OT', 'Og nafn þriðju árinnar er Hiddekel, hún er sú sem rennur austan við Assýríu. Og fjórða áin er Efrat.'),
(46, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 15, 'OT', 'Og Jahve Guð tók manninn og setti hann í Edensgarð til að yrkja hann og gæta hans.'),
(47, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 16, 'OT', 'Og Jahve Guð bauð manninum og sagði: Af öllum trjám garðsins máttu eta.'),
(48, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 17, 'OT', 'En af tré þekkingar góðs og ills skalt þú ekki eta, því að á þeim degi sem þú etur af því, skalt þú vissulega deyja.'),
(49, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 18, 'OT', 'Og Jahve Guð sagði: Ekki er gott að maðurinn sé einn. Ég vil gera honum hjálp við hæfi.'),
(50, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 19, 'OT', 'Og Jahve Guð mótaði af jörðinni öll villidýr merkurinnar og alla fugla himinsins og leiddi þau til mannsins til að sjá hvað hann kallaði þau, og hvað sem maðurinn kallaði hverja lifandi sál, það skyldi vera nafn hennar.'),
(51, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 20, 'OT', 'Og maðurinn gaf öllum skepnunum nöfn, og fuglum himinsins og öllum villidýrum akursins, en manninum fannst engin hjálp við sitt hæfi.'),
(52, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 21, 'OT', 'Þá lét Jahve Guð djúpan dá falla á manninn, og hann sofnaði. Og hann tók eitt af rifjum hans og fyllti upp með holdi í staðinn.'),
(53, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 22, 'OT', 'Og Jahve Guð myndaði konu af rifinu sem hann hafði tekið úr manninum og leiddi hana til mannsins.'),
(54, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 23, 'OT', 'Og maðurinn sagði: Að þessu sinni er þetta bein af mínum beinum og hold af mínu holdi. Hún skal kallast kona, því að af manni var hún tekin.'),
(55, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 24, 'OT', 'Fyrir því yfirgefur maður föður sinn og móður sína og heldur sig að konu sinni, og þau verða eitt hold.'),
(56, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 2, 25, 'OT', 'Þau voru bæði nakin, maðurinn og kona hans, og skömmuðust sín ekki.'),
(57, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 1, 'OT', 'Höggormurinn var kænni en öll villidýr akursins sem Jahve Guð hafði gert. Hann sagði við konuna: Hefur Guð í raun sagt: Þér megið ekki eta af neinu tré garðsins?'),
(58, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 2, 'OT', 'Konan sagði við höggorminn: Af ávexti trjánna í garðinum megum við eta.'),
(59, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 3, 'OT', 'En um ávöxt trésins sem er í miðjum garðinum sagði Guð: Þér megið ekki eta af honum og ekki snerta hann, svo að þér deyið ekki.'),
(60, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 4, 'OT', 'Þá sagði höggormurinn við konuna: Þér munuð alls ekki deyja.'),
(61, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 5, 'OT', 'Heldur veit Guð að þann dag sem þér etið af því munu augu yðar opnast, og þér verðið eins og Guð og þekkið gott og illt.'),
(62, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 6, 'OT', 'Konan sá að tréð var gott til fæðu og að það var þrá augnanna, og tréð var eftirsóknarvert til að veita vit. Hún tók af ávexti þess og át, og gaf einnig manni sínum sem með henni var, og hann át.'),
(63, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 7, 'OT', 'Þá opnuðust augu þeirra beggja, og þau sáu að þau voru nakin. Og þau saumuðu saman lauf af fíkjutré og gerðu sér belti.'),
(64, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 8, 'OT', 'Þá heyrðu þau rödd Jahve Guðs ganga um garðinn í svalanum þegar dagur var að kvöldi kominn, og maðurinn og kona hans földu sig fyrir andliti Jahve Guðs mitt á meðal trjánna í garðinum.'),
(65, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 9, 'OT', 'Jahve Guð kallaði á manninn og sagði við hann: Hvar ert þú?'),
(66, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 10, 'OT', 'Hann sagði: Ég heyrði rödd þína í garðinum og varð hræddur, því að ég er nakinn, og ég faldi mig.'),
(67, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 11, 'OT', 'Hann sagði: Hver sagði þér að þú værir nakinn? Hefur þú etið af trénu sem ég bauð þér að eta ekki af?'),
(68, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 12, 'OT', 'Maðurinn sagði: Konan sem þú gafst mér til fylgdar, hún gaf mér af trénu, og ég át.'),
(69, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 13, 'OT', 'Þá sagði Jahve Guð við konuna: Hvað hefur þú gert? Konan sagði: Höggormurinn tældi mig, og ég át.'),
(70, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 14, 'OT', 'Þá sagði Jahve Guð við höggorminn: Af því að þú gerðir þetta ertu bölvaður meðal allra skepna og allra villidýra akursins. Á kviði þínum skaltu ganga og mold skaltu eta alla daga lífs þíns.'),
(71, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 15, 'OT', 'Ég set óvild milli þín og konunnar og milli sæðis þíns og sæðis hennar. Hann skal merja höfuð þitt, og þú skalt merja hæl hans.'),
(72, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 16, 'OT', 'Við konuna sagði hann: Ég mun stórum auka erfiði þitt og getnað þinn. Með sársauka skaltu fæða sonu. Þrá þín mun standa til manns þíns, og hann mun drottna yfir þér.'),
(73, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 17, 'OT', 'Og við Adam sagði hann: Af því að þú hlýddir rödd konu þinnar og ætir af trénu sem ég bauð þér með þessum orðum: Þú skalt ekki eta af því, þá sé jörðin bölvuð þín vegna. Með erfiði skaltu eta af henni alla daga lífs þíns.'),
(74, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 18, 'OT', 'Þyrna og þistla mun hún láta spretta handa þér, og þú skalt eta gras akursins.'),
(75, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 19, 'OT', 'Í svita nefs þíns skaltu eta brauð, þar til þú hverfur aftur til jarðarinnar, því að af henni varst þú tekinn. Því að mold ertu og til moldar skaltu hverfa.'),
(76, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 20, 'OT', 'Og maðurinn gaf konu sinni nafnið Eva, því að hún varð móðir allra sem lifa.'),
(77, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 21, 'OT', 'Og Jahve Guð gerði manninum og konu hans kyrtla úr skinni og klæddi þau í þá.'),
(78, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 22, 'OT', 'Þá sagði Jahve Guð: Sjá, maðurinn er orðinn eins og einn af oss, þekkir gott og illt. Nú má hann ekki rétta út hönd sína og taka einnig af tré lífsins og eta og lifa um eilífð.'),
(79, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 23, 'OT', 'Og Jahve Guð sendi hann burt úr garðinum í Eden til að yrkja jörðina sem hann var tekinn af.'),
(80, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 3, 24, 'OT', 'Hann rak manninn burt og setti fyrir austan garðinn í Eden kerúba og loga sverðsins sem snerist í allar áttir, til að gæta vegarins að tré lífsins.'),
(81, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 1, 'OT', 'Og maðurinn þekkti Evu konu sína, og hún varð þunguð og ól Kain og sagði: Ég hef eignast mann með Jahve.'),
(82, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 2, 'OT', 'Og hún bætti við sig og ól bróður hans Abel. Og Abel varð hirðir sauðfjár, en Kain var yrkjandi jarðar.'),
(83, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 3, 'OT', 'Er dagarnir voru á enda, kom Kain með fórn af ávexti jarðarinnar handa Jahve.'),
(84, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 4, 'OT', 'Og Abel kom einnig með fórn af frumburðum sauðfjár síns og af fitu þeirra. Og Jahve leit með velþóknun á Abel og fórn hans.'),
(85, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 5, 'OT', 'En á Kain og fórn hans leit hann ekki með velþóknun. Þá reiddist Kain mjög og andlit hans féll.'),
(86, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 6, 'OT', 'Og Jahve sagði við Kain: Hví ertu reiður, og hví er andlit þitt fallið?'),
(87, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 7, 'OT', 'Ef þú gerir gott, hlýtur þú upphefð, en gerir þú ekki gott, liggur synd við innganginn, og þrá hennar stendur til þín, en þú átt að drottna yfir henni.'),
(88, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 8, 'OT', 'Kain talaði við Abel bróður sinn. Og þegar þeir voru á akrinum, réðst Kain á Abel bróður sinn og drap hann.'),
(89, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 9, 'OT', 'Þá sagði Jahve við Kain: Hvar er Abel bróðir þinn? Hann sagði: Ég veit það ekki. Á ég að gæta bróður míns?'),
(90, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 10, 'OT', 'Hann sagði: Hvað hefur þú gert? Rödd blóðs bróður þíns hrópar til mín af jörðinni.'),
(91, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 11, 'OT', 'Og nú ertu bölvaður af jörðinni sem lauk upp munni sínum til að taka við blóði bróður þíns af hendi þinni.'),
(92, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 12, 'OT', 'Þegar þú yrkir jörðina skal hún ekki framar gefa þér kraft sinn. Flakkari og förumaður skaltu vera á jörðinni.'),
(93, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 13, 'OT', 'Kain sagði við Jahve: Misgjörð mín er meiri en svo að ég fái borið hana.'),
(94, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 14, 'OT', 'Sjá, þú hefur rekið mig í dag burt af andliti jarðarinnar, og fyrir andliti þínu mun ég hulinn. Ég verð flakkari og förumaður á jörðinni, og hver sem finnur mig mun drepa mig.'),
(95, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 15, 'OT', 'Þá sagði Jahve við hann: Fyrir því skal sjöfalt hefnt verða hvers þess sem drepur Kain. Og Jahve setti tákn á Kain, svo að enginn sem fyndi hann skyldi drepa hann.'),
(96, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 16, 'OT', 'Og Kain gekk burt frá andliti Jahve og settist að í landinu Nód, austan Edens.'),
(97, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 17, 'OT', 'Og Kain þekkti konu sína, og hún varð þunguð og ól Enok. Og hann reisti borg og nefndi borgina eftir nafni sonar síns Enoks.'),
(98, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 18, 'OT', 'Og Enok fæddist Írad, og Írad gat Mehújael, og Mehújael gat Metúsael, og Metúsael gat Lamek.'),
(99, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 19, 'OT', 'Og Lamek tók sér tvær konur. Nafn annarrar var Ada og nafn hinnar Silla.'),
(100, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 20, 'OT', 'Og Ada ól Jabal. Hann varð faðir þeirra sem búa í tjöldum og eiga fénað.'),
(101, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 21, 'OT', 'Nafn bróður hans var Jabal; hann var faðir þeirra sem leika á hörpu og orgel.'),
(102, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 22, 'OT', 'Silla ól einnig Túbal-Kain; hann smíðaði öll verkfæri úr eiri og járni. Systir Túbal-Kains var Naama.'),
(103, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 23, 'OT', 'Lamek sagði við konum sínum: Ada og Silla, heyrið rödd mína, konur Lameks, hlustið á orð mín. Ég drap mann fyrir sár mitt og dreng fyrir strípu mína.'),
(104, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 24, 'OT', 'Því að Kain verður hefnt sjöfalt, en Lamek sjötíu og sjöfalt.'),
(105, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 25, 'OT', 'Adam þekkti konu sína aftur, og hún ól son og kallaði nafn hans Set: Guð hefur gefið mér annað sæði í stað Abels, því að Kain drap hann.'),
(106, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 4, 26, 'OT', 'Og Set eignaðist einnig son og kallaði nafn hans Enos. Þá var farið að ákalla nafn Jahve.'),
(107, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 1, 'OT', 'Þetta er bók ættartölu Adams. Á þeim degi þegar Guð skapaði mann, bjó hann hann til í líkingu Guðs.'),
(108, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 2, 'OT', 'Hann skapaði þau karl og kvenkyn, blessaði þau og kallaði nafn þeirra mann á þeim degi sem þau voru sköpuð.'),
(109, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 3, 'OT', 'Adam lifði hundrað og þrjátíu ár og gat son í sinni líkingu, eftir sinni mynd, og kallaði nafn hans Set.'),
(110, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 4, 'OT', 'Dagar Adams urðu eftir að hann hafði getið Set átta hundruð ár, og hann eignaðist sonu og dætur.'),
(111, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 5, 'OT', 'Allir dagar Adams, sem hann lifði, voru níu hundruð og þrjátíu ár, og hann dó.'),
(112, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 6, 'OT', 'Set lifði hundrað og fimm ár og eignaðist Enos.'),
(113, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 7, 'OT', 'Eftir að hann hafði eignast Enos lifði Set átta hundruð og sjö ár og eignaðist sonu og dætur.'),
(114, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 8, 'OT', 'Allir dagar Sets voru níu hundruð og tólf ár, og hann dó.'),
(115, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 9, 'OT', 'Enos lifði níutíu ár og eignaðist Kenan.'),
(116, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 10, 'OT', 'Eftir að hann hafði eignast Kenan lifði Enos átta hundruð og fimmtán ár og eignaðist sonu og dætur.'),
(117, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 11, 'OT', 'Allir dagar Enosar voru níu hundruð og fimm ár, og hann dó.'),
(118, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 12, 'OT', 'Kenan lifði sjötíu ár og eignaðist Mahalalel.'),
(119, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 13, 'OT', 'Eftir að hann hafði eignast Mahalalel lifði Kenan átta hundruð og fjörutíu ár og eignaðist sonu og dætur.'),
(120, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 14, 'OT', 'Allir dagar Kenans voru níu hundruð og tíu ár, og hann dó.'),
(121, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 15, 'OT', 'Mahalalel lifði sextíu og fimm ár og eignaðist Jared.'),
(122, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 16, 'OT', 'Eftir að hann hafði eignast Jared lifði Mahalalel átta hundruð og þrjátíu ár og eignaðist sonu og dætur.'),
(123, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 17, 'OT', 'Allir dagar Mahalalels voru átta hundruð níutíu og fimm ár, og hann dó.'),
(124, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 18, 'OT', 'Jared lifði hundrað og sextíu og tvö ár og eignaðist Enok.'),
(125, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 19, 'OT', 'Eftir að hann hafði eignast Enok lifði Jared átta hundruð ár og eignaðist sonu og dætur.'),
(126, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 20, 'OT', 'Allir dagar Jareds voru níu hundruð sextíu og tvö ár, og hann dó.'),
(127, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 21, 'OT', 'Enok lifði sextíu og fimm ár og eignaðist Metúsala.'),
(128, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 22, 'OT', 'Enok gekk með Guði eftir að hann hafði eignast Metúsala þrjú hundruð ár og eignaðist sonu og dætur.'),
(129, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 23, 'OT', 'Allir dagar Enoks voru þrjú hundruð sextíu og fimm ár.'),
(130, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 24, 'OT', 'Enok gekk með Guði, og hann var ekki lengur til, því að Guð tók hann.'),
(131, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 25, 'OT', 'Metúsala lifði hundrað áttatíu og sjö ár og eignaðist Lamek.'),
(132, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 26, 'OT', 'Eftir að hann hafði eignast Lamek lifði Metúsala sjö hundruð áttatíu og tvö ár og eignaðist sonu og dætur.'),
(133, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 27, 'OT', 'Allir dagar Metúsala voru níu hundruð sextíu og níu ár, og hann dó.'),
(134, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 28, 'OT', 'Lamek lifði hundrað áttatíu og tvö ár og eignaðist son.'),
(135, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 29, 'OT', 'Hann kallaði nafn hans Nói og sagði: Þessi mun hugga okkur í verki okkar og erfiði handar okkar af jörðinni sem Jahve hefur bölvað.'),
(136, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 30, 'OT', 'Eftir að hann hafði eignast Nói lifði Lamek fimm hundruð níutíu og fimm ár og eignaðist sonu og dætur.'),
(137, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 31, 'OT', 'Allir dagar Lameks voru sjö hundruð sjötíu og sjö ár, og hann dó.'),
(138, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 5, 32, 'OT', 'Nói var fimm hundruð ára gamall, og hann eignaðist sonu: Sem, Kam og Jafet.'),
(139, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 1, 'OT', 'Þegar mönnum tók að fjölga á andliti jarðar og dætur fæddust þeim.'),
(140, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 2, 'OT', 'Synir Guðs sáu dætur mannanna, að þær voru fagrar, og þeir tóku sér konur af öllum þeim sem þeir völdu.'),
(141, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 3, 'OT', 'Þá sagði Jahve: Andi minn skal ekki deila við manni um eilífð, því að hann er hold. Dagar hans skulu vera hundrað og tuttugu ár.'),
(142, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 4, 'OT', 'Á þeim dögum voru risar á jörðinni, og einnig síðar, þegar synir Guðs gengu inn til dætra mannanna og þær ólu þeim börn. Þetta voru hetjurnar frá eilífð, menn að nafni.'),
(143, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 5, 'OT', 'Og Jahve sá að illska mannsins var mikil á jörðinni, og að hvert hugarsmíð ráðagerðar hjarta hans var eingöngu illt allan dag.'),
(144, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 6, 'OT', 'Jahve iðraðist þess að hafa skapað mann á jörðinni, og honum sárnaði í hjarta sínu.'),
(145, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 7, 'OT', 'Jahve sagði: Ég mun afmá af yfirborði jarðar mann sem ég skapaði, frá manni allt til skepnu, skriðdýr og fugl himinsins, því að mér þykir miður að ég skapaði þá.'),
(146, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 8, 'OT', 'En Nói fann hylli í augum Jahve.'),
(147, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 9, 'OT', 'Þetta er ættartala Nóa. Nói var réttlátur maður, ráðvandur meðal kynslóða sinna. Nói gekk með Guði.'),
(148, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 10, 'OT', 'Nói eignaðist þrjá sonu: Sem, Kam og Jafet.'),
(149, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 11, 'OT', 'Jörð var spillt frammi fyrir Guði, og jörð fylltist af ofbeldi.'),
(150, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 12, 'OT', 'Guð sá jörðina, og sjá, hún var spillt, því að allt hold hafði spillt veg sinn á jörðinni.'),
(151, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 13, 'OT', 'Og Guð sagði við Nói: Endir alls holds er kominn fyrir andlit mitt, því að jörðin er full af ofbeldi vegna þeirra, og sjá, ég mun eyða þeim ásamt jörðinni.'),
(152, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 14, 'OT', 'Gerðu þér örk úr gófertrjám; gerðu hreiður í örkinni og smyrðu hana innan húss og utan með kvoðu.'),
(153, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 15, 'OT', 'Og þannig skalt þú gera hana: þrjú hundruð álnir skal lengd arkarinnar vera, fimmtíu álnir breidd hennar og þrjátíu álnir vöxt hennar.'),
(154, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 16, 'OT', 'Glugga skalt þú gera á örkina, og upp að einni alin skalt þú ljúka henni að ofan. Inngang arkarinnar skalt þú setja á hliðina; neðri, annað og þriðja hæð skalt þú gera.'),
(155, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 17, 'OT', 'Og sjá, ég læt syndaflóð koma yfir jörðina, vötn yfir jörðina til að tortíma hverju holdi sem hefur anda lífs undir himni; allt sem er á jörðinni skal deyja.'),
(156, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 18, 'OT', 'En ég mun staðfesta sáttmála minn við þig, og þú skalt ganga inn í örkina, þú og synir þínir, kona þín og konur sona þinna með þér.'),
(157, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 19, 'OT', 'Og af öllu lifandi holdi skalt þú leiða tvö af hverju inn í örkina, til að halda þeim lífi með þér; karl og kvenkyn skulu þau vera.'),
(158, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 20, 'OT', 'Af fuglum eftir tegund þeirra, af skepnum eftir tegund þeirra og af öllu skriðdýri jarðarinnar eftir tegund þess; tvö af hverju skulu koma til þín, til að halda lífi.'),
(159, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 21, 'OT', 'Og þú skalt taka til þín af allri fæðu sem etin er og safna henni saman; og hún skal vera þér til fæðu og þeim.'),
(160, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 6, 22, 'OT', 'Og Nói gerði allt eins og Guð hafði boðið honum; svo gerði hann.'),
(161, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 1, 'OT', 'Og Jahve sagði við Nói: Gakk þú og allt þitt hús inn í örkina, því að ég hef séð þig réttlátan fyrir andliti mínu meðal þessarar kynslóðar.'),
(162, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 2, 'OT', 'Af öllum hreinum skepnum skalt þú taka sjö og sjö, mann og konu hans; en af skepnum sem ekki eru hreinar, tvö, mann og konu hans.'),
(163, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 3, 'OT', 'Einnig af fuglum himins sjö og sjö, karl og kvenkyn, til að varðveita sæði á andliti jarðar.'),
(164, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 4, 'OT', 'Því að eftir sjö daga mun ég láta rigna yfir jörðina í fjörutíu daga og fjörutíu nætur; og ég mun afmá alla lifandi veru sem ég hef skapað af andliti jarðarinnar.'),
(165, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 5, 'OT', 'Og Nói gerði allt eins og Jahve hafði boðið honum.'),
(166, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 6, 'OT', 'Og Nói var sex hundruð ára gamall, og syndaflóðið var vötn yfir jörðinni.'),
(167, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 7, 'OT', 'Og Nói gekk inn í örkina ásamt sonum sínum, konu sinni og konum sona sinna, undan vötnum syndaflóðsins.'),
(168, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 8, 'OT', 'Af hreinum skepnum og af skepnum sem ekki eru hreinar, og af fuglum og öllu sem skríður á jörðinni,'),
(169, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 9, 'OT', 'Tvö og tvö komu til Nói inn í örkina, karl og kvenkyn, eins og Guð hafði boðið Nói.'),
(170, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 10, 'OT', 'Og eftir sjö daga voru vötn syndaflóðsins yfir jörðinni.'),
(171, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 11, 'OT', 'Á sex hundruðasta ári ævi Nóa, í öðrum mánuði, á sautjánda degi mánaðar, á þessum degi sprungu upp allar lindir undirdjúps og gluggar himins opnuðust.'),
(172, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 12, 'OT', 'Og skúrin var yfir jörðinni í fjörutíu daga og fjörutíu nætur.'),
(173, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 13, 'OT', 'Á þessum sama degi fór Nói inn í örkina ásamt Sem, Kam og Jafet, sonum sínum, og konu hans og þremur konum sona hans.'),
(174, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 14, 'OT', 'Þau og öll skepnan eftir tegund sinni, öll skriðdýr jarðarinnar eftir tegund sinni, og allir fuglar, hver fugl með vængjum sínum.'),
(175, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 15, 'OT', 'Þau fóru til Nói inn í örkina tvö og tvö, af öllu holdi sem hefur í sér anda lífs.'),
(176, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 16, 'OT', 'Þeir sem komu, karl og kvenkyn af öllu holdi, komu eins og Guð hafði boðið honum; og Jahve lokaði á eftir honum.'),
(177, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 17, 'OT', 'Og syndaflóðið var fjörutíu daga yfir jörðinni; vötn uxu og lyftu örkinni frá jörðinni.'),
(178, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 18, 'OT', 'Vötn gerðust sterk og uxu mjög yfir jörðina, og örkin flaut yfir andlit vatns.'),
(179, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 19, 'OT', 'Og vötn uxu mjög mjög yfir jörðina, og öll há fjöll undir öllum himni voru þakin.'),
(180, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 20, 'OT', 'Fimmtán álnir hærra gengu vötn, og fjöll voru þakin.'),
(181, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 21, 'OT', 'Og allt hold sem hrærðist á jörðinni dó, með fuglum, skepnum, villidýrum og skriðdýrum, og allir menn.'),
(182, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 22, 'OT', 'Allt sem hafði anda lífs í nefi sínu, af öllu sem var á þurrlendi, dó.'),
(183, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 23, 'OT', 'Þannig afmáði hann alla lifandi veru sem var á andliti jarðarinnar, frá manni til skepnu, til skriðdýrs og fugls himins; og þau voru afmáð af jörðinni. Aðeins Nói var eftir og þau sem voru með honum í örkinni.'),
(184, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 7, 24, 'OT', 'Og vötn uxu yfir jörðinni í hundrað og fimmtíu daga.'),
(185, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 1, 'OT', 'Og Guð minntist Nói og allra lifandi veru og allrar skepnu sem var með honum í örkinni; og Guð lét anda fara yfir jörðina, og vötn sefuðust.'),
(186, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 2, 'OT', 'Og lindir undirdjúps voru stíflaðar, og gluggar himins lokaðir, og skúrin var stöðvuð af himni.'),
(187, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 3, 'OT', 'Og vötn hurfu smám saman af jörðinni, og eftir hundrað og fimmtíu daga tóku vötn að minnka.'),
(188, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 4, 'OT', 'Og örkin hvíldi í sjöunda mánuði, á sautjánda degi mánaðar, á fjöllum Ararat.'),
(189, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 5, 'OT', 'Vötn héldu áfram að minnka fram að tíunda mánuði; á fyrsta degi tíunda mánaðar sáust höfuð fjalla.'),
(190, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 6, 'OT', 'Og eftir fjörutíu daga opnaði Nói glugga arkarinnar sem hann hafði gert.'),
(191, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 7, 'OT', 'Og hann sleppti hrafn, sem fór út og kom aftur þar til vötn þornuðu af jörðinni.'),
(192, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 8, 'OT', 'Og hann sleppti dúfu frá sér til að sjá hvort vötn væru þornuð af andliti jarðarinnar.'),
(193, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 9, 'OT', 'En dúfan fann enga hvíld fyrir fót sinn; hún sneri aftur til hans í örkina, því að vötn voru yfir allri jörðinni. Hann rétti út hönd, tók hana og færði hana aftur inn í örkina.'),
(194, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 10, 'OT', 'Og hann beið enn sjö aðra daga og sendi dúfu aftur út úr örkinni.'),
(195, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 11, 'OT', 'Um kvöldið kom dúfan til hans, og sjá, í munni hennar var lauf af olíutré nýslitið; þá vissi Nói að vötn voru þorrin af jörðinni.'),
(196, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 12, 'OT', 'Og hann beið enn sjö aðra daga og sendi dúfu út; en hún kom ekki aftur til hans framar.'),
(197, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 13, 'OT', 'Og á sex hundruð og fyrsta ári, í fyrsta mánuði, á fyrsta degi mánaðar, þornuðu vötn af jörðinni; og Nói tók hlíf af örkinni og leit, og sjá, andlit jarðar var þurrt.'),
(198, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 14, 'OT', 'Og í öðrum mánuði, á sjö og tuttugasta degi mánaðar, var jörðin þurr.'),
(199, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 15, 'OT', 'Og Guð talaði við Nói og sagði:'),
(200, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 16, 'OT', 'Gakk út úr örkinni, þú og kona þín, synir þínir og konur sona þinna með þér.'),
(201, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 17, 'OT', 'Far út með þér allar lifandi verur, af öllu holdi, bæði fuglum og skepnum og öllum skriðdýrum sem skríða á jörð, og þau skulu fjölga sér og margfaldast á jörð.'),
(202, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 18, 'OT', 'Og Nói gekk út og synir hans, kona hans og konur sona hans með honum.'),
(203, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 19, 'OT', 'Öll lifandi skepna, öll skriðdýr og allir fuglar, allt sem skríður á jörð, fóru út eftir ættum sínum úr örk.'),
(204, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 20, 'OT', 'Nói reisti Jahve altari, tók af hreinum skepnum og af hreinum fuglum og bar fram brennifórnir á altari.'),
(205, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 21, 'OT', 'Og Jahve fann þægilegan ilm og sagði í hjarta sínu: Ég mun framar ekki bölva jörð vegna manns, því að hugarsmíð hjarta manns er vond frá æsku hans, og ég mun ekki framar drepa allt lifandi eins og ég hef gjört.'),
(206, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 8, 22, 'OT', 'Allir dagar jarðar, sæði og grein, kuldi og hiti, sumar og vetur, dagur og nótt skulu ekki hætta.'),
(207, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 1, 'OT', 'Og Guð blessaði Nói og sonu hans og sagði við þá: Fjölgið, margfaldist og fyllið jörð.'),
(208, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 2, 'OT', 'Ótti yðar og skelfing skal vera yfir öllum dýrum jarðar og yfir fuglum himins, yfir öllu sem skríður á jörð og yfir fiskum hafs; í hendur yðar eru þau gefin.'),
(209, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 3, 'OT', 'Hvert skriðdýr sem lifir skal vera ykkur til fæðu; eins og grænt gras hef ég gefið ykkur allt.'),
(210, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 4, 'OT', 'En hold með sál sinni, það er með blóði þess, skuluð þér ekki eta.'),
(211, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 5, 'OT', 'En blóð yðar, fyrir sálum yðar, mun ég krefjast; af hendi sérhvers dýrs mun ég krefjast þess, og af hendi manns, af hendi bróður síns, mun ég krefjast sálar manns.'),
(212, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 6, 'OT', 'Hver sem úthellir blóð manns, af manni skal blóð hans úthellt verða, því að í mynd Guðs skapaði Guð mann.'),
(213, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 7, 'OT', 'En þér, fjölgið og margfaldist, vaxið á jörð og margfaldist á henni.'),
(214, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 8, 'OT', 'Og Guð talaði við Nói og syni hans með honum og sagði:'),
(215, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 9, 'OT', 'Og sjá, ég set sáttmála minn við ykkur og við sæði ykkar eftir ykkur.'),
(216, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 10, 'OT', 'Og ég set sáttmála minn við hverri sál lifandi sem er með ykkur, fuglum, skepnum og öllum dýrum jarðar, þeim sem gengu út úr örk.'),
(217, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 11, 'OT', 'Og ég reisi sáttmála minn við ykkur: allt hold skal ekki framar tortímast af vötnum syndaflóðs, og ekki skal framar vera syndaflóð til að eyða jörð.'),
(218, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 12, 'OT', 'Og Guð sagði: Þetta er tákn sáttmála sem ég set milli mín og ykkar og milli allrar sálar lifandi sem er með ykkur, um kynslóðir eilífðar.'),
(219, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 13, 'OT', 'Boga minn hef ég sett í skýi, og hann skal vera tákn sáttmála milli mín og jarðar.'),
(220, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 14, 'OT', 'Og verði það, þegar ég dreg ský yfir jörð og bogi sést í skýi.'),
(221, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 15, 'OT', 'Og ég mun minnast sáttmála míns, sem er milli mín og ykkar og milli allrar sálar lifandi og alls holds; og vötnin skulu ekki framar verða að syndaflóði til að eyða holdinu.'),
(222, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 16, 'OT', 'Bogi skal vera í skýi og ég mun líta á hann til að minnast eilífs sáttmála milli Guðs og allrar sálar lifandi í öllu holdi sem er á jörð.'),
(223, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 17, 'OT', 'Og Guð sagði við Nói: Þetta er tákn sáttmála sem ég hef reist milli mín og alls holds sem er á jörð.'),
(224, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 18, 'OT', 'Synir Nóa sem gengu út úr örk voru Sem, Kam og Jafet, og Kam er faðir Kanaans.'),
(225, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 19, 'OT', 'Þessir þrír eru synir Nóa, og af þeim dreifðist öll jörð.'),
(226, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 20, 'OT', 'Nói, maður jarðar, hóf jarðyrkju og gróðursetti víngarð.'),
(227, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 21, 'OT', 'Og hann drakk af víni og varð drukkinn og lá nakinn í tjaldi sínu.'),
(228, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 22, 'OT', 'Og Kam, faðir Kanaans, sá nekt föður síns og sagði bræðrum sínum úti fyrir.'),
(229, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 23, 'OT', 'Þá tóku Sem og Jafet skikkju, lögðu hana á öxl sér, gengu aftur á bak og huldu nekt föður síns; andlit þeirra sneru ábak, og þeir sáu ekki nekt föður síns.'),
(230, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 24, 'OT', 'Og Nói vaknaði af víni sínu og vissi hvað yngsti sonur hans hafði gert honum.'),
(231, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 25, 'OT', 'Og hann sagði: Bölvaður sé Kanaan; þjónn þjóna skal hann vera bræðrum sínum.'),
(232, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 26, 'OT', 'Og hann sagði: Blessaður sé Jahve, Guð Sems; og Kanaan skal vera þjónn þeirra.'),
(233, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 27, 'OT', 'Guð mun auka hlut Jafets, og hann skal búa í tjöldum Sems; og Kanaan skal vera þjónn þeirra.'),
(234, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 28, 'OT', 'Og Nói lifði eftir syndaflóð þrjú hundruð og fimmtíu ár.'),
(235, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 9, 29, 'OT', 'Og dagar Nóa voru níu hundruð og fimmtíu ár, og hann dó.'),
(236, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 1, 'OT', 'Þetta eru ættartölur sona Nóa: Sem, Kam og Jafet; og þeim fæddust synir eftir syndaflóð.'),
(237, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 2, 'OT', 'Synir Jafets: Gómer, Magog, Medía, Javan, Túbal, Mesek og Tíras.'),
(238, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 3, 'OT', 'Og synir Gómers: Askenas, Rífat og Togarma.'),
(239, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 4, 'OT', 'Og synir Javans: Elísa, Tarsis, Kittím og Dódaním.'),
(240, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 5, 'OT', 'Af þeim dreifðust eyjar þjóða í löndum sínum, hver maður eftir tungu sinni, eftir ættum sínum, meðal þjóða sinna.'),
(241, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 6, 'OT', 'Synir Kams: Kús, Egyptaland, Pút og Kanaan.'),
(242, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 7, 'OT', 'Og synir Kúss: Seba, Havíla, Sabta, Raema og Sabteka; og synir Raema: Séba og Dedan.'),
(243, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 8, 'OT', 'Og Kús gat Nimrod; hann varð kappi á jörð.'),
(244, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 9, 'OT', 'Hann var sterkur á veiði fyrir andliti Jahve; þess vegna er sagt: Eins og Nimrod, sterkur á veiði fyrir andliti Jahve.'),
(245, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 10, 'OT', 'Upphaf ríkis hans var Babýlon, Erek, Akkad og Kalne í jörð Sínear.'),
(246, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 11, 'OT', 'Frá jörð þeirri gekk Assýría út og reisti Níníve, Rehóbót-borg og Kala.'),
(247, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 12, 'OT', 'Og Resen milli Níníve og Kala; hún er mikil borg.'),
(248, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 13, 'OT', 'Og Egyptaland gat Lúdíta, Anamím, Lehabím og Naftúhím.'),
(249, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 14, 'OT', 'Og Patrusíta, Kasluhíta og Kaftóríta; þaðan komu Filistar.'),
(250, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 15, 'OT', 'Og Kanaan gat Sídon, frumgetinn sinn, og Het.'),
(251, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 16, 'OT', 'Og Jebúsíta, Amorita og Girgasíta.'),
(252, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 17, 'OT', 'Og Hevíta, Arkíta og Siníta.'),
(253, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 18, 'OT', 'Og Arvadíta, Semaríta og Hamatíta; og síðan dreifðust ættir Kanaanita.'),
(254, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 19, 'OT', 'Og landamæri Kanaanita náðu frá Sídon í átt til Gerar, allt til Gasa, og síðan í átt til Sódóma, Gómorra, Adma og Sebóím, allt til Lasa.'),
(255, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 20, 'OT', 'Þetta eru synir Kams eftir ættum þeirra, tungum þeirra, jörðum þeirra og þjóðum þeirra.'),
(256, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 21, 'OT', 'Og Sem fæddist einnig, faðir allra sona Ebers, bróðir Jafets hins eldri.'),
(257, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 22, 'OT', 'Synir Sems voru Elam, Assýría, Arpaksad, Lúd og Aram.'),
(258, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 23, 'OT', 'Synir Arams voru Ús, Húl, Geter og Mas.'),
(259, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 24, 'OT', 'Og Arpaksad gat Sela, og Sela gat Eber.'),
(260, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 25, 'OT', 'Eber eignaðist tvo sonu. Nafn annars var Peleg, því að á hans dögum klofnaði jörðin, og nafn bróður hans var Joktan.'),
(261, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 26, 'OT', 'Og Joktan gat Almódad, Selef, Hasarmavet og Jerak.'),
(262, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 27, 'OT', 'Og Hadóram, Úsal og Dikla.'),
(263, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 28, 'OT', 'Og Óbal, Abímael og Séba.'),
(264, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 29, 'OT', 'Og Ófír, Havíla og Jóbab. Allir þessir voru synir Joktans.'),
(265, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 30, 'OT', 'Og bústaður þeirra var frá Mesa í átt til Sefar, fjallsins í austri.'),
(266, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 31, 'OT', 'Þetta eru synir Sems eftir ættum þeirra, tungum þeirra, jörðum þeirra og þjóðum þeirra.'),
(267, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 10, 32, 'OT', 'Þetta eru ættir sona Nóa, eftir ættartölum þeirra og þjóðum þeirra. Af þeim dreifðust þjóðirnar um jörðina eftir syndaflóðið.'),
(268, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 1, 'OT', 'Öll jörðin hafði eina vör og sömu orð.'),
(269, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 2, 'OT', 'Þegar þeir héldu austur á bóginn, fundu þeir sléttu í jörðinni Sínear og settust þar að.'),
(270, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 3, 'OT', 'Og þeir sögðu hver maður við sinn náunga: Komið, við skulum búa til múrsteina og brenna þá til bruna. Og múrsteinninn varð þeim að steini, og jarðbikið varð þeim að leir.'),
(271, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 4, 'OT', 'Og þeir sögðu: Komið, byggjum okkur borg og turn, sem höfuð hans nái upp til himins, og gerum okkur nafn, svo að við tvístrumst ekki yfir allt andlit jarðarinnar.'),
(272, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 5, 'OT', 'Og Jahve steig niður til að sjá borgina og turninn, sem synir mannanna höfðu reist.'),
(273, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 6, 'OT', 'Og Jahve sagði: Sjá, þetta er einn lýður og ein vör, og þetta er það sem þeir byrja að gera. Og nú verður ekkert ókleift fyrir þá af öllu því sem þeir ætla að gera.'),
(274, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 7, 'OT', 'Komið, förum niður og ruglum þar vör þeirra, svo að enginn maður skilji vör náunga síns.'),
(275, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 8, 'OT', 'Og Jahve tvístraði þeim þaðan yfir allt andlit jarðarinnar, og þeir hættu að byggja borgina.'),
(276, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 9, 'OT', 'Þess vegna var nafn hennar kallað Babýlon, því að þar ruglaði Jahve vör allrar jarðarinnar. Og þaðan tvístraði Jahve þeim yfir allt andlit jarðarinnar.'),
(277, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 10, 'OT', 'Þetta er ættartala Sems. Sem var hundrað ára þegar hann gat soninn Arpaksad, tveimur árum eftir syndaflóðið.'),
(278, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 11, 'OT', 'Og Sem lifði eftir að hann gat Arpaksad fimm hundruð ár og gat sonu og dætur.'),
(279, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 12, 'OT', 'Og Arpaksad lifði þrjátíu og fimm ár og gat Sela.'),
(280, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 13, 'OT', 'Og Arpaksad lifði eftir að hann gat Sela fjögur hundruð og þrjú ár og gat sonu og dætur.'),
(281, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 14, 'OT', 'Og Sela lifði þrjátíu ár og gat Eber.'),
(282, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 15, 'OT', 'Og Sela lifði eftir að hann gat Eber fjögur hundruð og þrjú ár og gat sonu og dætur.'),
(283, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 16, 'OT', 'Og Eber lifði þrjátíu og fjögur ár og gat Peleg.'),
(284, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 17, 'OT', 'Og Eber lifði eftir að hann gat Peleg fjögur hundruð og þrjátíu ár og gat sonu og dætur.'),
(285, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 18, 'OT', 'Og Peleg lifði þrjátíu ár og gat Reú.'),
(286, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 19, 'OT', 'Og Peleg lifði eftir að hann gat Reú tvö hundruð og níu ár og gat sonu og dætur.'),
(287, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 20, 'OT', 'Og Reú lifði þrjátíu og tvö ár og gat Serúg.'),
(288, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 21, 'OT', 'Og Reú lifði eftir að hann gat Serúg tvö hundruð og sjö ár og gat sonu og dætur.'),
(289, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 22, 'OT', 'Og Serúg lifði þrjátíu ár og gat Nahor.'),
(290, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 23, 'OT', 'Og Serúg lifði eftir að hann gat Nahor tvö hundruð ár og gat sonu og dætur.'),
(291, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 24, 'OT', 'Og Nahor lifði tuttugu og níu ár og gat Tera.'),
(292, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 25, 'OT', 'Og Nahor lifði eftir að hann gat Tera hundrað og nítján ár og gat sonu og dætur.'),
(293, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 26, 'OT', 'Og Tera lifði sjötíu ár og gat Abram, Nahor og Haran.'),
(294, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 27, 'OT', 'Þetta er ættartala Tera. Tera gat Abram, Nahor og Haran, og Haran gat Lot.'),
(295, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 28, 'OT', 'Og Haran dó frammi fyrir andliti Tera föður síns, í jörð ættar sinnar, í Úr Kaldea.'),
(296, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 29, 'OT', 'Abram og Nahor tóku sér konur. Nafn konu Abrams var Saraí, og nafn konu Nahors var Milka, dóttir Harans, en Haran var faðir Milku og Jisku.'),
(297, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 30, 'OT', 'Og Saraí var óbyrja, hún átti ekki barn.'),
(298, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 31, 'OT', 'Tera tók Abram son sinn og Lot, son Harans, sonarson sinn, og Saraí brúði sína, konu Abrams sonar síns. Þeir fóru saman frá Úr Kaldea til að halda til jarðar Kanaans; en þegar þeir komu til Haran settust þeir þar að.'),
(299, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 11, 32, 'OT', 'Og dagar Tera urðu tvö hundruð og fimm ár, og Tera dó í Haran.'),
(300, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 1, 'OT', 'Og Jahve sagði við Abram: Far þú burt frá jörð þinni, frá ætt þinni og úr húsi föður þíns, til jörðina sem ég mun sýna þér.'),
(301, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 2, 'OT', 'Og ég mun gera þig að mikilli þjóð, blessa þig og gera nafn þitt mikið, og þú skalt verða blessun.'),
(302, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 3, 'OT', 'Ég mun blessa þá, sem blessa þig, og þann, sem bölvar þér, mun ég bölva; og í þér skulu allar ættir jarðarinnar blessast.'),
(303, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 4, 'OT', 'Abram fór eins og Jahve hafði boðið honum, og Lot fór með honum. Abram var fimm og sjötíu ára gamall, þegar hann fór frá Haran.'),
(304, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 5, 'OT', 'Abram tók Saraí, konu sína, og Lot, son bróður síns, og allar eignir þeirra, sem þeir höfðu aflað, og þær sálir sem þeir höfðu eignast í Haran; og þeir lögðu af stað til jarðar Kanaans og komu í jörð Kanaans.'),
(305, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 6, 'OT', 'Abram fór um jörðina allt til staðarins Síkem, til eikarinnar Móre. Kanaanítinn var þá í jörðinni.'),
(306, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 7, 'OT', 'Jahve birtist Abram og sagði: Sæði þínu mun ég gefa þessa jörð. Og hann reisti þar altari til Jahve, sem hafði birst honum.'),
(307, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 8, 'OT', 'Hann fór þaðan að fjallinu austur af Betel og tjaldaði tjaldi sínu, með Betel í vestri og Aí í austri. Þar reisti hann altari til Jahve og kallaði á nafn Jahve.'),
(308, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 9, 'OT', 'Abram hélt áfram til suðurlandsins.'),
(309, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 10, 'OT', 'Hungursneyð var í jörðinni, og Abram fór niður til Egyptalands til að dvelja þar, því hungursneyðin var þung í jörðinni.'),
(310, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 11, 'OT', 'Þegar hann var um það bil að fara inn í Egyptaland, sagði hann við Saraí, konu sína: Sjá, ég veit að þú ert kona fögur á útlit.'),
(311, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 12, 'OT', 'Þegar Egyptarnir sjá þig, munu þeir segja: Þetta er kona hans; og þeir munu drepa mig, en láta þig lifa.'),
(312, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 13, 'OT', 'Seg því, að þú sért systir mín, svo að mér farnist vel fyrir þína sakir, og sál mín lifi vegna þín.'),
(313, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 14, 'OT', 'Þegar Abram kom til Egyptalands, sáu Egyptarnir að konan var mjög fögur.'),
(314, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 15, 'OT', 'Höfðingjar Faraós sáu hana og lofuðu hana við Faraó; og konan var leidd í hús Faraós.'),
(315, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 16, 'OT', 'Og Faraó fór vel með Abram vegna hennar, og Abram eignaðist sauðfé, naut, asna, þjóna, ambáttir, ösnur og úlfalda.'),
(316, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 17, 'OT', 'En Jahve plagaði Faraó og hús hans með miklum plágum vegna Saraí, konu Abrams.'),
(317, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 18, 'OT', 'Þá kallaði Faraó á Abram og sagði: Hvað er þetta, sem þú hefur gert mér? Hvers vegna sagðir þú mér ekki að hún væri kona þín?'),
(318, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 19, 'OT', 'Hvers vegna sagðir þú: Hún er systir mín, svo að ég tók hana mér til konu? Nú, sjá, hér er kona þín; taktu hana og far burt.'),
(319, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 12, 20, 'OT', 'Og Faraó gaf mönnum sínum skipun um hann, og þeir fylgdu honum á brott ásamt konu hans og öllu sem hann átti.'),
(320, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 1, 'OT', 'Abram fór upp frá Egyptalandi, hann og kona hans og allt sem hann átti, og Lot með honum, suður til suðurlandsins.'),
(321, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 2, 'OT', 'Abram var mjög auðugur af fénaði, silfri og gulli.'),
(322, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 3, 'OT', 'Hann hélt í ferðir sínar frá suðurlandi til Betel, til staðarins þar sem tjald hans hafði verið í upphafi, milli Betel og Aí.'),
(323, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 4, 'OT', 'Hann kom aftur á staðinn við altarið, sem hann hafði gert áður, og þar kallaði Abram á nafn Jahve.'),
(324, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 5, 'OT', 'Lot, sem fór með Abram, átti líka sauðfé, naut og tjöld.'),
(325, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 6, 'OT', 'Jörðin gat ekki borið þá, svo að þeir gætu ekki búið saman, því eignir þeirra voru miklar.'),
(326, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 7, 'OT', 'Og þrætur urðu milli hirðmanna fénaðar Abrams og hirðmanna fénaðar Lots. Og Kanaanítar og Peresítar bjuggu þá í jörðinni.'),
(327, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 8, 'OT', 'Abram sagði við Lot: Ég bið þig, láttu enga deilu vera milli mín og þín, né milli hirðmanna minna og hirðmanna þinna, því við erum menn, bræður.'),
(328, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 9, 'OT', 'Er ekki öll jörðin fyrir andliti þínu? Skildu þig frá mér: ef þú ferð til vinstri handar, fer ég til hægri handar, og ef þú ferð til hægri handar, fer ég til vinstri handar.'),
(329, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 10, 'OT', 'Þá hóf Lot upp augu sín og sá alla talentu Jórdanar, að hún var öll vel vökvuð, áður en Jahve eyddi Sódómu og Gómorru, eins og garð Jahve, eins og jörðin í Egyptalandi, allt til Sóar.'),
(330, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 11, 'OT', 'Lot valdi sér alla talentu Jórdanar og fór austur á bóginn; og hver maður skildi við bróður sinn.'),
(331, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 12, 'OT', 'Abram bjó í jörð Kanaans, en Lot bjó í borgum á talentunni og tjaldaði nálægt Sódómu.'),
(332, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 13, 'OT', 'En mennirnir í Sódómu voru vondir og syndugir gegn Jahve mjög.'),
(333, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 14, 'OT', 'Jahve sagði við Abram, eftir að Lot hafði skilið við hann: Lyftu upp augum þínum og sjá frá staðnum þar sem þú ert: norður, til suðurlands, austur og til hafs í vestri.'),
(334, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 15, 'OT', 'Alla jörðina, sem þú sérð, mun ég gefa þér og sæði þínu um eilífð.'),
(335, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 16, 'OT', 'Ég mun gera sæði þitt eins og moldina á jörðinni; ef maður getur talið moldina á jörðinni, þá verður líka hægt að telja sæði þitt.'),
(336, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 17, 'OT', 'Rís upp, gakk um jörðina eftir lengd hennar og breidd, því ég mun gefa þér hana.'),
(337, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 13, 18, 'OT', 'Abram tjaldaði og settist að í eikunum Mamre, sem eru í Hebron, og reisti þar altari til Jahve.'),
(338, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 1, 'OT', 'Á dögum Amrafels, konungs í Sínear, Aríoks, konungs í Ellasar, Kedorlaómers, konungs í Elam, og Tídals, konungs þjóðanna.'),
(339, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 2, 'OT', 'Þeir háðu stríð: við Bera konung Sódómu, og Birsa konung Gómorru, Sinab konung Adma, og Semeber konung Sebóím, og konung Bela, sem er Sóar.'),
(340, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 3, 'OT', 'Allir þessir söfnuðust saman í dalnum Siddím, sem er Saltahafið.'),
(341, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 4, 'OT', 'Í tólf ár þjónuðu þeir Kedorlaómer, en á þrettánda ári gerðu þeir uppreisn.'),
(342, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 5, 'OT', 'Á fjórtánda ári kom Kedorlaómer og konungarnir sem með honum voru, og þeir sigruðu risa í Astarót-Karnaím, Súsím í Kam og Emía í Save-Kirjataím.'),
(343, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 6, 'OT', 'Hórítar í fjalli sínu Seír, allt til El-Paran, sem er við eyðimörkina.'),
(344, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 7, 'OT', 'Þeir sneru við og komu til En-Mispat, það er Kades, og sigruðu allan akur Amalekíta og líka Amóríta, sem bjuggu í Hasason-Tamar.'),
(345, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 8, 'OT', 'Þá fóru konungurinn í Sódómu, konungurinn í Gómorru, konungurinn í Adma, konungurinn í Sebóím og konungurinn í Bela, sem er Sóar, og þeir gengu fram til stríðs í Siddímdalnum.'),
(346, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 9, 'OT', 'Kedorlaómer, konungur í Elam, Tídal, konungur þjóðanna, Amrafel, konungur í Sínear, og Aríok, konungur í Ellasar: fjórir konungar gegn fimm.'),
(347, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 10, 'OT', 'En dalurinn Siddím var fullur af jarðbiksbrunnum; konungar Sódómu og Gómorru flýðu og féllu þar, en þeir sem eftir lifðu flýðu til fjallsins.'),
(348, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 11, 'OT', 'Þeir tóku allar eignir Sódómu og Gómorru og allan mat þeirra, og fóru burt.'),
(349, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 12, 'OT', 'Þeir tóku líka Lot, son bróður Abrams, og eignir hans, og fóru burt; því hann bjó í Sódómu.'),
(350, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 13, 'OT', 'Þá kom flóttamaðurinn og sagði Abram Hebrea; hann sem bjó í eikunum hjá Mamre Amóríta, bróður Eskóls og bróður Aners. Þeir voru herrar sáttmála Abrams.'),
(351, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 14, 'OT', 'Þegar Abram heyrði að bróðir hans væri tekinn til fanga, vopnaði hann þjálfaða þjóna sína, þrjú hundruð og átján, fædda í húsi hans, og elti þá allt til Dan.'),
(352, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 15, 'OT', 'Hann skipti liði sínu um nótt, hann og þjónar hans, sló þá og elti þá allt til Hóbu, sem er til vinstri handar við Damaskus.'),
(353, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 16, 'OT', 'Hann endurheimti allar eignir og líka Lot, bróður sinn, og eignir hans, og einnig konurnar og lýðinn.'),
(354, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 17, 'OT', 'Konungur Sódómu gekk út á móti honum, eftir að hann kom aftur frá því að sigra Kedorlaómer og konungana sem með honum voru, í dalnum Save, sem er konungsdalurinn.'),
(355, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 18, 'OT', 'Melkísedek, konungur Salem, bar fram brauð og vín; hann var prestur Guðs hins hæsta.'),
(356, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 19, 'OT', 'Hann blessaði hann og sagði: Blessaður sé Abram af Guði hinum hæsta, skapara himins og jarðar.'),
(357, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 20, 'OT', 'Og lofaður sé Guð hinn hæsti, sem frelsaði þig úr þrengslum og lagði óvini þína í þínar hendur. Og Abram gaf honum tíund af öllu.'),
(358, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 21, 'OT', 'Konungur Sódómu sagði við Abram: Gef mér sálirnar, en eignirnar tak þér.'),
(359, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 22, 'OT', 'Abram sagði við konung Sódómu: Ég hef lyft hönd mína til Jahve, Guðs hins hæsta, skapara himins og jarðar.'),
(360, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 23, 'OT', 'Ekki þráð, ekki skóþveng né skó, og ekki neitt af því sem þín er, svo að þú getir ekki sagt: Ég hef auðgað Abram.'),
(361, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 14, 24, 'OT', 'Ég vil ekkert nema það sem sveinarnir hafa etið, og hlut mannanna sem fóru með mér: Aner, Eskól og Mamre; þeir skulu taka sinn hlut.'),
(362, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 1, 'OT', 'Eftir þessa atburði kom orð Jahve til Abrams í sýn og sagði: Óttast þú ekki, Abram. Ég er skjöldur þinn; laun þín verða mjög mikil.'),
(363, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 2, 'OT', 'Abram sagði: Drottinn Jahve, hvað gefur þú mér, þar sem ég fer barnlaus? Og erfinginn er sonur ráðsmanns húss míns, Elíeser frá Damaskus.'),
(364, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 3, 'OT', 'Abram sagði: Sjá, þú hefur ekki gefið mér sæði, og sjá, sonur húss míns skal erfa mig.'),
(365, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 4, 'OT', 'En sjá, orð Jahve kom til hans: Þessi skal ekki erfa þig, heldur sá sem kemur af þínu eigin iðri, hann skal erfa þig.'),
(366, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 5, 'OT', 'Hann leiddi hann út og sagði: Lít þú til himins og tel stjörnurnar, ef þú getur talið þær. Og hann sagði við hann: Svo skal sæði þitt verða.'),
(367, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 6, 'OT', 'Og hann trúði á Jahve, og hann taldi það honum til réttlætis.'),
(368, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 7, 'OT', 'Og hann sagði við hann: Ég er Jahve, sem leiddi þig út frá Úr Kaldea, til að gefa þér þessa jörð til eignar.'),
(369, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 8, 'OT', 'Hann sagði: Drottinn Jahve, hvernig get ég vitað, að ég muni erfa hana?'),
(370, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 9, 'OT', 'Hann sagði við hann: Tak fyrir mig kvígu, þriggja ára, geit, þriggja ára, hrút, þriggja ára, turtildúfu og unga.'),
(371, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 10, 'OT', 'Hann tók öll þessi dýr, skar þau í tvennt og lagði hvern hluta gegnt náunga sínum; en fuglinn skar hann ekki í tvennt.'),
(372, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 11, 'OT', 'Og ránfuglar sóttu niður á hræin, en Abram rak þá burt.'),
(373, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 12, 'OT', 'Þegar sólin var að setjast, féll þung dá yfir Abram; og sjá, mikil skelfing og myrkur féll yfir hann.'),
(374, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 13, 'OT', 'Þá sagði hann við Abram: Vit þú fyrir víst, að sæði þitt mun verða útlendingar í jörð, sem ekki er þeirra; og þeir munu þjóna þeim og þjaka þá í fjögur hundruð ár.'),
(375, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 14, 'OT', 'En líka þjóðina, sem þeir þjóna, skal ég dæma, og eftir það munu þeir fara út með miklar eignir.'),
(376, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 15, 'OT', 'En þú munt fara til feðra þinna í friði, og þú verður grafinn í góðri elli, í gráu hári.'),
(377, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 16, 'OT', 'Í fjórðu kynslóð munu þeir koma aftur hingað, því misgjörð Amóríta er ekki enn fullnuð.'),
(378, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 17, 'OT', 'Þegar sólin var sest og rökkrið kom, sjá, þá var ofn með reyk og kyndill, eldur logandi, sem fór á milli þessara stykkja.'),
(379, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 18, 'OT', 'Á þeim degi gerði Jahve sáttmála við Abram og sagði: Sæði þínu gef ég þessa jörð, frá fljótinu Egyptalands til hins mikla fljóts, Efratfljóts.'),
(380, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 19, 'OT', 'Keníta, Kenasíta og Kadmóníta.'),
(381, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 20, 'OT', 'Hetíta, Peresíta og risa.'),
(382, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 15, 21, 'OT', 'Amóríta, Kanaanita, Girgasíta og Jebúsíta.'),
(383, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 1, 'OT', 'Saraí, kona Abrams, eignaðist engin börn; hún átti egypska ambátt, og nafn hennar var Hagar.'),
(384, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 2, 'OT', 'Og Saraí sagði við Abram: Sjá, Jahve hefur haldið mér frá því að eignast börn. Gakk þú inn til ambáttar minnar, ef til vill get ég eignast börn fyrir hennar tilstilli. Og Abram hlýddi röddu Saraí.'),
(385, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 3, 'OT', 'Saraí, kona Abrams, tók Hagar, egypsku ambátt sína, og gaf hana Abram, manni sínum, til konu eftir að Abram hafði búið tíu ár í jörðinni Kanaans.'),
(386, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 4, 'OT', 'Hann gekk inn til Hagar, og hún varð þunguð; og þegar hún sá að hún var þunguð, fyrirleit hún húsfreyju sína í augum sínum.'),
(387, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 5, 'OT', 'Saraí sagði við Abram: Ofbeldið gegn mér er þín sök; ég lagði ambátt mína í skaut þitt, og þegar hún sá að hún var þunguð, fyrirleit hún mig í augum sínum. Jahve dæmi milli mín og þín.'),
(388, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 6, 'OT', 'Abram sagði við Saraí: Sjá, ambátt þín er í þínum höndum; gjör við hana það, sem þér sýnist gott í þínum augum. Og Saraí þjakaði hana, og hún flúði frá andliti hennar.'),
(389, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 7, 'OT', 'Sendiboði Jahve fann hana við vatnsaugað í eyðimörkinni, á veginum til Súr.'),
(390, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 8, 'OT', 'Hann sagði: Hagar, ambátt Saraí, hvaðan kemur þú og hvert ætlar þú? Og hún sagði: Ég flý frá andliti Saraí, húsfreyju minnar.'),
(391, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 9, 'OT', 'Sendiboði Jahve sagði við hana: Snú aftur til húsfreyju þinnar og beygðu þig undir hendur hennar.'),
(392, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 10, 'OT', 'Sendiboði Jahve sagði við hana: Ég mun margfalda sæði þitt, svo að það verði ekki talið vegna mannfjölda.'),
(393, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 11, 'OT', 'Og sendiboði Jahve sagði við hana: Sjá, þú ert þunguð og munt fæða son, og þú skalt kalla nafn hans Ísmael, því Jahve hefur heyrt eymd þína.'),
(394, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 12, 'OT', 'Hann mun verða villiasni meðal manna; hönd hans verður gegn öllum, og hönd allra gegn honum, og hann mun búa fyrir andliti allra bræðra sinna.'),
(395, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 13, 'OT', 'Og hún kallaði nafn Jahve, sem talaði við hana: Þú ert Guð augnayndisins; því hún sagði: Hef ég hér líka séð þann sem sér mig?'),
(396, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 14, 'OT', 'Þess vegna var brunnurinn kallaður Beer-Lakaí-Róí; hann er milli Kades og Bered.'),
(397, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 15, 'OT', 'Hagar ól Abram son, og Abram gaf syni sínum, sem Hagar ól, nafnið Ísmael.'),
(398, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 16, 16, 'OT', 'Abram var áttatíu og sex ára gamall, þegar Hagar ól honum son, Ísmael.'),
(399, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 1, 'OT', 'Þegar Abram var níutíu og níu ára, birtist Jahve honum og sagði: Ég er Almáttugur Guð; gakk fyrir andliti mínu og vertu ráðvandur.'),
(400, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 2, 'OT', 'Og ég mun gera sáttmála minn milli mín og þín, og ég mun margfalda þig mjög mikið.'),
(401, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 3, 'OT', 'Abram féll fram á andlit sitt, og Guð talaði við hann og sagði:'),
(402, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 4, 'OT', 'Sjá, sáttmáli minn er við þig: Þú skalt verða faðir fjölda þjóða.'),
(403, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 5, 'OT', 'Nafn þitt skal ekki framar kallast Abram, heldur skal nafn þitt vera Abraham, því ég hef gert þig að föður fjölda þjóða.'),
(404, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 6, 'OT', 'Ég mun gera þig mjög frjósaman, ég mun gera þig að þjóðum, og konungar munu koma út af þér.'),
(405, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 7, 'OT', 'Ég mun staðfesta sáttmála minn milli mín og þín og sæðis þíns eftir þig, kynslóð eftir kynslóð, sem eilífan sáttmála um eilífð, til þess að ég verði Guð þinn og sæðis þíns eftir þig.'),
(406, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 8, 'OT', 'Ég mun gefa þér og sæði þínu eftir þig jörðina, sem þú ert í útlegð í, alla jörð Kanaans, til eignar um eilífð; og ég mun vera Guð þeirra.'),
(407, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 9, 'OT', 'Og Guð sagði við Abraham: Þú skalt varðveita sáttmála minn, þú og sæði þitt eftir þig, kynslóð eftir kynslóð.'),
(408, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 10, 'OT', 'Þetta er sáttmáli minn, sem þér skuluð varðveita milli mín og yðar og sæðis þíns eftir þig: Umskerið sérhvern karlmann meðal yðar.'),
(409, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 11, 'OT', 'Og þér skuluð umskera hold yfirhúðar yðar, og það skal vera tákn sáttmálans milli mín og yðar.'),
(410, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 12, 'OT', 'Átta daga gamall sonur skal umskerast meðal yðar, sérhver karlmaður, í öllum kynslóðum yðar: bæði heimafædd barn í húsi þínu og þeir sem keyptir eru fyrir kaup af útlendum manni, sem ekki er af sæði þínu.'),
(411, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 13, 'OT', 'Heimafædd barn í húsi þínu og þeir sem keyptir eru fyrir þitt silfur skulu umskerast; og sáttmáli minn skal vera á holdi yðar um eilífð.'),
(412, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 14, 'OT', 'Óumskorinn karlmaður, sem ekki lætur umskera hold yfirhúðar sinnar, sú sál skal upprætt verða úr lýð sínum: hún hefur rofið sáttmála minn.'),
(413, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 15, 'OT', 'Og Guð sagði við Abraham: Saraí, konu þína, skalt þú ekki kalla Saraí; nafn hennar skal vera Sara.'),
(414, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 16, 'OT', 'Ég mun blessa hana, og ég mun gefa þér son með henni. Ég mun blessa hana, og hún skal verða móðir þjóða; konungar lýða skulu koma af henni.'),
(415, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 17, 'OT', 'Þá féll Abraham á andlit sitt og hló og sagði í hjarta sínu: Mun sonur fæðast manni, sem er hundrað ára? Og mun Sara, níutíu ára, fæða?'),
(416, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 18, 'OT', 'Og Abraham sagði við Guð: Ó, að Ísmael mætti lifa fyrir andliti þínu.'),
(417, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 19, 'OT', 'Þá sagði Guð: Nei, Sara, kona þín, mun fæða þér son, og þú skalt gefa honum nafnið Ísak; og ég mun staðfesta sáttmála minn við hann sem sáttmála um eilífð fyrir sæði hans eftir hann.'),
(418, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 20, 'OT', 'Og um Ísmael hef ég heyrt bæn þína: Sjá, ég hef blessað hann og gjört hann frjósaman og mjög fjölmennan; hann mun eignast tólf höfðingja, og ég mun gera hann að mikilli þjóð.'),
(419, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 21, 'OT', 'En sáttmála minn mun ég staðfesta við Ísak, sem Sara mun fæða þér á þessum tiltekna tíma að ári.'),
(420, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 22, 'OT', 'Og er hann hafði lokið við að tala við hann, steig Guð upp frá Abraham.'),
(421, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 23, 'OT', 'Abraham tók Ísmael, son sinn, og alla heimafædda í húsi sínu og alla sem keyptir voru fyrir silfur, alla menn í húsi Abrahams; og hann umskar hold yfirhúðar þeirra þá á sama degi, eins og Guð hafði talað við hann.'),
(422, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 24, 'OT', 'Abraham var níutíu og níu ára, þegar hann umskar hold yfirhúðar sinnar.'),
(423, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 25, 'OT', 'Og Ísmael, sonur hans, var þrettán ára, þegar hann umskar hold yfirhúðar sinnar.'),
(424, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 26, 'OT', 'Á þessum sama degi var Abraham umskorinn og Ísmael, sonur hans.'),
(425, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 17, 27, 'OT', 'Og allir menn í húsi hans, heimafædd barn og þeir sem keyptir voru fyrir kaup af útlendingi, voru umskornir með honum.'),
(426, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 1, 'OT', 'Jahve birtist Abraham við eikurnar í Mamre, þegar hann sat í inngangi tjaldsins í hitanum um daginn.'),
(427, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 2, 'OT', 'Hann lyfti upp augunum og sá þrjá menn standa fyrir framan sig; og er hann sá þá, hljóp hann á móti þeim úr inngangi tjaldsins og laut til jarðar.'),
(428, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 3, 'OT', 'Hann sagði: Herra minn, ef ég hef fundið hylli í augum þínum, þá skalt þú ekki ganga fram hjá þjóni þínum.'),
(429, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 4, 'OT', 'Látið sækja lítið vatn, þvoið fætur yðar og hvílist undir trénu.'),
(430, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 5, 'OT', 'Ég vil sækja brauðbita, og styrkið hjarta yðar; síðan megið þið halda áfram, því þess vegna komuð þið til þjóns yðar. Þeir sögðu: Gjör svo, eins og þú hefur mælt.'),
(431, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 6, 'OT', 'Abraham flýtti sér í tjaldið til Söru og sagði: Flýttu þér, taktu þrjá mælikvarða af fínu mjöli, hnoðaðu það og gjörðu hlóðakökur.'),
(432, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 7, 'OT', 'Og Abraham hljóp til nautgripanna og tók ungan og góðan kálf, son nautsins, og fékk hann sveini; hann flýtti sér að matreiða hann.'),
(433, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 8, 'OT', 'Hann tók smjör og mjólk og kálfinn, son nautsins, sem hann hafði matreitt, og setti fyrir andlit þeirra; og hann stóð hjá þeim undir trénu, og þeir átu.'),
(434, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 9, 'OT', 'Þeir sögðu við hann: Hvar er Sara, kona þín? Hann sagði: Hún er í tjaldinu.'),
(435, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 10, 'OT', 'Hann sagði: Ég mun vissulega koma aftur til þín á þessum tíma, og sjá, Sara, kona þín, mun eignast son. Og Sara hlustaði við inngang tjaldsins, sem var fyrir aftan hann.'),
(436, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 11, 'OT', 'Abraham og Sara voru gömul, komin á efri dögum; Söru hafði hætt að ganga þann stíg sem konur ganga.'),
(437, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 12, 'OT', 'Þá hló Sara í hjarta sínu og sagði: Eftir að ég er orðin visin, á ég þá unaður að njóta? Og herra minn er gamall.'),
(438, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 13, 'OT', 'Jahve sagði við Abraham: Hví hló Sara og sagði: Á ég virkilega að fæða barn, þegar ég er orðin gömul?'),
(439, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 14, 'OT', 'Er nokkuð of erfitt fyrir Jahve? Á tilsettum tíma mun ég koma aftur til þín, á þessum tíma, og Sara mun eignast son.'),
(440, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 15, 'OT', 'Sara neitaði og sagði: Ég hló ekki, því ég var hrædd. Hann sagði: Nei, þú hlóst.'),
(441, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 16, 'OT', 'Mennirnir risu þaðan og horfðu fyrir andlit Sódómu, og Abraham gekk með þeim til að fylgja þeim.'),
(442, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 17, 'OT', 'Og Jahve sagði: Skal ég leyna Abraham því sem ég ætla að gera?'),
(443, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 18, 'OT', 'Abraham mun verða að mikilli og voldugri þjóð, og allar þjóðir jarðarinnar munu blessast í honum.'),
(444, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 19, 'OT', 'Því ég þekki hann, svo að hann bjóði sonum sínum og húsi sínu eftir sig að varðveita vegu Jahve, með því að gjöra réttlæti og dóm, svo að Jahve megi uppfylla um Abraham það sem hann hefur sagt.'),
(445, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 20, 'OT', 'Og Jahve sagði: Ópið yfir Sódómu og Gómorru er mikið, og synd þeirra er mjög þung.'),
(446, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 21, 'OT', 'Ég mun fara niður og sjá, hvort þeir hafa framið eyðingu, eins og neyðaróp það sem kemur til mín segir; og ef ekki, þá mun ég vita það.'),
(447, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 22, 'OT', 'Mennirnir sneru sér þaðan og gengu til Sódómu, en Abraham stóð enn fyrir andliti Jahve.'),
(448, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 23, 'OT', 'Abraham gekk nær og sagði: Vilt þú líka tortíma hinum réttláta með hinum óguðlega?'),
(449, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 24, 'OT', 'Ef til vill eru fimmtíu réttlátir innan borgarinnar; vilt þú þá líka tortíma henni og ekki þyrma staðnum vegna fimmtíu réttlátra, sem eru í henni?'),
(450, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 25, 'OT', 'Fjarri sé það frá þér að gjöra slíkt, sem þessum orðum samsvarar: að deyða hinn réttláta með hinum óguðlega, svo að hinn réttláti sé sem hinn óguðlegi! Fjarri sé það frá þér! Mun ekki dómarinn yfir allri jörðinni gjöra dóm?'),
(451, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 26, 'OT', 'Og Jahve sagði: Finni ég í Sódóma fimmtíu réttláta menn innan borgarinnar, þá mun ég þyrma öllum staðnum þeirra vegna.'),
(452, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 27, 'OT', 'Þá svaraði Abraham og sagði: Sjá, ég hef leyft mér að tala við Drottin, þótt ég sé ekki annað en mold og aska.'),
(453, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 28, 'OT', 'Og hann sagði: Vanti kannski fimm af fimmtíu réttlátu mönnunum, munt þú þá tortíma allri borginni fyrir þá fimm sem vantar? Hann sagði: Ég mun ekki tortíma, finni ég þar fjörutíu og fimm.'),
(454, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 29, 'OT', 'Hann bætti enn við að tala við hann og sagði: Kannski finnast þar fjörutíu. Hann sagði: Ég mun ekki gera það vegna hinna fjörutíu.'),
(455, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 30, 'OT', 'Þá sagði hann: Reiðist ekki Drottni, og ég mun tala. Kannski finnast þar þrjátíu. Hann svaraði: Ég mun ekki gera það, ef ég finn þar þrjátíu.'),
(456, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 31, 'OT', 'Hann sagði: Sjá, ég hef leyft mér að tala við Drottin. Kannski finnast þar tuttugu. Hann svaraði: Ég mun ekki tortíma vegna hinna tuttugu.'),
(457, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 32, 'OT', 'Þá sagði hann: Reiðist ekki Drottni, og ég mun tala aðeins þetta sinn. Kannski finnast þar tíu. Hann svaraði: Ég mun ekki tortíma vegna hinna tíu.'),
(458, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 18, 33, 'OT', 'Og Jahve fór, þegar hann hafði lokið við að tala við Abraham, og Abraham sneri aftur til staðar síns.'),
(459, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 1, 'OT', 'Tveir sendiboðar komu til Sódómu að kvöldi, og Lot sat í borgarhliðinu í Sódóma. Þegar Lot sá þá, reis hann upp til að mæta þeim og laut fram með nefinu til jarðar.'),
(460, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 2, 'OT', 'Hann sagði: Sjá, herrar mínir, komið nú og gangið inn í hús þjóns ykkar, gistið þar og þvoið fætur ykkar. Þá getið þið risið snemma og haldið veg ykkar. En þeir sögðu: Nei, við munum gista á torginu.'),
(461, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 3, 'OT', 'Hann þrábað þá mjög, og þeir sneru til hans og fóru inn í hús hans. Hann bjó þeim veislu og bakaði ósýrt brauð, og þeir átu.'),
(462, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 4, 'OT', 'Áður en þeir lögðust til hvílu, umkringdu menn borgarinnar, menn Sódómu, húsið, frá sveini til öldungs, allur lýðurinn úr öllum endum.'),
(463, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 5, 'OT', 'Þeir kölluðu á Lot og sögðu við hann: Hvar eru mennirnir sem komu til þín í nótt? Leiddu þá út til okkar, svo að vér getum átt samfarir við þá.'),
(464, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 6, 'OT', 'Lot gekk út til þeirra að inngangi, og hurðina lokaði hann á eftir sér.'),
(465, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 7, 'OT', 'Hann sagði: Ó, bræður mínir, gjörið ekki þetta illt.'),
(466, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 8, 'OT', 'Sjá, ég á tvær dætur sem hafa ekki þekkt karlmann. Ég vil leiða þær út til ykkar, og gerið við þær það sem gott þykir í augum ykkar. En við þessa menn skuluð þið ekkert gera, því að þeir hafa komið í skugga þakbjálka míns.'),
(467, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 9, 'OT', 'Þeir sögðu: Farið frá! Og þeir sögðu: Þessi maður kom hingað sem útlendingur og vill nú dæma? Nú munum við gera þér verra en þeim. Þeir þrýstu mjög á manninn, Lot, og komu nær til að brjóta upp hurðina.'),
(468, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 10, 'OT', 'Mennirnir réttu út hendur sínar, drógu Lot til sín inn í húsið og lokuðu hurðinni.'),
(469, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 11, 'OT', 'Og mennina sem stóðu við dyr hússins lömdu þeir með blindu, bæði smáa og stóra, svo að þeir gátu ekki fundið inngang.'),
(470, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 12, 'OT', 'Mennirnir sögðu við Lot: Hver er þér hér enn? Tengdason þinn, synir þínir, dætur þínar og allt sem þér tilheyrir í borginni, far út af þessum stað.'),
(471, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 13, 'OT', 'Því að við munum tortíma þessum stað, því að neyðaróp þeirra hefur vaxið mikið fyrir andliti Jahve, og Jahve hefur sent okkur til að tortíma honum.'),
(472, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 14, 'OT', 'Lot gekk út og talaði við tengdasonu sína, sem höfðu tekið dætur hans, og sagði: Standið upp, farið út af þessum stað, því að Jahve mun tortíma borginni. En í augum tengdasona hans var hann eins og gamanmaður.'),
(473, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 15, 'OT', 'Þegar dögun rann upp, hvöttu sendiboðarnir Lot og sögðu: Statt upp, taktu konu þína og dætur þínar tvær sem hér eru, svo að þú farist ekki vegna misgjörðar borgarinnar.'),
(474, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 16, 'OT', 'Hann tafði, en mennirnir tóku í hönd hans, í hönd konu hans og í hendur tveggja dætra hans, af miskunn Jahve, leiddu hann út og settu hann utan borgarinnar.'),
(475, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 17, 'OT', 'Og svo var, þegar þeir höfðu leitt hann út, að hann sagði: Bjargaðu sál þinni! Líttu ekki aftur, og staldraðu ekki við á sléttlendinu. Forðastu fjallið, svo að þú farist ekki.'),
(476, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 18, 'OT', 'Þá sagði Lot við þá: Nei, Drottinn minn.'),
(477, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 19, 'OT', 'Sjá, þjónn þinn hefur fundið hylli í augum þínum, og þú hefur sýnt mikla miskunn þína, sem þú hefur gert mér, með því að varðveita sál mína. En ég get ekki komist upp á fjallið, svo að illskan nái mér og ég deyi.'),
(478, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 20, 'OT', 'Sjá, borgin þessi er nálæg til að flýja þangað, og hún er í lítilleika. Ó, leyf mér að flýja þangað, er hún ekki smá? Og sál mín mun lifa.'),
(479, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 21, 'OT', 'Hann sagði við hann: Sjá, ég hef líka tekið tillit til andlits þíns í þessu orði, svo að ég muni ekki eyða borginni sem þú talaðir um.'),
(480, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 22, 'OT', 'Flýttu þér, flý þangað, því að ég get ekki gert neitt fyrr en þú kemur þangað. Þess vegna var nafn borgarinnar kallað Sóar.'),
(481, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 23, 'OT', 'Sólin reis yfir jörðina, og Lot kom til Sóar.'),
(482, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 24, 'OT', 'Og Jahve lét rigna yfir Sódóma og Gómorra brennisteini og eldi, frá Jahve af himni.'),
(483, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 25, 'OT', 'Og hann umturnaði þessum borgum, öllu hringlendinu, öllum íbúum borganna og öllum kvisti sem óx á jörðinni.'),
(484, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 26, 'OT', 'En kona hans leit aftur fyrir sig, og hún varð að saltsúlu.'),
(485, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 27, 'OT', 'Abraham reis árla að morgni og fór á staðinn þar sem hann hafði staðið frammi fyrir andliti Jahve.'),
(486, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 28, 'OT', 'Og hann leit yfir andlit Sódóma og Gómorra og yfir alla jörðina í hringlendinu, og sjá, reykur steig upp af jörðinni eins og reykur úr ofninum.'),
(487, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 29, 'OT', 'Þegar Guð eyddi borgum hringlendisins, minntist Guð Abrahams og sendi Lot út úr umturnuninni, þegar hann umturnaði borgunum þar sem Lot hafði búið.'),
(488, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 30, 'OT', 'Lot fór upp frá Sóar og settist að á fjallinu, og báðar dætur hans með honum, því að hann óttaðist að búa í Sóar. Og hann settist að í hellinum, hann og báðar dætur hans.'),
(489, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 31, 'OT', 'Hin frumgetna dóttir sagði við hina yngri: Faðir okkar er gamall, og enginn maður er á jörðinni sem komi til okkar, eins og vegur er um alla jörðina.'),
(490, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 32, 'OT', 'Komdu, við skulum gefa föður okkar vín að drekka og leggjast hjá honum, svo að við getum varðveitt sæði frá föður okkar.'),
(491, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 33, 'OT', 'Þær gáfu föður sínum vín að drekka þessa nótt, og hin frumgetna dóttir kom og lagðist hjá föður sínum, og hann vissi ekki þegar hún lagðist né þegar hún reis upp.'),
(492, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 34, 'OT', 'Morguninn eftir sagði hin frumgetna dóttir við hina yngri: Sjá, í gærkvöldi lagðist ég hjá föður mínum. Gefum honum vín líka þessa nótt, og farðu þú inn og leggstu hjá honum, svo að við getum varðveitt sæði frá föður okkar.'),
(493, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 35, 'OT', 'Þær gáfu föður sínum vín einnig þessa nótt, og hin yngri kom og lagðist hjá honum, og hann vissi ekki þegar hún lagðist né þegar hún reis upp.'),
(494, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 36, 'OT', 'Þannig urðu báðar dætur Lots þungaðar af föður sínum.'),
(495, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 37, 'OT', 'Hin frumgetna dóttir ól son og gaf honum nafnið Móab. Hann er faðir Móabíta allt til þessa dags.'),
(496, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 19, 38, 'OT', 'Og hin yngri ól einnig son og gaf honum nafnið Ben-Ammí. Hann er faðir sona Ammóns allt til þessa dags.'),
(497, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 1, 'OT', 'Abraham fór þaðan til jarðar suðurlandsins og settist að milli Kades og Súr, og dvaldist í Gerar.'),
(498, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 2, 'OT', 'Abraham sagði um Söru konu sína: Hún er systir mín. Þá sendi Abímelek konungur til Gerar og tók Söru.'),
(499, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 3, 'OT', 'En Guð kom til Abímeleks í draumi um nóttina og sagði við hann: Sjá, þú ert dauðans vegna konunnar sem þú hefur tekið, því að hún er í eigu herra síns.'),
(500, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 4, 'OT', 'En Abímelek hafði ekki nálgast hana, og hann sagði: Drottinn, ætlarðu að drepa þjóð, jafnvel réttláta?'),
(501, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 5, 'OT', 'Sagði hann ekki sjálfur við mig: Hún er systir mín? Og hún sjálf sagði: Hann er bróðir minn. Í ráðvendni hjarta míns og í sakleysi lófa minna hef ég gert þetta.'),
(502, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 6, 'OT', 'Þá sagði Guð við hann í draumi: Já, ég veit að þú gerðir þetta í ráðvendni hjarta þíns. Ég hélt þig einnig frá því að syndga gegn mér, og þess vegna leyfði ég þér ekki að snerta hana.'),
(503, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 7, 'OT', 'Skilaðu nú konu mannsins, því að hann er spámaður, og hann mun biðja fyrir þér, og þú munt lifa. En ef þú skilar henni ekki, skalt þú vita að þú munt deyja, þú og allt sem þitt er.'),
(504, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 8, 'OT', 'Abímelek reis árla að morgni, kallaði á alla þjóna sína og talaði öll þessi orð í eyru þeirra. Og mennirnir urðu mjög hræddir.'),
(505, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 9, 'OT', 'Abímelek kallaði á Abraham og sagði við hann: Hvað hefur þú gert okkur? Og hvað hef ég syndgað gegn þér, að þú leiðir yfir mig og yfir ríki mitt svo mikla synd? Verk sem ekki má gera hefur þú gert við mig.'),
(506, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 10, 'OT', 'Abímelek sagði við Abraham: Hvað sástu, að þú gerðir þetta?'),
(507, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 11, 'OT', 'Abraham sagði: Ég hugsaði með mér að það væri enginn guðsótti á þessum stað, og að þeir myndu drepa mig vegna konu minnar.'),
(508, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 12, 'OT', 'Og hún er líka sannarlega systir mín, dóttir föður míns, þó ekki dóttir móður minnar. Og hún varð mér að konu.'),
(509, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 13, 'OT', 'Og þegar Guð lét mig reika burt frá húsi föður míns, sagði ég við hana: Þetta er sú miskunn sem þú skalt sýna mér: á hvern stað sem við komum, seg um mig: Hann er bróðir minn.'),
(510, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 14, 'OT', 'Þá tók Abímelek sauðfé og naut, þjóna og ambáttir og gaf Abraham þau, og hann skilaði honum Söru konu hans.'),
(511, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 15, 'OT', 'Og Abímelek sagði: Sjá, jörð mín er fyrir andliti þínu. Settu þig þar sem þér þykir gott í augum þínum.'),
(512, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 16, 'OT', 'Og við Söru sagði hann: Sjá, ég hef gefið bróður þínum þúsund silfurpeninga. Sjá, þeir eru þér til klæðis fyrir augunum gagnvart öllum sem eru með þér, og þú ert réttlætt.'),
(513, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 17, 'OT', 'Abraham bað til Guðs, og Guð læknaði Abímelek, konu hans og ambáttir hans, og þær tóku að eignast börn.'),
(514, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 20, 18, 'OT', 'Því að Jahve hafði lokað öllum móðurlífum í húsi Abímeleks vegna Söru, konu Abrahams.'),
(515, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 1, 'OT', 'Og Jahve vitjaði Söru eins og hann hafði sagt, og Jahve gerði Söru eins og hann hafði talað.'),
(516, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 2, 'OT', 'Sara varð þunguð og ól Abraham son á elliárum hans, á tilsettum tíma sem Guð hafði talað um.'),
(517, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 3, 'OT', 'Abraham gaf syni sínum, sem Sara ól honum, nafnið Ísak.'),
(518, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 4, 'OT', 'Abraham umskar Ísak son sinn, átta daga gamlan, eins og Guð hafði boðið honum.'),
(519, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 5, 'OT', 'Abraham var hundrað ára þegar Ísak sonur hans fæddist honum.'),
(520, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 6, 'OT', 'Og Sara sagði: Guð hefur gert mér hlátur. Allir sem heyra það munu hlæja með mér.'),
(521, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 7, 'OT', 'Og hún sagði: Hver hefði sagt Abraham að Sara myndi gefa sonum brjóst? Ég hef þó alið honum son á elliárum hans.'),
(522, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 8, 'OT', 'Drengurinn óx og var vaninn af brjósti, og Abraham hélt mikla veislu þann dag sem Ísak var vaninn.'),
(523, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 9, 'OT', 'Sara sá son Hagars Egypta, sem hún hafði alið Abraham, gera gys.'),
(524, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 10, 'OT', 'Hún sagði við Abraham: Rektu burt þessa ambátt og son hennar, því að sonur þessarar ambáttar skal ekki erfa með syni mínum, Ísak.'),
(525, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 11, 'OT', 'Þetta orð var mjög þungbært í augum Abrahams vegna sonar hans.'),
(526, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 12, 'OT', 'Guð sagði við Abraham: Láttu þetta ekki vera þungt í augum þínum vegna sveinsins og ambáttar þinnar. Hvað sem Sara segir þér, hlýddu rödd hennar, því að frá Ísak mun sæði þitt kallast.'),
(527, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 13, 'OT', 'Og son ambáttarinnar geri ég líka að þjóð, því að hann er þitt sæði.'),
(528, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 14, 'OT', 'Abraham reis árla að morgni, tók brauð og vínbelg með vatni og lagði á öxl Hagars ásamt drengnum, og lét hana fara. Hún gekk burt og villtist í eyðimörkinni við Beerseba.'),
(529, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 15, 'OT', 'Vatnið í vínbelgnum var á þrotum, og hún lagði drenginn undir einn runna.'),
(530, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 16, 'OT', 'Hún gekk burt og settist sér á móti, í hæfilegri fjarlægð eins og bogaskot, því að hún sagði: Ég get ekki horft á dauða drengsins. Og hún settist á móti honum og hóf upp rödd sína og grét.'),
(531, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 17, 'OT', 'Guð heyrði rödd sveinsins, og sendiboði Guðs kallaði á Hagar af himni og sagði við hana: Hvað gengur á, Hagar? Óttastu ekki, því að Guð hefur heyrt rödd sveinsins þar sem hann er.'),
(532, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 18, 'OT', 'Statt upp, lyftu sveininum og haltu fast í hönd þína á honum, því að ég mun gera hann að mikilli þjóð.'),
(533, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 19, 'OT', 'Guð opnaði augu hennar, og hún sá vatnsbrunn. Hún fór, fyllti vínbelginn með vatni og gaf sveininum að drekka.'),
(534, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 20, 'OT', 'Guð var með sveininum, og hann óx upp, settist að í eyðimörkinni og varð bogmaður.'),
(535, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 21, 'OT', 'Hann settist að í eyðimörkinni Paran, og móðir hans tók honum konu frá jörð Egyptalands.'),
(536, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 22, 'OT', 'Á þessum tíma sagði Abímelek, ásamt Pikól, höfðingja hers hans, við Abraham: Guð er með þér í öllu sem þú gerir.'),
(537, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 23, 'OT', 'Svo sver nú við Guð að þú munir ekki svíkja mig né syni mína né barnabörn mín, heldur sýna mér þá miskunn sem ég hef sýnt þér, og þeirri jörð sem þú dvelst í.'),
(538, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 24, 'OT', 'Abraham sagði: Ég skal sverja.'),
(539, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 25, 'OT', 'Og Abraham ávítaði Abímelek vegna vatnsbrunnsins sem þjónar Abímeleks höfðu rænt.'),
(540, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 26, 'OT', 'Abímelek sagði: Ég veit ekki hver gerði þetta, og þú hefur ekki sagt mér það, og ekki heyrði ég það fyrr en í dag.'),
(541, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 27, 'OT', 'Abraham tók sauðfé og naut og gaf Abímelek, og þeir gerðu sáttmála báðir.'),
(542, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 28, 'OT', 'Abraham skipaði sjö lömbum úr sauðfénu til hliðar.'),
(543, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 29, 'OT', 'Abímelek sagði við Abraham: Hvað merkja þessi sjö lömb sem þú hefur skipað til hliðar?'),
(544, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 30, 'OT', 'Hann sagði: Þú skalt þiggja þessi sjö lömb af hendi minni, svo að þau verði mér til vitnisburðar um að ég hafi grafið þennan brunn.'),
(545, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 31, 'OT', 'Þess vegna kallaði hann þann stað Beerseba, því að þar sóru þeir báðir.'),
(546, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 32, 'OT', 'Þeir gerðu sáttmála í Beerseba. Þá reis Abímelek upp ásamt Pikól, höfðingja hers hans, og þeir sneru aftur til jarðar Filista.'),
(547, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 33, 'OT', 'Abraham gróðursetti tamarisktré í Beerseba og ákallaði þar nafn Jahve, Guðs eilífðar.'),
(548, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 21, 34, 'OT', 'Abraham dvaldist í jörð Filista um langa daga.'),
(549, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 1, 'OT', 'Eftir þessi orð reyndi Guð Abraham og sagði við hann: Abraham! Og hann svaraði: Hér er ég.'),
(550, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 2, 'OT', 'Hann sagði: Taktu son þinn, þinn eina son, sem þú elskar, Ísak, og farðu til jarðar Móríju og fórnaðu honum þar sem brennifórn á einu fjallanna sem ég mun segja þér frá.'),
(551, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 3, 'OT', 'Abraham reis árla að morgni, batt asnann sinn, tók tvo sveina sína með sér og Ísak son sinn, klauf tré til brennifórnarinnar og lagði af stað til staðarins sem Guð hafði sagt við hann.'),
(552, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 4, 'OT', 'Á þriðja degi lyfti Abraham augum sínum og sá staðinn langt í burtu.'),
(553, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 5, 'OT', 'Abraham sagði við sveina sína: Verið þið hér hjá asnanum, en ég og sveinninn förum þangað og tilbiðjum, og við munum snúa aftur til ykkar.'),
(554, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 6, 'OT', 'Abraham lagði tréð til brennifórnarinnar á Ísak son sinn, og tók í hönd sína eldinn og hnífinn, og þeir gengu báðir saman.'),
(555, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 7, 'OT', 'Ísak sagði við Abraham föður sinn: Faðir minn! Hann svaraði: Hér er ég, sonur minn. Þá sagði hann: Sjá, eldurinn og trén eru hér, en hvar er lambið til brennifórnarinnar?'),
(556, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 8, 'OT', 'Abraham svaraði: Guð mun sjá sér fyrir lambi til brennifórnar, sonur minn. Og þeir gengu báðir saman.'),
(557, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 9, 'OT', 'Þeir komu að staðnum sem Guð hafði sagt við hann. Þar reisti Abraham altari, raðaði trénu, batt Ísak son sinn og lagði hann á altarið ofan á trén.'),
(558, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 10, 'OT', 'Abraham rétti út hönd sína, tók hnífinn til að slátra syni sínum.'),
(559, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 11, 'OT', 'Þá kallaði sendiboði Jahve á hann af himni og sagði: Abraham! Abraham! Og hann svaraði: Hér er ég.'),
(560, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 12, 'OT', 'Hann sagði: Leggðu ekki hönd þína á sveininn og gerðu honum ekkert. Nú veit ég að þú óttast Guð, því að þú hefur ekki sparað son þinn, þinn eina, mér.'),
(561, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 13, 'OT', 'Abraham lyfti augum sínum og sá hrút sem var fastur í kjarrinu með hornum sínum. Abraham fór, tók hrútinn og fórnaði honum sem brennifórn í stað sonar síns.'),
(562, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 14, 'OT', 'Abraham gaf staðnum nafnið Jahve sér fyrir, eins og sagt er í dag: Á fjallinu sést Jahve.'),
(563, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 15, 'OT', 'Þá kallaði sendiboði Jahve aftur á Abraham af himni.'),
(564, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 16, 'OT', 'Hann sagði: Ég sver við sjálfan mig, segir Jahve: Af því að þú hefur gert þetta og ekki sparað son þinn, þinn eina.'),
(565, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 17, 'OT', 'Ég mun blessa þig og fjölga sæði þínu sem stjörnum himinsins og sem sandi við sjávarvörina við hafið, og sæði þitt mun erfa hlið óvina sinna.'),
(566, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 18, 'OT', 'Og allar þjóðir jarðarinnar munu blessa sig með sæði þínu sem laun fyrir að þú hlýddir rödd minni.'),
(567, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 19, 'OT', 'Abraham sneri aftur til sveina sinna, og þeir risu upp og fóru saman til Beerseba, og Abraham dvaldist í Beerseba.'),
(568, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 20, 'OT', 'Eftir þessi orð var Abraham sagt: Sjá, Milka hefur einnig alið syni Nahors bróður þíns.'),
(569, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 21, 'OT', 'Ús frumgetinn hans, og Bús bróðir hans og Kemúel faðir Arams.'),
(570, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 22, 'OT', 'Kesed, Haso, Pildas, Jidlaf og Betúel.'),
(571, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 23, 'OT', 'Betúel ól Rebekku, átta börn ól Milka Nahor bróður Abrahams.'),
(572, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 22, 24, 'OT', 'Og friðla hans, sem nafn hennar var Reúma, ól líka Teba, Gaham, Tahas og Maaka.'),
(573, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 1, 'OT', 'Líf Söru var hundrað tuttugu og sjö ár, árin sem Sara lifði.'),
(574, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 2, 'OT', 'Sara dó í Kirjat-Arba, það er Hebron, í jörð Kanaans, og Abraham kom til að syrgja Söru og gráta hana.'),
(575, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 3, 'OT', 'Abraham reis upp frá andliti hins látna og talaði við sonu Hets:'),
(576, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 4, 'OT', 'Ég er aðkomumaður og útlendingur hjá ykkur. Gefið mér eignarland í gröf hjá ykkur, svo að ég megi grafa dauðan minn frá andliti mínu.'),
(577, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 5, 'OT', 'Synir Hets svöruðu Abraham og sögðu við hann:'),
(578, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 6, 'OT', 'Heyr oss, herra. Þú ert höfðingi Guðs meðal okkar. Grafðu dauðan þinn í úrvali gröfum okkar; enginn maður okkar mun neita þér um gröf sína til að jarða dauðan þinn.'),
(579, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 7, 'OT', 'Abraham reis upp og laut fyrir lýðnum í jörðinni, sonum Hets.'),
(580, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 8, 'OT', 'Hann talaði við þá og sagði: Ef sálir ykkar vilja að ég jarði dauðan minn frá andliti mínu, hlustið þá á mig og biðjið Efron fyrir mig, son Sóhars.'),
(581, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 9, 'OT', 'Að hann gefi mér hellinn Makpela, sem hann á, sem er í enda akurs síns; fyrir fullt silfur gefi hann mér hann hjá ykkur sem eignarland til grafar.'),
(582, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 10, 'OT', 'Efron sat meðal sona Hets, og Efron Hetíti svaraði Abraham í eyrum allra sona Hets sem komu að hliði borgarinnar hans, og sagði:'),
(583, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 11, 'OT', 'Nei, herra, hlustaðu á mig: akurinn gef ég þér, og hellinn sem er á honum gef ég þér. Fyrir augum sona lýðs míns gef ég þér hann. Jarðaðu dauðan þinn.'),
(584, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 12, 'OT', 'Abraham laut fyrir andliti lýðs jarðarinnar.'),
(585, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 13, 'OT', 'Hann talaði við Efron í eyrum lýðs jarðarinnar og sagði: Ef þú vilt aðeins hlusta á mig, þá gef ég silfur fyrir akurinn: taktu það af mér, og ég mun grafa dauðan minn þar.'),
(586, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 14, 'OT', 'Efron svaraði Abraham og sagði við hann:'),
(587, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 15, 'OT', 'Herra, hlustaðu á mig. Jörðin er fjögur hundruð sikla silfurs milli mín og þín, hvað er það? Jarðaðu dauðan þinn.'),
(588, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 16, 'OT', 'Abraham hlýddi á Efron og vó fyrir Efron silfur, sem hann hafði talað um í eyrum sona Hets, fjögur hundruð sikla silfurs, gjaldgengt meðal kaupmanna.'),
(589, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 17, 'OT', 'Þannig var akur Efrons í Makpela, sem var fyrir andliti Mamre, akurinn og hellirinn sem í honum var, og öll trén á akrinum, á öllum landamærunum í kring.'),
(590, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 18, 'OT', 'Abraham fékk þetta sem kaup fyrir augum sona Hets, meðal allra sem komu að hliði borgar hans.'),
(591, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 19, 'OT', 'Eftir þetta jarðaði Abraham Söru konu sína í hellinum á akri Makpela, fyrir andliti Mamre, sem er Hebron, í jörð Kanaans.'),
(592, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 23, 20, 'OT', 'Akurinn og hellirinn sem í honum var voru þá staðfest sem eignarland Abrahams til grafar frá sonum Hets.'),
(593, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 1, 'OT', 'Abraham var orðinn gamall, kominn á efri dögum, og Jahve hafði blessað Abraham í öllu.'),
(594, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 2, 'OT', 'Abraham sagði við elsta þjón húss síns, sem stjórnaði öllu sem hann átti: Leggðu hönd þína undir lærið á mér.'),
(595, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 3, 'OT', 'Ég læt þig sverja við Jahve, Guð himinsins og Guð jarðarinnar, að þú takir ekki konu handa syni mínum af dætrum Kanaaníta, meðal þeirra sem ég bý með.'),
(596, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 4, 'OT', 'Heldur far þú til lands míns og til ættar minnar og tak konu handa syni mínum, Ísak.'),
(597, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 5, 'OT', 'Þjónninn sagði við hann: Kannski vill konan ekki fara með mér til þessarar jarðar. Á ég þá að flytja son þinn aftur til jarðarinnar sem þú fórst frá?'),
(598, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 6, 'OT', 'Abraham sagði við hann: Gættu þín að þú skalt ekki flytja son minn þangað aftur.'),
(599, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 7, 'OT', 'Jahve, Guð himinsins, sem tók mig úr húsi föður míns og af ættjörð minni, og sem talaði við mig og sór mér: Sæði þínu mun ég gefa þessa jörð. Hann mun senda sendiboða sinn á undan þér, og þú skalt taka konu handa syni mínum þaðan.'),
(600, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 8, 'OT', 'Ef konan vill ekki fara með þér, þá skaltu vera laus við eið minn, en son minn skalt þú aðeins ekki flytja þangað.'),
(601, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 9, 'OT', 'Og þjónninn lagði hönd sína undir læri Abrahams herra síns og sór honum eið um þetta mál.'),
(602, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 10, 'OT', 'Þá tók þjónninn tíu úlfalda af úlföldum herra síns og hafði með sér gæði herra síns í hendi sinni. Hann reis upp og hélt til Aram-Naharajím, til borgar Nahors.'),
(603, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 11, 'OT', 'Hann lét úlfaldana krjúpa utan borgarinnar, hjá brunninum við vatnið, um kvöld, á þeim tíma þegar konur fara út að sækja vatn.'),
(604, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 12, 'OT', 'Og hann sagði: Jahve, Guð herra míns Abrahams, lát mig í dag mæta velgengni fyrir andliti mínu og sýndu miskunn herra mínum Abraham.'),
(605, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 13, 'OT', 'Sjá, ég stend hjá vatnsauga, og dætur manna í borginni koma út til að sækja vatn.'),
(606, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 14, 'OT', 'Og sú stúlka sem ég segi við: Lækkaðu krukku þína svo að ég megi drekka, og hún svari: Drekk þú, og ég mun einnig vökva úlfalda þína. Hana hefur þú valið fyrir þjón þinn Ísak, og af því skal ég vita að þú hefur sýnt herra mínum miskunn.'),
(607, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 15, 'OT', 'Og áður en hann lauk máli sínu, sjá, þá kom Rebekka út, dóttir Betúels sonar Milku konu Nahors bróður Abrahams, með krukku sína á öxl sér.'),
(608, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 16, 'OT', 'Stúlkan var mjög fögur að útliti, mey, og enginn maður hafði kynnst henni. Hún gekk niður að vatnsauganu, fyllti krukku sína og kom upp aftur.'),
(609, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 17, 'OT', 'Þjónninn hljóp á móti henni og sagði: Gefðu mér, bið ég þig, dálítinn sopa vatns úr krukkunni þinni.'),
(610, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 18, 'OT', 'Hún sagði: Drekk, herra minn. Hún flýtti sér, lét krukku sína síga á hendi sér og gaf honum að drekka.'),
(611, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 19, 'OT', 'Þegar hún hafði lokið við að gefa honum að drekka sagði hún: Ég mun líka ausa vatni fyrir úlfalda þína, þar til þeir eru búnir að drekka.'),
(612, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 20, 'OT', 'Hún flýtti sér, hellti úr krukku sinni í trogið, hljóp aftur að brunninum til að ausa vatni og ausaði fyrir alla úlfalda hans.'),
(613, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 21, 'OT', 'Maðurinn starði á hana þegjandi til að vita hvort Jahve hefði látið veg sinn heppnast eða ekki.'),
(614, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 22, 'OT', 'Þegar úlfaldarnir voru búnir að drekka tók maðurinn gulleyrnalokk, hálfs bekah að vigt, og tvö armbönd um hendur hennar, tíu sikla gull að vigt.'),
(615, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 23, 'OT', 'Hann sagði: Dóttir hvers ertu? Segðu mér, bið ég þig, er staður í húsi föður þíns fyrir okkur til að gista á?'),
(616, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 24, 'OT', 'Hún svaraði honum: Ég er dóttir Betúels, sonar Milku, sem hún ól Nahor.'),
(617, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 25, 'OT', 'Hún sagði við hann: Hjá okkur er nóg af hálmi og skepnufóðri, og einnig staður til að gista á.'),
(618, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 26, 'OT', 'Maðurinn laut höfði og féll fram fyrir Jahve.'),
(619, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 27, 'OT', 'Hann sagði: Lofaður sé Jahve, Guð herra míns Abrahams, sem ekki hefur vanrækt miskunn sína og sannleik við herra minn. Ég var á vegi, og Jahve leiddi mig til húss bræðra herra míns.'),
(620, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 28, 'OT', 'Stúlkan hljóp og sagði frá þessum orðum í húsi móður sinnar.'),
(621, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 29, 'OT', 'Rebekka átti bróður sem hét Laban. Laban hljóp út til mannsins við vatnsauganu.'),
(622, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 30, 'OT', 'Þegar hann sá eyrnalokkinn og armböndin á höndum systur sinnar og þegar hann heyrði orð Rebekku systur sinnar, sem sagði: Svo talaði maðurinn við mig, kom hann til mannsins, og sjá, hann stóð hjá úlföldunum við vatnsauganu.'),
(623, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 31, 'OT', 'Hann sagði: Kom inn, þú sem ert blessaður af Jahve. Hvers vegna stendur þú úti? Ég hef búið húsið og stað fyrir úlfaldana.'),
(624, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 32, 'OT', 'Maðurinn kom inn í húsið og leysti úlfaldana. Hann gaf úlföldunum hálm og skepnufóður, og vatn til að þvo fætur hans og fætur mannanna sem voru með honum.'),
(625, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 33, 'OT', 'Honum var borinn matur fyrir andliti hans, en hann sagði: Ég mun ekki eta fyrr en ég hef sagt orð mín. Og hann sagði: Talaðu.'),
(626, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 34, 'OT', 'Hann sagði: Ég er þjónn Abrahams.'),
(627, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 35, 'OT', 'Jahve hefur blessað herra minn mjög mikið, og hann hefur auðgast. Hann hefur gefið honum sauðfé og naut, silfur og gull, þjóna og ambáttir, úlfalda og asna.'),
(628, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 36, 'OT', 'Sara, kona herra míns, ól herra mínum son í elli hennar, og hann gaf honum allt sem hann á.'),
(629, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 37, 'OT', 'Herra minn lét mig sverja og sagði: Þú skalt ekki taka konu handa syni mínum af dætrum Kanaanítum, í jörðinni þar sem ég bý.'),
(630, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 38, 'OT', 'Heldur skalt þú fara í hús föður míns og til ættar minnar og taka konu handa syni mínum.'),
(631, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 39, 'OT', 'Ég sagði við herra minn: Kannski mun konan ekki fylgja mér.'),
(632, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 40, 'OT', 'Hann sagði við mig: Jahve, sem ég hef gengið fyrir andliti hans, mun senda sendiboða sinn með þér og láta veg þinn heppnast, og þú skalt taka konu handa syni mínum af ætt minni og af húsi föður míns.'),
(633, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 41, 'OT', 'Þá verðurðu laus undan bölvun minni þegar þú kemur í ætt mína. Og ef þeir gefa þér hana ekki, þá verðurðu laus við bölvun mína.'),
(634, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 42, 'OT', 'Ég kom í dag við vatnsauganu og sagði: Jahve, Guð herra míns Abrahams, ef þú vilt láta veg minn heppnast, sem ég fer nú.'),
(635, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 43, 'OT', 'Sjá, ég stend hjá vatnsauga, og þegar unga konan kemur út til að sækja vatn og ég segi við hana: Lát mig fá dálítinn sopa vatns úr krukku þinni.'),
(636, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 44, 'OT', 'Og hún svarar mér: Drekk þú líka, og ég mun einnig vökva úlfalda þína. Hún er konan sem Jahve hefur valið handa syni herra míns.'),
(637, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 45, 'OT', 'Áður en ég hafði lokið við að tala í hjarta mínu, sjá, þá kom Rebekka út með krukku sína á öxl sér, fór niður að vatnsauganu og ausaði. Og ég sagði við hana: Gefðu mér að drekka, bið ég þig.'),
(638, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 46, 'OT', 'Hún flýtti sér, lét krukku sína síga af öxl sér og sagði: Drekk þú, og ég mun einnig vökva úlfalda þína. Ég drakk, og hún vökvaði líka úlfaldana.'),
(639, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 47, 'OT', 'Ég spurði hana: Dóttir hvers ert þú? Hún sagði: Ég er dóttir Betúels, sonar Nahors, sem Milka ól honum. Þá setti ég eyrnalokkinn á nef hennar og armböndin um hendur hennar.'),
(640, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 48, 'OT', 'Ég laut höfði og féll fram fyrir Jahve og lofaði Jahve, Guð herra míns Abrahams, sem leiddi mig á réttum vegi til að taka dóttur bróður herra míns handa syni hans.'),
(641, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 49, 'OT', 'Og nú, ef þér viljið sýna herra mínum miskunn og sannleik, segið mér það. Og ef ekki, segið mér það líka, svo að ég geti snúið mér til hægri handar eða vinstri handar.'),
(642, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 50, 'OT', 'Þá svöruðu Laban og Betúel: Þetta orð er frá Jahve. Við getum ekki sagt þér hvorki illt né gott.'),
(643, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 51, 'OT', 'Sjá, Rebekka er fyrir andliti þínu. Tak hana og far, og hún verði kona sonar herra þíns, eins og Jahve hefur talað.'),
(644, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 52, 'OT', 'Þegar þjónn Abrahams heyrði orð þeirra laut hann til jarðar fyrir Jahve.'),
(645, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 53, 'OT', 'Þjónninn tók fram áhöld úr silfri og gulli og klæði og gaf Rebekku. Hann gaf líka dýrgripi bróður hennar og móður hennar.'),
(646, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 54, 'OT', 'Þá átu og drukku hann og mennirnir sem voru með honum, og þeir gistu þar. Þegar þeir risu upp að morgni sagði hann: Lát mig fara til herra míns.'),
(647, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 55, 'OT', 'Bróðir hennar og móðir sögðu: Lát stúlkuna vera hjá okkur nokkra daga, eða tíu. Eftir það skaltu fara.'),
(648, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 56, 'OT', 'Hann sagði við þá: Tefjið mig ekki, því Jahve hefur látið veg minn heppnast. Sendið mig, svo að ég megi fara til herra míns.'),
(649, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 57, 'OT', 'Þeir sögðu: Við skulum kalla á stúlkuna og heyra hvað munn hennar segir.'),
(650, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 58, 'OT', 'Þeir kölluðu á Rebekku og sögðu við hana: Vilt þú fara með þessum manni? Hún sagði: Ég fer.'),
(651, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 59, 'OT', 'Þau sendu burt Rebekku, systur sína, og fóstru hennar, og þjón Abrahams og menn hans.'),
(652, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 60, 'OT', 'Þau blessuðu Rebekku og sögðu: Systir vor, megir þú verða að tíuþúsund, og sæði þitt eignist hlið óvina sinna.'),
(653, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 61, 'OT', 'Rebekka og stúlkur hennar risu upp, stigu á úlfaldana og riðu á eftir manninum. Þjónninn tók Rebekku og fór.'),
(654, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 62, 'OT', 'Ísak kom frá Beer-Lakaí-Róí, því að hann bjó í suðurlandinu.'),
(655, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 63, 'OT', 'Ísak gekk út á akurinn að kvöldi til að hugleiða. Hann lyfti augum sínum og sá úlfalda koma.'),
(656, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 64, 'OT', 'Rebekka lyfti augum sínum, og þegar hún sá Ísak, steig hún af úlfaldanum.'),
(657, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 65, 'OT', 'Hún sagði við þjóninn: Hver er maðurinn sem gengur á akrinum til móts við okkur? Þjónninn sagði: Það er herra minn. Þá tók hún blæjuna og huldi sig.'),
(658, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 66, 'OT', 'Þjónninn sagði Ísaki frá öllum orðunum sem hann hafði talað.'),
(659, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 24, 67, 'OT', 'Ísak leiddi hana inn í tjald Söru, móður sinnar, og tók Rebekku sér til konu, og hann elskaði hana. Þannig huggaðist Ísak eftir móður sína.'),
(660, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 1, 'OT', 'Abraham tók sér aðra konu, og nafn hennar var Ketúra.'),
(661, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 2, 'OT', 'Hún ól honum Símran, Jokshan, Medan, Midían, Jisbak og Súa.'),
(662, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 3, 'OT', 'Jokshan gat Séba og Dedan. Synir Dedans voru Assúrítar, Letúsím og Leúmmím.'),
(663, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 4, 'OT', 'Synir Midíans voru Efa, Efer, Enok, Abída og Eldaa. Allir þessir voru synir Ketúru.'),
(664, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 5, 'OT', 'Abraham gaf Ísaki allt sem hann átti.'),
(665, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 6, 'OT', 'En sonum friðla gaf Abraham gjafir, og meðan hann lifði sendi hann þá frá Ísaki, syni sínum, austur á bóginn, til landsins í austri.'),
(666, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 7, 'OT', 'Þetta voru dagar Abrahams, og ár lífs hans voru hundrað ár og sjötíu og fimm ár.'),
(667, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 8, 'OT', 'Abraham gaf upp andann og dó í góðri elli, með grátt hár, gamall maður og saddur daga, og var safnað til lýðs síns.'),
(668, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 9, 'OT', 'Ísak og Ísmael, synir hans, jörðuðu hann í hellinum Makpela, á akrinum Efrons, sonar Sóhars Hetíta, fyrir andliti Mamre.'),
(669, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 10, 'OT', 'Akurinn sem Abraham keypti af sonum Hets. Þar var Abraham jarðaður ásamt Söru, konu sinni.'),
(670, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 11, 'OT', 'Eftir dauða Abrahams blessaði Guð Ísak, son hans. Ísak bjó hjá brunninum Beer-Lakaí-Róí.'),
(671, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 12, 'OT', 'Þetta eru ættartölur Ísmaels, sonar Abrahams, sem Hagar Egypti, ambátt Söru, ól Abrahami.'),
(672, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 13, 'OT', 'Þetta eru nöfn sona Ísmaels, eftir nöfnum þeirra og ættartölum. Frumgetinn Ísmaels var Nebajót, síðan Kedar, Adbeel og Mibsam.'),
(673, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 14, 'OT', 'Misma, Dúma og Massa.'),
(674, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 15, 'OT', 'Hadad, Tema, Jetúr, Nafís og Kedema.'),
(675, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 16, 'OT', 'Þetta eru synir Ísmaels og þetta eru nöfn þeirra, í forgörðum þeirra og virkjum, tólf höfðingjar eftir þjóðum sínum.'),
(676, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 17, 'OT', 'Þetta eru árin sem Ísmael lifði, hundrað þrjátíu og sjö ár. Hann gaf upp andann og dó og var safnað til lýðs síns.'),
(677, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 18, 'OT', 'Þeir bjuggu frá Havílu til Súr, sem er austur af Egyptalandi í átt til Assýríu. Hann settist að fyrir andliti allra bræðra sinna.'),
(678, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 19, 'OT', 'Þetta eru ættartölur Ísaks, sonar Abrahams. Abraham gat Ísak.'),
(679, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 20, 'OT', 'Ísak var fjörutíu ára þegar hann tók sér Rebekku, dóttur Betúels Aramíta frá Paddan Aram, systur Labans Aramíta, til konu.'),
(680, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 21, 'OT', 'Ísak bað til Jahve fyrir konu sinni, því að hún var ófrjó. Jahve bænheyrði hann, og Rebekka, kona hans, varð þunguð.'),
(681, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 22, 'OT', 'Synirnir skutust hvor á annan innan í henni, og hún sagði: Ef svo er, hvers vegna er ég þá svona? Hún fór að spyrjast fyrir hjá Jahve.'),
(682, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 23, 'OT', 'Jahve sagði við hana: Tvær þjóðir eru í kviði þínum, og tvær þjóðir munu skiljast frá iðrum þínum. Ein þjóðin verður sterkari en hin, og hinn eldri mun þjóna hinum yngri.'),
(683, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 24, 'OT', 'Þegar dagar hennar voru úti til fæðingar, sjá, þá voru tvíburar í kviði hennar.'),
(684, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 25, 'OT', 'Hinn fyrri kom út rauður, allur eins og skikkja úr hári, og nafn hans var Esaú.'),
(685, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 26, 'OT', 'Síðan kom bróðir hans út, og hönd hans hélt í hæl Esaú; og nafn hans var Jakob. Ísak var sextíu ára þegar þeir fæddust.'),
(686, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 27, 'OT', 'Sveinarnir uxu upp, og Esaú varð mikill veiðimaður, maður akursins; en Jakob var rólegur maður sem bjó í tjöldum.'),
(687, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 28, 'OT', 'Ísak elskaði Esaú, því að veiði var í munni hans. En Rebekka elskaði Jakob.'),
(688, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 29, 'OT', 'Jakob var að sjóða baunasúpu, og Esaú kom úr akrinum, og hann var þreyttur.'),
(689, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 30, 'OT', 'Esaú sagði við Jakob: Gef mér, bið ég þig, af þessari rauðu, rauðu súpu, því að ég er þreyttur. Þess vegna var nafn hans kallað Edóm.'),
(690, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 31, 'OT', 'Jakob sagði: Seldu mér fyrst frumburðarréttinn þinn í dag.'),
(691, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 32, 'OT', 'Esaú sagði: Sjá, ég er við það að deyja, hvað gagnar mér þá frumburðarrétturinn?'),
(692, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 33, 'OT', 'Jakob sagði: Sverðu mér það í dag. Hann sór það og seldi Jakobi frumburðarréttinn sinn.'),
(693, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 25, 34, 'OT', 'Þá gaf Jakob Esaú brauð og linsubaunasúpu. Hann át og drakk, reis upp og fór. Þannig lítilsvirti Esaú frumburðarréttinn.'),
(694, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 1, 'OT', 'Hungursneyð kom yfir jörðina, auk fyrri hungursneyðarinnar sem varð á dögum Abrahams. Ísak fór til Abímeleks, konungs Filista, til Gerar.'),
(695, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 2, 'OT', 'Jahve birtist Ísaki og sagði: Farðu ekki til Egyptalands, heldur vertu í jörðinni sem ég segi þér.'),
(696, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 3, 'OT', 'Vertu í þessari jörðinni, og ég mun vera með þér og blessa þig, því að ég mun gefa þér og sæði þínu allar þessar jarðir, og ég mun standa við eiðinn sem ég sór Abraham, föður þínum.'),
(697, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 4, 'OT', 'Ég mun margfalda sæði þitt eins og stjörnur himinsins, og ég mun gefa sæði þínu allar þessar jarðir. Í sæði þínu munu allar þjóðir jarðarinnar blessast.'),
(698, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 5, 'OT', 'Af því að Abraham hlýddi rödd minni, gætti varðstöðu minnar, boðorð mín, lagaákvæði mín og lögmál mín.'),
(699, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 6, 'OT', 'Ísak settist að í Gerar.'),
(700, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 7, 'OT', 'Mennirnir á staðnum spurðu um konu hans, og hann sagði: Hún er systir mín, því að hann óttaðist að segja: Hún er konan mín. Rebekka var fögur að útliti, og mennirnir á staðnum gætu drepið hann vegna hennar.'),
(701, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 8, 'OT', 'Þegar dagar hans þar voru orðnir margir, leit Abímelek, konungur Filista, út um glugga og sá að Ísak var að kela við Rebekku, konu sína.'),
(702, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 9, 'OT', 'Þá kallaði Abímelek á Ísak og sagði: Sjá, hún er víst konan þín. Hvers vegna sagðir þú: Hún er systir mín? Ísak svaraði honum: Því að ég hugsaði með mér að ég gæti dáið vegna hennar.'),
(703, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 10, 'OT', 'Abímelek sagði: Hvað er þetta sem þú hefur gert okkur? Lítið hefði munað að einn af lýðnum hefði lagst með konu þinni, og þú hefðir leitt yfir okkur sök og sektarfórn.'),
(704, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 11, 'OT', 'Abímelek bauð öllum lýðnum og sagði: Hver sem snertir þennan mann eða konu hans skal deyja.'),
(705, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 12, 'OT', 'Ísak sáði í þessari jörðinni og fékk það ár hundraðfaldan ávöxt, því að Jahve blessaði hann.'),
(706, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 13, 'OT', 'Maðurinn varð ríkur, og hann óx stöðugt þar til hann varð mjög mikill.'),
(707, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 14, 'OT', 'Hann átti fénað af sauðfé og fénað af nautum, og mikið þjónustulið. Þess vegna öfunduðu Filistar hann.'),
(708, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 15, 'OT', 'Allir brunnarnir sem þjónar föður hans höfðu grafið á dögum Abrahams, föður hans, fylltu Filistar með mold.'),
(709, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 16, 'OT', 'Abímelek sagði við Ísak: Farðu burt frá okkur, því að þú ert orðinn miklu voldugri en við.'),
(710, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 17, 'OT', 'Ísak fór þaðan og settist að við lækinn í Gerar og bjó þar.'),
(711, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 18, 'OT', 'Ísak gróf aftur brunnana vatnsins sem höfðu verið grafnir á dögum Abrahams, föður síns, því að Filistar höfðu stíflað þá eftir dauða Abrahams. Og hann gaf þeim sömu nöfn og faðir hans hafði gefið þeim.'),
(712, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 19, 'OT', 'Þjónar Ísaks grófu í læknum og fundu þar brunn af lindarvatni.'),
(713, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 20, 'OT', 'Hirðar Gerar deildu við hirða Ísaks og sögðu: Vatnið er okkar. Þess vegna gaf hann brunninum nafnið Esek, því að þeir höfðu deilt við hann.'),
(714, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 21, 'OT', 'Þeir grófu annan brunn, og um hann deildu þeir líka. Hann gaf honum nafnið Sitna.'),
(715, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 22, 'OT', 'Hann flutti þaðan og gróf annan brunn, og um hann deildu þeir ekki. Hann gaf honum nafnið Rehóbót og sagði: Nú hefur Jahve veitt okkur rúm, og við munum vaxa og dafna í jörðinni.'),
(716, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 23, 'OT', 'Þaðan fór hann upp til Beerseba.'),
(717, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 24, 'OT', 'Jahve birtist honum um nóttina og sagði: Ég er Guð Abrahams, föður þíns. Óttastu ekki, því að ég er með þér. Ég mun blessa þig og margfalda sæði þitt vegna þjóns míns Abrahams.'),
(718, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 25, 'OT', 'Hann reisti þar altari og ákallaði nafn Jahve, sló þar tjald sitt, og þjónar Ísaks grófu þar brunn.'),
(719, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 26, 'OT', 'Abímelek kom til hans frá Gerar, ásamt Akússat, vini sínum, og Pikól, höfðingja hers síns.'),
(720, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 27, 'OT', 'Ísak sagði við þá: Hvers vegna komið þið til mín, úr því að þið hatið mig og hafið rekið mig frá ykkur?'),
(721, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 28, 'OT', 'Þeir sögðu: Við höfum séð að Jahve er með þér, og við sögðum: Gerum eiðsbölvun á milli okkar og gerum sáttmála við þig.'),
(722, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 29, 'OT', 'Að þú gerir ekkert illt við okkur, eins og við höfum ekki snert þig og aðeins gert þér gott og sent þig burt í friði. Þú ert nú blessaður af Jahve.'),
(723, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 30, 'OT', 'Hann hélt þeim veislu, og þeir átu og drukku.'),
(724, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 31, 'OT', 'Morguninn eftir risu þeir snemma og sóru hver öðrum eið. Síðan lét Ísak þá fara, og þeir fóru frá honum í friði.'),
(725, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 32, 'OT', 'Sama dag komu þjónar Ísaks og sögðu honum frá brunninum sem þeir höfðu grafið, og sögðu: Við höfum fundið vatn.'),
(726, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 33, 'OT', 'Hann gaf henni nafnið Sebúa, þess vegna heitir borgin Beerseba allt til þessa dags.'),
(727, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 34, 'OT', 'Esaú, sonur Ísaks, var fjörutíu ára þegar hann tók sér konu, Júdit, dóttur Beerí Hetíta, og Basmat, dóttur Elon Hetíta.'),
(728, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 26, 35, 'OT', 'Þær voru Ísaki og Rebekku mikil sorg í anda.'),
(729, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 1, 'OT', 'Þegar Ísak var orðinn gamall og augu hans dofnuðu svo að hann sá ekki, kallaði hann á Esaú, eldri son sinn, og sagði við hann: Sonur minn! Hann svaraði: Hér er ég.'),
(730, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 2, 'OT', 'Hann sagði: Sjá, ég er gamall og veit ekki dag dauða míns.'),
(731, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 3, 'OT', 'Taktu nú áhöldin þín, bogann og örvamælinn, far út á akurinn og veiddu mér vistir.'),
(732, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 4, 'OT', 'Gerðu mér kræsingar, eins og ég elska, og færðu mér þær, svo að sál mín megi blessa þig áður en ég dey.'),
(733, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 5, 'OT', 'Rebekka heyrði þegar Ísak talaði við Esaú, son sinn. Esaú fór út á akurinn til veiði og til að færa heim.'),
(734, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 6, 'OT', 'Rebekka sagði við Jakob son sinn: Ég heyrði föður þinn tala við Esaú bróður þinn og segja:'),
(735, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 7, 'OT', 'Færðu mér veiði og gerðu mér kræsingar, svo að ég megi eta og blessa þig fyrir andliti Jahve, fyrir dauða minn.'),
(736, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 8, 'OT', 'Nú, sonur minn, hlustaðu á rödd mína og gerðu eins og ég segi þér.'),
(737, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 9, 'OT', 'Farðu núna til sauðfésins og sæktu mér þaðan tvö góð kið úr geitahjörðinni, og ég mun gera þau að kræsingum handa föður þínum, eins og hann elskar.'),
(738, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 10, 'OT', 'Þú skalt færa föður þínum það, og hann skal eta það, svo að hann blessi þig fyrir andliti sínu, fyrir dauða sinn.'),
(739, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 11, 'OT', 'Jakob sagði við Rebekku, móður sína: Sjá, Esaú bróðir minn er loðinn maður, en ég er sléttur maður.'),
(740, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 12, 'OT', 'Ef faðir minn þreifar á mér, mun ég í augum hans vera sviksamur. Ég mun færa yfir mig bölvun en ekki blessun.'),
(741, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 13, 'OT', 'Móðir hans sagði við hann: Bölvun þín komi yfir mig, sonur minn. Hlýddu aðeins á rödd mína og far og sæktu þá til mín.'),
(742, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 14, 'OT', 'Hann fór, sótti þá og færði móður sinni, og móðir hans gerði kræsingar eins og faðir hans elskaði.'),
(743, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 15, 'OT', 'Rebekka tók fínustu klæðin Esaú, eldri sonar síns, sem voru í húsinu, og fékk þau Jakobi, yngri syni sínum.'),
(744, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 16, 'OT', 'Hún batt skinn geitarkiðanna um hendur hans og um hið slétta á hálsi hans.'),
(745, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 17, 'OT', 'Síðan fékk hún kræsingarnar og brauðið sem hún hafði búið til í hendur Jakobs, sonar síns.'),
(746, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 18, 'OT', 'Hann kom til föður síns og sagði: Faðir minn! Hann svaraði: Hér er ég. Hver ert þú, sonur minn?'),
(747, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 19, 'OT', 'Jakob sagði við föður sinn: Ég er Esaú, frumgetinn þinn. Ég hef gert eins og þú sagðir mér; statt upp, sestu og et af veiðinni minni, svo að sál þín megi blessa mig.'),
(748, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 20, 'OT', 'Ísak sagði við son sinn: Hvernig fannstu þetta svona fljótt, sonur minn? Hann svaraði: Jahve, Guð þinn, lét það mæta mér fyrir andliti mínu.'),
(749, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 21, 'OT', 'Ísak sagði við Jakob: Komdu nær, sonur minn, svo að ég geti þreifað á þér, hvort þú sért sonur minn Esaú eða ekki.'),
(750, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 22, 'OT', 'Jakob gekk til Ísaks, föður síns, og hann þreifaði á honum og sagði: Röddin er rödd Jakobs, en hendurnar eru hendur Esaú.'),
(751, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 23, 'OT', 'Og hann þekkti hann ekki, því að hendur hans voru loðnar eins og hendur Esaús, bróður hans, og hann blessaði hann.'),
(752, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 24, 'OT', 'Og hann sagði: Þú ert sá, sonur minn Esaú. Og hann sagði: Ég er það.'),
(753, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 25, 'OT', 'Og hann sagði: Færðu mér það, og ég vil eta af veiði sonar míns, til þess að sál mín geti blessað þig. Hann gekk nær og át, og hann bar honum vín, og hann drakk.'),
(754, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 26, 'OT', 'Og Ísak, faðir hans, sagði við hann: Komdu nær og kysstu mig, sonur minn.'),
(755, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 27, 'OT', 'Og hann gekk nær og kyssti hann. Hann fann lyktina af klæðum hans og blessaði hann og sagði: Sjá, ilmur sonar míns er eins og ilmur af akri, sem Jahve hefur blessað.'),
(756, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 28, 'OT', 'Guð gefi þér af dögg himinsins og af feitmeti jarðarinnar, og mikið korn og vín.'),
(757, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 29, 'OT', 'Lýðir skulu þjóna þér og þjóðir beygja sig fyrir þér. Vertu herra bræðra þinna, og synir móður þinnar skulu beygja sig fyrir þér. Bölvaður sé hver sem bölvar þér, og blessaður sé hver sem blessar þig.'),
(758, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 30, 'OT', 'Og svo bar við, þegar Ísak hafði lokið við að blessa Jakob, og Jakob var rétt farinn frá andliti Ísaks, föður síns, að Esaú, bróðir hans, kom heim úr veiði sinni.'),
(759, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 31, 'OT', 'Og hann gerði einnig kræsingar og bar þær til föður síns. Og hann sagði við föður sinn: Rístu upp, faðir minn, og et af veiði sonar þíns, til þess að sál þín blessi mig.'),
(760, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 32, 'OT', 'Og Ísak, faðir hans, sagði við hann: Hver ert þú? Og hann sagði: Ég er sonur þinn, frumgetinn þinn, Esaú.'),
(761, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 33, 'OT', 'Og Ísak skalf af miklum ótta, mjög mikið, og sagði: Hver er þá sá sem veiddi veiði og færði mér hana? Ég át af öllu áður en þú komst, og ég blessaði hann; já, blessaður skal hann verða.'),
(762, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 34, 'OT', 'Þegar Esaú heyrði orð föður síns, hrópaði hann upp með miklu og beisku neyðarópi og sagði við föður sinn: Blessaðu mig líka, faðir minn!'),
(763, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 35, 'OT', 'Og hann sagði: Bróðir þinn kom með svikum og tók blessun þína.'),
(764, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 36, 'OT', 'Og hann sagði: Er nafn hans ekki rétt valið, Jakob? Hann hefur tvisvar sinnum svikið mig; hann tók frumburðarrétt minn, og nú, sjá, hefur hann tekið blessun mína. Og hann sagði: Áskildir þú mér ekki blessun?'),
(765, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 37, 'OT', 'Ísak svaraði og sagði við Esaú: Sjá, ég hef gert hann að herra yfir þér og gefið honum alla bræður hans sem þjóna; korn og vín hef ég gefið honum. Hvað get ég þá gert fyrir þig, sonur minn?'),
(766, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 38, 'OT', 'Og Esaú sagði við föður sinn: Hefur þú aðeins eina blessun, faðir minn? Blessaðu mig líka, faðir minn! Og Esaú hóf upp rödd sína og grét.'),
(767, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 39, 'OT', 'Ísak, faðir hans, svaraði og sagði við hann: Sjá, bústaður þinn skal vera í feitmeti jarðarinnar og í dögg himinsins að ofan.'),
(768, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 40, 'OT', 'Af sverði þínu skaltu lifa og bróður þínum skaltu þjóna; en þegar þú brýtur þig lausan, skaltu slíta ok hans af hálsi þínum.'),
(769, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 41, 'OT', 'Esaú hataði Jakob vegna blessunarinnar, sem faðir hans hafði veitt honum, og Esaú sagði í hjarta sínu: Dagar sorgarinnar vegna föður míns eru í nánd; þá mun ég drepa Jakob, bróður minn.'),
(770, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 42, 'OT', 'Rebekka fékk fregnir af orðum Esaús, eldri sonar síns, og hún sendi eftir Jakob, yngri syni sínum, og sagði við hann: Sjá, Esaú, bróðir þinn, huggar sig við að drepa þig.'),
(771, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 43, 'OT', 'Og nú, sonur minn, hlýddu rödd minni: Rístu upp og flýðu til Labans, bróður míns, í Haran.'),
(772, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 44, 'OT', 'Og þú skalt dvelja hjá honum nokkra daga, þangað til reiði bróður þíns snýst frá þér.'),
(773, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 45, 'OT', 'Þar til reiði bróður þíns hjaðnar og hann gleymir því sem þú gerðir honum, þá læt ég sækja þig þaðan. Hvers vegna skyldi ég missa ykkur báða á einum degi?'),
(774, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 27, 46, 'OT', 'Og Rebekka sagði við Ísak: Ég er orðin leið á lífinu vegna dætra Hets. Ef Jakob tekur sér konu af dætrum Hets, slíkri sem þessar eru, af dætrum jarðarinnar, til hvers á ég þá að lifa?'),
(775, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 1, 'OT', 'Ísak kallaði á Jakob, blessaði hann og bauð honum og sagði við hann: Þú skalt ekki taka þér konu af dætrum Kanaans.'),
(776, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 2, 'OT', 'Farðu af stað, haltu til Paddan-Aram, í hús Betúels, föður móður þinnar, og taktu þér þaðan konu af dætrum Labans, bróður móður þinnar.'),
(777, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 3, 'OT', 'Almáttugur Guð blessi þig, geri þig frjósaman og margfaldi þig, svo að þú verðir að söfnuði lýða.'),
(778, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 4, 'OT', 'Og hann gefi þér blessun Abrahams, þér og sæði þínu með þér, svo að þú megir erfa jörð útlegðar þinnar, sem Guð gaf Abraham.'),
(779, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 5, 'OT', 'Ísak sendi Jakob, og hann fór til Paddan-Aram, til Labans, sonar Betúels Aramíta, bróður Rebekku, móður Jakobs og Esaús.'),
(780, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 6, 'OT', 'Esaú sá að Ísak hafði blessað Jakob og sent hann til Paddan-Aram til að taka sér þar konu, og þegar hann blessaði hann, bauð hann honum og sagði: Þú skalt ekki taka konu af dætrum Kanaans.'),
(781, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 7, 'OT', 'Jakob hlýddi föður sínum og móður sinni og fór til Paddan-Aram.'),
(782, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 8, 'OT', 'Esaú sá að dætur Kanaans voru illar í augum Ísaks, föður síns.'),
(783, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 9, 'OT', 'Esaú fór til Ísmaels og tók sér Mahalat, dóttur Ísmaels, sonar Abrahams, systur Nebajóts, til konu, auk kvenna sinna.'),
(784, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 10, 'OT', 'Og Jakob lagði af stað frá Beerseba og hélt til Haran.'),
(785, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 11, 'OT', 'Og hann kom á stað og gisti þar, því að sólin var sest. Hann tók nokkra steina af staðnum og lagði þá undir höfðalagi sínu og lagðist til svefns á þeim stað.'),
(786, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 12, 'OT', 'Og hann dreymdi, og sjá, stigi stóð á jörð, og höfuð hans náði upp til himins; og sjá, sendiboðar Guðs stigu upp og niður eftir honum.'),
(787, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 13, 'OT', 'Og sjá, Jahve stóð yfir honum og sagði: Ég er Jahve, Guð Abrahams, föður þíns, og Guð Ísaks. Jörðina, sem þú liggur á, gef ég þér og sæði þínu.'),
(788, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 14, 'OT', 'Sæði þitt skal verða eins og mold jarðarinnar, og þú munt breiðast út til hafs og austurs og norðurs og til suðurlands; og allar ættir jarðarinnar munu blessa sig í þér og í sæði þínu.'),
(789, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 15, 'OT', 'Og sjá, ég er með þér, ég mun gæta þín hvert sem þú ferð og skila þér aftur til þessarar jarðar, því að ég yfirgef þig ekki, þar til ég hef gert það sem ég hef talað um við þig.'),
(790, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 16, 'OT', 'Jakob vaknaði af svefni sínum og sagði: Sannarlega er Jahve á þessum stað, og ég vissi það ekki.'),
(791, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 17, 'OT', 'Og hann óttaðist og sagði: Hversu ógnvekjandi er þessi staður! Þetta er ekki annað en hús Guðs, og þetta er hlið himnanna.'),
(792, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 18, 'OT', 'Og Jakob reis árla að morgni, tók steininn sem hann hafði lagt undir höfðalagi sínu, reisti hann sem steinsúlu og hellti olíu yfir höfuð hennar.'),
(793, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 19, 'OT', 'Og hann gaf þessum stað nafnið Betel, en áður hét borgin Lús í upphafi.'),
(794, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 20, 'OT', 'Og Jakob strengdi heit og sagði: Ef Guð verður með mér og gætir mín á þessum vegi, sem ég fer, og gefur mér brauð að eta og klæði að klæðast,'),
(795, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 21, 'OT', 'og ég sný aftur í friði til húss föður míns, og þá skal Jahve vera Guð minn.'),
(796, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 28, 22, 'OT', 'Og þessi steinn, sem ég hef reist sem steinsúlu, skal verða hús Guðs, og af öllu sem þú gefur mér mun ég gefa þér tíund.'),
(797, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 1, 'OT', 'Þá lyfti Jakob fótum sínum og hélt áfram til jarðar sona austurs.'),
(798, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 2, 'OT', 'Og hann sá brunn á akri, og þar lágu þrjár hjarðir sauðfjár við brunninn, því að úr þeim brunni vökvuðu hjarðirnar. Steinninn á munni brunnsins var stór.'),
(799, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 3, 'OT', 'Þegar allar hjarðirnar voru þar saman komnar, veltu þær steininum af munni brunnsins og vökvuðu sauðféð, og settu steininn aftur á munn brunnsins, á sinn stað.'),
(800, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 4, 'OT', 'Og Jakob sagði við þá: Bræður mínir, hvaðan eruð þið? Og þeir sögðu: Við erum frá Haran.'),
(801, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 5, 'OT', 'Hann sagði við þá: Þekkið þið Laban, son Nahors? Og þeir sögðu: Við þekkjum hann.'),
(802, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 6, 'OT', 'Hann sagði við þá: Er friður með honum? Og þeir sögðu: Friður. Og sjá, Rakel, dóttir hans, kemur með sauðfé.'),
(803, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 7, 'OT', 'Hann sagði: Sjá, dagurinn er enn langur, og ekki er tími til að safna fénaðinum saman. Vökvið sauðféð og farið og beitið.'),
(804, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 8, 'OT', 'Þeir sögðu: Við getum ekki, fyrr en allar hjarðirnar eru komnar saman og þeir hafa velt steininum af munni brunnsins; þá vökvum við sauðféð.'),
(805, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 9, 'OT', 'Enn var hann að tala við þá, þegar Rakel kom með sauðféð sem tilheyrði föður hennar, því að hún var hirðir.'),
(806, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 10, 'OT', 'Og svo bar við, þegar Jakob sá Rakel, dóttur Labans, bróður móður sinnar, og sauðfé Labans, bróður móður sinnar, að Jakob gekk fram, velti steininum af munni brunnsins og vökvaði sauðfé Labans, bróður móður sinnar.'),
(807, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 11, 'OT', 'Og Jakob kyssti Rakel, hóf upp rödd sína og grét.'),
(808, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 12, 'OT', 'Og Jakob sagði Rakel, að hann væri bróðir föður hennar og sonur Rebekku; og hún hljóp og sagði föður sínum tíðindin.'),
(809, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 13, 'OT', 'Þegar Laban heyrði orðróminn um Jakob, son systur sinnar, hljóp hann á móti honum, faðmaði hann og kyssti og leiddi hann inn í hús sitt. Og hann sagði Laban öll þessi orð.'),
(810, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 14, 'OT', 'Þá sagði Laban við hann: Þú ert sannarlega bein mitt og hold mitt. Og hann dvaldist hjá honum í heilan mánuð daga.'),
(811, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 15, 'OT', 'Og Laban sagði við Jakob: Af því að þú ert bróðir minn, áttu þá að þjóna mér ókeypis? Seg mér, hver skulu laun þín vera?'),
(812, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 16, 'OT', 'Labans átti tvær dætur. Nafn hinnar eldri var Lea, og nafn hinnar yngri var Rakel.'),
(813, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 17, 'OT', 'Augu Leu voru döpur, en Rakel var fögur á vaxtarlagi og fríð á útliti.'),
(814, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 18, 'OT', 'Og Jakob elskaði Rakel og sagði: Ég skal þjóna þér í sjö ár fyrir Rakel, dóttur þína, þá yngri.'),
(815, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 19, 'OT', 'Og Laban sagði: Betra er að ég gefi hana þér en að ég gefi hana öðrum manni. Vertu hjá mér.'),
(816, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 20, 'OT', 'Og Jakob þjónaði fyrir Rakel í sjö ár, og þau voru í augum hans eins og fáeinir dagar vegna elsku hans til hennar.'),
(817, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 21, 'OT', 'Og Jakob sagði við Laban: Gef mér konu mína, því að dagar mínir eru fullnaðir, og ég vil ganga inn til hennar.'),
(818, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 22, 'OT', 'Og Laban safnaði saman öllum mönnunum á staðnum og hélt veislu.'),
(819, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 23, 'OT', 'Þegar kvöld var komið, tók hann Leu, dóttur sína, og leiddi hana til hans; og hann gekk inn til hennar.'),
(820, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 24, 'OT', 'Og Laban gaf henni Silpa, ambátt sína, sem ambátt handa Leu, dóttur sinni.'),
(821, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 25, 'OT', 'Þegar morguninn kom, sjá, þá var það Lea! Og hann sagði við Laban: Hvað er þetta sem þú hefur gert mér? Þjónaði ég þér ekki fyrir Rakel? Hvers vegna hefur þú svikið mig?'),
(822, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 26, 'OT', 'Og Laban sagði: Það er ekki svo gert á okkar stað, að gefa þá yngri á undan frumgetinni dóttur.'),
(823, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 27, 'OT', 'Ljúktu við þessa viku, og þá munum við gefa þér hina líka í þjónustu, sem þú vinnur fyrir mig enn í sjö ár önnur.'),
(824, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 28, 'OT', 'Og Jakob gerði svo, og hann lauk við þessa viku, og Laban gaf honum Rakel, dóttur sína, sem konu.'),
(825, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 29, 'OT', 'Og Laban gaf Rakel, dóttur sinni, Bilha, ambátt sína, til að þjóna henni sem ambátt.'),
(826, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 30, 'OT', 'Og hann gekk einnig inn til Rakelar, og hann elskaði Rakel líka meira en Leu; og hann þjónaði með honum enn í sjö ár önnur.'),
(827, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 31, 'OT', 'Og Jahve sá að Lea var hötuð, og hann opnaði móðurlíf hennar, en Rakel var ófrjó.'),
(828, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 32, 'OT', 'Og Lea varð þunguð og fæddi son, og hún gaf honum nafnið Rúben, því að hún sagði: Jahve hefur litið á eymd mína, því að nú mun maðurinn minn elska mig.'),
(829, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 33, 'OT', 'Og hún varð aftur þunguð og fæddi son, og hún sagði: Því að Jahve heyrði að ég var hötuð, hefur hann gefið mér þennan líka. Og hún gaf honum nafnið Símeon.'),
(830, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 34, 'OT', 'Og hún varð þunguð enn og fæddi son, og hún sagði: Nú í þetta sinn mun maðurinn minn tengjast mér, því að ég hef fætt honum þrjá sonu. Þess vegna gaf hún honum nafnið Leví.'),
(831, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 29, 35, 'OT', 'Og hún varð þunguð enn og fæddi son, og hún sagði: Í þetta sinn vil ég lofa Jahve. Þess vegna gaf hún honum nafnið Júda, og hún hætti að eignast börn.'),
(832, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 1, 'OT', 'Þegar Rakel sá að hún hafði ekki fætt Jakob nein börn, öfundaði Rakel systur sína og sagði við Jakob: Gefðu mér sonu, ella dey ég.'),
(833, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 2, 'OT', 'Þá reiddist Jakob Rakel og sagði: Er ég í stað Guðs, sem hefur haldið frá þér ávöxt kviðarins?'),
(834, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 3, 'OT', 'Og hún sagði: Sjá, ambátt mín Bilha; gakktu inn til hennar, og hún mun fæða á hnjám mínum, og fyrir hennar tilstilli mun ég líka eignast börn.'),
(835, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 4, 'OT', 'Og hún gaf honum Bilha, ambátt sína, til konu; og Jakob gekk inn til hennar.'),
(836, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 5, 'OT', 'Og Bilha varð þunguð og fæddi Jakobi son.'),
(837, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 6, 'OT', 'Og Rakel sagði: Guð hefur dæmt mig, og hann heyrði líka rödd mína og gaf mér son. Þess vegna gaf hún honum nafnið Dan.'),
(838, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 7, 'OT', 'Og Bilha, ambátt Rakelar, varð aftur þunguð og fæddi Jakobi annan son.'),
(839, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 8, 'OT', 'Og Rakel sagði: Guð hefur háð mikla glímu við mig, ég hef glímt við systur mína og unnið; og hún gaf honum nafnið Naftalí.'),
(840, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 9, 'OT', 'Þegar Lea sá að hún hafði hætt að eignast börn, tók hún Silpa, ambátt sína, og gaf hana Jakobi til konu.'),
(841, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 10, 'OT', 'Og Silpa, ambátt Leu, fæddi Jakobi son.'),
(842, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 11, 'OT', 'Og Lea sagði: Flokkur kemur! Og hún gaf honum nafnið Gað.'),
(843, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 12, 'OT', 'Og Silpa, ambátt Leu, fæddi Jakobi annan son.'),
(844, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 13, 'OT', 'Og Lea sagði: Ég er sæl, því að dætur munu kalla mig sæla; og hún gaf honum nafnið Asser.'),
(845, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 14, 'OT', 'Á dögum hveitiuppskerunnar fór Rúben út og fann ástarepli á akrinum og færði þau Leu, móður sinni. Þá sagði Rakel við Leu: Gefðu mér af ástareplum sonar þíns.'),
(846, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 15, 'OT', 'Og hún sagði við hana: Er það lítið, að þú hafir tekið manninn minn? Og þú vilt líka taka ástareplin af syni mínum? Þá sagði Rakel: Hann skal sofa hjá þér þessa nótt í stað ástareplanna sonar þíns.'),
(847, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 16, 'OT', 'Þegar Jakob kom af akrinum um kvöldið, gekk Lea út til móts við hann og sagði: Þú skalt koma inn til mín, því að ég hef leigt þig fyrir ástareplin sonar míns. Og hann svaf hjá henni þá nótt.'),
(848, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 17, 'OT', 'Og Guð bænheyrði Leu, og hún varð þunguð og fæddi Jakobi fimmta soninn.'),
(849, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 18, 'OT', 'Og Lea sagði: Guð hefur gefið mér laun mín, því að ég gaf ambátt mína manni mínum; og hún gaf honum nafnið Íssakar.'),
(850, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 19, 'OT', 'Og Lea varð þunguð enn og fæddi Jakobi sjötta son.'),
(851, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 20, 'OT', 'Og Lea sagði: Guð hefur gefið mér góða brúðargjöf; í þetta sinn mun maðurinn minn búa hjá mér, því að ég hef fætt honum sex sonu. Og hún gaf honum nafnið Sebúlon.'),
(852, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 21, 'OT', 'Eftir það fæddi hún dóttur og gaf henni nafnið Dína.'),
(853, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 22, 'OT', 'Og Guð minntist Rakelar, og Guð heyrði hana og opnaði móðurlíf hennar.'),
(854, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 23, 'OT', 'Og hún varð þunguð og fæddi son og sagði: Guð hefur tekið burt svívirðingu mína.'),
(855, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 24, 'OT', 'Og hún gaf honum nafnið Jósef og sagði: Jahve gefi mér annan son.'),
(856, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 25, 'OT', 'Og svo bar við, þegar Rakel hafði fætt Jósef, að Jakob sagði við Laban: Lát mig fara, svo að ég fari heim til staðar míns og til jarðar minnar.'),
(857, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 26, 'OT', 'Gef mér konur mínar og drengi mína, sem ég hef þjónað þér fyrir, og lát mig fara; því að þú veist hvaða þjónustu ég hef veitt þér.'),
(858, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 27, 'OT', 'Og Laban sagði við hann: Ef ég hef fundið hylli í augum þínum, þá hef ég fengið fyrirboða, og Jahve hefur blessað mig vegna þín.'),
(859, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 28, 'OT', 'Og hann sagði: Nefndu laun þín við mig, og ég skal gefa þau.'),
(860, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 29, 'OT', 'Og hann sagði við hann: Þú veist hvernig ég hef þjónað þér og hvernig fénaður þinn hefur verið hjá mér.'),
(861, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 30, 'OT', 'Því að lítið var það sem þú áttir fyrir andliti mínu, en það hefur vaxið mjög mikið, og Jahve hefur blessað þig á fæti mínum. Og nú, hvenær á ég líka að sjá fyrir mínu eigin húsi?'),
(862, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 31, 'OT', 'Og hann sagði: Hvað á ég að gefa þér? Og Jakob sagði: Þú skalt alls ekki gefa mér neitt; ef þú gerir mér þetta orð, mun ég aftur gæta sauðfjár þíns og varðveita það.'),
(863, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 32, 'OT', 'Ég vil fara um allt sauðfé þitt þennan dag og taka þaðan hvert flekkótt og deplótt lamb, og hvert svart meðal lamba, og hvert flekkótt og deplótt meðal geita; og það skal vera laun mín.'),
(864, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 33, 'OT', 'Og réttlæti mitt mun bera vitni fyrir mig á morgundegi, þegar þú kemur til að skoða laun mín fyrir andliti þínu. Hvert það sem er ekki flekkótt og deplótt meðal geita og svart meðal lamba, það er stolið hjá mér.'),
(865, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 34, 'OT', 'Og Laban sagði: Já, látum það vera eftir orði þínu.'),
(866, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 35, 'OT', 'Og hann skildi þann dag frá flekkótta og deplótta geithafra, og allar flekkóttu og deplóttu geiturnar, og hvert svart lamb, og fékk þau í hendur sona sinna.'),
(867, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 36, 'OT', 'Og hann setti þriggja daga veg á milli sín og Jakobs, og Jakob gætti sauðfjár Labans, sem eftir var.'),
(868, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 37, 'OT', 'Og Jakob tók sér grænan staf úr ösp, heslihnetu og kastaníutré, og hann gerði í þeim hvít skarð og afhjúpaði hvítu hluti stafanna.'),
(869, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 38, 'OT', 'Og hann setti stafina, sem hann hafði flekkað, í rennibrautir í trogum vatnsins, þar sem sauðféð kom til að drekka, og þegar þær komu til að drekka, urðu þær þungaðar.'),
(870, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 39, 'OT', 'Og sauðféð varð þungt við stafina, og sauðféð fæddi flekkótt, deplótt og röndótt lömb.'),
(871, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 40, 'OT', 'Og lömbin skildi Jakob frá, og hann sneri andliti sauðfjárins að röndóttu og svörtu hjörðinni af fé Labans; og hann setti sína eigin hjörð sérstaklega og blandaði henni ekki saman við fé Labans.'),
(872, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 41, 'OT', 'Og það varð, þegar sauðféð var í hita, að Jakob setti stafina fyrir augum sauðfjárins í rennibrautum, til þess að það yrði þungað við stafina.'),
(873, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 42, 'OT', 'En þegar sauðféð var veikburða, setti hann þá ekki þar; og veiklulegu dýrin urðu Labans, en þau hraustu urðu Jakobs.'),
(874, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 30, 43, 'OT', 'Og maðurinn varð mjög ríkur; hann eignaðist mikið sauðfé, ambáttir, þjóna, úlfalda og asna.'),
(875, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 1, 'OT', 'Og hann heyrði orð sona Labans, sem sögðu: Jakob hefur tekið allt, sem var föður vors; og af því, sem var föður vors, hefur hann aflað sér allrar þessarar dýrðar.'),
(876, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 2, 'OT', 'Og Jakob sá andlit Labans, og sjá, hann var ekki lengur með honum eins og í gær og fyrradag.'),
(877, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 3, 'OT', 'Og Jahve sagði við Jakob: Snúðu aftur til jarðar feðra þinna og til ættar þinnar, og ég mun vera með þér.'),
(878, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 4, 'OT', 'Og Jakob sendi boð og kallaði á Rakel og Leu út á akur til sauðfjár síns.'),
(879, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 5, 'OT', 'Og hann sagði við þær: Ég sé andlit föður ykkar, að það er ekki lengur við mig eins og í gær og fyrradag; en Guð föður míns hefur verið með mér.'),
(880, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 6, 'OT', 'Og þið vitið sjálfar, að ég hef þjónað föður ykkar af öllum mínum krafti.'),
(881, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 7, 'OT', 'Faðir ykkar hefur blekkt mig og breytt launum mínum tíu skipti; en Guð leyfði honum ekki að gera mér illt.'),
(882, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 8, 'OT', 'Ef hann sagði: Flekkótt skulu vera laun þín, þá báru allt sauðféð flekkótt lömb; og ef hann sagði: Röndótt skulu vera laun þín, þá báru þau röndótt lömb.'),
(883, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 9, 'OT', 'Og Guð tók fénað föður ykkar og gaf mér hann.'),
(884, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 10, 'OT', 'Og svo bar við á þeim tíma, þegar sauðféð var í hita, að ég lyfti augum mínum og sá í draumi; og sjá, hafrarnir sem stukku á sauðféð voru röndóttir, flekkóttir og deplóttir.'),
(885, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 11, 'OT', 'Og sendiboði Guðs sagði við mig í draumi: Jakob! Og ég sagði: Hér er ég.'),
(886, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 12, 'OT', 'Og hann sagði: Lyftu augum þínum og sjá: Allir hafrarnir sem stukku á sauðféð eru röndóttir, flekkóttir og deplóttir, því að ég hef séð allt sem Laban gerir þér.'),
(887, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 13, 'OT', 'Ég er Guð Betels, þar sem þú smurðir steinsúlu og strengdir mér heit; nú skalt þú rísa, fara út úr þessari jörð og snúa aftur til jarðar ættar þinnar.'),
(888, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 14, 'OT', 'Og Rakel og Lea svöruðu honum: Eigum við enn hlut og arfleifð í húsi föður okkar?'),
(889, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 15, 'OT', 'Teljum við ekki sem útlendingar af honum? Því að hann hefur selt okkur, og hann hefur líka etið upp silfur okkar.'),
(890, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 16, 'OT', 'Því að auðurinn, sem Guð hefur tekið frá föður okkar, er okkar og sona okkar; og nú, gerðu allt sem Guð hefur sagt þér.'),
(891, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 17, 'OT', 'Og Jakob reis upp, setti sonu sína og konur sínar á úlfalda.'),
(892, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 18, 'OT', 'Og hann flutti allan fénað sinn og allar eignir sínar, sem hann hafði aflað í Paddan-Aram, til að fara til Ísaks, föður síns, til jarðar Kanaans.'),
(893, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 19, 'OT', 'Og Laban var farinn til að klippa sauðfé sitt, og Rakel stal húsgoðin föður síns.'),
(894, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 20, 'OT', 'Og Jakob stal hjarta Labans Aramíta, án þess að segja honum að hann væri á flótta.'),
(895, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 21, 'OT', 'Og hann flúði og allt sem hann átti; hann reis upp, fór yfir fljótið og sneri andliti sínu til fjallsins Gíleaðs.'),
(896, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 22, 'OT', 'Og Laban var sagt á þriðja degi, að Jakob væri flúinn.'),
(897, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 23, 'OT', 'Og hann tók bræður sína með sér og elti hann sjö daga veg, og náði honum á fjallinu Gíleaðs.'),
(898, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 24, 'OT', 'Og Guð kom til Labans Aramíta í draumi um nóttina og sagði við hann: Varaðu þig, að þú talir ekki við Jakob, hvorki gott né illt.'),
(899, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 25, 'OT', 'Og Laban náði Jakob; Jakob hafði slegið upp tjaldi sínu á fjallinu, og Laban sló upp tjaldi með bræðrum sínum á fjallinu Gíleaðs.'),
(900, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 26, 'OT', 'Og Laban sagði við Jakob: Hvað hefur þú gert? Þú hefur blekkt mig og leitt dætur mínar burt eins og fanga sverðs.'),
(901, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 27, 'OT', 'Hvers vegna flýðir þú í laumi og stalst frá mér, og sagðir mér ekki frá? Ég lét þig fara með gleði, með söng, með bumbu og hörpu.'),
(902, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 28, 'OT', 'Og þú leyfðir mér ekki að kyssa sonu mína og dætur mínar. Nú hefur þú heimskulega aðhafst.'),
(903, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 29, 'OT', 'Í hendi minni er vald til að gera ykkur illt, en Guð föður ykkar talaði við mig í gærkvöldi og sagði: Varaðu þig á að tala við Jakob, hvort sem er gott eða illt.'),
(904, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 30, 'OT', 'Og nú fórst þú, því að þú þráðir mjög að komast heim til húss föður þíns. Hvers vegna stalst þú Guð minn?'),
(905, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 31, 'OT', 'Jakob svaraði og sagði við Laban: Ég óttaðist, því ég hugsaði: Þú myndir ræna dætur þínar frá mér.'),
(906, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 32, 'OT', 'Hvern sem þú finnur með guði þína, sá skal ekki lifa. Frammi fyrir bræðrum okkar skalt þú kanna hvað hjá mér er þitt og taka það. En Jakob vissi ekki að Rakel hafði stolið þeim.'),
(907, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 33, 'OT', 'Laban gekk inn í tjald Jakobs, í tjald Leu og í tjald ambáttanna tveggja, en fann ekki. Hann fór út úr tjaldi Leu og gekk inn í tjald Rakelar.'),
(908, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 34, 'OT', 'Rakel hafði tekið húsgoðin og komið þeim fyrir í hnakkinum á úlfaldanum og sest ofan á þau. Laban þreifaði um allt tjaldið og fann ekki.'),
(909, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 35, 'OT', 'Hún sagði við föður sinn: Vertu ekki reiður í augum herra míns, því að ég get ekki risið upp fyrir andliti þínu, því að ég er á tíðum kvenna. Hann leitaði, en fann ekki húsgoðin.'),
(910, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 36, 'OT', 'Jakob varð reiður við Laban og deildi við hann. Jakob svaraði og sagði við Laban: Hvert er afbrot mitt, hver er synd mín, að þú hefur elt mig uppi?'),
(911, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 37, 'OT', 'Þú hefur þreifað öll áhöld mín. Hvað hefurðu fundið af áhöldum húss þíns? Legðu það hér frammi fyrir bræðrum mínum og bræðrum þínum, og þeir skulu dæma milli okkar tveggja.'),
(912, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 38, 'OT', 'Tuttugu ár hef ég verið hjá þér. Ærnar þínar og geiturnar þínar köstuðu ekki, og hrúta sauðfjár þinnar át ég ekki.'),
(913, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 39, 'OT', 'Rifið dýr færði ég þér ekki; ég bar tjónið sjálfur. Af hendi minni kræfðir þú það, hvort sem stolið var um dag eða stolið var um nótt.'),
(914, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 40, 'OT', 'Um daginn át mig þurrkurinn, og um nóttina ísinn, og svefn minn flúði frá augum mínum.'),
(915, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 41, 'OT', 'Þessi tuttugu ár hef ég verið í húsi þínu. Ég þjónaði þér fjórtán ár fyrir dætur þínar tvær og sex ár fyrir sauðfé þitt, og þú breyttir launum mínum í tíu skipti.'),
(916, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 42, 'OT', 'Ef Guð föður míns, Guð Abrahams og ótti Ísaks hefði ekki verið með mér, þá hefðir þú sent mig tómhentan núna. Guð sá eymd mína og strit handa minna, og hann ávítaði þig í gærkvöldi.'),
(917, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 43, 'OT', 'Laban svaraði og sagði við Jakob: Dæturnar eru dætur mínar, synirnir eru synir mínir, sauðféð er sauðfé mitt og allt sem þú sérð er mitt. Hvað get ég gert þeim í dag, eða sonum þeirra sem þær hafa fætt?'),
(918, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 44, 'OT', 'Og nú, komdu, gerum sáttmála, ég og þú, og hann skal vera vottur milli mín og þín.'),
(919, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 45, 'OT', 'Jakob tók stein og reisti hann upp sem steinsúlu.'),
(920, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 46, 'OT', 'Jakob sagði við bræður sína: Safnið steina. Þeir tóku steina og gerðu öldu, og þeir átu þar á öldunni.'),
(921, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 47, 'OT', 'Laban kallaði það Jegar-Sahadúta, en Jakob kallaði það Gíleað.'),
(922, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 48, 'OT', 'Laban sagði: Þessi alda er vottur milli mín og þín í dag. Þess vegna kallaði hann nafn hennar Gíleað.'),
(923, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 49, 'OT', 'Og Mispa, þar sem hann sagði: Jahve vaki milli mín og þín, þegar hver maður er frá náunga sínum.'),
(924, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 50, 'OT', 'Ef þú kúgar dætur mínar og ef þú tekur konur fram yfir dætur mínar, og enginn maður er með okkur, sjáðu: Guð er vottur milli mín og þín.'),
(925, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 51, 'OT', 'Laban sagði við Jakob: Sjáðu þessa öldu og þessa steinsúlu, sem ég hef reist milli mín og þín.'),
(926, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 52, 'OT', 'Þessi alda er vottur og þessi steinsúla er vitnisburður: Ég mun ekki fara yfir öldu þessa til þín, og þú skalt ekki fara yfir öldu þessa og steinsúlu þessa til mín til illsku.'),
(927, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 53, 'OT', 'Guð Abrahams og Guð Nahors dæmi milli okkar, Guð föður þeirra. Og Jakob sór við ótta föður síns Ísaks.'),
(928, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 54, 'OT', 'Jakob fórnaði sláturfórn á fjallinu og kallaði á bræður sína að eta brauð. Þeir átu brauð og gistu á fjallinu.'),
(929, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 31, 55, 'OT', 'Laban reis árla morguns, kyssti sonu sína og dætur sínar og blessaði þau. Síðan fór Laban og sneri aftur á stað sinn.'),
(930, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 1, 'OT', 'Jakob hélt áfram veg sinn, og sendiboðar Guðs mættu honum.'),
(931, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 2, 'OT', 'Þegar Jakob sá þá, sagði hann: Þetta eru herbúðir Guðs. Og hann kallaði nafn staðarins Mahanaím.'),
(932, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 3, 'OT', 'Jakob sendi sendiboða á undan sér til Esaús bróður síns, til jarðar Seírs, akurs Edóms.'),
(933, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 4, 'OT', 'Hann bauð þeim og sagði: Svo skuluð þið segja herra mínum Esaú: Svo segir þjónn þinn Jakob: Hjá Laban hef ég dvalið og tafist til þessa.'),
(934, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 5, 'OT', 'Ég á naut og asna, sauðfé, þjón og ambátt. Ég sendi boð til að segja herra mínum, til að finna hylli í augum þínum.'),
(935, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 6, 'OT', 'Sendiboðarnir sneru aftur til Jakobs og sögðu: Við komum til bróður þíns, Esaús, og hann er líka á leiðinni til móts við þig, og fjögur hundruð manna með honum.'),
(936, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 7, 'OT', 'Jakob óttaðist mjög og varð hræddur. Hann skipti lýðnum, sem var með honum, og sauðféð, nautið og úlfaldana í tvennar herbúðir.'),
(937, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 8, 'OT', 'Og hann sagði: Ef Esaú kemur að fyrri herbúðunum og slær þær, þá munu herbúðirnar sem eftir verða, þær munu ná undankomu.'),
(938, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 9, 'OT', 'Jakob sagði: Guð föður míns Abrahams og Guð föður míns Ísaks, Jahve, sem sagði við mig: Snú aftur til jarðar þinnar og til ættar þinnar, og ég mun gera þér gott.'),
(939, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 10, 'OT', 'Ég er of lítill fyrir alla miskunnina og allan sannleikann sem þú hefur sýnt þjóni þínum, því með staf mínum fór ég yfir þennan Jórdan, og nú er ég orðinn tvennar herbúðir.'),
(940, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 11, 'OT', 'Frelsaðu mig, ég bið þig, úr hendi bróður míns, úr hendi Esaús, því ég óttast hann, að hann komi og slái mig og móður ásamt sonum.'),
(941, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 12, 'OT', 'Og þú sagðir: Ég mun gera þér gott, og ég mun gera sæði þitt eins og sand hafsins, sem ekki verður talið fyrir mergð.'),
(942, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 13, 'OT', 'Hann gisti þar þessa nótt og tók af því, sem hann hafði í hendi sér, fórn handa Esaú bróður sínum.'),
(943, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 14, 'OT', 'Tvö hundruð geitur og tuttugu geithafrar, tvö hundruð ær og tuttugu hrútar.'),
(944, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 15, 'OT', 'Þrjátíu mjólkandi úlfaldar ásamt afkvæmum sínum, fjörutíu kýr og tíu ungnaut, tuttugu ösnur og tíu asnafolöld.'),
(945, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 16, 'OT', 'Hann fékk þjónum sínum í hendur hverja hjörð út af fyrir sig, og sagði við þjóna sína: Farið á undan mér og hafið bil á milli hjarða.'),
(946, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 17, 'OT', 'Hann bauð þeim fremsta og sagði: Þegar Esaú bróðir minn mætir þér og spyr þig: Hverjum tilheyrir þú, og hvert ferðu, og hverjum tilheyra þessir frammi fyrir andliti þínu?'),
(947, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 18, 'OT', 'Þá skaltu segja þjóni þínum Jakobi: Þetta er fórn send herra mínum Esaú, og sjá, hann er líka á eftir okkur.'),
(948, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 19, 'OT', 'Hann bauð líka öðrum og þriðja, og öllum sem gengu á eftir hjörðunum, og sagði: Með þessum orðum skuluð þið tala við Esaú, þegar þið finnið hann.'),
(949, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 20, 'OT', 'Og þið skuluð segja: Sjá, þjónn þinn Jakob er líka á eftir okkur. Því hann hugsaði: Ég mun sefa reiði hans með fórninni sem fer á undan mér, og síðan mun ég sjá andlit hans. Kannski tekur hann vel á móti mér.'),
(950, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 21, 'OT', 'Fórnin fór fram fyrir andlit hans, en hann gisti þessa nótt í herbúðunum.'),
(951, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 22, 'OT', 'Um nóttina tók hann konur sínar, ambáttirnar sínar og drengi sína tvo og fór yfir vaðið Jabbok.'),
(952, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 23, 'OT', 'Hann tók þá og lét þá fara yfir lækinn, og lét fara yfir það sem hann átti.'),
(953, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 24, 'OT', 'Jakob varð einn eftir, og maður glímdi við hann til dögunar.'),
(954, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 25, 'OT', 'Þegar hann sá að hann réð ekki við hann, snerti hann liðinn í læri Jakobs, svo að læri Jakobs gekk úr liði í glímunni við hann.'),
(955, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 26, 'OT', 'Hann sagði: Slepptu mér, því að dögunin er komin. Hann svaraði: Ég slepp þér ekki nema þú blessir mig.'),
(956, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 27, 'OT', 'Hann sagði: Hvert er nafn þitt? Hann svaraði: Jakob.'),
(957, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 28, 'OT', 'Nafn þitt skal ekki framar kallast Jakob, heldur Ísrael, því þú hefur barist við Guð og menn og sigrað.'),
(958, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 29, 'OT', 'Jakob spurði: Seg mér nafn þitt. Hann svaraði: Hvers vegna spyrð þú um nafn mitt? Og hann blessaði hann þar.'),
(959, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 30, 'OT', 'Jakob kallaði staðinn Penúel: Því ég sá Guð augliti til auglitis, og sál mín var frelsuð.'),
(960, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 31, 'OT', 'Sólin rann upp fyrir honum, þegar hann fór fram hjá Penúel, og hann haltraði á læri sínu.'),
(961, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 32, 32, 'OT', 'Þess vegna eta synir Ísraels ekki sinina, sem er á læri, allt til þessa dags, því hann snerti læri Jakobs á sininni.'),
(962, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 1, 'OT', 'Jakob lyfti augunum, og sjá, Esaú kom, og með honum voru fjögur hundruð manna. Hann skipti drengjunum milli Leu, Rakelar og ambáttanna tveggja.'),
(963, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 2, 'OT', 'Hann setti ambáttirnar og drengi þeirra fremst, Leu og drengi hennar þar næst, og Rakel og Jósef síðast.'),
(964, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 3, 'OT', 'Hann gekk sjálfur fram fyrir andliti þeirra og laut til jarðar sjö sinnum, þar til hann kom að bróður sínum.'),
(965, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 4, 'OT', 'Esaú hljóp á móti honum, faðmaði hann, féll um háls hans og kyssti hann, og þeir grétu.'),
(966, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 5, 'OT', 'Hann lyfti augunum og sá konurnar og drengina og sagði: Hverjir eru þessir með þér? Hann svaraði: Drengirnir, sem Guð hefur gefið þjóni þínum.'),
(967, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 6, 'OT', 'Þá gengu ambáttirnar fram með drengi sína og lutu.'),
(968, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 7, 'OT', 'Lea gekk fram með drengi sína og laut, og síðan gengu Jósef og Rakel fram og lutu.'),
(969, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 8, 'OT', 'Hann sagði: Hvað átt þú með allar þessar herbúðir, sem ég mætti? Hann svaraði: Til að finna hylli í augum herra míns.'),
(970, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 9, 'OT', 'Esaú sagði: Ég á nóg, bróðir minn. Það sem þú átt, sé þitt.'),
(971, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 10, 'OT', 'Jakob sagði: Nei, ef ég hef fundið hylli í augum þínum, þá taktu fórnina mína úr hendi minni, því ég hef séð andlit þitt eins og maður sér andlit Guðs, og þú tókst mér vel.'),
(972, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 11, 'OT', 'Taktu blessunina mína, sem hefur verið færð þér, því Guð hefur sýnt mér náð, og ég á allt.'),
(973, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 12, 'OT', 'Hann sagði: Förum af stað og höldum áfram, og ég mun fara á undan þér.'),
(974, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 13, 'OT', 'Hann sagði við hann: Herra minn veit að drengirnir eru veikburða, og sauðféð og nautin með ungum eru hjá mér; ef þeim verður þrengt einn dag, deyr allt sauðféð.'),
(975, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 14, 'OT', 'Herra minn fari á undan þjóni sínum, og ég fari hægt á eftir, í takt við starfsins, og eftir fótum drengjanna, þar til ég kem til herra míns í Seír.'),
(976, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 15, 'OT', 'Esaú sagði: Ég vil skilja eftir hjá þér nokkra af lýðnum sem er með mér. Hann sagði: Hvers vegna þarf það? Láttu mig finna hylli í augum herra míns.'),
(977, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 16, 'OT', 'Esaú sneri aftur þann dag á veg sinn til Seír.'),
(978, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 17, 'OT', 'Jakob hélt til Súkkót, reisti sér hús og gerði fénaði sínum laufskála. Þess vegna kallaði hann nafn staðarins Súkkót.'),
(979, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 18, 'OT', 'Jakob kom heill til borgarinnar Síkem í Kanaanslandi, þegar hann kom frá Paddan Aram, og tjaldaði fyrir andliti borgarinnar.'),
(980, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 19, 'OT', 'Hann keypti landspildu, þar sem hann hafði tjald sitt, af hendi sona Hemors, föður Síkems, fyrir hundrað silfurpeninga.'),
(981, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 33, 20, 'OT', 'Hann reisti þar altari og kallaði það Guð, Guð Ísraels.'),
(982, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 1, 'OT', 'Dína, dóttir Leu, sem hún ól Jakobi, fór út til að sjá dætur jarðarinnar.'),
(983, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 2, 'OT', 'Síkem, sonur Hemors Hevíta, höfðingi landsins, sá hana, tók hana, lá með henni og nauðgaði henni.'),
(984, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 3, 'OT', 'Sál hans festist við Dínu, dóttur Jakobs, og hann elskaði stúlkuna og talaði við hjarta stúlkunnar.'),
(985, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 4, 'OT', 'Síkem talaði við Hemor föður sinn og sagði: Taktu þessa stúlku fyrir konu handa mér.'),
(986, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 5, 'OT', 'Jakob hafði heyrt að hann hefði svívirt Dínu, dóttur sína, en synir hans voru með fénaðinn sinn á akrinum, og Jakob þagði þar til þeir komu.'),
(987, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 6, 'OT', 'Hemor, faðir Síkems, gekk út til Jakobs til að tala við hann.'),
(988, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 7, 'OT', 'Synir Jakobs komu af akrinum þegar þeir heyrðu það, og mennirnir sárnuðu og urðu mjög reiðir, því hann hafði framið ósvífni í Ísrael með því að liggja með dóttur Jakobs, en slíkt á ekki að gerast.'),
(989, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 8, 'OT', 'Hemor talaði við þá og sagði: Sál Síkems, sonar míns, þráir dóttur ykkar. Gefið honum hana fyrir konu.'),
(990, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 9, 'OT', 'Giftist okkur, gefið okkur dætur ykkar og takið dætur okkar handa ykkur.'),
(991, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 10, 'OT', 'Jörðin er fyrir andliti ykkar; setjist hér að, verslið og eignist hér land.'),
(992, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 11, 'OT', 'Síkem sagði við föður hennar og bræður hennar: Ég finn hylli í augum ykkar, og hvað sem þið segið mun ég gefa.'),
(993, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 12, 'OT', 'Setjið á mig mikið brúðarverð og gjöf, og ég mun gefa eins og þið segið, aðeins gefið mér stúlkuna fyrir konu.'),
(994, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 13, 'OT', 'Synir Jakobs svöruðu Síkem og Hemor föður hans með svikum, og töluðu, af því að hann hafði svívirt Dínu, systur þeirra.'),
(995, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 14, 'OT', 'Þeir sögðu við þá: Við getum ekki gert þetta, að gefa systur okkar manni, sem er með óumskorna yfirhúð, því það er svívirðing fyrir okkur.'),
(996, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 15, 'OT', 'Aðeins með þessu skilyrði munum við samþykkja, ef þið verðið eins og við, með því að hver karlmaður meðal ykkar sé umskorinn.'),
(997, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 16, 'OT', 'Þá munum við gefa ykkur dætur okkar og taka dætur ykkar til okkar, og við munum búa með ykkur og verða einn lýður.'),
(998, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 17, 'OT', 'En ef þið hlustið ekki á okkur og látið umskera ykkur, þá tökum við dóttur okkar og förum.'),
(999, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 18, 'OT', 'Orð þeirra voru góð í augum Hemors og í augum Síkems, sonar Hemors.'),
(1000, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 19, 'OT', 'Sveinninn tafði ekki við að gera þetta, því hann hafði yndi af dóttur Jakobs, og hann var virtur umfram alla í húsi föður síns.'),
(1001, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 20, 'OT', 'Hemor og Síkem, sonur hans, komu að hliði borgar þeirra og töluðu við mennina í borginni.'),
(1002, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 21, 'OT', 'Þessir menn eru friðsamir við okkur. Látum þá búa í landinu og versla í því, því landið er nógu stórt fyrir andliti þeirra. Dætur þeirra tökum við til okkar sem konur, og dætur okkar gefum við þeim.'),
(1003, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 22, 'OT', 'Aðeins með þessu skilyrði munu mennirnir samþykkja að búa hjá okkur og verða einn lýður: að hver karlmaður meðal þeirra verði umskorinn.'),
(1004, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 23, 'OT', 'Fénað þeirra, eignir þeirra og skepnur þeirra; verður það ekki okkar? Aðeins samþykkjum við þeim, og þeir munu búa hjá okkur.'),
(1005, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 24, 'OT', 'Og allir sem gengu út um hlið borgar hans hlustuðu á Hemor og Síkem, son hans; og allir karlmenn, sem gengu út um hlið borgar hans, voru umskornir.'),
(1006, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 25, 'OT', 'Á þriðja degi, þegar þeir voru sárir, tóku tveir synir Jakobs, Símeon og Leví, bræður Dínu, hvor sitt sverð, gengu inn í borgina án öryggis og drápu alla karlmennina.'),
(1007, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 26, 'OT', 'Þeir drápu Hemor og Síkem, son hans, með sverði, tóku Dínu úr húsi Síkems og fóru.'),
(1008, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 27, 'OT', 'Synir Jakobs komu yfir hina föllnu og rændu borgina, af því að þeir höfðu svívirt systur þeirra.'),
(1009, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 28, 'OT', 'Sauðfé þeirra, naut þeirra, asna þeirra og allt sem var í borginni og á akrinum tóku þeir.'),
(1010, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 29, 'OT', 'Allan styrk þeirra, öll börn þeirra og konur þeirra tóku þeir herfang, og allt sem var í húsinu.'),
(1011, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 30, 'OT', 'Jakob sagði við Símeon og Leví: Þið hafið steypt mér í ógæfu og gert mig óþokkaðan meðal íbúa landsins, meðal Kanaanítum og Peresítum. Ég hef fáa menn að tölu; ef þeir safnast saman gegn mér og ráðast á mig, munu þeir eyða mér og húsi mínu.'),
(1012, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 34, 31, 'OT', 'Þeir sögðu: Á að fara með systur okkar eins og portkonu?'),
(1013, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 1, 'OT', 'Guð sagði við Jakob: Farðu upp til Betel og búðu þar, og gerðu þar altari fyrir Guð, sem birtist þér þegar þú flýðir frá Esaú bróður þínum.'),
(1014, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 2, 'OT', 'Jakob sagði við heimafólk sitt og alla sem voru með honum: Takið burt útlenda guði, sem eru meðal ykkar, hreinsið ykkur og skiptið um skikkjur.'),
(1015, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 3, 'OT', 'Við skulum fara upp til Betel og gera þar altari fyrir Guð, sem svaraði mér á degi neyðar minnar og var með mér á veginum sem ég fór.'),
(1016, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 4, 'OT', 'Þeir létu Jakob fá alla framandi guði sem voru í höndum þeirra og eyrnalokka í eyrum sínum; Jakob faldi þá undir eik hjá Síkem.'),
(1017, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 5, 'OT', 'Þá kom skelfing Guðs yfir borgirnar allt í kring, svo að þær eltu ekki sonu Jakobs.'),
(1018, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 6, 'OT', 'Jakob kom til Lús, sem er í Kanaanslandi, það er Betel, hann og allur lýðurinn sem var með honum.'),
(1019, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 7, 'OT', 'Hann reisti þar altari og kallaði staðinn El-Betel, því að Guð opinberaði sig honum þar, þegar hann flýði undan bróður sínum.'),
(1020, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 8, 'OT', 'Debóra, fóstra Rebekku, dó og var grafin fyrir neðan Betel undir eik; nafn hennar var Allon-Bakút.'),
(1021, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 9, 'OT', 'Guð birtist Jakobi aftur þegar hann kom frá Paddan Aram, og hann blessaði hann.'),
(1022, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 10, 'OT', 'Guð sagði við hann: Nafn þitt er Jakob; nafn þitt skal ekki framar kallast Jakob, heldur skal nafn þitt vera Ísrael. Og hann kallaði hann Ísrael.'),
(1023, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 11, 'OT', 'Guð sagði við hann: Ég er Guð Almáttugur. Vertu frjósamur og margfaldastu; þjóð og söfnuður þjóða skal verða af þér, og konungar skulu koma út úr lendum þínum.'),
(1024, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 12, 'OT', 'Jörðina sem ég gaf Abraham og Ísak, hana gef ég þér, og sæði þínu eftir þig gef ég jörðina.'),
(1025, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 13, 'OT', 'Guð fór upp frá Jakobi á staðnum þar sem hann hafði talað við hann.'),
(1026, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 14, 'OT', 'Jakob reisti steinsúlu á staðnum þar sem hann hafði talað við hann, steinsúlu úr steini, hellti dreypifórn á hana og olíu yfir hana.'),
(1027, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 15, 'OT', 'Jakob kallaði nafn staðarins, þar sem Guð hafði talað við hann, Betel.'),
(1028, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 16, 'OT', 'Þeir fóru frá Betel. Þegar nokkurn spöl var eftir til Efrat, fæddi Rakel, og fæðingin var erfið.'),
(1029, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 17, 'OT', 'Þegar hún átti erfitt í fæðingunni, sagði ljósmóðirin við hana: Óttastu ekki, því að þú átt líka son.'),
(1030, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 18, 'OT', 'Þegar sál hennar fór, því hún dó, kallaði hún hann Ben-Óní, en faðir hans kallaði hann Benjamín.'),
(1031, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 19, 'OT', 'Rakel dó og var grafin á veginum til Efrat, það er Betlehem.'),
(1032, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 20, 'OT', 'Jakob reisti steinsúlu yfir greftrun hennar; það er minnisstoð á greftrun Rakelar til þessa dags.'),
(1033, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 21, 'OT', 'Ísrael lagði af stað og sló tjald sitt handan Migdal-Eder.'),
(1034, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 22, 'OT', 'Þegar Ísrael bjó í landinu, fór Rúben og lá með Bilhu, friðlu föður síns, og Ísrael frétti það. Synir Jakobs voru tólf.'),
(1035, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 23, 'OT', 'Synir Leu: Rúben, frumgetinn Jakobs, Símeon, Leví, Júda, Íssakar og Sebúlon.'),
(1036, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 24, 'OT', 'Synir Rakelar: Jósef og Benjamín.'),
(1037, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 25, 'OT', 'Synir Bilhu, ambáttar Rakelar: Dan og Naftalí.'),
(1038, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 26, 'OT', 'Synir Silpu, ambáttar Leu: Gað og Asser. Þetta eru synir Jakobs, sem fæddust honum í Paddan Aram.'),
(1039, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 27, 'OT', 'Jakob kom til Ísaks föður síns í Mamre, í Kirjat-Arba, það er Hebron, þar sem Abraham og Ísak dvöldu.'),
(1040, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 28, 'OT', 'Dagar Ísaks voru hundrað og áttatíu ár.'),
(1041, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 35, 29, 'OT', 'Ísak gaf upp andann og dó, og hann var saddur daga og safnaðist til lýðs síns. Esaú og Jakob, synir hans, grófu hann.'),
(1042, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 1, 'OT', 'Þetta er ættartala Esaús, það er Edóm.'),
(1043, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 2, 'OT', 'Esaú tók sér konur af dætrum Kanaans: Ada, dóttur Elons Hetíta, og Aholíbama, dóttur Ana, dóttur Sibeons Hevíta.'),
(1044, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 3, 'OT', 'Basmat, dóttir Ísmaels, systir Nebajóts.'),
(1045, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 4, 'OT', 'Ada fæddi Esaú Elífas, og Basmat fæddi Regúel.'),
(1046, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 5, 'OT', 'Aholíbama fæddi Jeús, Jalam og Kóra. Þetta eru synir Esaús, sem fæddust honum í Kanaanslandi.'),
(1047, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 6, 'OT', 'Esaú tók konur sínar, sonu sína og dætur sínar, allar sálir húss síns, fénað sinn, allar skepnur sínar og eignir sínar, sem hann hafði aflað í Kanaanslandi, og fór í annað land, fjarri Jakobi bróður sínum.'),
(1048, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 7, 'OT', 'Eignir þeirra voru of miklar til að þeir gætu búið saman, og landið, þar sem þeir dvöldu, gat ekki borið þá vegna fénaðar þeirra.'),
(1049, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 8, 'OT', 'Esaú bjó á fjallinu Seír; Esaú er Edóm.'),
(1050, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 9, 'OT', 'Þetta er ættartala Esaús, föður Edóms, á fjallinu Seír.'),
(1051, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 10, 'OT', 'Þetta eru nöfn sona Esaús: Elífas, sonur Ödu, konu Esaús, og Regúel, sonur Basmatar, konu Esaús.'),
(1052, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 11, 'OT', 'Synir Elífasar voru Teman, Ómar, Sefó, Gatam og Kenas.'),
(1053, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 12, 'OT', 'Timna var friðla Elífasar, sonar Esaús, og hún fæddi Elífasi Amalek. Þetta eru synir Ödu, konu Esaús.'),
(1054, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 13, 'OT', 'Þetta eru synir Regúels: Nahat, Sera, Samma og Missa. Þetta voru synir Basmatar, konu Esaús.'),
(1055, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 14, 'OT', 'Þetta voru synir Aholíbamu, dóttur Ana, dóttur Sibeons, konu Esaús. Hún fæddi Esaú Jeús, Jalam og Kóra.'),
(1056, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 15, 'OT', 'Þetta eru höfðingjar sona Esaús. Synir Elífasar, frumgetins Esaús, eru: höfðingi Teman, höfðingi Ómar, höfðingi Sefó og höfðingi Kenas.'),
(1057, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 16, 'OT', 'Höfðingi Kóra, höfðingi Gatam og höfðingi Amalek. Þetta eru höfðingjar Elífasar í landinu Edóm; þetta eru synir Ödu.'),
(1058, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 17, 'OT', 'Þetta eru synir Regúels, sonar Esaús: höfðingi Nahat, höfðingi Sera, höfðingi Samma og höfðingi Missa. Þetta eru höfðingjar Regúels í landinu Edóm. Þetta eru synir Basmatar, konu Esaús.'),
(1059, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 18, 'OT', 'Þetta eru synir Aholíbamu, konu Esaús: höfðingi Jeús, höfðingi Jalam og höfðingi Kóra. Þetta eru höfðingjar Aholíbamu, dóttur Ana, konu Esaús.'),
(1060, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 19, 'OT', 'Þetta eru synir Esaús, og þetta eru höfðingjar þeirra; hann er Edóm.'),
(1061, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 20, 'OT', 'Þetta eru synir Seírs Hóríta, íbúa jarðarinnar: Lótan, Sóbal, Sibeon og Ana.'),
(1062, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 21, 'OT', 'Dísón, Eser og Dísan. Þetta eru höfðingjar Hóríta, sona Seírs, í landinu Edóm.'),
(1063, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 22, 'OT', 'Synir Lótans voru Hóri og Heman, og systir Lótans var Timna.'),
(1064, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 23, 'OT', 'Þetta eru synir Sóbals: Alvan, Manahat, Ebal, Sefó og Ónam.'),
(1065, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 24, 'OT', 'Þetta eru synir Sibeons: Aja og Ana. Þetta er sá Ana sem fann múlasna í eyðimörkinni, þegar hann gætti asna Sibeons, föður síns.'),
(1066, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 25, 'OT', 'Þetta eru synir Ana: Dísón, og Aholíbama, dóttir Ana.'),
(1067, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 26, 'OT', 'Þetta eru synir Dísans: Hemdan, Esban, Jitran og Keran.'),
(1068, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 27, 'OT', 'Þetta eru synir Esers: Bilhan, Saavan og Akan.'),
(1069, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 28, 'OT', 'Þetta eru synir Dísans: Ús og Aran.'),
(1070, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 29, 'OT', 'Þetta eru höfðingjar Hóríta: höfðingi Lótan, höfðingi Sóbal, höfðingi Sibeon, höfðingi Ana.'),
(1071, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 30, 'OT', 'Höfðingi Dísón, höfðingi Eser og höfðingi Dísan. Þetta eru höfðingjar Hóríta, eftir höfðingjum þeirra í landinu Seír.'),
(1072, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 31, 'OT', 'Þetta eru konungarnir, sem réðu í landinu Edóm áður en nokkur konungur réð yfir sonum Ísraels.'),
(1073, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 32, 'OT', 'Bela, sonur Beórs, varð konungur í Edóm, og nafn borgar hans var Dinhaba.'),
(1074, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 33, 'OT', 'Bela dó, og Jóbab, sonur Sera frá Bosra, varð konungur í hans stað.'),
(1075, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 34, 'OT', 'Jóbab dó, og Húsam úr landi Temaníta varð konungur í hans stað.'),
(1076, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 35, 'OT', 'Húsam dó, og Hadad, sonur Bedads, sá sem sigraði Midían á akri Móabs, varð konungur í hans stað; nafn borgar hans var Avít.'),
(1077, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 36, 'OT', 'Hadad dó, og Samla frá Masreka varð konungur í hans stað.'),
(1078, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 37, 'OT', 'Samla dó, og Sál frá Rehóbót við fljótinu varð konungur í hans stað.'),
(1079, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 38, 'OT', 'Sál dó, og Baal-Hanan, sonur Akbórs, varð konungur í hans stað.'),
(1080, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 39, 'OT', 'Baal-Hanan, sonur Akbórs, dó, og Hadar varð konungur í hans stað. Nafn borgar hans var Pagú, og nafn konu hans var Mehetabel, dóttir Matreds, dóttur Mesahabs.'),
(1081, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 40, 'OT', 'Þetta eru nöfn höfðingja Esaús eftir ættum þeirra, stöðum og nöfnum: höfðingi Timna, höfðingi Alva, höfðingi Jetet.'),
(1082, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 41, 'OT', 'Höfðingi Aholíbama, höfðingi Ela og höfðingi Pínon.'),
(1083, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 42, 'OT', 'Höfðingi Kenas, höfðingi Teman og höfðingi Mibsar.'),
(1084, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 36, 43, 'OT', 'Höfðingi Magdíel og höfðingi Íram. Þetta eru höfðingjar Edóms eftir bústöðum sínum í landi eignar sinnar. Hann er Esaú, faðir Edóms.'),
(1085, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 1, 'OT', 'Jakob settist að í landi útlegðar föður síns, í landi Kanaans.'),
(1086, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 2, 'OT', 'Þetta eru ættartölur Jakobs. Jósef var sautján ára og gætti sauðfjár með bræðrum sínum; hann var sveinn með sonum Bilhu og Silpu, kvenna föður síns. Jósef sagði föður sínum frá illum rógi þeirra.'),
(1087, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 3, 'OT', 'Ísrael elskaði Jósef meira en alla sonu sína, því að hann var sonur ellinnar, og lét gera honum marglitan kyrtil.'),
(1088, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 4, 'OT', 'Bræður hans sáu, að faðir þeirra elskaði hann meira en alla bræður þeirra, og þeir hötuðu hann og gátu ekki talað við hann með friði.'),
(1089, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 5, 'OT', 'Jósef dreymdi draum og sagði bræðrum sínum frá honum, og þeir hötuðu hann enn meira.'),
(1090, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 6, 'OT', 'Hann sagði við þá: Hlustið nú á þennan draum, sem mér dreymdi.'),
(1091, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 7, 'OT', 'Við vorum að binda kornbundin á akrinum. Sjá, kornbundin mín reis upp og stóð, og sjá, kornbundin ykkar umkringdu hana og lutu niður fyrir kornbundinu mínu.'),
(1092, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 8, 'OT', 'Þá sögðu bræður hans við hann: Ætlar þú virkilega að verða konungur yfir okkur, eða ætlar þú að ríkja yfir okkur? Og þeir hötuðu hann enn meira vegna drauma hans og orða hans.'),
(1093, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 9, 'OT', 'Hann dreymdi annan draum og sagði bræðrum sínum frá honum. Hann sagði: Sjá, ég dreymdi enn draum: Sólin, tunglið og ellefu stjörnur beygðu sig fyrir mér.'),
(1094, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 10, 'OT', 'Hann sagði þetta föður sínum og bræðrum, og faðir hans ávítaði hann og sagði við hann: Hvað þýðir þessi draumur, sem þú dreymdir? Eigum við, móðir þín og bræður þínir, virkilega að koma og falla fram til jarðar fyrir þér?'),
(1095, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 11, 'OT', 'Bræður hans öfunduðu hann, en faðir hans geymdi orðið í huga sér.'),
(1096, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 12, 'OT', 'Bræður hans fóru að gæta sauðfjár föður síns í Síkem.'),
(1097, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 13, 'OT', 'Ísrael sagði við Jósef: Eru bræður þínir ekki að gæta fjárins í Síkem? Kom, ég ætla að senda þig til þeirra. Hann svaraði: Hér er ég.'),
(1098, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 14, 'OT', 'Hann sagði við hann: Farðu nú og sjáðu, hvort friður sé hjá bræðrum þínum og hjá sauðfénu, og færðu mér orð aftur. Þá sendi hann hann úr dal Hebrons, og hann kom til Síkem.'),
(1099, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 15, 'OT', 'Maður fann hann reikandi á akrinum, og maðurinn spurði hann: Hvað leitar þú að?'),
(1100, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 16, 'OT', 'Hann sagði: Ég leita bræðra minna. Segðu mér, hvar þeir eru að gæta hjarðarinnar.'),
(1101, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 17, 'OT', 'Maðurinn sagði: Þeir eru farnir héðan, því að ég heyrði þá segja: Förum til Dótans. Jósef fór á eftir bræðrum sínum og fann þá í Dótan.'),
(1102, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 18, 'OT', 'Þeir sáu hann álengdar, og áður en hann kom nær þeim lögðu þeir á ráðin um að ráða hann af dögum.'),
(1103, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 19, 'OT', 'Hver maður sagði við bróður sinn: Sjá, þarna kemur herra drauma.'),
(1104, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 20, 'OT', 'Komið nú, drepum hann og köstum honum í einn af brunnunum. Og við segjum: Villidýr hefur étið hann. Og þá sjáum við, hvað verður um drauma hans.'),
(1105, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 21, 'OT', 'Rúben heyrði það og bjargaði honum úr höndum þeirra og sagði: Tökum ekki sál hans.'),
(1106, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 22, 'OT', 'Rúben sagði við þá: Úthellið ekki blóði. Kastið honum í þennan brunn, sem er í eyðimörkinni, en leggið ekki hönd á hann. Þannig gæti hann bjargað honum úr höndum þeirra og skilað honum aftur til föður síns.'),
(1107, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 23, 'OT', 'Þegar Jósef kom til bræðra sinna, afklæddu þeir Jósef kyrtli hans, marglita kyrtlinum sem hann var í.'),
(1108, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 24, 'OT', 'Þeir tóku hann og köstuðu honum í brunninn. Brunnurinn var tómur, og ekkert vatn var í honum.'),
(1109, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 25, 'OT', 'Þeir settust niður til að eta brauð. Þegar þeir lyftu augunum sáu þeir ferðalest Ísmaelíta koma frá Gíleað, með úlfalda sína hlaðna ilmjurtum, smyrsli og myrru á leiðinni til Egyptalands.'),
(1110, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 26, 'OT', 'Júda sagði við bræður sína: Hvaða ábati er af því að drepa bróður okkar og hylja blóð hans?'),
(1111, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 27, 'OT', 'Komið, seljum hann Ísmaelítum, en hönd okkar sé ekki á honum, því að hann er bróðir okkar og hold okkar. Bræður hans hlýddu.'),
(1112, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 28, 'OT', 'Þá fóru hjá menn af Midíanítum, kaupmenn. Þeir drógu Jósef upp úr brunninum og seldu Jósef Ísmaelítum fyrir tuttugu silfurpeninga, og þeir fóru með Jósef til Egyptalands.'),
(1113, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 29, 'OT', 'Rúben sneri aftur að brunninum, en sjá, Jósef var ekki í brunninum. Þá reif hann klæði sín.'),
(1114, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 30, 'OT', 'Hann sneri aftur til bræðra sinna og sagði: Drengurinn er horfinn! Og hvert á ég að fara?'),
(1115, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 31, 'OT', 'Þeir tóku kyrtil Jósefs, slátruðu geithafri af geitum og dýfðu kyrtlinum í blóðið.'),
(1116, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 32, 'OT', 'Þeir sendu marglita kyrtilinn til föður síns og sögðu: Þetta höfum við fundið. Þekktu nú, hvort þetta er kyrtill sonar þíns eða ekki.'),
(1117, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 33, 'OT', 'Hann þekkti hann og sagði: Þetta er kyrtill sonar míns! Villidýr hefur étið hann, og Jósef er tættur í sundur.'),
(1118, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 34, 'OT', 'Jakob reif skikkjur sínar, lagði hærusekk um lendar sínar og syrgði son sinn marga daga.'),
(1119, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 35, 'OT', 'Allir synir hans og dætur risu upp til að hugga hann, en hann neitaði að láta hugga sig og sagði: Ég fer niður til Helju, til sonar míns, syrgjandi. Og faðir hans grét yfir honum.'),
(1120, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 37, 36, 'OT', 'Midíanítar seldu Jósef til Egyptalands, Pótífar, hirðmanni Faraós og höfðingja lífvarðarins.'),
(1121, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 1, 'OT', 'Á þessum tíma fór Júda frá bræðrum sínum og settist að hjá manni Adúllamíta; nafn hans var Híra.'),
(1122, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 2, 'OT', 'Þar sá Júda dóttur manns Kanaanita, og nafn hans var Súa. Hann tók hana og gekk inn til hennar.'),
(1123, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 3, 'OT', 'Hún varð þunguð og ól son, og hann gaf honum nafnið Er.'),
(1124, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 4, 'OT', 'Hún varð aftur þunguð og ól son, og hún gaf honum nafnið Ónan.'),
(1125, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 5, 'OT', 'Enn ól hún son og gaf honum nafnið Sela. Hann fæddist í Kesíb, þegar hún ól hann.'),
(1126, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 6, 'OT', 'Júda tók konu handa Er, frumgetnum syni sínum, og nafn hennar var Tamar.'),
(1127, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 7, 'OT', 'Er, frumgetinn sonur Júda, var illur í augum Jahve, og Jahve drap hann.'),
(1128, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 8, 'OT', 'Júda sagði við Ónan: Gakktu inn til konu bróður þíns, kvæntu hana og vektu sæði fyrir bróður þinn.'),
(1129, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 9, 'OT', 'Ónan vissi, að afkvæmið yrði ekki hans. Þegar hann gekk inn til konu bróður síns, eyddi hann sæðinu niður á jörðina, til þess að hann gæfi bróður sínum ekki afkvæmi.'),
(1130, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 10, 'OT', 'Það sem hann gerði var illt í augum Jahve, og hann drap hann líka.'),
(1131, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 11, 'OT', 'Júda sagði við Tamar, brúði sína: Vertu ekkja í húsi föður þíns, þar til Sela, sonur minn, er orðinn fullorðinn, því að hann óttaðist, að hann myndi líka deyja eins og bræður hans. Og Tamar fór og bjó í húsi föður síns.'),
(1132, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 12, 'OT', 'Eftir langa daga dó dóttir Súa, kona Júda. Júda huggaði sig og fór upp í Timna, til þeirra sem klipptu sauðfé hans, ásamt náunga sínum Híra Adúllamíta.'),
(1133, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 13, 'OT', 'Þá var sagt Tamar: Sjá, tengdafaðir þinn er á leið í Timna til að klippa sauðfé sitt.'),
(1134, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 14, 'OT', 'Þá fór hún úr klæðum ekkjudóms síns, huldi sig með blæju og settist í inngangi Enaím, sem er á veginum til Timnu. Hún sá, að Sela var orðinn fullorðinn, en hún var ekki gefin honum til konu.'),
(1135, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 15, 'OT', 'Þegar Júda sá hana, hélt hann, að hún væri skækja, því að hún hafði hulið andlit sitt.'),
(1136, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 16, 'OT', 'Hann sneri sér að henni á veginum og sagði: Leyfðu mér að koma inn til þín. Hann vissi ekki, að hún var brúður hans. Hún sagði: Hvað ætlar þú að gefa mér, ef þú vilt koma til mín?'),
(1137, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 17, 'OT', 'Hann sagði: Ég skal senda þér kið af geitum úr sauðfénu. Hún sagði: Gefðu mér veð, þangað til þú sendir það.'),
(1138, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 18, 'OT', 'Hann sagði: Hvað er veðið, sem ég á að gefa þér? Hún sagði: Innsiglið þitt, bandið þitt og stafinn þinn, sem er í hendi þinni. Hann gaf henni þetta og gekk inn til hennar, og hún varð þunguð af honum.'),
(1139, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 19, 'OT', 'Hún stóð upp, fór, tók af sér blæjuna og klæddist klæðum ekkjudóms síns.'),
(1140, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 20, 'OT', 'Júda sendi kiðið af geitunum með náunga sínum Adúllamítanum, til að ná veðinu aftur úr hendi konunnar, en hann fann hana ekki.'),
(1141, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 21, 'OT', 'Hann spurði menn staðarins: Hvar er hóran, sem var við Enaím á veginum? En þeir sögðu: Hér hefur engin hóra verið.'),
(1142, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 22, 'OT', 'Hann sneri aftur til Júda og sagði: Ég fann hana ekki, og mennirnir á staðnum sögðu, að þar hefði engin hóra verið.'),
(1143, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 23, 'OT', 'Þá sagði Júda: Látum hana halda því, svo að við verðum ekki að fyrirlitningu. Sjá, ég sendi kiðið, en þú fannst hana ekki.'),
(1144, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 24, 'OT', 'Eftir þrjá mánuði var Júda sagt: Tamar, brúður þín, hefur drýgt hór og er jafnvel ófrísk af hórdómi. Þá sagði Júda: Leiðið hana út, og brennið hana.'),
(1145, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 25, 'OT', 'Þegar hún var leidd út, sendi hún til tengdaföður síns og sagði: Ég er ófrísk af manninum, sem þetta tilheyrir. Hún sagði: Athugaðu nú, hvers eru þessi innsigli, bandið og stafurinn.'),
(1146, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 26, 'OT', 'Júda kannaðist við þau og sagði: Hún er réttlátari en ég, því að ég gaf hana ekki Sela, syni mínum. Og hann svaf ekki hjá henni framar.'),
(1147, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 27, 'OT', 'Þegar tími hennar var kominn til að fæða, voru tvíburar í móðurkviði hennar.'),
(1148, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 28, 'OT', 'Þegar hún fæddi, rétti annar fram hönd, og ljósmóðirin batt skarlatsþráð um höndina á honum og sagði: Þessi kom fyrst út.'),
(1149, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 29, 'OT', 'Þegar hann dró hönd sína til baka, kom bróðir hans út. Þá sagði hún: Hvílíkt skarð hefur þú rofið! Og nafn hans var kallað Peres.'),
(1150, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 38, 30, 'OT', 'Eftir þetta kom bróðir hans út, sá sem var með skarlatsþráðinn á hendi sér, og nafn hans var kallað Sera.'),
(1151, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 1, 'OT', 'Jósef var fluttur til Egyptalands, og Pótífar, hirðmaður Faraós og höfðingi lífvarðarins, Egypti, keypti hann af hendi Ísmaelíta, sem höfðu flutt hann þangað.'),
(1152, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 2, 'OT', 'Jahve var með Jósef, og hann varð farsæll maður. Hann var í húsi herra síns, Egypta.'),
(1153, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 3, 'OT', 'Herra hans sá, að Jahve var með honum, og að Jahve lét allt, sem hann gerði, heppnast vel í höndum hans.'),
(1154, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 4, 'OT', 'Jósef fann hylli í augum hans, og hann þjónaði honum. Hann setti hann yfir hús sitt og fól honum allt, sem hann átti, í hendur hans.'),
(1155, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 5, 'OT', 'Frá þeim tíma, sem hann setti hann yfir hús sitt og allt, sem hann átti, blessaði Jahve hús Egypta vegna Jósefs. Blessun Jahve var yfir öllu, sem hann átti, bæði í húsinu og á akrinum.'),
(1156, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 6, 'OT', 'Hann skildi allt, sem hann átti, eftir í hendi Jósefs og skeytti ekki um neitt annað en brauðið, sem hann át. Jósef var fagur á vaxtarlag og fríður í útliti.'),
(1157, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 7, 'OT', 'Eftir þessi orð leit kona herra hans girndaraugum á Jósef og sagði: Leggstu hjá mér.'),
(1158, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 8, 'OT', 'Hann neitaði og sagði við konu herra síns: Sjá, herra minn hefur engar áhyggjur af neinu í húsinu, og allt, sem hann á, hefur hann falið mínum höndum.'),
(1159, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 9, 'OT', 'Enginn er mér meiri í þessu húsi en hann, og hann hefur ekkert dregið undan mér nema þig, því að þú ert kona hans. Hvernig ætti ég þá að fremja þessa miklu illsku og syndga gegn Guði?'),
(1160, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 10, 'OT', 'Dag eftir dag talaði hún við Jósef, en hann hlustaði ekki á hana og lagðist ekki hjá henni, og var ekki með henni.'),
(1161, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 11, 'OT', 'Svo bar við einn dag, að hann gekk inn í húsið til að vinna starf sitt, en enginn af mönnum hússins var þar inni í húsinu.'),
(1162, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 12, 'OT', 'Hún greip í klæði hans og sagði: Leggstu hjá mér! En hann skildi klæðið eftir í hendi hennar, hljóp út og fór burt.'),
(1163, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 13, 'OT', 'Þegar hún sá, að hann hafði skilið klæðið eftir í hendi hennar og flúið út.'),
(1164, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 14, 'OT', 'Hún kallaði á menn hússins síns og sagði við þá: Sjáið, hann hefur leitt inn til okkar Hebrea til að gera sér gys að okkur. Hann kom inn til mín til að liggja hjá mér, og ég æpti hárri röddu.'),
(1165, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 15, 'OT', 'Þegar hann heyrði, að ég hóf rödd mína og hrópaði, skildi hann klæðið sitt eftir hjá mér, flúði og fór út.'),
(1166, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 16, 'OT', 'Hún geymdi klæðið hans hjá sér, þar til herra hans kom heim til hússins.'),
(1167, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 17, 'OT', 'Hún talaði við hann með þessum orðum og sagði: Þjónninn Hebrei, sem þú komst með til okkar, kom inn til mín til að gera sér gys að mér.'),
(1168, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 18, 'OT', 'En þegar ég hóf rödd mína og hrópaði, skildi hann klæðið sitt eftir hjá mér og flúði út.'),
(1169, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 19, 'OT', 'Þegar herra hans heyrði orð konu sinnar, sem hún talaði til hans og sagði: Svona gerði þjónninn þinn við mig, þá reiddist hann mjög.'),
(1170, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 20, 'OT', 'Herra Jósefs tók hann og setti hann í fangelsið, á þann stað þar sem fangar konungsins voru bundnir. Hann var þar í fangelsinu.'),
(1171, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 21, 'OT', 'Jahve var með Jósef, sýndi honum miskunn og gaf honum hylli í augum höfðingja fangelsisins.'),
(1172, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 22, 'OT', 'Höfðingi fangelsisins fól Jósef í hendur allra fanganna, sem voru í fangelsinu, og allt, sem þar var gert, hafði hann umsjón með.'),
(1173, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 39, 23, 'OT', 'Höfðingi fangelsisins leit ekki eftir neinu, sem var í höndum hans, af því að Jahve var með honum, og það sem hann gerði, lét Jahve heppnast.'),
(1174, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 1, 'OT', 'Eftir þessi orð syndguðu byrlari konungs Egyptalands og bakarinn gegn herra sínum, konungi Egyptalands.'),
(1175, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 2, 'OT', 'Faraó reiddist báðum hirðmönnum sínum, höfðingja byrlaranna og höfðingja bakaranna.'),
(1176, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 3, 'OT', 'Hann setti þá í varðstöðu í húsi höfðingja hirðmannanna, í fangelsið, á þann stað þar sem Jósef var bundinn.'),
(1177, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 4, 'OT', 'Höfðingi hirðmannanna fól Jósef að þjóna þeim, og þeir voru nokkra daga í varðstöðu.'),
(1178, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 5, 'OT', 'Þá dreymdi þá báða, byrlara konungs Egyptalands og bakarann, sem voru í fangelsinu, sömu nóttina. Hver maður dreymdi sinn draum, og hver þeirra fékk sína ráðningu eftir draumi sínum.'),
(1179, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 6, 'OT', 'Jósef kom til þeirra að morgni og sá, að þeir voru daufir.'),
(1180, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 7, 'OT', 'Hann spurði hirðmenn Faraós, sem voru með honum í varðstöðu í húsi herra síns: Hvers vegna er andlit ykkar svo dapurt í dag?'),
(1181, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 8, 'OT', 'Þeir svöruðu honum: Okkur hefur dreymt draum, en enginn er til að ráða hann. Jósef sagði við þá: Tilheyra ráðningar ekki Guði? Segið mér það nú.'),
(1182, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 9, 'OT', 'Þá sagði höfðingi byrlaranna Jósef drauminn sinn og sagði: Í draumi mínum sá ég vínvið fyrir andliti mínu.'),
(1183, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 10, 'OT', 'Á vínviðnum voru þrjár greinar. Hann laufgaðist, blómin sprungu út, og vínberjaklasi bar þroskuð vínber.'),
(1184, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 11, 'OT', 'Bikar Faraós var í hendi minni. Ég tók vínberin, kreisti þau í bikar Faraós og rétti bikarinn í lófa Faraós.'),
(1185, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 12, 'OT', 'Jósef sagði við hann: Þetta er ráðning hans: Greinarnar þrjár eru þrír dagar.'),
(1186, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 13, 'OT', 'Innan þriggja daga mun Faraó hefja höfuð þitt og endurreisa þig á stall þinn, og þú munt setja bikar Faraós í hönd hans, eins og þú varst áður byrlari hans.'),
(1187, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 14, 'OT', 'En minnstu mín, þegar þér vegnar vel, og sýndu mér miskunn. Nefndu mig við Faraó og leystu mig úr þessu húsi.'),
(1188, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 15, 'OT', 'Því að ég var stolinn úr landi Hebrea, og jafnvel hér hef ég ekkert gert, sem réttlætti að setja mig í brunninn.'),
(1189, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 16, 'OT', 'Þegar höfðingi bakaranna sá, að túlkunin var góð, sagði hann við Jósef: Ég var líka í draumi mínum, og sjá, þrjár körfur með hvítu brauði voru á höfði mér.'),
(1190, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 17, 'OT', 'Í efstu körfunni var alls konar fæða handa Faraó, bakstursverk, og fuglarnir átu það úr körfunni af höfði mér.'),
(1191, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 18, 'OT', 'Jósef svaraði og sagði: Þetta er ráðning hennar: Körfurnar þrjár eru þrír dagar.'),
(1192, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 19, 'OT', 'Innan þriggja daga mun Faraó hefja höfuð þitt af þér og hengja þig á tré, og fuglarnir munu éta hold þitt af þér.'),
(1193, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 20, 'OT', 'Þriðja daginn, sem var afmælisdagur Faraós, hélt hann veislu fyrir alla þjóna sína og lyfti höfði höfðingja byrlaranna og höfðingja bakaranna upp meðal þjóna sinna.'),
(1194, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 21, 'OT', 'Hann setti höfðingja byrlaranna aftur í stöðu sína sem byrlara, og hann rétti Faraó bikarinn í lófa hans.'),
(1195, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 22, 'OT', 'En höfðingja bakaranna lét hann hengja, eins og Jósef hafði túlkað fyrir þá.'),
(1196, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 40, 23, 'OT', 'En höfðingi byrlaranna mundi ekki eftir Jósef, heldur gleymdi honum.'),
(1197, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 1, 'OT', 'Við endi tveggja fullra ára dreymdi Faraó draum: Hann stóð við Nílarfljótið.'),
(1198, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 2, 'OT', 'Og sjá, sjö kýr, fagrar að útliti og feitar á holdi, stigu upp úr Nílarfljótinu og beittu í engjagrasinu.'),
(1199, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 3, 'OT', 'Og sjá, sjö aðrar kýr, ljótar að útliti og horaðar á holdi, komu upp úr Nílarfljótinu á eftir þeim og stóðu hjá hinum kúnum á vörinni.'),
(1200, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 4, 'OT', 'Ljótu kýrnar, ljótar að útliti og horaðar á holdi, átu upp hinar sjö fögru kýrnar. Þá vaknaði Faraó.'),
(1201, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 5, 'OT', 'Og hann sofnaði aftur og dreymdi annan draum. Og sjá, sjö kornöx spruttu upp á einum reyr, þróttmikil og góð.'),
(1202, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 6, 'OT', 'Og sjá, sjö kornöx til viðbótar spruttu upp á eftir þeim, mögur og sviðin af austri.'),
(1203, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 7, 'OT', 'Og mögru kornöxin gleyptu upp sjö feitu og fullu kornöxin. Þá vaknaði Faraó, og sjá, það var draumur.'),
(1204, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 8, 'OT', 'Um morguninn var andi hans órólegur, og hann sendi eftir öllum særingamönnum Egyptalands og öllum vitringum þess. Faraó sagði þeim draum sinn, en enginn gat ráðið hann fyrir Faraó.'),
(1205, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 9, 'OT', 'Þá talaði höfðingi byrlaranna við Faraó og sagði: Ég minnist syndar minnar í dag.'),
(1206, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 10, 'OT', 'Faraó reiddist þjónum sínum og setti mig í varðstöðu í húsi höfðingja hirðmannanna, bæði mig og höfðingja bakaranna.'),
(1207, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 11, 'OT', 'Okkur dreymdi draum eina nótt, mig og hann; sérhver maður dreymdi eftir ráðningu draums síns.'),
(1208, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 12, 'OT', 'Þar var með okkur ungur sveinn, Hebrei, þjónn höfðingja hirðmannanna. Við sögðum honum drauma okkar, og hann réð þá fyrir okkur. Hver maður fékk ráðningu eftir draumi sínum.'),
(1209, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 13, 'OT', 'Og það fór eins og hann hafði ráðið fyrir okkur: mig setti hann aftur á stall minn, en hinn hengdi hann upp.'),
(1210, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 14, 'OT', 'Þá sendi Faraó eftir Jósef og lét kalla hann. Hann var sóttur í skyndi úr brunni, lét raka sig, skipti um skikkjur sínar og gekk til Faraós.'),
(1211, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 15, 'OT', 'Og Faraó sagði við Jósef: Mig hefur dreymt draum, og enginn er sá sem ráðið getur hann. En ég hef heyrt um þig að þú heyrir draum og ráðir hann.'),
(1212, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 16, 'OT', 'Jósef svaraði Faraó: Ekki ég. Guð mun svara um frið Faraós.'),
(1213, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 17, 'OT', 'Og Faraó sagði við Jósef: Í draumi mínum stóð ég á vör Nílar.'),
(1214, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 18, 'OT', 'Og sjá, sjö kýr komu upp úr Níl, feitar og fagrar að vaxtarlagi, og þær beittu á engjagrasi.'),
(1215, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 19, 'OT', 'Og sjá, sjö aðrar kýr komu upp á eftir þeim, magrar og mjög ljótar að vaxtarlagi. Ég hef aldrei séð slíkar í allri jörð Egyptalands.'),
(1216, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 20, 'OT', 'Og mögru og ljótu kýrnar átu upp sjö fyrstu feitu kýrnar.'),
(1217, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 21, 'OT', 'Þær komu inn í miðju þeirra, og enginn vissi það, en útlit þeirra var ljótt eins og í upphafi. Þá vaknaði ég.'),
(1218, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 22, 'OT', 'Ég sá í draumi mínum, og sjá, sjö kornöx spruttu á einum reyr, full og góð.'),
(1219, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 23, 'OT', 'Og sjá, sjö önnur kornöx, visnuð, mögur og sviðin af austri, spruttu upp á eftir þeim.'),
(1220, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 24, 'OT', 'Og mögru kornöxin gleyptu sjö góðu kornöxin. Ég sagði við særingamennina, en enginn gat sagt mér það.'),
(1221, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 25, 'OT', 'Jósef sagði við Faraó: Draumur Faraós er einn og hinn sami. Það sem Guð gerir, hefur hann kunngjört Faraó.'),
(1222, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 26, 'OT', 'Sjö góðu kýrnar eru sjö ár, og sjö góðu kornöxin eru sjö ár. Draumurinn er einn og hinn sami.'),
(1223, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 27, 'OT', 'Mögru og ljótu kýrnar sem komu á eftir þeim eru sjö ár, og sjö tómu kornöxin, sviðin af austri, verða sjö ára hungursneyð.'),
(1224, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 28, 'OT', 'Þetta er orðið sem ég talaði við Faraó: Það sem Guð gerir hefur hann sýnt Faraó.'),
(1225, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 29, 'OT', 'Sjá, sjö ár koma, mikil gnægð í öllu Egyptalandi.'),
(1226, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 30, 'OT', 'Þá munu sjö ára hungursneyð rísa upp á eftir þeim, og gnægðin gleymist í Egyptalandi, og hungursneyðin eyðir jörðinni.'),
(1227, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 31, 'OT', 'Gnægðin mun ekki þekkjast í jörðinni vegna þeirrar hungursneyðar sem á eftir kemur, því að hún verður mjög þung.'),
(1228, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 32, 'OT', 'Að draumurinn var endurtekinn fyrir Faraó tvisvar sinnum er vegna þess að orðið er ákveðið af Guði, og Guð flýtir fyrir að framkvæma það.'),
(1229, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 33, 'OT', 'Nú skal Faraó velja mann skynsaman og vitran og setja hann yfir Egyptaland.'),
(1230, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 34, 'OT', 'Faraó skal gera þetta: Hann skipi umsjónarmenn yfir jörðina og taki fimmtung af jörð Egyptalands á sjö árum gnægðarinnar.'),
(1231, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 35, 'OT', 'Þeir skulu safna öllum mat hinna góðu ára sem koma, og safna korni undir hendi Faraós, mat í borgum, og varðveita það.'),
(1232, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 36, 'OT', 'Og maturinn skal vera til umsjónar fyrir jörðina á þeim sjö árum hungursneyðarinnar sem verða í Egyptalandi, svo að jörðin farist ekki af hungri.'),
(1233, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 37, 'OT', 'Og orðið þótti gott í augum Faraós og í augum allra þjóna hans.'),
(1234, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 38, 'OT', 'Og Faraó sagði við þjóna sína: Finnum við annan mann eins og þennan, mann sem hefur anda Guðs í sér?'),
(1235, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 39, 'OT', 'Og Faraó sagði við Jósef: Þar sem Guð hefur kunngjört þér allt þetta, er enginn svo vitur og skynsamur sem þú.'),
(1236, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 40, 'OT', 'Þú skalt vera yfir húsi mínu, og eftir munni þínum skal allur lýður minn hlýða; aðeins hásætið skal ég vera meiri en þú.'),
(1237, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 41, 'OT', 'Og Faraó sagði við Jósef: Sjá, ég set þig yfir allt Egyptaland.'),
(1238, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 42, 'OT', 'Og Faraó tók innsiglishringinn af hendi sinni og setti hann á hönd Jósefs. Hann klæddi hann í línklæði og setti gullkeðju um háls hans.'),
(1239, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 43, 'OT', 'Og hann lét hann aka í öðrum vagni sínum, afriti hins fyrsta, og menn kölluðu fyrir andliti hans: Beygið knéð! Og hann var settur yfir allt Egyptaland.'),
(1240, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 44, 'OT', 'Og Faraó sagði við Jósef: Ég er Faraó, og án þín skal enginn maður hreyfa hönd sína né fót í öllu Egyptalandi.'),
(1241, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 45, 'OT', 'Og Faraó gaf Jósef nafnið Safnat-Paneak, og hann gaf honum Asenat, dóttur Pótífera prests í On, fyrir konu. Og Jósef fór um allt Egyptaland.'),
(1242, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 46, 'OT', 'Jósef var þrjátíu ára þegar hann stóð frammi fyrir Faraó, konungi Egyptalands. Jósef gekk frá andliti Faraós og fór um allt Egyptaland.'),
(1243, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 47, 'OT', 'Og jörðin gaf ríkulega á þeim sjö árum gnægðarinnar, í lúkum.'),
(1244, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 48, 'OT', 'Og hann safnaði öllum mat þessara sjö ára sem voru í Egyptalandi og lagði matinn í borgirnar. Matinn af ökrum hverrar borgar í kring lagði hann inn í þær.'),
(1245, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 49, 'OT', 'Og Jósef safnaði korni eins og sandi hafsins, svo mikið að hann hætti að telja, því að engin var tölu á því.'),
(1246, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 50, 'OT', 'Og Jósef eignaðist tvo sonu áður en hungursneyðin kom, þá sem Asenat, dóttir Pótífera prests í On, ól honum.'),
(1247, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 51, 'OT', 'Og Jósef gaf frumgetnum syni sínum nafnið Manasse, því að Guð hefur látið mig gleyma öllu erfiði mínu og öllu húsi föður míns.'),
(1248, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 52, 'OT', 'Og seinni son sinn nefndi hann Efraím, því að Guð hefur gert mig frjóan í jörð eymdar minnar.'),
(1249, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 53, 'OT', 'Og sjö ára gnægðinni lauk, sem var í Egyptalandi.'),
(1250, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 54, 'OT', 'Og sjö ára hungursneyðin tók að koma, eins og Jósef hafði sagt. Hungur var í öllum jörðum, en í öllu Egyptalandi var brauð.'),
(1251, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 55, 'OT', 'Þegar öll jörð Egyptalands hungraði og lýðurinn kallaði til Faraós um brauð, sagði Faraó við alla Egypta: Farið til Jósefs og gerið það sem hann segir við ykkur.'),
(1252, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 56, 'OT', 'Hungursneyðin lá á öllu andliti jarðarinnar. Þá opnaði Jósef öll búr og seldi Egyptum korn, og hungursneyðin magnaðist í jörð Egyptalands.'),
(1253, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 41, 57, 'OT', 'Og allar þjóðir komu til Egyptalands til að kaupa korn hjá Jósef, því að hungursneyðin magnaðist um alla jörðina.'),
(1254, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 1, 'OT', 'Jakob sá að korn var í Egyptalandi, og Jakob sagði við sonu sína: Hví horfið þið hver á annan?'),
(1255, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 2, 'OT', 'Hann sagði: Sjá, ég hef heyrt að korn sé í Egyptalandi. Farið þangað niður og kaupið fyrir okkur korn þaðan, svo að við lifum og deyjum ekki.'),
(1256, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 3, 'OT', 'Bræður Jósefs, tíu talsins, fóru niður til að kaupa korn frá Egyptalandi.'),
(1257, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 4, 'OT', 'En Benjamín, bróður Jósefs, sendi Jakob ekki með bræðrum sínum, því að hann sagði: Svo að ekki henti hann slys.'),
(1258, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 5, 'OT', 'Synir Ísraels komu til að kaupa korn ásamt þeim sem komu, því að hungursneyðin var í jörð Kanaans.'),
(1259, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 6, 'OT', 'Jósef var landstjóri yfir jörðinni, og hann seldi öllum lýðnum á jörðinni. Bræður Jósefs komu og lutu honum með andlitinu til jarðar.'),
(1260, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 7, 'OT', 'Jósef sá bræður sína og kannaðist við þá, en lét eins og hann þekkti þá ekki. Hann talaði harkalega við þá og sagði: Hvaðan komið þið? Þeir sögðu: Úr jörð Kanaans til að kaupa mat.'),
(1261, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 8, 'OT', 'Jósef þekkti bræður sína, en þeir þekktu hann ekki.'),
(1262, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 9, 'OT', 'Jósef minntist draumanna sem hann hafði dreymt um þá. Hann sagði við þá: Njósnarar eruð þið; þið eruð komnir til að skoða nekt jarðarinnar.'),
(1263, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 10, 'OT', 'Þeir sögðu við hann: Nei, herra minn; þjónar þínir komu til að kaupa mat.'),
(1264, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 11, 'OT', 'Við erum allir synir eins manns; við erum heiðarlegir menn, þjónar þínir eru ekki njósnarar.'),
(1265, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 12, 'OT', 'Hann sagði: Nei, heldur eruð þið komnir til að skoða nekt jarðarinnar.'),
(1266, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 13, 'OT', 'Þeir sögðu: Við þjónar þínir erum tólf bræður, synir eins manns í jörð Kanaans. Og sjá, sá yngsti er hjá föður okkar í dag, og hinn er ekki til.'),
(1267, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 14, 'OT', 'Jósef sagði við þá: Þetta er það sem ég sagði við ykkur: Njósnarar eruð þið.'),
(1268, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 15, 'OT', 'Með þessu verður ykkur prófað: Svo sannarlega sem Faraó lifir, þið farið ekki héðan nema yngsti bróðir ykkar komi hingað.'),
(1269, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 16, 'OT', 'Sendið einn af ykkur til að sækja bróður ykkar, en þið sjálfir verðið settir í varðstöðu, svo að orð ykkar verði prófuð hvort þau séu í sannleika. Ef ekki, svo sannarlega sem Faraó lifir, þá eruð þið njósnarar.'),
(1270, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 17, 'OT', 'Og hann setti þá í varðstöðu í þrjá daga.'),
(1271, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 18, 'OT', 'Á þriðja degi sagði Jósef við þá: Gerið þetta og lifið, því að ég óttast Guð.'),
(1272, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 19, 'OT', 'Ef þið eruð heiðarlegir, þá sé einn af bræðrum ykkar bundinn í húsi varðstöðu ykkar. En þið farið og flytjið korn til hungursneyðar í hús ykkar.'),
(1273, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 20, 'OT', 'En yngsta bróður ykkar skuluð þið koma með til mín; þá mun orð ykkar reynast satt og þér deyið ekki. Og þeir gerðu svo.'),
(1274, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 21, 'OT', 'Þá sagði hver maður við bróður sinn: Sannarlega erum við sekir um bróður okkar, því að við sáum neyð sálar hans þegar hann bað okkur miskunnar, en við hlýddum ekki. Þess vegna er þessi neyð komin yfir okkur.'),
(1275, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 22, 'OT', 'Rúben svaraði þeim: Sagði ég ekki við ykkur: Syndgið ekki gegn drengnum? En þið hlýddust ekki. Og nú er blóð hans krafist.'),
(1276, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 23, 'OT', 'Þeir vissu ekki að Jósef heyrði það, því að túlkurinn var milli þeirra.'),
(1277, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 24, 'OT', 'Og hann sneri sér frá þeim og grét. Síðan sneri hann aftur til þeirra og talaði við þá, og hann tók Símeon frá þeim og batt hann fyrir augum þeirra.'),
(1278, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 25, 'OT', 'Jósef gaf skipun um að fylla áhöld þeirra með korni og skila silfri hvers manns í hærusekk hans, og gefa þeim vistir á veginum. Og þannig var við þá gert.'),
(1279, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 26, 'OT', 'Þeir létu korn sitt á asna sína og héldu þaðan burt.'),
(1280, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 27, 'OT', 'Einn þeirra opnaði hærusekk sinn til að gefa asna sínum skepnufóður á náttstaðnum. Hann sá silfur sitt, og sjá, það var í munni pokans.'),
(1281, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 28, 'OT', 'Og hann sagði við bræður sína: Silfur mitt hefur verið endurgreitt; og sjá, það er í poka mínum. Þá féll hjarta þeirra, og þeir urðu hræddir. Sérhver maður sneri sér að bróður sínum og sagði: Hvað hefur Guð gert við okkur?'),
(1282, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 29, 'OT', 'Þeir komu til Jakobs, föður síns, til jarðar Kanaans og sögðu honum allt það sem hafði komið fyrir þá.'),
(1283, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 30, 'OT', 'Maðurinn, herra jarðarinnar, talaði harkalega við okkur og tók okkur fyrir njósnara jarðarinnar.'),
(1284, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 31, 'OT', 'Og við sögðum við hann: Við erum heiðarlegir, við vorum ekki njósnarar.'),
(1285, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 32, 'OT', 'Við erum tólf bræður, synir föður okkar; einn er horfinn, og hinn yngsti er í dag hjá föður okkar í jörð Kanaans.'),
(1286, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 33, 'OT', 'Maðurinn, herra jarðarinnar, sagði við okkur: Á þessu skal ég marka að þið eruð heiðarlegir: Skiljið eftir hjá mér einn af bræðrum ykkar og takið korn til hungursneyðar í húsum ykkar, og farið.'),
(1287, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 34, 'OT', 'Og færið mér yngsta bróður ykkar; þá veit ég að þið eruð ekki njósnarar, heldur heiðarlegir. Þá gef ég ykkur bróður ykkar, og þið munuð versla í jörðinni.'),
(1288, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 35, 'OT', 'Og þegar þeir tæmdu hærusekki sína, sjá, þá var knippi silfurs hvers manns í hærusekk hans. Og þegar þeir og faðir þeirra sáu knippin af silfri sínu, óttuðust þeir.'),
(1289, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 36, 'OT', 'Og Jakob, faðir þeirra, sagði við þá: Þið hafið sviptað mig börnunum. Jósef er ekki til, og Símeon er ekki til, og Benjamín viljið þið taka. Allt þetta kemur yfir mig.'),
(1290, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 37, 'OT', 'Rúben sagði við föður sinn: Þú mátt drepa tvo sonu mína, ef ég kem ekki með hann aftur til þín. Fel hann í mína hönd, og ég skal skila honum aftur til þín.'),
(1291, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 42, 38, 'OT', 'Jakob sagði: Sonur minn skal ekki fara með ykkur, því að bróðir hans er dáinn og hann er einn eftir. Ef slys henda hann á veginum sem þið farið, þá munuð þið færa grátt hár mitt með sorg niður til Helju.'),
(1292, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 1, 'OT', 'Og hungursneyðin var þung í jörðinni.'),
(1293, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 2, 'OT', 'Og þegar þeir höfðu étið upp kornið sem þeir höfðu flutt frá Egyptalandi, sagði faðir þeirra við þá: Farið aftur og kaupið fyrir okkur lítið mat.'),
(1294, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 3, 'OT', 'Júda sagði við hann: Maðurinn hefur í alvöru varað okkur við: Þér munuð ekki sjá andlit mitt nema bróðir ykkar sé með ykkur.'),
(1295, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 4, 'OT', 'Ef þú vilt senda bróður okkar með okkur, förum við niður og kaupum mat handa þér.'),
(1296, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 5, 'OT', 'En ef þú vilt ekki senda hann, förum við ekki niður, því að maðurinn sagði við okkur: Þér munuð ekki sjá andlit mitt nema bróðir ykkar sé með ykkur.'),
(1297, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 6, 'OT', 'Ísrael sagði: Hví gerðuð þið mér þetta illt, að segja manninum að þið ættuð enn annan bróður?'),
(1298, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 7, 'OT', 'Þeir sögðu: Maðurinn spurði okkur nákvæmlega um okkur sjálfa og ætt okkar, og sagði: Lifir faðir ykkar enn? Á hann annan bróður? Og við sögðum honum eftir þessum orðum. Hvernig áttum við að vita að hann myndi segja: Færið bróður ykkar niður?'),
(1299, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 8, 'OT', 'Júda sagði við Ísrael, föður sinn: Send sveininn með mér, og við skulum leggja af stað og fara, og við munum lifa og ekki deyja, bæði við, þú og börn okkar.'),
(1300, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 9, 'OT', 'Ég skal ábyrgjast hann; af minni hendi skalt þú krefjast hans. Ef ég færi hann ekki aftur til þín og legg hann ekki fyrir andlitið þitt, þá sé ég sekur gagnvart þér alla daga.'),
(1301, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 10, 'OT', 'Því að ef við hefðum ekki dregið þetta á langinn, hefðum við nú snúið aftur tvisvar sinnum.'),
(1302, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 11, 'OT', 'Þá sagði Ísrael, faðir þeirra, við þá: Ef svo er, þá gerið þetta: Takið úrvalsávöxt jarðarinnar í áhöldum ykkar og færið manninum fórn: dálítið af smyrsli og dálítið af hunangi, ilmjurt og myrru, hnetur og möndlur úr möndlutrjám.'),
(1303, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 12, 'OT', 'Takið einnig tvöfalt afrit silfurs í hendur ykkar, og silfrið sem skilað var í munn pokanna ykkar skuluð þið skila í hendur ykkar; kannski er það mistök.'),
(1304, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 13, 'OT', 'Takið líka bróður ykkar, standið upp og farið aftur til mannsins.'),
(1305, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 14, 'OT', 'Og Almáttugur Guð gefi ykkur miskunn fyrir andliti mannsins, svo að hann sendi ykkur hinn bróðurinn og Benjamín. Og ég, ef ég er sviptur börnum mínum, þá er ég sviptur þeim.'),
(1306, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 15, 'OT', 'Mennirnir tóku fórnina, og tvöfalt afrit silfurs tóku þeir í hendur sínar, og Benjamín. Þeir risu upp, fóru niður til Egyptalands og stóðu fyrir andliti Jósefs.'),
(1307, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 16, 'OT', 'Þegar Jósef sá Benjamín með þeim, sagði hann við ráðsmann húss síns: Far með mennina inn í húsið, og gerðu slátrun og undirbúðu mat, því að mennirnir skulu borða með mér í hádeginu.'),
(1308, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 17, 'OT', 'Maðurinn gerði eins og Jósef hafði sagt, og maðurinn leiddi mennina inn í hús Jósefs.'),
(1309, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 18, 'OT', 'En mennirnir urðu hræddir, þegar þeir voru leiddir inn í hús Jósefs, og þeir sögðu: Vegna orðsins um silfrið sem skilað var í pokum okkar í upphafi erum við leiddir hingað, til að ráðast á okkur, yfirbuga okkur, taka okkur sem þjóna og asna okkar.'),
(1310, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 19, 'OT', 'Þeir gengu að manninum sem var yfir húsi Jósefs og töluðu við hann við inngangi hússins.'),
(1311, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 20, 'OT', 'Og þeir sögðu: Ó, herra minn, í upphafi komum við niður til að kaupa mat.'),
(1312, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 21, 'OT', 'Og þegar við komum á náttstaðinn og opnuðum poka okkar, sjá, þá var silfur hvers manns í munni pokans, silfur okkar í fullri vigt; og við skiluðum því aftur í hendur okkar.'),
(1313, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 22, 'OT', 'Og annað silfur höfum við fært með okkur í hendur okkar til að kaupa mat, og við vitum ekki hver lagði silfur okkar í poka okkar.'),
(1314, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 23, 'OT', 'Og hann sagði: Friður sé með yður; óttist ekki. Guð yðar og Guð föður yðar hefur gefið yður falinn fjársjóð í pokum yðar; silfur yðar kom til mín. Og hann leiddi Símeon út til þeirra.'),
(1315, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 24, 'OT', 'Maðurinn leiddi mennina inn í hús Jósefs, og hann gaf þeim vatn; þeir þvoðu fætur sína, og hann gaf asnum þeirra skepnufóður.'),
(1316, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 25, 'OT', 'Og þeir bjuggu fórnina til þar til Jósef kæmi um hádegið, því að þeir höfðu heyrt að þeir myndu borða brauð þar.'),
(1317, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 26, 'OT', 'Jósef kom heim, og þeir færðu honum fórnina sem var í höndum þeirra inn í húsið, og þeir féllu fram fyrir honum til jarðar.'),
(1318, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 27, 'OT', 'Hann spurði þá um frið þeirra og sagði: Er faðir yðar, gamli maðurinn sem þér sögðuð mér frá, enn á lífi?'),
(1319, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 28, 'OT', 'Þeir svöruðu: Friður sé með þjóni þínum, föður okkar; hann er enn á lífi. Og þeir hneigðu sig og féllu fram.'),
(1320, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 29, 'OT', 'Og hann lyfti augunum og sá Benjamín, bróður sinn, son móður sinnar, og sagði: Er þetta yngsti bróðir ykkar, sem þér sögðuð mér frá? Og hann sagði: Guð sé þér náðugur, sonur minn.'),
(1321, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 30, 'OT', 'Og Jósef flýtti sér, því að hjarta hans brann af miskunn við bróður sinn, og hann leitaði að stað til að gráta; og hann gekk inn í herbergið og grét þar.'),
(1322, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 31, 'OT', 'Hann þvoði andlit sitt, gekk út og stillti sig, og sagði: Berið fram brauð.'),
(1323, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 32, 'OT', 'Þeir báru fram fyrir hann sérstaklega, og fyrir þá sérstaklega, og fyrir Egypta sem snæddu með honum sérstaklega, því að Egyptar gátu ekki snætt brauð með Hebreum, sem er viðurstyggð fyrir Egypta.'),
(1324, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 33, 'OT', 'Þeir sátu fyrir andliti hans, frumgetinn eftir frumburðarrétti sínum og hinn yngsti eftir æsku sinni. Og mennirnir undruðust, maður við annan.'),
(1325, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 43, 34, 'OT', 'Og hann tók merki af andliti sínu og sendi þeim; merki Benjamíns var fimm sinnum meira en merki þeirra allra. Og þeir drukku og urðu drukknir með honum.'),
(1326, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 1, 'OT', 'Og hann bauð þeim sem var yfir húsi sínu og sagði: Fylltu poka mannanna með mat, svo mikið sem þeir geta borið, og legg silfur hvers manns í munn poka hans.'),
(1327, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 2, 'OT', 'Og bikar minn, silfurbikarinn, skalt þú leggja í munn poka hins yngsta, ásamt silfri korns hans. Og hann gerði eftir orði Jósefs sem hann hafði talað.'),
(1328, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 3, 'OT', 'Þegar morguninn var kominn og birta, voru mennirnir sendir af stað, þeir og asnar þeirra.'),
(1329, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 4, 'OT', 'Þeir voru komnir út úr borginni, en ekki langt; og Jósef sagði við þann sem var yfir húsi hans: Rís upp, elta mennina, og þegar þú nærð þeim, seg við þá: Hví hafið þið goldið illt fyrir gott?'),
(1330, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 5, 'OT', 'Er þetta ekki bikarinn sem herra minn drekkur úr og sem hann notar til að spá með? Þið hafið illa gert það sem þið gerðuð.'),
(1331, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 6, 'OT', 'Hann náði þeim og talaði við þá þessi orð.'),
(1332, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 7, 'OT', 'Þeir sögðu við hann: Hví talar herra minn þvílík orð? Fjarri sé það þjónum þínum að gera slíkt.'),
(1333, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 8, 'OT', 'Sjá, silfrið sem við fundum í munni poka okkar skiluðum við þér aftur úr jörð Kanaans, og hvernig ættum við þá að stela silfri eða gulli úr húsi herra þíns?'),
(1334, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 9, 'OT', 'Sá sem finnst með það af þjónum þínum skal deyja, og við munum einnig verða þjónar herra míns.'),
(1335, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 10, 'OT', 'Og hann sagði: Já, eins og orð ykkar eru, svo sé það: sá sem finnst með það skal verða þjónn minn, en þið skuluð vera saklausir.'),
(1336, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 11, 'OT', 'Þeir fljótuðu sér og settu hver maður poka sinn niður til jarðar, og hver opnaði poka sinn.'),
(1337, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 12, 'OT', 'Hann leitaði frá þeim elsta og til þess yngsta, og bikarinn fannst í poka Benjamíns.'),
(1338, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 13, 'OT', 'Þá rifu þeir skikkjur sínar, og hver maður hlóð asna sinn, og þeir sneru aftur til borgarinnar.'),
(1339, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 14, 'OT', 'Júda og bræður hans komu í hús Jósefs; hann var þar enn, og þeir féllu fram fyrir andliti hans til jarðar.'),
(1340, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 15, 'OT', 'Jósef sagði við þá: Hvaða verk er þetta sem þið hafið gert? Vitið þið ekki að maður eins og ég getur fyllilega spáð?'),
(1341, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 16, 'OT', 'Júda sagði: Hvað eigum við að segja herra mínum? Hvað eigum við að tala, og hvernig getum við réttlætt okkur? Guð hefur fundið misgjörð þjóna þinna; sjá, við erum þjónar herra míns, bæði við og sá sem bikarinn fannst í hendi hans.'),
(1342, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 17, 'OT', 'Hann sagði: Fjarri sé það mér að gera þetta; maðurinn sem bikarinn fannst í hendi hans skal verða þjónn minn, en þér farið upp í friði til föður yðar.'),
(1343, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 18, 'OT', 'Júda gekk að honum og sagði: Ó herra minn, leyf þjóni þínum að tala orð í eyru herra míns, og lát ekki reiði þína brenna gegn þjóni þínum, því að þú ert eins og Faraó.'),
(1344, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 19, 'OT', 'Herra minn spurði þjóna sína: Eigið þið föður eða bróður?'),
(1345, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 20, 'OT', 'Við sögðum við herra minn: Við eigum gamlan föður og ungan dreng, barn ellinnar, sem er minnstur. Bróðir hans er dáinn, og hann einn er eftir af móður sinni, og faðir hans elskar hann.'),
(1346, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 21, 'OT', 'Þú sagðir við þjóna þína: Færið hann til mín, svo að ég geti haft augu mín á honum.'),
(1347, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 22, 'OT', 'Við sögðum við herra minn: Sveinninn getur ekki yfirgefið föður sinn, því að ef hann yfirgefur föður sinn, þá deyr hann.'),
(1348, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 23, 'OT', 'En þú sagðir við þjóna þína: Nema yngsti bróðir ykkar komi með ykkur, munuð þið ekki framar sjá andlit mitt.'),
(1349, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 24, 'OT', 'Og svo bar við að við fórum upp til föður míns, þjóns þíns, og sögðum honum orð herra míns.'),
(1350, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 25, 'OT', 'Og faðir okkar sagði: Farið aftur og kaupið fyrir okkur lítið mat.'),
(1351, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 26, 'OT', 'Og vér sögðum: Vér getum ekki farið niður. Ef yngsti bróðir vor er með oss, þá förum vér niður, því að vér getum ekki séð andlit mannsins, þegar yngsti bróðir vor er ekki með oss.'),
(1352, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 27, 'OT', 'Og hann sagði: Þjónn þinn, faðir minn, sagði við okkur: Þér vitið að kona mín ól mér tvo syni.'),
(1353, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 28, 'OT', 'Annar þeirra gekk frá mér, og ég sagði: Vissulega er hann rifinn í tætlur. Og ég hef ekki séð hann allt til þessa.'),
(1354, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 29, 'OT', 'Ef þér takið einnig þennan frá mínu andliti, og honum verður eitthvert slys, þá munuð þér koma gráu hári mínu með harmi niður til Heljar.'),
(1355, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 30, 'OT', 'Og nú, þegar ég kem til þjóns þíns, föður míns, og sveinninn er ekki með okkur, þá er sál hans bundin við sálu hans.'),
(1356, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 31, 'OT', 'Og verður þegar hann sér að sveinninn er ekki til, þá deyr hann; og þjónar þínir munu koma gráu hári þjóns þíns, föður vors, með sorg niður til Heljar.'),
(1357, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 32, 'OT', 'Því að þjónn þinn gekk í ábyrgð fyrir sveininn við föður minn og sagði: Ef ég færi hann ekki aftur til þín, þá beri ég sökina gagnvart föður mínum alla daga.'),
(1358, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 33, 'OT', 'Og nú, lát þjón þinn sitja í stað sveinsins sem þjónn herra míns, og lát sveininn fara upp með bræðrum sínum.'),
(1359, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 44, 34, 'OT', 'Því að hvernig á ég að fara upp til föður míns, og sveinninn er ekki með mér? Ég vil ekki sjá þá ógæfu sem mun henda föður minn.'),
(1360, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 1, 'OT', 'Og Jósef gat ekki stillt sig gagnvart öllum þeim sem stóðu hjá honum, og hann kallaði: Látið alla menn fara út frá mér. Og enginn maður var hjá honum þegar Jósef gerði sig þekktan fyrir bræðrum sínum.'),
(1361, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 2, 'OT', 'Og hann gaf upp rödd sína í gráti, og Egyptar heyrðu það, og hús Faraós heyrði það.'),
(1362, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 3, 'OT', 'Og Jósef sagði við bræður sína: Ég er Jósef. Lifir faðir minn enn? Og bræður hans gátu ekki svarað honum, því að þeir urðu skelfdir frammi fyrir andliti hans.'),
(1363, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 4, 'OT', 'Og Jósef sagði við bræður sína: Komið nær mér. Og þeir gengu nær. Og hann sagði: Ég er Jósef, bróðir yðar, sem þér seldu til Egyptalands.'),
(1364, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 5, 'OT', 'Og nú, hryggist ekki og reiðist ekki í augum yðar, af því að þér seldu mig hingað; því að Guð sendi mig á undan yður til lífsviðurværis.'),
(1365, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 6, 'OT', 'Því að nú eru tvö ár liðin af hungursneyðinni í landinu, og enn eru fimm ár eftir, þar sem hvorki er plægingartími né uppskerutími.'),
(1366, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 7, 'OT', 'Og Guð sendi mig á undan yður til að varðveita handa yður leif á jörðinni og halda lífi í yður til mikillar undankomu.'),
(1367, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 8, 'OT', 'Og nú eruð það ekki þér sem sendu mig hingað, heldur Guð. Hann hefur gert mig að föður Faraós og herra alls húss hans og drottnara yfir öllu Egyptalandi.'),
(1368, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 9, 'OT', 'Flýtið yður og farið upp til föður míns og segið við hann: Svo segir sonur þinn Jósef: Guð hefur gert mig að herra alls Egyptalands. Kom niður til mín, dvel ekki.'),
(1369, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 10, 'OT', 'Þú skalt búa í Gósenlandi og vera mér nærri, þú og synir þínir og synir sona þinna, og sauðfé þitt og naut þín og allt sem þú átt.'),
(1370, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 11, 'OT', 'Þar mun ég sjá fyrir þér, því að enn eru fimm ár hungursneyðar eftir; til þess að þú og hús þitt og allt sem þú átt farist ekki í neyð.'),
(1371, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 12, 'OT', 'Og sjá, augu yðar sjá og augu bróður míns Benjamíns, að það er munnur minn sem talar við yður.'),
(1372, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 13, 'OT', 'Og segið föður mínum frá allri dýrð minni í Egyptalandi og frá öllu sem þér hafið séð. Flýtið yður og komið með föður minn hingað niður.'),
(1373, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 14, 'OT', 'Og hann féll um háls Benjamíns bróður síns og grét, og Benjamín grét á hálsi hans.'),
(1374, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 15, 'OT', 'Og hann kyssti alla bræður sína og grét yfir þeim. Eftir það töluðu bræður hans við hann.'),
(1375, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 16, 'OT', 'Og röddin barst í hús Faraós: Bræður Jósefs eru komnir. Og það var vel séð í augum Faraós og þjóna hans.'),
(1376, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 17, 'OT', 'Og Faraó sagði við Jósef: Seg bræðrum þínum: Gerið þetta: hlaðið fénaði yðar og farið, komið til jarðar Kanaans.'),
(1377, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 18, 'OT', 'Takið föður yðar og hús yðar og komið til mín, og ég mun gefa yður gæði Egyptalands, og þér munuð eta fitu jarðarinnar.'),
(1378, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 19, 'OT', 'Og þú ert boðinn: Gerið þetta: takið yður vagna úr jörð Egyptalands handa börnum yðar og konum yðar, og berið föður yðar og komið.'),
(1379, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 20, 'OT', 'Og augu yðar sjái ekki eftir áhöldum yðar, því að gæði alls Egyptalands eru yðar.'),
(1380, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 21, 'OT', 'Og synir Ísraels gerðu svo. Og Jósef gaf þeim vagna eftir munni Faraós, og gaf þeim vistir til vegarins.'),
(1381, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 22, 'OT', 'Hverjum manni gaf hann breytingar á skikkjum, en Benjamíni gaf hann þrjú hundruð silfurs og fimm breytingar á skikkjum.'),
(1382, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 23, 'OT', 'Og föður sínum sendi hann á sama hátt tíu asna hlaðna því besta af gæðum Egyptalands, og tíu ösnur hlaðnar korni, brauði og mat handa föður sínum til vegarins.'),
(1383, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 24, 'OT', 'Og hann lét bræður sína fara, og þeir fóru. Og hann sagði við þá: Verið ekki í uppnámi á veginum.'),
(1384, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 25, 'OT', 'Þeir fóru upp frá Egyptalandi og komu til jarðar Kanaans, til Jakobs föður síns.'),
(1385, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 26, 'OT', 'Og þeir sögðu honum: Jósef er enn á lífi, og hann drottnar yfir öllu Egyptalandi. Og hjarta hans brást honum, því að hann trúði þeim ekki.'),
(1386, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 27, 'OT', 'Og þeir sögðu honum öll orð Jósefs, sem hann hafði talað við þá; og þegar hann sá vagnana sem Jósef hafði sent til að flytja hann, lifnaði andi Jakobs, föður þeirra.'),
(1387, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 45, 28, 'OT', 'Og Ísrael sagði: Nóg er komið. Jósef sonur minn er enn á lífi. Ég vil fara og sjá hann áður en ég dey.'),
(1388, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 1, 'OT', 'Og Ísrael lagði af stað með allt sem hann átti og kom til Beerseba og færði sláturfórnir Guði föður síns, Ísaks.'),
(1389, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 2, 'OT', 'Og Guð talaði við Ísrael í sjónum næturinnar og sagði: Jakob, Jakob! Og hann sagði: Hér er ég.'),
(1390, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 3, 'OT', 'Og hann sagði: Ég er Guð, Guð föður þíns. Óttastu ekki að fara niður til Egyptalands, því að ég mun gera þig að mikilli þjóð þar.'),
(1391, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 4, 'OT', 'Ég mun fara með þér niður til Egyptalands, og ég mun einnig leiða þig upp aftur; og Jósef mun leggja hönd sína á augu þín.'),
(1392, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 5, 'OT', 'Og Jakob lagði af stað frá Beerseba, og synir Ísraels fluttu Jakob föður sinn og börnin þeirra og konur þeirra á vögnunum sem Faraó hafði sent til að flytja hann.'),
(1393, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 6, 'OT', 'Og þeir tóku fénað sinn og eignir sínar, sem þeir höfðu aflað í Kanaan, og fóru til Egyptalands, Jakob og allt afkvæmi hans með honum.'),
(1394, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 7, 'OT', 'Synir hans og synir sona hans voru með honum, dætur hans og dætur sona hans, og allt afkvæmi hans kom hann með sér til Egyptalands.'),
(1395, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 8, 'OT', 'Og þetta eru nöfn sona Ísraels, þeirra sem komu til Egyptalands: Jakob og synir hans. Rúben var frumgetinn Jakobs.'),
(1396, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 9, 'OT', 'Synir Rúbens voru Enok, Pallú, Hesron og Karmí.'),
(1397, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 10, 'OT', 'Synir Símeons voru Jemúel, Jamín, Óhad, Jakín, Sóhar og Sál, sonur Kanaanítinnar.'),
(1398, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 11, 'OT', 'Synir Leví voru Gerson, Kahat og Merarí.'),
(1399, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 12, 'OT', 'Synir Júda voru Er, Ónan, Sela, Peres og Sera. Og Er og Ónan dóu í landi Kanaans, og synir Peresar voru Hesron og Hamúl.'),
(1400, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 13, 'OT', 'Synir Íssakars voru Tóla, Púa, Job og Símron.'),
(1401, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 14, 'OT', 'Og synir Sebúlons voru Sered, Elon og Jahleel.'),
(1402, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 15, 'OT', 'Þetta eru synir þeir sem Lea ól Jakobi í Paddan Aram, ásamt dóttur sinni Dínu; allar sálir sona hans og dætra voru þrjátíu og þrjár.'),
(1403, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 16, 'OT', 'Synir Gaðs voru Sifjon, Haggíti, Súní, Esbon, Erí, Aródí og Arelí.'),
(1404, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 17, 'OT', 'Synir Assers voru Jimna, Jísva, Jisví og Bería, og systir þeirra Sera. Synir Bería voru Heber og Malkíel.'),
(1405, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 18, 'OT', 'Þessir eru synir Silpu, sem Laban gaf Leu dóttur sinni, og hún ól þá Jakobi: sextán sálir.'),
(1406, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 19, 'OT', 'Synir Rakelar, sem var kona Jakobs, voru Jósef og Benjamín.'),
(1407, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 20, 'OT', 'Og Jósef eignaðist í Egyptalandi synina Manasse og Efraím, sem Asenat, dóttir Pótífera prests í On, ól honum.'),
(1408, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 21, 'OT', 'Synir Benjamíns voru Bela, Beker, Asbel, Gera, Naaman, Eki, Rós, Muppím, Húppím og Ard.'),
(1409, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 22, 'OT', 'Þessir eru synir Rakelar, sem fæddust Jakobi; allar sálir voru fjórtán.'),
(1410, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 23, 'OT', 'Synir Dans voru Húsím.'),
(1411, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 24, 'OT', 'Synir Naftalí voru Jahseel, Gúní, Jeser og Sillem.'),
(1412, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 25, 'OT', 'Þessir eru synir Bilhu, sem Laban gaf Rakel dóttur sinni, og hún ól þá Jakobi; allar sálir voru sjö.'),
(1413, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 26, 'OT', 'Allar sálir sem komu með Jakobi til Egyptalands, þær sem komnar voru af lærum hans, auk kvenna sona Jakobs, voru alls sextíu og sex sálir.'),
(1414, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 27, 'OT', 'Og synir Jósefs, sem fæddust honum í Egyptalandi, voru tvær sálir. Allar sálir af húsi Jakobs, sem komu til Egyptalands, voru sjötíu.'),
(1415, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 28, 'OT', 'Og Jakob sendi Júda á undan sér til Jósefs, til að vísa honum veginn til Gósen; og þeir komu til jarðar Gósen.'),
(1416, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 29, 'OT', 'Þá beislaði Jósef vagn sinn og fór í móti Ísrael, föður sínum, til Gósen. Og þegar hann sá hann, féll hann um háls hans og grét lengi á hálsi hans.'),
(1417, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 30, 'OT', 'Og Ísrael sagði við Jósef: Nú get ég dáið í þetta sinn, eftir að ég hef séð andlit þitt, því að þú lifir enn.'),
(1418, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 31, 'OT', 'Og Jósef sagði við bræður sína og við hús föður síns: Ég fer upp og segi Faraó það, og segi honum: Bræður mínir og hús föður míns, sem voru í Kanaan, eru komnir til mín.'),
(1419, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 32, 'OT', 'Og mennirnir eru hirðar sauðfjár, því að þeir hafa átt fénað; sauðfé þeirra og naut og allt sem þeir eiga, það hafa þeir komið með.'),
(1420, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 33, 'OT', 'Og verður það, þegar Faraó kallar á yður og spyr: Hver eru verk yðar?'),
(1421, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 46, 34, 'OT', 'Þá skuluð þér segja: Þjónar þínir hafa átt fénað frá æsku okkar og allt til þessa, bæði vér og feður vorir; svo að þér megið búa í Gósen, því að hver sá sem hirðir sauðfé er viðurstyggð Egyptum.'),
(1422, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 1, 'OT', 'Þá kom Jósef og sagði Faraó: faðir minn og bræður mínir, sauðfé þeirra og naut og allt sem þeir eiga, eru komin frá Kanaan; og sjá, þeir eru í Gósen.'),
(1423, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 2, 'OT', 'Og frá enda bræðra sinna tók hann fimm menn og stillti þeim fyrir andliti Faraós.'),
(1424, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 3, 'OT', 'Og Faraó sagði við bræður hans: Hver eru verk yðar? Og þeir sögðu við Faraó: þjónar þínir eru hirðar sauðfjár, bæði vér og feður vorir.'),
(1425, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 4, 'OT', 'Og þeir sögðu við Faraó: Vér erum komnir til að dvelja í landinu, því að engin beitiland er til fyrir sauðfé þjóna þinna, því að hungursneyðin er þung í Kanaan; og nú biðjum vér þig, að þjónar þínir fái að búa í Gósen.'),
(1426, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 5, 'OT', 'Og Faraó sagði við Jósef: faðir þinn og bræður þínir eru komnir til þín.'),
(1427, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 6, 'OT', 'Land Egyptalands liggur fyrir framan þig; settu föður þinn og bræður þína í úrvali landsins; þeir skulu búa í Gósen. Og ef þú veist að meðal þeirra eru menn með styrk, þá settu þá sem höfðingja yfir fénaði mínum.'),
(1428, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 7, 'OT', 'Og Jósef leiddi Jakob föður sinn og stillti honum fyrir andlit Faraós, og Jakob blessaði Faraó.'),
(1429, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 8, 'OT', 'Og Faraó sagði við Jakob: Hve mörg eru dagar ára þinna?'),
(1430, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 9, 'OT', 'Og Jakob sagði við Faraó: Dagar ára útlegðar minnar eru hundrað og þrjátíu ár; fá og vond hafa verið dagar ára ævi minnar, og þeir hafa ekki náð dögum ára feðra minna á dögum útlegðar þeirra.'),
(1431, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 10, 'OT', 'Og Jakob blessaði Faraó og gekk burt frá andliti Faraós.'),
(1432, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 11, 'OT', 'Og Jósef lét föður sinn og bræður sína setjast að og gaf þeim eignir í Egyptalandi, í úrvali landsins, í Raamses, eins og Faraó bauð.'),
(1433, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 12, 'OT', 'Og Jósef framfleytti föður sínum og bræðrum sínum og öllu húsi föður síns með brauði, eftir fjölda barnanna.'),
(1434, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 13, 'OT', 'Og brauð var ekki til í allri jörðinni, því að hungursneyðin var mjög þung; og land Egyptalands og land Kanaans voru örmagna vegna hungursneyðarinnar.'),
(1435, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 14, 'OT', 'Og Jósef safnaði saman öllu silfrinu sem fannst í Egyptalandi og Kanaan, fyrir kornið sem þeir keyptu; og Jósef flutti silfrið í hús Faraós.'),
(1436, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 15, 'OT', 'Og silfrið þvarr úr Egyptalandi og úr Kanaan, og allir Egyptar komu til Jósefs og sögðu: Gefðu oss brauð; hvers vegna eigum við að deyja fyrir augum þínum? Því að silfrið er þrotið.'),
(1437, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 16, 'OT', 'Og Jósef sagði: Gefið mér fénað yðar, og ég mun gefa yður fyrir fénað yðar, ef silfrið er þrotið.'),
(1438, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 17, 'OT', 'Og þeir fluttu fénað sinn til Jósefs, og Jósef gaf þeim brauð í skiptum fyrir hesta, sauðfé, naut og asna, og hann framfleytti þeim með brauði fyrir allt fénað þeirra það ár.'),
(1439, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 18, 'OT', 'Og þegar það ár var liðið, komu þeir til hans árið eftir og sögðu við hann: Vér viljum ekki leyna herra vorum, að silfrið er þrotið og fénaðurinn og skepnan tilheyra herranum; ekkert er eftir fyrir herra vorn nema lík vort og jörð vor.'),
(1440, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 19, 'OT', 'Hvers vegna eigum við að deyja fyrir augum þínum, bæði við og jörð vor? Kauptu okkur og jörð vora fyrir brauð, og við og jörð vor munum verða þjónar Faraós; gef oss sæði, að vér megum lifa og ekki deyja, og jörðin verði ekki í eyði.'),
(1441, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 20, 'OT', 'Og Jósef keypti alla jörð Egyptalands handa Faraó, því að Egyptar seldu hver sinn akur, því að hver maður seldi akur sinn, þar sem hungursneyðin var þung yfir þeim; og jörðin varð Faraós.'),
(1442, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 21, 'OT', 'Og lýðinn flutti hann til borganna, frá einum enda landamæra Egyptalands til hins endans.'),
(1443, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 22, 'OT', 'Aðeins jörð prestanna keypti hann ekki, því að prestunum voru ákveðin lög frá Faraó, og þeir átu af þeim lögum sem Faraó hafði gefið þeim; þess vegna seldu þeir ekki jörð sína.'),
(1444, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 23, 'OT', 'Og Jósef sagði við lýðinn: Sjá, ég hef keypt yður í dag og jörð yðar handa Faraó. Hér er sæði handa yður, og þér skuluð sá jörðina.'),
(1445, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 24, 'OT', 'Og þegar uppskeran kemur, skuluð þér gefa fimmtung Faraó, en fjórir hlutar skulu vera yðar, til sæðis akursins, til matar handa yður og handa þeim sem eru í húsum yðar, og til matar barna yðar.'),
(1446, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 25, 'OT', 'Og þeir sögðu: Þú hefur bjargað lífi okkar; vér höfum fundið hylli í augum herra vors, og vér munum vera þjónar Faraós.'),
(1447, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 26, 'OT', 'Og Jósef setti þetta að lögum allt til þessa dags, að fimmtungur skyldi vera Faraó á jörð Egyptalands; aðeins jörð prestanna var ekki Faraós.'),
(1448, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 27, 'OT', 'Og Ísrael settist að í Egyptalandi, í Gósen; og þeir eignuðust þar eignir, fjölgðu sér og margfölduðust mjög.'),
(1449, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 28, 'OT', 'Og Jakob lifði í Egyptalandi sautján ár, og dagar Jakobs voru hundrað fjörutíu og sjö ár.'),
(1450, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 29, 'OT', 'Og dagar Ísraels nálguðust dauðann, og hann kallaði á son sinn Jósef og sagði við hann: Ef ég hef fundið hylli í augum þínum, þá legg þú hönd þína undir læri mitt og gjör við mig miskunn og sannleika; grafðu mig ekki í Egyptalandi.'),
(1451, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 30, 'OT', 'Og ég mun leggjast hjá feðrum mínum, og þú skalt flytja mig burt frá Egyptalandi og grafa mig í greftrun þeirra. Og hann sagði: Ég mun gera eftir orði þínu.'),
(1452, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 47, 31, 'OT', 'Og hann sagði: Sverðu mér það. Og hann sór honum það. Og Ísrael laut yfir höfuð rekkjunnar.'),
(1453, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 1, 'OT', 'Og eftir þessi orð var sagt við Jósef: Sjá, faðir þinn er veikur. Og hann tók með sér báða sonu sína, Manasse og Efraím.'),
(1454, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 2, 'OT', 'Og það var sagt Jakob: Sjá, sonur þinn Jósef kemur til þín. Og Ísrael safnaði kröftum og settist upp á rekkjunni.'),
(1455, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 3, 'OT', 'Og Jakob sagði við Jósef: Almáttugur Guð birtist mér í Lús í Kanaan og blessaði mig.'),
(1456, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 4, 'OT', 'Hann sagði við mig: Sjá, ég mun gera þig frjósaman og fjölga þér, og ég mun gera þig að söfnuði lýða, og ég mun gefa sæði þínu eftir þig þessa jörð sem eign til eilífðar.'),
(1457, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 5, 'OT', 'Og nú, synir þínir tveir, sem fæddust þér í Egyptalandi áður en ég kom til þín til Egyptalands, þeir eru mínir; Efraím og Manasse skulu vera mínir eins og Rúben og Símeon.'),
(1458, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 6, 'OT', 'Og ætt þín, sem þú eignast eftir þá, skal vera þín; þau skulu kallast eftir nafni bræðra sinna í arfleifð sinni.'),
(1459, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 7, 'OT', 'En ég, þegar ég kom frá Paddan, dó Rakel hjá mér í Kanaan á veginum, þegar enn var nokkur spölur eftir til Efrata; og ég jarðaði hana þar á veginum til Efrata, sem er Betlehem.'),
(1460, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 8, 'OT', 'Og Ísrael sá sonu Jósefs og sagði: Hverjir eru þessir?'),
(1461, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 9, 'OT', 'Og Jósef sagði við föður sinn: Þeir eru synir mínir, sem Guð hefur gefið mér hér. Og hann sagði: Taktu þá til mín, svo að ég megi blessa þá.'),
(1462, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 10, 'OT', 'Og augu Ísraels voru orðin sljó af elli; hann gat ekki séð. Og hann lét þá nálgast sig, og hann kyssti þá og faðmaði þá.'),
(1463, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 11, 'OT', 'Og Ísrael sagði við Jósef: Ég hafði ekki gert ráð fyrir að sjá andlit þitt, og sjá, Guð hefur leyft mér að sjá einnig sæði þitt.'),
(1464, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 12, 'OT', 'Og Jósef tók þá frá hné föður síns og laut niður með andlitinu til jarðar.'),
(1465, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 13, 'OT', 'Og Jósef tók þá báða, Efraím í hægri hönd sína, á vinstri hönd Ísraels, og Manasse í vinstri hönd sína, á hægri hönd Ísraels, og lét þá nálgast hann.'),
(1466, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 14, 'OT', 'Og Ísrael rétti út hægri hönd sína og lagði hana á höfuð Efraíms, en hann var yngri, og lagði vinstri hönd sína á höfuð Manasse; hann krosslagði hendur sínar, því að Manasse var frumgetinn.'),
(1467, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 15, 'OT', 'Og hann blessaði Jósef og sagði: Guð, sem feður mínir Abraham og Ísak gengu fyrir andliti hans, Guð, sem hefur verið hirðir minn frá því ég var til þessa dags.'),
(1468, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 16, 'OT', 'Sendiboðinn sem frelsaði mig frá öllu illu, hann blessi sveinana; og nafn mitt og nafn feðra minna, Abrahams og Ísaks, sé nefnt yfir þeim, og þeir vaxi til fjölda á jörðinni.'),
(1469, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 17, 'OT', 'Og Jósef sá að faðir hans lagði hægri hönd sína á höfuð Efraíms, og það þótti honum illa í augum; og hann studdi hönd föður síns til að taka hana af höfði Efraíms og setja á höfuð Manasse.'),
(1470, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 18, 'OT', 'Og Jósef sagði við föður sinn: Ekki svo, faðir minn, því að þessi er frumgetinn; leggðu hægri hönd þína á höfuð hans.'),
(1471, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 19, 'OT', 'En faðir hans neitaði og sagði: Ég veit það, sonur minn, ég veit það; hann mun einnig verða að lýð, og hann mun einnig vaxa; en yngri bróðir hans mun vaxa meira en hann, og sæði hans mun verða að fjölda þjóða.'),
(1472, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 20, 'OT', 'Og hann blessaði þá þann dag og sagði: Með þér mun Ísrael blessa, og menn munu segja: Guð gjöri þig eins og Efraím og eins og Manasse. Og hann setti Efraím á undan Manasse.'),
(1473, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 21, 'OT', 'Og Ísrael sagði við Jósef: Sjá, ég dey; en Guð mun vera með yður og leiða yður aftur til jarðar feðra yðar.'),
(1474, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 48, 22, 'OT', 'Og ég gef þér einn hlut umfram bræður þína, sem ég tók af hendi Amoríta með sverði mínu og boga.'),
(1475, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 1, 'OT', 'Og Jakob kallaði á sonu sína og sagði: Safnist saman, og ég mun segja yður það sem mun henda yður á endi daganna.'),
(1476, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 2, 'OT', 'Safnist saman og hlýðið, synir Jakobs, og hlýðið Ísrael, föður yðar.'),
(1477, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 3, 'OT', 'Rúben, þú ert frumgetinn minn, kraftur minn og upphaf afls míns, mestur í upphefð og mestur í mætti.'),
(1478, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 4, 'OT', 'Þú ert óstöðugur maður eins og vatn, og skalt ekki skara fram úr; því að þú fórst upp í hvílu föður þíns; þá vanhelgaðir þú hvílu mína, hún steig upp.'),
(1479, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 5, 'OT', 'Símeon og Leví eru bræður; áhöld ofbeldisins eru sverð þeirra.'),
(1480, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 6, 'OT', 'Í ráðagerð þeirra komi sál mín ekki; í söfnuði þeirra sé dýrð mín ekki; því að í reiði sinni drápu þeir mann, og í velþóknun sinni lömuðu þeir naut.'),
(1481, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 7, 'OT', 'Bölvuð sé reiði þeirra, því að hún er harðneskjuleg, og heift þeirra, því að hún er grimm; ég mun skipta þeim í Jakob og dreifa þeim í Ísrael.'),
(1482, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 8, 'OT', 'Júda, þig skulu bræður þínir lofa; hönd þín skal vera á hálsi óvina þinna; synir föður þíns skulu lúta þér.'),
(1483, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 9, 'OT', 'Júda er ljónshvolpur; úr bráð ertu upp kominn, sonur minn. Hann kraup, lagðist sem ljón og sem ljónynja; hver mun vekja hann?'),
(1484, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 10, 'OT', 'Ættkvísl skal ekki víkja frá Júda, né veldisstafurinn frá milli fóta hans, uns Síló kemur; og söfnuður lýðanna skal hlýða honum.'),
(1485, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 11, 'OT', 'Hann bindur við vínviðinn asnafolald sitt og við úrvalsvínviðinn son asnu sinnar; hann þvær klæðnað sinn í víni og klæði sín í blóði vínberjanna.'),
(1486, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 12, 'OT', 'Augu hans eru rauðari en vín, og tennur hans hvítari en mjólk.'),
(1487, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 13, 'OT', 'Sebúlon mun búa við hafströnd, og hann mun vera við strönd skipa; og takmörk hans ná til Sídon.'),
(1488, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 14, 'OT', 'Íssakar er beinsterkur asni, sem liggur milli fjárgarðanna.'),
(1489, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 15, 'OT', 'Og hann sá að hvíldin var góð og jörðin yndisleg; og hann beygði öxl sína til að bera, og varð þrælkaður til nauðungarvinnu.'),
(1490, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 16, 'OT', 'Dan mun dæma lýð sinn, eins og ein af ættkvíslum Ísraels.'),
(1491, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 17, 'OT', 'Dan verði höggormur á veginum, naðra á stígnum, sem bítur hæla hestsins, svo að knapi hans fellur aftur á bak.'),
(1492, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 18, 'OT', 'Á hjálpræði þitt vona ég, Jahve.'),
(1493, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 19, 'OT', 'Gað, herflokkur mun herja á hann, en hann mun herja á hæla hans.'),
(1494, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 20, 'OT', 'Frá Asser: feitt er brauð hans, og hann mun gefa kræsingar konungs.'),
(1495, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 21, 'OT', 'Naftalí er hind, laus og sleppt, sem gefur orð af fegurð.'),
(1496, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 22, 'OT', 'Jósef er sonur ávaxtasamrar greinar, sonur ávaxtasamrar greinar við lind; dætur hans ganga yfir múrinn.'),
(1497, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 23, 'OT', 'Herrar örvanna sýndu honum fjandskap, skutu á hann og ofsóttu hann.'),
(1498, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 24, 'OT', 'En bogi hans var áfram stöðugur, og armar hans og hendur urðu liðugir af hendi hins volduga Jakobs; þaðan er hirðir, steinn Ísraels.'),
(1499, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 25, 'OT', 'Af Guði föður þíns, sem hjálpar þér, og af Almáttugum, sem blessar þig, með blessunum himinsins að ofan, blessunum undirdjúpsins sem liggur undir, blessunum brjóstanna og miskunnar.'),
(1500, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 26, 'OT', 'Blessanir föður þíns hafa farið fram úr blessunum forfeðra minna, allt að endimörkum eilífðarhæðanna; þær skulu vera á höfuð Jósefs og á hvirfil nasírea bræðra sinna.'),
(1501, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 27, 'OT', 'Benjamín er grimmur úlfur; að morgni etur hann bráð, og að kvöldi skiptir hann herfang.'),
(1502, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 28, 'OT', 'Allar þessar tólf eru ættkvíslir Ísraels; og þetta er það sem faðir þeirra talaði við þá, þegar hann blessaði þá; hver maður fékk sína blessun.'),
(1503, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 29, 'OT', 'Og hann bauð þeim og sagði við þá: Ég verð lagður til lýðs míns. Grafið mig hjá feðrum mínum í helli sem er í akri Efrons Hetíta.'),
(1504, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 30, 'OT', 'Í helli sem er í akri Makpela, fyrir andliti Mamre, í jörð Kanaans, sem Abraham keypti af Efron Hetíta til grafar og eignar.'),
(1505, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 31, 'OT', 'Þar grófu þeir Abraham og Söru, konu hans; þar grófu þeir Ísak og Rebekku, konu hans; og þar jarðsetti ég Leu.'),
(1506, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 32, 'OT', 'Akurinn og hellirinn sem í honum er voru keyptir af sonum Hets.'),
(1507, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 49, 33, 'OT', 'Jakob lauk við að bjóða sonum sínum. Hann dró fætur sína upp í rekkju, andaðist og var lagður til lýðs síns.'),
(1508, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 1, 'OT', 'Jósef féll á andlit föður síns, grét yfir honum og kyssti hann.'),
(1509, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 2, 'OT', 'Jósef bauð þjónum sínum, læknunum, að balsamera föður sinn; og læknarnir balsameruðu Ísrael.'),
(1510, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 3, 'OT', 'Fjörutíu dagar liðu að því loknu, því að svo lengi tekur að balsamera; og Egyptar grétu hann í sjötíu daga.'),
(1511, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 4, 'OT', 'Þegar dagar harms hans voru liðnir, talaði Jósef við hús Faraós og sagði: Ef ég hef fundið náð í augum yðar, talið þá við eyru Faraós og segið:'),
(1512, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 5, 'OT', 'Faðir minn lét mig sverja og sagði: Sjá, ég er að deyja. Í gröf minni, sem ég hef grafið mér í jörð Kanaans, þar skalt þú grafa mig. Nú vil ég fara upp og grafa föður minn, og síðan kem ég aftur.'),
(1513, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 6, 'OT', 'Faraó sagði: Farðu upp og grafðu föður þinn, eins og hann lét þig sverja.'),
(1514, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 7, 'OT', 'Jósef fór upp til að grafa föður sinn; með honum fóru allir þjónar Faraós, öldungar húss hans og allir öldungar Egyptalands.'),
(1515, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 8, 'OT', 'Allt hús Jósefs, bræður hans og hús föður hans; aðeins börn þeirra, sauðfé og naut létu þeir eftir í jörð Gósen.'),
(1516, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 9, 'OT', 'Með honum fóru bæði vagnar og riddarar, og fylgdin var mjög mikil eins og herbúðir.'),
(1517, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 10, 'OT', 'Þeir komu að þreskivelli Atads, sem er handan Jórdanar, og þar héldu þeir mikinn harm, mjög mikinn; og hann gerði sorg fyrir föður sinn í sjö daga.'),
(1518, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 11, 'OT', 'Kanaanítar, íbúar jarðar, sáu sorg á þreskivelli Atads og sögðu: Þetta er þung sorg fyrir Egypta. Þess vegna var nafn þess kallað Abel-Mísraím, sem er handan Jórdanar.'),
(1519, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 12, 'OT', 'Synir hans gerðu honum svo sem hann hafði boðið þeim.'),
(1520, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 13, 'OT', 'Synir hans fluttu hann til jarðar Kanaans og grófu hann í helli á akri Makpela, sem Abraham hafði keypt af Efron Hetíta sem eign til grafar, gegnt Mamre.'),
(1521, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 14, 'OT', 'Jósef sneri aftur til Egyptalands, hann og bræður hans og allir sem fóru með honum til að grafa föður sinn, eftir að hann hafði grafið föður sinn.'),
(1522, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 15, 'OT', 'Þegar bræður Jósefs sáu að faðir þeirra var dáinn, sögðu þeir: Kannski hatar Jósef okkur, og hann mun endurgjalda okkur allt það illa sem við gerðum honum.'),
(1523, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 16, 'OT', 'Þeir sendu boð til Jósefs og sögðu: Faðir þinn bauð fyrir dauða sinn og sagði:'),
(1524, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 17, 'OT', 'Svo skuluð þér segja við Jósef: Fyrirgef nú afbrot bræðra þinna og synd þeirra, því að þeir gerðu þér illt. Og nú, fyrirgef afbrot þjóna Guðs föður þíns. Og Jósef grét þegar þeir töluðu við hann.'),
(1525, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 18, 'OT', 'Bræður hans gengu einnig til hans, féllu fram fyrir andlit hans og sögðu: Sjá, við erum þjónar þínir.'),
(1526, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 19, 'OT', 'Jósef sagði við þá: Óttist ekki. Er ég í stað Guðs?'),
(1527, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 20, 'OT', 'Þér hugsuðuð illt gegn mér, en Guð hugsaði það til góðs, til þess að gera eins og í dag, til að halda lífi í miklum lýð.'),
(1528, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 21, 'OT', 'Og nú, óttist ekki. Ég mun sjá fyrir yður og börnum yðar. Og hann huggaði þá og talaði til hjarta þeirra.'),
(1529, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 22, 'OT', 'Jósef bjó í Egyptalandi, hann og hús föður hans; og Jósef lifði hundrað og tíu ár.'),
(1530, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 23, 'OT', 'Jósef sá sonu Efraíms til þriðja ættliðar; einnig fæddust synir Makírs, sonar Manasse, á hnjám Jósefs.'),
(1531, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 24, 'OT', 'Jósef sagði við bræður sína: Ég er að deyja. En Guð mun vitja yðar og leiða yður úr þessari jörð í jörð þá sem hann sór Abraham, Ísak og Jakobi.'),
(1532, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 25, 'OT', 'Jósef lét sonu Ísraels sverja og sagði: Guð mun vitja yðar, og þér skuluð flytja bein mín héðan.'),
(1533, 1, 'GOI_Is', 'GOI_Is', 'is', 'GEN', 50, 26, 'OT', 'Jósef dó, hundrað og tíu ára gamall. Þeir balsameruðu hann og lögðu hann í örk í Egyptalandi.'),
(1534, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 1, 'OT', 'Þetta eru nöfn sona Ísraels, sem komu til Egyptalands með Jakobi; hver maður kom með húsi sínu.'),
(1535, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 2, 'OT', 'Rúben, Símeon, Leví og Júda.'),
(1536, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 3, 'OT', 'Íssakar, Sebúlon og Benjamín.'),
(1537, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 4, 'OT', 'Dan og Naftalí, Gað og Asser.'),
(1538, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 5, 'OT', 'Allar sálir sem komu út af læri Jakobs voru sjötíu sálir; og Jósef var í Egyptalandi.'),
(1539, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 6, 'OT', 'Jósef dó, og allir bræður hans, og öll sú kynslóð.'),
(1540, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 7, 'OT', 'Synir Ísraels frjóvguðust og uxu, margfölduðust og urðu afar sterkir, svo að jörðin fylltist af þeim.'),
(1541, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 8, 'OT', 'Þá kom upp nýr konungur yfir Egyptalandi, sem þekkti ekki Jósef.'),
(1542, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 9, 'OT', 'Hann sagði við lýð sinn: Sjá, lýður sona Ísraels er fjölmennari og sterkari en við.'),
(1543, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 10, 'OT', 'Komið, skulum vara okkur á þeim, svo að þeir fjölgi sér ekki; því að ef stríð ber að höndum, gætu þeir gengið í lið með fjandmönnum okkar, barist gegn oss og horfið úr jörðinni.'),
(1544, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 11, 'OT', 'Þá settu þeir yfir þá höfðingja til að íþyngja þeim með nauðungarvinnu og byrðum þeirra. Þeir reistu fyrir Faraó borgir til forðabúra, Pítom og Raamses.'),
(1545, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 12, 'OT', 'En því meira sem þeir kúguðu þá, því meira fjölgaði þeim og því meira breiddust þeir út; og þeim stóð ógn af sonum Ísraels.'),
(1546, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 13, 'OT', 'Og Egyptar létu sonu Ísraels þjóna með harðýðgi.'),
(1547, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 14, 'OT', 'Þeir gerðu líf þeirra beiskt með harðri þjónustu við leir og múrsteina og alla þjónustu á akri; öll þjónusta þeirra, sem þeir þvinguðu þá til, var með harðýðgi.'),
(1548, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 15, 'OT', 'Konungur Egyptalands talaði við ljósmæður Hebrea, en nafn annarrar var Sifra og nafn hinnar Púa.'),
(1549, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 16, 'OT', 'Og hann sagði: Þegar þér hjálpið Hebreum konum við fæðingu og lítið á fæðingarstólinn: Ef það er sonur, skuluð þér drepa hann; en ef það er dóttir, þá skal hún lifa.'),
(1550, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 17, 'OT', 'En ljósmæðurnar óttuðust Guð og gerðu ekki eins og konungur Egyptalands hafði sagt þeim, og þær létu drengi lifa.'),
(1551, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 18, 'OT', 'Konungur Egyptalands kallaði á ljósmæðurnar og sagði við þær: Hvers vegna gerðuð þér þetta og létuð drengina lifa?'),
(1552, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 19, 'OT', 'Ljósmæðurnar svöruðu Faraó: Konur Hebrea eru ekki eins og konur Egypta, því að þær eru hraustar; áður en ljósmóðirin kemur til þeirra hafa þær fætt.'),
(1553, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 20, 'OT', 'Og Guð gerði vel við ljósmæðurnar, og lýðurinn fjölgaði og varð mjög sterkur.'),
(1554, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 21, 'OT', 'Og af því að ljósmæðurnar óttuðust Guð, gerði hann þeim hús.'),
(1555, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 1, 22, 'OT', 'Þá bauð Faraó öllum lýð sínum: Hvern son sem fæðist skuluð þér kasta í Níl, en allar dætur skuluð þér láta lifa.'),
(1556, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 1, 'OT', 'Maður af húsi Leví fór og tók sér dóttur Leví að konu.'),
(1557, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 2, 'OT', 'Konan varð þunguð og ól son. Hún sá að hann var góður og faldi hann í þrjá mánuði.'),
(1558, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 3, 'OT', 'En hún gat ekki lengur falið hann, og hún tók örk úr sefi, smurði hana jarðbiki og biki, lagði drenginn í hana og setti hana í sefi við vör Nílar.'),
(1559, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 4, 'OT', 'Systir hans stóð álengdar til að vita hvað yrði um hann.'),
(1560, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 5, 'OT', 'Dóttir Faraós fór niður að Níl til að baða sig, og stúlkur hennar gengu á hendi Nílar. Hún sá örkina í sefi, sendi ambátt sína og lét sækja hana.'),
(1561, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 6, 'OT', 'Hún opnaði og sá drenginn, og sjá, sveinninn grét; hún kenndi í brjósti um hann og sagði: Þetta er eitt af drengjum Hebrea.'),
(1562, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 7, 'OT', 'Systir hans sagði þá við dóttur Faraós: Á ég að fara og kalla fyrir þig konu af Hebreum sem hjúkri drengnum?'),
(1563, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 8, 'OT', 'Dóttir Faraós sagði við hana: Far þú! Þá fór ung kona og kallaði á móður drengsins.'),
(1564, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 9, 'OT', 'Dóttir Faraós sagði við hana: Taktu þetta barn og ammaðu það fyrir mig, og ég skal greiða þér laun. Þá tók konan drenginn og gaf honum brjóst.'),
(1565, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 10, 'OT', 'Drengurinn stækkaði, og hún fór með hann til dóttur Faraós, og hann varð henni sonur. Hún gaf honum nafnið Móses og sagði: Því að ég dró hann upp úr vatni.'),
(1566, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 11, 'OT', 'Á þeim dögum varð Móses fullorðinn og fór út til bræðra sinna og sá byrðar þeirra; og hann sá Egypta slá mann Hebrea, einn af bræðrum sínum.'),
(1567, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 12, 'OT', 'Hann leit til hægri og vinstri og sá að enginn maður var nær; þá drap hann Egypta og faldi hann í sandi.'),
(1568, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 13, 'OT', 'Næsta dag fór hann út, og sjá, tveir menn af Hebreum rifust; og hann sagði við þann sem hafði rangt fyrir sér: Hví slærðu náunga þinn?'),
(1569, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 14, 'OT', 'En hann svaraði: Hver setti þig að höfðingja og dómara yfir okkur? Ætlarðu að drepa mig eins og þú drapst Egypta? Þá óttaðist Móses og sagði: Þetta orð er þá komið upp.'),
(1570, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 15, 'OT', 'Faraó heyrði þetta orð og leitaði að Móses til að drepa hann. En Móses flúði fyrir andliti Faraós og settist að í jörð Midíans; og hann settist við brunninn.'),
(1571, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 16, 'OT', 'Prestur í Midían átti sjö dætur; þær komu, drógu vatn og fylltu rennibrautirnar til að vökva sauðfé föður síns.'),
(1572, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 17, 'OT', 'Hirðarnir komu og ráku þær burt, en Móses reis upp, hjálpaði þeim og vökvaði sauðfé þeirra.'),
(1573, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 18, 'OT', 'Þær komu til Regúels föður síns, og hann sagði: Hvers vegna komuð þér svona snemma í dag?'),
(1574, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 19, 'OT', 'Þær sögðu: Maður Egypta bjargaði okkur úr hendi hirðanna, og hann dró líka vatn fyrir okkur og vökvaði sauðfé.'),
(1575, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 20, 'OT', 'Hann sagði við dætur sínar: Hvar er hann? Hvers vegna hafið þið skilið manninn eftir? Kallið hann, svo að hann eti brauð.'),
(1576, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 21, 'OT', 'Móses ákvað að vera hjá manninum, og hann gaf Sippóru, dóttur sína, Mósesi.'),
(1577, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 22, 'OT', 'Hún ól son, og hann gaf honum nafnið Gersom, því að hann sagði: Ég hef verið útlendingur í framandi jörð.'),
(1578, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 23, 'OT', 'Á þeim löngu dögum dó konungur Egyptalands, og synir Ísraels andvörpuðu vegna þjónustunnar; óp þeirra vegna ánauðarinnar komst upp til Guðs.'),
(1579, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 24, 'OT', 'Guð heyrði andvarp þeirra, og Guð minntist sáttmála síns við Abraham, Ísak og Jakobi.'),
(1580, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 2, 25, 'OT', 'Guð leit til sona Ísraels, og Guð þekkti þá.'),
(1581, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 1, 'OT', 'Móses gætti sauðfé Jetrós, tengdaföður síns, prests í Midían; hann rak féð yfir eyðimörkina og kom að fjallinu Hóreb, fjalli Guðs.'),
(1582, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 2, 'OT', 'Sendiboði Jahve birtist honum í loga elds úr miðjum þyrnirunnanum; hann horfði, og sjá, þyrnirunninn brann í eldi, en þyrnirunninn brann ekki upp.'),
(1583, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 3, 'OT', 'Og Móses sagði: Ég vil snúa við og sjá þetta mikla útlit: hvers vegna brennur þyrnirunninn ekki?'),
(1584, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 4, 'OT', 'Jahve sá að hann kom til að líta; þá kallaði Guð til hans úr miðjum þyrnirunnanum: Móses, Móses! Og hann sagði: Hér er ég.'),
(1585, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 5, 'OT', 'Hann sagði: Nálgastu ekki hingað; fjarlægðu skóna af fæti þínum, því að staðurinn sem þú stendur á er jörð helgi.'),
(1586, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 6, 'OT', 'Hann sagði: Ég er Guð föður þíns, Guð Abrahams, Guð Ísaks og Guð Jakobs. Móses huldi andlit sitt, því að hann óttaðist að líta á Guð.'),
(1587, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 7, 'OT', 'Jahve sagði: Ég hef séð eymd lýðs míns í Egyptalandi, og ég hef heyrt neyðaróp þeirra vegna þeirra sem þvinga þá; ég þekki sársauka þeirra.'),
(1588, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 8, 'OT', 'Ég er kominn niður til að frelsa þá úr hendi Egypta og leiða þá upp úr jörðinni til góðrar og víðrar jarðar, jarðar sem flýtur í mjólk og hunangi, til staðar Kanaanita, Hetíta, Amorita, Peresíta, Hevíta og Jebúsíta.'),
(1589, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 9, 'OT', 'Og nú, sjá, neyðaróp sona Ísraels er komið til mín, og ég hef séð þrenginguna sem Egyptar kúga þá með.'),
(1590, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 10, 'OT', 'Far þú nú, ég sendi þig til Faraós, og þú skalt leiða lýð minn, sonu Ísraels, út úr Egyptalandi.'),
(1591, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 11, 'OT', 'Móses sagði við Guð: Hver er ég, að ég skuli fara til Faraós og leiða sonu Ísraels út úr Egyptalandi?'),
(1592, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 12, 'OT', 'Hann svaraði: Ég verð með þér, og þetta skal vera þér tákn um að ég hef sent þig: þegar þú leiðir lýðinn út úr Egyptalandi, þá skuluð þið þjóna Guði á þessu fjallinu.'),
(1593, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 13, 'OT', 'Móses sagði við Guð: Sjá, þegar ég kem til sona Ísraels og segi við þá: Guð feðra ykkar hefur sent mig til ykkar; og þeir spyrja mig: Hvert er nafn hans? Hvað á ég að segja þeim?'),
(1594, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 14, 'OT', 'Guð sagði við Móses: Ég er sá sem ég er. Og hann sagði: Svo skalt þú segja sonum Ísraels: Ég er hefur sent mig til ykkar.'),
(1595, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 15, 'OT', 'Guð sagði enn við Móses: Svo skalt þú segja sonum Ísraels: Jahve, Guð feðra ykkar, Guð Abrahams, Guð Ísaks og Guð Jakobs, hefur sent mig til ykkar. Þetta er nafn mitt um eilífð, og þetta er minning mín frá kynslóð til kynslóðar.'),
(1596, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 16, 'OT', 'Far þú og safnaðu saman öldungum Ísraels og seg við þá: Jahve, Guð feðra ykkar, Guð Abrahams, Ísaks og Jakobs, hefur birst mér og sagt: Ég hef vitjað yðar og þess sem gert hefur verið við yður í Egyptalandi.'),
(1597, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 17, 'OT', 'Og ég hef sagt: Ég mun leiða yður upp úr eymd Egyptalands til jarðar Kanaanita, Hetíta, Amorita, Peresíta, Hevíta og Jebúsíta, til jarðar sem flýtur í mjólk og hunangi.'),
(1598, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 18, 'OT', 'Og þeir munu hlýða rödd þinni; og þú og öldungar Ísraels skuluð fara til konungs Egyptalands og segja við hann: Jahve, Guð Hebrea, hefur mætt okkur; nú viljum við fara þriggja daga veg í eyðimörkina og færa Jahve Guði okkar fórn.'),
(1599, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 19, 'OT', 'Ég veit að konungur Egyptalands mun ekki leyfa yður að fara, nema með sterkri hendi.'),
(1600, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 20, 'OT', 'Ég mun rétta út hönd mína og slá Egypta með öllum undrum mínum, sem ég mun gera í miðju þess; og eftir það mun hann láta yður fara.'),
(1601, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 21, 'OT', 'Ég mun gefa þessum lýð hylli í augum Egypta; og þegar þið farið skuluð þið ekki fara tómhentir.'),
(1602, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 3, 22, 'OT', 'Hver kona skal biðja nágrannakonu sína og gestkonu sem býr í húsi hennar um silfur og gull, áhöld og skikkjur; og þið skuluð leggja þau á sonu yðar og dætur, og þið skuluð ræna Egypta.'),
(1603, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 1, 'OT', 'Móses svaraði og sagði: Sjá, þeir munu ekki trúa mér og ekki hlýða rödd minni, því að þeir munu segja: Jahve hefur ekki birst þér.'),
(1604, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 2, 'OT', 'Jahve sagði við hann: Hvað er í hendi þinni? Hann svaraði: Stafur.'),
(1605, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 3, 'OT', 'Hann sagði: Kastaðu honum á jörðina. Og hann kastaði honum á jörðina, og hann varð að höggormi; og Móses flýði fyrir andliti hans.'),
(1606, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 4, 'OT', 'Jahve sagði við Móses: Réttu út hönd þína og gríptu hann í halann. Hann rétti út hönd sína og greip hann, og hann varð að staf í lófa hans.'),
(1607, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 5, 'OT', 'Þetta gerir þú til þess að þeir trúi að Jahve, Guð feðra þeirra, Guð Abrahams, Guð Ísaks og Guð Jakobs, hafi birst þér.'),
(1608, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 6, 'OT', 'Jahve sagði enn við hann: Stingdu hendi þinni í skaut þitt. Og hann stakk hendi sinni í skaut sitt, og þegar hann dró hana út, sjá, hönd hans var holdsveik eins og snjór.'),
(1609, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 7, 'OT', 'Hann sagði: Stingdu hendi þinni aftur í skaut þitt. Og hann stakk hendi sinni aftur í skaut sitt, og þegar hann dró hana út úr skautinu, var hún aftur eins og hold hans.'),
(1610, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 8, 'OT', 'Og ef þeir trúa þér ekki og hlusta ekki á rödd hins fyrra tákns, þá munu þeir trúa rödd hins síðara tákns.'),
(1611, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 9, 'OT', 'Ef þeir trúa jafnvel ekki þessum tveimur táknum og hlusta ekki á rödd þína, þá skalt þú taka vatn úr Nílinni og hella því á þurrlendi; og vatnið sem þú tekur úr Nílinni skal verða blóð á þurrlendi.'),
(1612, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 10, 'OT', 'Móses sagði við Jahve: Ó, Drottinn minn, ég er ekki maður orða, hvorki áður né síðan þú talaðir við þjón þinn; því að ég er þungmæltur í munni og í tungu.'),
(1613, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 11, 'OT', 'Jahve sagði við hann: Hver setti munn í manninn? Eða hver gerir hann mállausan, heyrnarlausan, sjáandi eða blindan? Er það ekki ég, Jahve?'),
(1614, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 12, 'OT', 'Far þú nú, og ég mun vera með munni þínum og kenna þér hvað þú skalt tala.'),
(1615, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 13, 'OT', 'Hann sagði: Drottinn minn, send þú með hendi þess sem þú vilt senda.'),
(1616, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 14, 'OT', 'Þá upptendraðist reiði Jahve gegn Mósesi, og hann sagði: Er ekki Aron bróðir þinn Levíti? Ég veit að hann kann vel að tala; og sjá, hann mun einnig koma á móti þér, og þegar hann sér þig mun hann gleðjast í hjarta sínu.'),
(1617, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 15, 'OT', 'Þú skalt tala við hann og leggja orðin í munn hans; og ég mun vera með munni þínum og munni hans, og kenna yður hvað þér skuluð gera.'),
(1618, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 16, 'OT', 'Hann skal tala fyrir þig við lýðinn, og hann skal vera þér í munni; og þú skalt vera honum sem Guð.'),
(1619, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 17, 'OT', 'Og þennan staf skalt þú taka í hendi þinni, og með honum skalt þú gera táknin.'),
(1620, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 18, 'OT', 'Móses fór og sneri aftur til Jeters, tengdaföður síns, og sagði við hann: Leyf mér að fara og snúa aftur til bræðra minna í Egyptalandi og sjá hvort þeir séu enn á lífi. Jetró sagði við Móses: Far í friði.'),
(1621, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 19, 'OT', 'Jahve sagði við Móses í Midían: Far, snúðu aftur til Egyptalands, því að allir mennirnir sem sóttust eftir sál þinni eru dánir.'),
(1622, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 20, 'OT', 'Móses tók konu sína og sonu sína, setti þá á asna og sneri aftur til jarðar Egyptalands; og Móses tók staf Guðs í hönd sína.'),
(1623, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 21, 'OT', 'Jahve sagði við Móses: Þegar þú ferð aftur til Egyptalands, gættu þess að gera öll undur sem ég hef lagt í hönd þína fyrir augum Faraós; en ég mun herða hjarta hans, og hann mun ekki láta lýðinn fara.'),
(1624, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 22, 'OT', 'Og þú skalt segja við Faraó: Svo segir Jahve: Ísrael er sonur minn, frumgetinn minn.'),
(1625, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 23, 'OT', 'Ég hef sagt við þig: Slepptu syni mínum, svo að hann geti þjónað mér; en þú hefur neitað að láta hann fara. Sjá, ég mun deyða frumgetinn son þinn.'),
(1626, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 24, 'OT', 'Og á vegi, á náttstað, hitti Jahve hann og leitaði að því að drepa hann.'),
(1627, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 25, 'OT', 'Þá tók Sippóra tinnustein og skar yfirhúðina af syni sínum; hún snerti fætur hans og sagði: Þú ert blóðugur tengdasonur mér.'),
(1628, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 26, 'OT', 'Þá lét hann hana í friði. Þá sagði hún: Blóðugur tengdasonur vegna umskurnarinnar.'),
(1629, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 27, 'OT', 'Jahve sagði við Aron: Far til móts við Móses í eyðimörkinni. Og hann fór og hitti hann á fjalli Guðs og kyssti hann.'),
(1630, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 28, 'OT', 'Og Móses sagði Aroni öll orð Jahve, sem hann hafði sent honum, og öll táknin sem hann hafði boðið honum.'),
(1631, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 29, 'OT', 'Móses og Aron fóru og söfnuðu saman öllum öldungum sona Ísraels.'),
(1632, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 30, 'OT', 'Aron sagði öll orðin sem Jahve hafði talað við Móses, og gerði táknin fyrir augum lýðsins.'),
(1633, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 4, 31, 'OT', 'Lýðurinn trúði, og þeir heyrðu að Jahve hefði vitjað sona Ísraels og séð eymd þeirra; og þeir féllu fram og tilbáðu.'),
(1634, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 1, 'OT', 'Síðan gengu Móses og Aron inn og sögðu við Faraó: Svo segir Jahve, Guð Ísraels: Slepptu lýð mínum, svo að hann megi halda hátíð mér til heiðurs í eyðimörkinni.'),
(1635, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 2, 'OT', 'Faraó svaraði: Hver er Jahve, sem ég ætti að hlýða rödd hans og láta Ísrael fara? Ég þekki ekki Jahve, og Ísrael mun ég ekki láta fara.'),
(1636, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 3, 'OT', 'Þeir sögðu: Guð Hebrea hefur mætt okkur; leyfðu okkur að fara þriggja daga veg í eyðimörkina og fórna Jahve Guði okkar, svo að hann sendi ekki yfir okkur drepsótt eða sverð.'),
(1637, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 4, 'OT', 'Konungur Egyptalands sagði við þá: Hvers vegna, Móses og Aron, tefjið þið lýðinn frá verki sínu? Farið til byrða ykkar.'),
(1638, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 5, 'OT', 'Faraó sagði: Sjá, lýðurinn er nú orðinn margur í jörðinni, og þér látið þá hætta frá byrðum þeirra.'),
(1639, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 6, 'OT', 'Faraó bauð sama dag verkstjórunum yfir lýðnum og eftirlitsmönnum þeirra, og sagði:'),
(1640, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 7, 'OT', 'Þér megið ekki framar gefa lýðnum hálm til að búa til múrsteina, eins og áður; þeir skulu sjálfir fara og safna sér hálmi.'),
(1641, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 8, 'OT', 'Og þér skuluð leggja á þá sama mælikvarða múrsteina sem þeir hafa gert áður; þér skuluð ekki draga úr honum, því að þeir eru latir. Þess vegna hrópa þeir: Leyf okkur að fara og fórna Guði okkar.'),
(1642, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 9, 'OT', 'Þyngið þjónustuna á mönnunum og látið þá vinna hana, og látið þá ekki hlusta á lygaorðum.'),
(1643, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 10, 'OT', 'Verkstjórarnir og eftirlitsmennirnir gengu út og sögðu við lýðinn: Svo segir Faraó: Ég gef yður ekki hálm.'),
(1644, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 11, 'OT', 'Farið sjálfir og takið hálm þar sem þér finnið hann, því að ekkert af þjónustu yðar skal minnkað.'),
(1645, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 12, 'OT', 'Lýðurinn dreifðist um alla jörð Egyptalands til að safna hálmstráum í stað hálms.'),
(1646, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 13, 'OT', 'Verkstjórarnir ráku þá áfram og sögðu: Ljúkið verkum yðar, dag frá degi, eins og þegar hálmurinn var til staðar.'),
(1647, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 14, 'OT', 'Eftirlitsmenn sona Ísraels, sem verkstjórar Faraós höfðu sett yfir þá, voru barðir og spurðir: Hvers vegna hafið þér ekki lokið tilteknu lögum yðar í að búa til múrsteina, bæði í gær og í dag, eins og áður?'),
(1648, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 15, 'OT', 'Þá komu eftirlitsmenn sona Ísraels og hrópuðu til Faraós: Hvers vegna gerir þú þetta við þjóna þína?'),
(1649, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 16, 'OT', 'Engin hálmur er gefinn þjónum þínum, og þeir segja við okkur: Gerið múrsteina! Og sjá, þjónar þínir eru barðir, en lýður þinn er sekur.'),
(1650, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 17, 'OT', 'Hann sagði: Þér eruð latir, latir; þess vegna segið þér: Leyfið okkur að fara og fórna Jahve.'),
(1651, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 18, 'OT', 'En nú farið og vinnið. Hálmur verður ekki gefinn yður, en mál múrsteinanna skuluð þér afhenda.'),
(1652, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 19, 'OT', 'Og eftirlitsmenn sona Ísraels sáu að þeim var illa farið, þegar sagt var: Þér skuluð alls ekki draga neitt úr múrsteinum yðar, neitt af dagsverki og orði hvers dags á sínum degi.'),
(1653, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 20, 'OT', 'Og þeir mættu Móses og Aron, sem stóðu þar og tóku á móti þeim, þegar þeir komu út frá Faraós.'),
(1654, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 21, 'OT', 'og sögðu við þá: Jahve líti á yður og dæmi, því að þér hafið gert ilm okkar fúlan í augum Faraós og þjóna hans og lagt sverð í hendur þeirra til að drepa oss.'),
(1655, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 22, 'OT', 'Þá sneri Móses aftur til Jahve og sagði: Drottinn, hvers vegna hefur þú gert þessum lýð illt? Hvers vegna sendir þú mig?'),
(1656, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 5, 23, 'OT', 'Því að síðan ég kom til Faraós til að tala í þínu nafni, hefur hann gert þessum lýð illt, og þú hefur alls ekki frelsað lýð þinn.'),
(1657, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 1, 'OT', 'Þá sagði Jahve við Móses: Nú skalt þú sjá hvað ég geri Faraó, því að með sterkri hendi mun hann láta þá fara, og með sterkri hendi mun hann reka þá burt úr jörð sinni.'),
(1658, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 2, 'OT', 'Guð talaði við Móses og sagði við hann: Ég er Jahve.'),
(1659, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 3, 'OT', 'Ég birtist Abraham, Ísak og Jakob sem Almáttugur Guð, en með nafni mínu Jahve var ég þeim ekki kunnur.'),
(1660, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 4, 'OT', 'Ég reisti líka sáttmála minn við þá, að gefa þeim jörðina Kanaan, jörð útlegðar þeirra, þar sem þeir dvöldu.'),
(1661, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 5, 'OT', 'Ég hef líka heyrt andvarp sona Ísraels, sem Egyptar halda í þrældómi í Egyptalandi, og ég hef minnst sáttmála míns.'),
(1662, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 6, 'OT', 'Seg þú þess vegna við sonu Ísraels: Ég er Jahve. Ég mun leysa yður undan byrðum Egyptalands, frelsa yður úr þjónustu þeirra og endurleysa yður með útréttum armi og miklum dómum.'),
(1663, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 7, 'OT', 'Ég mun taka yður mér að lýð og verða yður að Guði, og þér skuluð vita að ég er Jahve, Guð yðar, sem leiði yður út undan byrðum Egyptalands.'),
(1664, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 8, 'OT', 'Ég mun leiða yður inn í jörðina, sem ég svór með uppréttri hönd að gefa Abraham, Ísak og Jakob, og ég mun gefa yður hana að arfleifð. Ég er Jahve.'),
(1665, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 9, 'OT', 'Og Móses talaði þannig við sonu Ísraels, en þeir hlustuðu ekki á Móses sakir angistar og anda og harðrar þjónustu.'),
(1666, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 10, 'OT', 'Þá talaði Jahve við Móses og sagði:'),
(1667, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 11, 'OT', 'Far þú og tala við Faraó konung Egyptalands og lát sonu Ísraels fara úr jörð sinni.'),
(1668, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 12, 'OT', 'Og Móses talaði fyrir andliti Jahve og sagði: Sjá, synir Ísraels hafa ekki hlustað á mig. Hvernig mun þá Faraó hlusta á mig, ég sem er óumskorinn á vörum?'),
(1669, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 13, 'OT', 'Þá talaði Jahve við Móses og Aron og bauð þeim varðandi sonu Ísraels og Faraó konung Egyptalands, að leiða sonu Ísraels út af jörð Egyptalands.'),
(1670, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 14, 'OT', 'Þetta eru höfuð ættanna í húsum feðra þeirra. Synir Rúbens, frumgetins Ísraels: Enok, Pallú, Hesron og Karmí. Þetta eru ættir Rúbens.'),
(1671, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 15, 'OT', 'Synir Símeons: Jemúel, Jamín, Óhad, Jakín, Sóhar og Sál, sonur konu Kanaanítu. Þetta eru ættir Símeons.'),
(1672, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 16, 'OT', 'Þetta eru nöfn Leví-sona eftir ættartölum þeirra: Gerson, Kahat og Merarí. Og Leví lifði hundrað þrjátíu og sjö ár.'),
(1673, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 17, 'OT', 'Synir Gersons eftir ættum þeirra: Libní og Símeí.'),
(1674, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 18, 'OT', 'Synir Kahats: Amram, Ísehar, Hebron og Ússíel. Og Kahat lifði hundrað þrjátíu og þrjú ár.'),
(1675, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 19, 'OT', 'Synir Merarí: Mahli og Músí. Þetta eru ættir Leví eftir ættartölum þeirra.'),
(1676, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 20, 'OT', 'Og Amram tók sér Jókebed, föðursystur sína, til konu, og hún ól honum Aron og Móses. Og Amram lifði hundrað þrjátíu og sjö ár.'),
(1677, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 21, 'OT', 'Synir Ísehars: Kóra, Nefeg og Síkrí.'),
(1678, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 22, 'OT', 'Synir Ússíels: Mísael, Elísafan og Sitrí.'),
(1679, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 23, 'OT', 'Og Aron tók sér Elísaba, dóttur Amínadabs, systur Naksons, til konu, og hún ól honum Nadab, Abíhú, Eleasar og Ítamar.'),
(1680, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 24, 'OT', 'Synir Kóra: Assír, Elkana og Abíasaf. Þetta eru ættir Kóraítar.'),
(1681, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 25, 'OT', 'Og Eleasar, sonur Arons, tók sér eina af dætrum Pútíels til konu, og hún ól honum Pínehas. Þetta eru höfuð feðra Levíta eftir ættum þeirra.'),
(1682, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 26, 'OT', 'Þetta eru Aron og Móses, sem Jahve sagði: Leiðið sonu Ísraels út af jörð Egyptalands, eftir herjum þeirra.'),
(1683, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 27, 'OT', 'Þetta eru þeir sem töluðu við Faraó konung Egyptalands til að leiða sonu Ísraels út af jörð Egyptalands, það er Móses og Aron.'),
(1684, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 28, 'OT', 'Á þeim degi, þegar Jahve talaði við Móses í jörð Egyptalands,'),
(1685, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 29, 'OT', 'Jahve talaði við Móses og sagði: Ég er Jahve. Seg Faraó konungi Egyptalands allt það sem ég segi þér.'),
(1686, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 6, 30, 'OT', 'Og Móses sagði fyrir andliti Jahve: Sjá, ég er óumskorinn á vörum. Hvernig mun þá Faraó hlusta á mig?'),
(1687, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 1, 'OT', 'Og Jahve sagði við Móses: Sjá, ég hef gert þig að Guði fyrir Faraó, og Aron, bróðir þinn, skal vera spámaður þinn.'),
(1688, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 2, 'OT', 'Þú skalt tala allt það sem ég býð þér, og Aron, bróðir þinn, skal tala við Faraó, og hann skal láta sonu Ísraels fara úr jörð sinni.'),
(1689, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 3, 'OT', 'En ég mun herða hjarta Faraós og margfalda tákn mín og undur mín í jörð Egyptalands.'),
(1690, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 4, 'OT', 'Faraó mun ekki hlusta á yður. Ég mun leggja hönd mína á Egyptaland og leiða heri mína, lýð minn, sonu Ísraels út af jörð Egyptalands með miklum dómum.'),
(1691, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 5, 'OT', 'Og Egyptar skulu vita að ég er Jahve, þegar ég rétti út hönd mína yfir Egyptaland og leiði sonu Ísraels út úr þeim.'),
(1692, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 6, 'OT', 'Og Móses og Aron gerðu eins og Jahve hafði boðið þeim, þeir gerðu það.'),
(1693, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 7, 'OT', 'Móses var áttatíu ára og Aron áttatíu og þriggja ára, þegar þeir töluðu við Faraó.'),
(1694, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 8, 'OT', 'Og Jahve talaði við Móses og Aron og sagði:'),
(1695, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 9, 'OT', 'Þegar Faraó talar við yður og segir: Gerið undur, þá seg við Aron: Tak staf þinn og kastaðu honum fyrir andliti Faraós, og hann skal verða að dreka.'),
(1696, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 10, 'OT', 'Og Móses og Aron gengu inn til Faraós og gerðu eins og Jahve hafði boðið. Aron kastaði staf sínum fyrir andliti Faraós og þjóna hans, og hann varð að dreka.'),
(1697, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 11, 'OT', 'Þá kallaði Faraó einnig á vitringa og galdramenn, og særingamenn Egyptalands gerðu einnig eins með loga sínum.'),
(1698, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 12, 'OT', 'Því að hver maður kastaði staf sínum, og þeir urðu að drekum; en staf Arons gleypti stafi þeirra.'),
(1699, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 13, 'OT', 'Og hjarta Faraós harðnaði, og hann hlustaði ekki á þá, eins og Jahve hafði talað.'),
(1700, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 14, 'OT', 'Og Jahve sagði við Móses: Hjarta Faraós er þungt; hann neitar að láta lýðinn fara.'),
(1701, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 15, 'OT', 'Far þú til Faraós að morgni. Sjá, hann fer út að vatni. Þú skalt standa á móti honum á vör Nílar, og staf þann, sem varð að höggormi, skalt þú taka í hendi þinni.'),
(1702, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 16, 'OT', 'Þú skalt segja við hann: Jahve, Guð Hebrea, hefur sent mig til þín og sagt: Lát lýð minn fara, svo að hann geti þjónað mér í eyðimörkinni. En sjá, þú hefur ekki hlýtt hingað til.'),
(1703, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 17, 'OT', 'Svo segir Jahve: Af þessu skalt þú vita að ég er Jahve. Sjá, ég slæ með staf, sem er í hendi minni, á Nílarvatnið, og það skal breytast í blóð.'),
(1704, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 18, 'OT', 'Fiskurinn í Nílinni mun deyja, og Nílin mun fúlna, og Egyptar munu þreytast á að drekka vatn úr Nílinni.'),
(1705, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 19, 'OT', 'Og Jahve sagði við Móses: Seg við Aron: Tak staf þinn og rétt hönd þína yfir vatnið í Egyptalandi, yfir fljót þeirra, yfir tjarnir þeirra og yfir öll vatnssöfn þeirra, og þau skulu verða að blóði. Og blóð skal vera um alla jörð Egyptalands, bæði í tré og í steini.'),
(1706, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 20, 'OT', 'Móses og Aron gerðu eins og Jahve hafði boðið. Hann lyfti staf sínum og laust vatnið í Nílinni fyrir augum Faraós og þjóna hans, og allt vatnið í Nílinni varð að blóði.'),
(1707, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 21, 'OT', 'Fiskurinn í Nílinni dó, og Nílin fúlnaði, og Egyptar gátu ekki drukkið vatn úr Nílinni, og blóðið var um alla jörð Egyptalands.'),
(1708, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 22, 'OT', 'Og særingamenn Egyptalands gerðu eins með leynd sinni. Og hjarta Faraós harðnaði, og hann hlustaði ekki á þá, eins og Jahve hafði talað.'),
(1709, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 23, 'OT', 'Faraó sneri sér við og gekk inn í hús sitt, og hann lagði ekki hjarta sitt við þetta heldur.'),
(1710, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 24, 'OT', 'Og allir Egyptar grófu umhverfis Nílina eftir vatni til að drekka, því að þeir gátu ekki drukkið af vatninu í Nílinni.'),
(1711, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 7, 25, 'OT', 'Og sjö dagar liðu eftir að Jahve sló Nílina.'),
(1712, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 1, 'OT', 'Og Jahve sagði við Móses: Far þú til Faraós og seg við hann: Svo segir Jahve: Lát lýð minn fara, svo að hann geti þjónað mér.'),
(1713, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 2, 'OT', 'En ef þú neitar að láta þá fara, sjá, þá mun ég slá öll landamæri þín með froskum.'),
(1714, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 3, 'OT', 'Og Nílin mun iða af froskum, og þeir munu koma upp og fara inn í hús þitt og í svefnherbergi þitt, á hvílu þína og á rekkju þína, og inn í hús þjóna þinna og lýðs þíns, og í ofna þína og í deigtrog þín.'),
(1715, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 4, 'OT', 'Og froskarnir munu fara upp á þig, og á lýð þinn og alla þjóna þína.'),
(1716, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 5, 'OT', 'Og Jahve sagði við Móses: Seg við Aron: Rétt út hönd þína með staf þínum yfir fljótin, yfir Nílina og yfir tjarnirnar, og lát froskana koma upp á jörð Egyptalands.'),
(1717, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 6, 'OT', 'Og Aron rétti út hönd sína yfir vatnið í Egyptalandi, og froskarnir komu upp og huldu jörð Egyptalands.'),
(1718, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 7, 'OT', 'Og særingamennirnir gerðu eins með leynd sinni og færðu froskana upp á jörð Egyptalands.'),
(1719, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 8, 'OT', 'Þá kallaði Faraó á Móses og Aron og sagði: Biðjið Jahve að taka froskana burt frá mér og lýð mínum, og ég mun láta lýðinn fara, svo að hann geti fórnað Jahve.'),
(1720, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 9, 'OT', 'Og Móses sagði við Faraó: Ég læt þig ráða, hvenær ég skuli biðja fyrir þér, þjónum þínum og lýð þínum, að froskarnir séu upprættir frá þér og húsum þínum. Aðeins í Nílinni munu þeir verða eftir.'),
(1721, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 10, 'OT', 'Og hann sagði: Á morgun. Og Móses sagði: Eftir þínu orði, svo að þú vitir að enginn er eins og Jahve, Guð vor.'),
(1722, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 11, 'OT', 'Og froskarnir munu fara frá þér, frá húsum þínum, frá þjónum þínum og frá lýð þínum. Aðeins í Nílinni munu þeir verða eftir.'),
(1723, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 12, 'OT', 'Og Móses og Aron gengu út frá Faraó, og Móses hrópaði til Jahve vegna froskanna, sem hann hafði lagt á Faraó.'),
(1724, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 13, 'OT', 'Og Jahve gerði eftir orði Móses, og froskarnir dóu í húsunum, á forgörðum og á ökrum.'),
(1725, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 14, 'OT', 'Og þeir hröngluðu þá saman í hrúgur, hrúgu ofan á hrúgu, og jörðin fúlnaði.'),
(1726, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 15, 'OT', 'En þegar Faraó sá að léttir var fenginn, herti hann hjarta sitt, og hann hlustaði ekki á þá, eins og Jahve hafði talað.'),
(1727, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 16, 'OT', 'Og Jahve sagði við Móses: Seg við Aron: Rétt út staf þinn og slá moldina á jörðinni, og hún skal verða að lúsum um alla jörð Egyptalands.'),
(1728, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 17, 'OT', 'Og þeir gerðu eins. Aron rétti út hönd sína með staf sínum og sló moldina á jörðinni, og lýs komu á mann og skepnu. Öll moldin á jörðinni varð að lúsum um alla jörð Egyptalands.'),
(1729, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 18, 'OT', 'Og særingamennirnir gerðu eins með leynd sinni til að framleiða lúsnar, en þeir gátu það ekki. Og lúsnar voru á mann og skepnu.'),
(1730, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 19, 'OT', 'Þá sögðu særingamennirnir við Faraó: Þetta er fingur Guðs. En hjarta Faraós harðnaði, og hann hlustaði ekki á þá, eins og Jahve hafði talað.'),
(1731, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 20, 'OT', 'Og Jahve sagði við Móses: Vakna snemma að morgni og gakk fram fyrir andliti Faraós. Sjá, hann fer út að vatni. Og seg við hann: Svo segir Jahve: Lát lýð minn fara, svo að hann geti þjónað mér.'),
(1732, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 21, 'OT', 'Ef þú lætur ekki lýð minn fara, sjá, þá sendi ég flugnager á þig, á þjóna þína og á lýð þinn og í hús þín. Hús Egypta munu fyllast af flugnagernum, og jafnvel jörðin, sem þeir standa á, mun fyllast af þeim.'),
(1733, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 22, 'OT', 'En á þeim degi mun ég aðgreina jörð Gósens, þar sem lýður minn býr, svo að þar verði ekkert flugnager. Þá skalt þú vita að ég er Jahve í miðri jörðinni.'),
(1734, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 23, 'OT', 'Og ég mun gera lausn milli lýðs míns og lýðs þíns. Á morgun mun þetta tákn verða.'),
(1735, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 24, 'OT', 'Og Jahve gerði þetta. Þungur flugnagerir kom í hús Faraós og í hús þjóna hans, og í allri jörð Egyptalands var jörðin spillt vegna flugnagernanna.'),
(1736, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 25, 'OT', 'Og Faraó kallaði á Móses og Aron og sagði: Farið og fórnið Guði yðar í jörðinni.'),
(1737, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 26, 'OT', 'Og Móses sagði: Það er ekki rétt að gera þetta, því að við mundum fórna viðurstyggð Egypta fyrir Jahve Guði okkar. Sjá, ef við fórnuðum viðurstyggð Egypta fyrir augum þeirra, myndu þeir ekki grýta okkur?'),
(1738, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 27, 'OT', 'Þriggja daga veg förum við inn í eyðimörkina og fórnum Jahve Guði okkar, eins og hann mun segja okkur.'),
(1739, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 28, 'OT', 'Og Faraó sagði: Ég skal láta ykkur fara, og þið skuluð fórna Jahve Guði ykkar í eyðimörkinni. Aðeins skuluð þið ekki fara of langt. Biðjið fyrir mér.'),
(1740, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 29, 'OT', 'Og Móses sagði: Sjá, ég fer út frá þér og bið til Jahve, og flugnagerinn mun á morgun fara frá Faraó, þjónum hans og lýð hans. Aðeins skal Faraó ekki framar svíkja og neita að láta lýðinn fara til að fórna Jahve.'),
(1741, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 30, 'OT', 'Og Móses gekk út frá Faraó og bað til Jahve.'),
(1742, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 31, 'OT', 'Og Jahve gerði eftir orði Móses, og flugnagerinn fór frá Faraó, þjónum hans og lýð hans. Ekki varð einn eftir.'),
(1743, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 8, 32, 'OT', 'En Faraó harðnaði í hjarta sínu, jafnvel í þetta sinn, og hann lét lýðinn ekki fara.'),
(1744, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 1, 'OT', 'Og Jahve sagði við Móses: Far þú inn til Faraós og seg við hann: Svo segir Jahve, Guð Hebrea: Lát lýð minn fara, svo að hann geti þjónað mér.'),
(1745, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 2, 'OT', 'Því að ef þú neitar að láta þá fara og heldur þeim enn.'),
(1746, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 3, 'OT', 'Sjá, hönd Jahve mun koma yfir fénað þinn, sem er á akrinum: yfir hestana, asna, úlfalda, nautin og sauðféð, og verður afar þung drepsótt.'),
(1747, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 4, 'OT', 'Og Jahve mun gera greinarmun á fénaði Ísraels og fénaði Egyptalands, og ekkert af því sem sonum Ísraels tilheyrir skal deyja.'),
(1748, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 5, 'OT', 'Og Jahve ákvað hátíðartíma og sagði: Á morgun mun Jahve gera þetta orð í jörðinni.'),
(1749, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 6, 'OT', 'Og Jahve gerði þetta orð daginn eftir, og allur fénaður Egyptalands dó, en af fénaði sona Ísraels dó ekki einn.'),
(1750, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 7, 'OT', 'Og Faraó sendi menn, og sjá, ekki einn af fénaði Ísraels hafði dáið. Og hjarta Faraós harðnaði, og hann lét lýðinn ekki fara.'),
(1751, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 8, 'OT', 'Og Jahve sagði við Móses og Aron: Takið lófafylli af ösku úr ofninum, og Móses skal kasta henni upp í himininn fyrir augum Faraós.'),
(1752, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 9, 'OT', 'Og það skal verða að dufti yfir alla jörð Egyptalands, og á mann og skepnu skal koma kýli sem springur í blöðrum um alla jörð Egyptalands.'),
(1753, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 10, 'OT', 'Og þeir tóku ösku úr ofninum og stóðu fyrir andliti Faraós. Og Móses kastaði henni upp í himininn, og kýli með blöðrum komu á mann og skepnu.'),
(1754, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 11, 'OT', 'Og særingamennirnir gátu ekki staðið fyrir andliti Móses vegna kýlanna, því að kýlin voru á særingamönnunum og á öllum Egyptum.'),
(1755, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 12, 'OT', 'Og Jahve herti hjarta Faraós, og hann hlustaði ekki á þá, eins og Jahve hafði talað við Móses.'),
(1756, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 13, 'OT', 'Og Jahve sagði við Móses: Rís árla að morgni, gakk fram fyrir andliti Faraós og seg við hann: Svo segir Jahve, Guð Hebrea: Lát lýð minn fara, svo að hann geti þjónað mér.'),
(1757, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 14, 'OT', 'Því að í þetta sinn sendi ég allar plágur mínar á hjarta þitt, á þjóna þína og á lýð þinn, svo að þú vitir að enginn er eins og ég á allri jörðinni.'),
(1758, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 15, 'OT', 'Því að nú hefði ég getað rétt út hönd mína og slegið þig og lýð þinn með drepsótt, og þú hefðir þurrkast út af jörðinni.'),
(1759, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 16, 'OT', 'En í þessu skyni hef ég látið þig standa, til að sýna þér kraft minn og til þess að nafn mitt verði boðað um alla jörðina.'),
(1760, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 17, 'OT', 'Ertu enn að upphefja þig gegn lýð mínum, svo að þú viljir ekki láta þá fara?'),
(1761, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 18, 'OT', 'Sjá, á morgun á þessum tíma læt ég hagl falla, afar þungt, sem ekki hefur verið í Egyptalandi frá þeim degi er það var stofnað og allt til þessa.'),
(1762, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 19, 'OT', 'Sendu nú og safnaðu fénaði þínum og öllu, sem þú átt á akrinum. Því að hver maður og skepna, sem finnst á akrinum og er ekki safnað inn í hús, mun falla undir haglið og deyja.'),
(1763, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 20, 'OT', 'Sá af þjónum Faraós, sem óttaðist orð Jahve, flýtti sér að koma þjónum sínum og fénaði sínum inn í húsin.'),
(1764, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 21, 'OT', 'En sá sem lagði ekki hjarta sitt við orð Jahve, lét þjóna sína og fénað sinn vera úti á akrinum.'),
(1765, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 22, 'OT', 'Og Jahve sagði við Móses: Rétt út hönd þína til himins, og lát hagl falla um alla jörð Egyptalands, á mann og skepnu og á allt gras akursins í Egyptalandi.'),
(1766, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 23, 'OT', 'Og Móses rétti út staf sinn til himins, og Jahve lét þrumuraddir og hagl koma, og eldur féll niður á jörðina. Og Jahve lét hagl falla yfir jörð Egyptalands.'),
(1767, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 24, 'OT', 'Og það var hagl, og eldur blossaði upp í miðju haglinu, afar þungt, slíkt sem ekki hafði verið í öllu Egyptalandi, síðan það varð að þjóð.'),
(1768, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 25, 'OT', 'Og haglið laust um alla jörð Egyptalands, allt sem var á akrinum, frá manni til skepnu. Haglið barði allt grasið á akrinum og braut hvert tré á akrinum.'),
(1769, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 26, 'OT', 'Aðeins á jörð Gósens, þar sem synir Ísraels voru, var ekkert hagl.'),
(1770, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 27, 'OT', 'Og Faraó sendi eftir Móses og Aroni og sagði við þá: Ég hef syndgað í þetta sinn. Jahve er réttlátur, en ég og lýður minn erum rangindamenn.'),
(1771, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 28, 'OT', 'Biðjið Jahve, því að nóg er af þrumuröddum Guðs og hagli. Ég mun láta ykkur fara, og þið skuluð ekki framar standa.'),
(1772, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 29, 'OT', 'Og Móses sagði við hann: Þegar ég fer út úr borginni, mun ég rétta upp lófa mína til Jahve. Þrumuraddirnar hætta og haglið verður ekki framar, til þess að þú vitir að jörðin er Jahve.'),
(1773, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 30, 'OT', 'En þú og þjóna þína: ég veit að þið óttist enn ekki fyrir andliti Jahve Guðs.'),
(1774, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 31, 'OT', 'Hörinn og byggið voru eyðilögð, því að byggið var í ax og hörinn í knúppum.'),
(1775, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 32, 'OT', 'En hveitið og spelturinn voru ekki eyðilögð, því að þau spruttu seinna.'),
(1776, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 33, 'OT', 'Og Móses fór út úr borginni frá Faraó og rétti út lófa sína til Jahve. Þá hættu þrumuraddirnar og haglið, og regnið hellti ekki lengur niður á jörðina.'),
(1777, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 34, 'OT', 'Og Faraó sá að regnið, haglið og þrumuraddirnar voru hætt. Þá syndgaði hann enn og herti hjarta sitt, hann og þjónar hans.'),
(1778, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 9, 35, 'OT', 'Og hjarta Faraós harðnaði, og hann lét sonu Ísraels ekki fara, eins og Jahve hafði talað með hendi Móses.'),
(1779, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 1, 'OT', 'Og Jahve sagði við Móses: Far þú inn til Faraós, því að ég hef gert hjarta hans og hjörtu þjóna hans þung, til þess að ég geti sýnt þessi tákn mín meðal þeirra.'),
(1780, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 2, 'OT', 'Og til þess að þú getir sagt í eyrum sonar þíns og sonarsonar þíns frá því, hvernig ég fór með Egyptaland og frá táknum mínum, sem ég gerði meðal þeirra, og þá skuluð þið vita að ég er Jahve.'),
(1781, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 3, 'OT', 'Og Móses og Aron gengu inn til Faraós og sögðu við hann: Svo segir Jahve, Guð Hebrea: Hversu lengi ætlar þú að neita að beygja þig fyrir andliti mínu? Lát lýð minn fara, svo að hann geti þjónað mér.'),
(1782, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 4, 'OT', 'Því að ef þú neitar að láta lýð minn fara, sjá, á morgun læt ég engisprettur koma yfir landamæri þín.'),
(1783, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 5, 'OT', 'Og þær munu hylja augu jarðarinnar, svo að ekki sé hægt að sjá jörðina. Þær munu eta það sem eftir er af undankomunni, sem ykkur var eftir af haglinu, og þær munu eta öll trén, sem vaxa fyrir ykkur á akrinum.'),
(1784, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 6, 'OT', 'Og hús þín munu fyllast og hús allra þjóna þinna og hús allra Egypta, það sem feður þínir og feður feðra þinna hafa aldrei séð, frá þeim degi sem þeir voru á jörðinni og allt til þessa dags. Og hann sneri sér við og gekk út frá Faraó.'),
(1785, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 7, 'OT', 'Og þjónar Faraós sögðu við hann: Hversu lengi á þessi maður að vera okkur til snöru? Lát mennina fara, svo að þeir geti þjónað Jahve Guði sínum. Veistu ekki enn að Egyptaland er tortímt?'),
(1786, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 8, 'OT', 'Og Móses og Aron voru færðir aftur til Faraós, og hann sagði við þá: Farið og þjónið Jahve Guði yðar. Hverjir eru það sem eiga að fara?'),
(1787, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 9, 'OT', 'Og Móses sagði: Með sveinum okkar og öldungum förum við, með sonum okkar og dætrum, með sauðfé okkar og nautgripum okkar förum við, því að hátíð Jahve er okkur.'),
(1788, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 10, 'OT', 'Og hann sagði við þá: Já, Jahve sé með yður, eins og ég sendi yður og börn yðar! Sjáið að illt er fyrir andliti yðar.'),
(1789, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 11, 'OT', 'Nei, ekki svo. Farið nú þið karlmennirnir og þjónið Jahve, því að það er það sem þið sóttust eftir. Og þeir voru reknir burt frá andliti Faraós.'),
(1790, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 12, 'OT', 'Og Jahve sagði við Móses: Rétt út hönd þína yfir Egyptaland fyrir engisprettuna, svo að hún komi yfir jörð Egyptalands og éti allt gras jarðarinnar, allt sem haglið lét eftir.'),
(1791, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 13, 'OT', 'Og Móses rétti út staf sinn yfir Egyptaland, og Jahve lét austanandann blása yfir jörðina allan þann dag og alla nóttina. Þegar morguninn kom, bar austanandinn engisprettuna.'),
(1792, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 14, 'OT', 'Og engisprettan gekk yfir alla jörð Egyptalands og settist um öll landamæri Egyptalands. Hún var afar þung. Fyrir andliti hennar hafði ekki verið slík engispretta, og eftir hana verður ekki slík.'),
(1793, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 15, 'OT', 'Og hún huldi augu allrar jarðarinnar, svo að jörðin myrkvaðist. Hún át allt gras jarðarinnar og ávexti trjánna, sem haglið hafði látið eftir. Ekkert grænt var eftir á trén né á grænu grasi akursins í öllu Egyptalandi.'),
(1794, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 16, 'OT', 'Og Faraó flýtti sér að kalla á Móses og Aron og sagði: Ég hef syndgað gegn Jahve Guði yðar og gegn yður.'),
(1795, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 17, 'OT', 'En fyrirgefið mér nú syndina í þetta eina sinn, og biðjið Jahve Guð yðar að taka þennan dauða burt frá mér.'),
(1796, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 18, 'OT', 'Og hann gekk út frá Faraó og bað til Jahve.'),
(1797, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 19, 'OT', 'Og Jahve sneri vestanandanum sterkum, og hann lyfti engisprettunni og kastaði henni í Sefhafið. Ekki varð ein engispretta eftir á öllum landamærum Egyptalands.'),
(1798, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 20, 'OT', 'En Jahve herti hjarta Faraós, og hann lét sonu Ísraels ekki fara.'),
(1799, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 21, 'OT', 'Og Jahve sagði við Móses: Rétt út hönd þína til himins, svo að myrkur komi yfir jörð Egyptalands, myrkur sem hægt er að þreifa á.'),
(1800, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 22, 'OT', 'Og Móses rétti út hönd sína til himins, og það varð þykkt myrkur um alla jörð Egyptalands í þrjá daga.'),
(1801, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 23, 'OT', 'Enginn maður sá bróður sinn og enginn maður reis úr sæti sínu í þrjá daga, en hjá öllum sonum Ísraels var ljós í bústöðum þeirra.'),
(1802, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 24, 'OT', 'Þá kallaði Faraó á Móses og sagði: Farið og þjónið Jahve. Aðeins sauðfé ykkar og naut skulu eftir verða. Börn ykkar mega fara með ykkur.'),
(1803, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 25, 'OT', 'Móses sagði: Þú skalt sjálfur láta í hendur okkar sláturfórnir og brennifórnir, og við munum fórna Jahve Guði okkar.'),
(1804, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 26, 'OT', 'Og fénaður okkar skal líka fara með okkur; ekki ein klauf skal eftir verða, því að af honum tökum við til að þjóna Jahve Guði okkar, og við vitum ekki hvernig við eigum að þjóna Jahve fyrr en við komum þangað.'),
(1805, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 27, 'OT', 'Og Jahve herti hjarta Faraós, og hann vildi ekki láta þá fara.'),
(1806, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 28, 'OT', 'Faraó sagði við hann: Farðu burt frá mér, gættu þín, að þú sjáir ekki andlit mitt framar, því að á þeim degi sem þú sérð andlit mitt skaltu deyja.'),
(1807, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 10, 29, 'OT', 'Móses sagði: Rétt hefur þú talað. Ég mun ekki framar sjá andlit þitt.'),
(1808, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 1, 'OT', 'Þá sagði Jahve við Móses: Enn mun ég leiða eina plágu yfir Faraó og Egyptaland. Eftir það mun hann láta ykkur fara héðan. Þegar hann lætur ykkur fara mun hann reka ykkur algerlega burt héðan.'),
(1809, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 2, 'OT', 'Talaðu nú í eyru lýðsins: Hver maður biðji náunga sinn og hver kona náunga sína um áhöld úr silfri og gulli.'),
(1810, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 3, 'OT', 'Og Jahve gaf lýðnum hylli í augum Egypta. Ennfremur var maðurinn Móses mjög mikill í Egyptalandi, í augum þjóna Faraós og í augum lýðsins.'),
(1811, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 4, 'OT', 'Og Móses sagði: Svo segir Jahve: Um miðnætti á nóttinni mun ég fara um Egyptaland.'),
(1812, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 5, 'OT', 'Þá munu allir frumgetnir í Egyptalandi deyja, allt frá frumgetnum Faraós, sem situr í hásæti sínu, til frumgetins ambáttar, sem er að baki kvarnarsteinanna, og allir frumgetnir af skepnum.'),
(1813, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 6, 'OT', 'Og mikið neyðaróp mun heyrast um alla jörð Egyptalands, slíkt sem aldrei hefur verið og aldrei verður framar.'),
(1814, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 7, 'OT', 'En meðal allra sona Ísraels skal enginn hundur hreyfa tungu sína, hvorki gegn manni né skepnu, svo að þið vitið að Jahve gerir mun á Egyptalandi og Ísrael.'),
(1815, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 8, 'OT', 'Og allir þessir þjónar þínir munu koma niður til mín og falla fram fyrir mér og segja: Far þú út og allur lýðurinn sem fylgir þér á fótum. Eftir það mun ég fara út. Og hann gekk út frá Faraó í brennandi reiði.'),
(1816, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 9, 'OT', 'Og Jahve sagði við Móses: Faraó mun ekki hlýða ykkur, svo að undur mín fjölgi í Egyptalandi.'),
(1817, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 11, 10, 'OT', 'Móses og Aron gerðu öll þessi undur frammi fyrir andliti Faraós. En Jahve herti hjarta Faraós, og hann lét ekki sonu Ísraels fara úr landi sínu.'),
(1818, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 1, 'OT', 'Og Jahve sagði við Móses og Aroni í Egyptalandi, svo hljóðandi:'),
(1819, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 2, 'OT', 'Þessi mánuður skal vera höfuð mánaða fyrir yður. Hann skal vera fyrsti mánuður ársins fyrir yður.'),
(1820, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 3, 'OT', 'Talið við allan söfnuð Ísraels og segið: Á tíunda degi þessa mánaðar taki hver maður lamb handa sér, eitt lamb fyrir hvert hús feðra sinna, eitt lamb fyrir hvert hús.'),
(1821, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 4, 'OT', 'Ef húsið er of lítið fyrir lamb, þá taki hann og næsti nágranni hans, sem býr næst húsi hans, lamb eftir tölu sála. Hver maður skal leggja til lambsins eftir því sem hann getur étið af mat.'),
(1822, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 5, 'OT', 'Lambið skal vera gallalaust, karldýr, eins árs gamalt. Þið megið taka það úr hópi lamba eða geita.'),
(1823, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 6, 'OT', 'Það skal vera yður til varðstöðu fram að fjórtánda degi þessa mánaðar. Þá skal allur söfnuður Ísraels slátra því á milli kvölda.'),
(1824, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 7, 'OT', 'Þeir skulu taka af blóðinu og bera á báða dyrastafi og dyrahlut húsanna, þar sem þeir eta lambið.'),
(1825, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 8, 'OT', 'Þeir skulu eta holdið sömu nótt, steikt við eldi, með ósýrðu brauði og beiskju.'),
(1826, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 9, 'OT', 'Ekki skuluð þér eta það hrátt, né soðið í vatni, heldur steikt við eldi, með höfði, leggjum og innyflum.'),
(1827, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 10, 'OT', 'Þér skuluð ekki láta neitt af því verða eftir til morguns, og það sem verður eftir til morguns skuluð þér brenna í eldi.'),
(1828, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 11, 'OT', 'Þannig skuluð þér eta það: með lendar yðar gyrtar, skó á fótum yðar og staf í hendi yðar, og þér skuluð eta það í flýti. Þetta er páskafórn til Jahve.'),
(1829, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 12, 'OT', 'Því að ég mun fara um Egyptaland þessa nótt og slá hvern frumgetinn í Egyptalandi, bæði frá mönnum og skepnum, og á öllum guðum Egyptalands mun ég fullnægja dómum. Ég er Jahve.'),
(1830, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 13, 'OT', 'Blóðið skal vera yður til tákns á húsunum þar sem þér eruð. Þegar ég sé blóðið mun ég ganga fram hjá yður, og engin plága skal koma yfir yður til eyðingar, þegar ég slæ í Egyptalandi.'),
(1831, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 14, 'OT', 'Þessi dagur skal vera yður til minningar, og þér skuluð halda hann sem hátíð til Jahve. Um allar kynslóðir yðar skuluð þér halda hann sem lagaákvæði um eilífð.'),
(1832, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 15, 'OT', 'Í sjö daga skuluð þér eta ósýrð brauð. Já, á fyrsta degi skuluð þér fjarlægja súrdeig úr húsum yðar. Því að sú sál sem etur súrt brauð skal afmáð verða úr Ísrael frá fyrsta degi til sjöunda dags.'),
(1833, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 16, 'OT', 'Á fyrsta degi skal vera helgi samkoma, og á sjöunda degi helgi samkoma. Engin störf skulu unnin á þeim, nema það sem sérhver sál þarf að eta; það einungis má gera fyrir yður.'),
(1834, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 17, 'OT', 'Þér skuluð gæta ósýrðra brauða, því að einmitt á þessum degi leiddi ég heri yðar út af Egyptalandi. Þér skuluð halda þennan dag um allar kynslóðir yðar sem lagaákvæði um eilífð.'),
(1835, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 18, 'OT', 'Í fyrsta mánuði, á fjórtánda degi mánaðarins að kvöldi, skuluð þér eta ósýrð brauð allt til tuttugasta og fyrsta dags mánaðarins að kvöldi.'),
(1836, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 19, 'OT', 'Í sjö daga má ekki finnast súrdeig í húsum yðar, því að sú sál sem etur súrt brauð skal afmáð verða úr söfnuði Ísraels, hvort sem hann er innfæddur maður eða útlendingur í landinu.'),
(1837, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 20, 'OT', 'Ekkert súrt skuluð þér eta. Í öllum bústöðum yðar skuluð þér eta ósýrð brauð.'),
(1838, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 21, 'OT', 'Móses kallaði saman alla öldunga Ísraels og sagði við þá: Takið sauðfé handa yður eftir ættum yðar og slátrið páska.'),
(1839, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 22, 'OT', 'Takið knippi af ísópi, dýfið því í blóðið sem er við þröskuldinn og berið af blóðinu á dyrastafina og dyrahlutinn. Enginn maður yðar skal fara út um inngang húss síns fyrr en um morgun.'),
(1840, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 23, 'OT', 'Því að Jahve mun fara um til að slá Egyptaland, og hann mun sjá blóðið á dyrahlutinum og á dyrastöfum tveimur. Jahve mun ganga fram hjá inngangi yðar og láta eyðinguna ekki koma inn í hús yðar til að slá.'),
(1841, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 24, 'OT', 'Og þetta orð skuluð þér varðveita sem lög fyrir þig og sonu þína um eilífð.'),
(1842, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 25, 'OT', 'Og þegar þér komið í landið sem Jahve mun gefa yður, eins og hann hefur heitið, þá skuluð þér varðveita þessa þjónustu.'),
(1843, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 26, 'OT', 'Og þegar synir yðar segja við yður: Hvað er þessi þjónusta fyrir yður?'),
(1844, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 27, 'OT', 'Þá skuluð þér svara: Þetta er sláturfórn páska til Jahve, sem gekk fram hjá húsum sona Ísraels í Egyptalandi, þegar hann sló Egypta, en bjargaði húsum okkar. Þá laut lýðurinn höfði og féll fram.'),
(1845, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 28, 'OT', 'Og synir Ísraels fóru og gerðu eins og Jahve hafði boðið Mósesi og Aroni. Þannig gerðu þeir.'),
(1846, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 29, 'OT', 'Um helming nætur sló Jahve alla frumgetna í Egyptalandi, frá frumgetnum Faraós, sem situr í hásæti sínu, til frumgetins fanga, sem var í brunnhúsinu, og allan frumgetinn fénað.'),
(1847, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 30, 'OT', 'Og Faraó reis upp um nóttina, hann og allir þjónar hans og allir Egyptar, og mikið neyðaróp varð í Egyptalandi, því að ekkert hús var þar sem ekki var dauður maður.'),
(1848, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 31, 'OT', 'Og hann kallaði á Móses og Aron um nóttina og sagði: Standið upp, farið burt úr lýð mínum, bæði þér og synir Ísraels, og farið og þjónið Jahve eins og þér hafið sagt.'),
(1849, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 32, 'OT', 'Takið með yður sauðfé og naut, eins og þér hafið sagt, og farið. Blessið einnig mig.'),
(1850, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 33, 'OT', 'Og Egyptar lögðu hart að lýðnum til að flýta brottför þeirra úr landinu, því að þeir sögðu: Við erum allir dauðir.'),
(1851, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 34, 'OT', 'Og lýðurinn tók deig sitt áður en það var súrnað. Deigtrog þeirra voru vafin í skikkjum þeirra og bundin á öxlum þeirra.'),
(1852, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 35, 'OT', 'Synir Ísraels gerðu samkvæmt orði Mósesar og báðu af Egyptalandi um áhöld úr silfri og áhöld úr gulli, og skikkjur.'),
(1853, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 36, 'OT', 'Og Jahve gaf lýðnum hylli í augum Egyptalands, svo að þeir lánuðu þeim, og þeir rændu Egyptaland.'),
(1854, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 37, 'OT', 'Synir Ísraels lögðu af stað frá Raamses til Súkkóts, um sex hundruð þúsund fótgangandi menn, auk barna.'),
(1855, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 38, 'OT', 'Og mikill blandaður lýður fór einnig með þeim, ásamt sauðfé og nautum, og mikill fénaður.'),
(1856, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 39, 'OT', 'Þeir bökuðu úr deiginu, sem þeir höfðu flutt út frá Egyptalandi, hlóðakökur úr ósýrðu brauði, því að það var ekki súrnað, þar sem þeir höfðu verið reknir út frá Egyptalandi og gátu ekki tafist. Engar vistir höfðu þeir útbúið sér.'),
(1857, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 40, 'OT', 'Bústaður sona Ísraels í Egyptalandi var fjögur hundruð og þrjátíu ár.'),
(1858, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 41, 'OT', 'Að endi fjögur hundruð og þrjátíu ára, einmitt þennan dag, gekk allur her Jahve út af Egyptalandi.'),
(1859, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 42, 'OT', 'Þetta er nótt varðveislu fyrir Jahve, til að leiða þá út af Egyptalandi. Þessi nótt er Jahve helguð, varðveisla fyrir alla sonu Ísraels um kynslóðir þeirra.'),
(1860, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 43, 'OT', 'Og Jahve sagði við Móses og Aroni: Þetta er lagaákvæði páska. Enginn sonur útlendings skal eta af því.'),
(1861, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 44, 'OT', 'En sérhver þjónn manns, sem er keyptur sem kaup fyrir silfur, skal eta af því, þegar hann er umskorinn.'),
(1862, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 45, 'OT', 'Útlendingur og leigjandi skulu ekki eta af því.'),
(1863, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 46, 'OT', 'Í einu húsi skal það etið. Þú skalt ekki bera neitt af holdinu út úr húsinu, og ekki brjóta bein þess.'),
(1864, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 47, 'OT', 'Allur söfnuður Ísraels skal gera það.'),
(1865, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 48, 'OT', 'Ef útlendingur býr hjá þér og vill halda páska fyrir Jahve, þá skal allir karlmenn hans umskerast, og þá getur hann komið og gert það. Hann skal þá vera eins og innfæddur maður í landinu, en enginn óumskorinn skal eta af því.'),
(1866, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 49, 'OT', 'Ein lögmál skulu gilda fyrir innfæddan mann og útlendinginn sem býr meðal yðar.'),
(1867, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 50, 'OT', 'Og allir synir Ísraels gerðu eins og Jahve hafði boðið Mósesi og Aroni. Þannig gerðu þeir.'),
(1868, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 12, 51, 'OT', 'Og á sjálfum þessum degi leiddi Jahve sonu Ísraels út af Egyptalandi, eftir herjum þeirra.'),
(1869, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(1870, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 2, 'OT', 'Helgaðu mér hvern frumgetinn, og hvern frumburð sem opnar móðurlíf meðal sona Ísraels, bæði af mönnum og skepnum; hann er minn.'),
(1871, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 3, 'OT', 'Og Móses sagði við lýðinn: Minnist þessa dags, þegar þér fóruð út af Egyptalandi, úr húsi þjóna, því að með styrk handar sinnar leiddi Jahve yður þaðan út. Súrdeig skuluð þér ekki eta.'),
(1872, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 4, 'OT', 'Í dag farið þér út í mánuði Abíb.'),
(1873, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 5, 'OT', 'Og þegar Jahve leiðir þig inn í landið Kanaaníta, Hetíta, Amoríta, Hevíta og Jebúsíta, sem hann sór feðrum þínum að gefa þér, land sem flýtur í mjólk og hunangi, þá skalt þú halda þessa þjónustu í þessum mánuði.'),
(1874, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 6, 'OT', 'Í sjö daga skalt þú eta ósýrð brauð, og á sjöunda degi skal vera hátíð fyrir Jahve.'),
(1875, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 7, 'OT', 'Ósýrð brauð skalt þú eta í sjö daga. Hjá þér skal ekki sjást súrdeig, og ekki heldur súrdeig á öllum landamærum þínum.'),
(1876, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 8, 'OT', 'Og þú skalt segja syni þínum á þeim degi: Þetta er gert vegna þess sem Jahve gerði mér, þegar ég fór út af Egyptalandi.'),
(1877, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 9, 'OT', 'Og það skal vera þér sem tákn á hendi þinni og sem minning á milli augna þinna, til þess að lögmál Jahve sé í munni þínum. Því að með styrk handar leiddi Jahve þig út af Egyptalandi.'),
(1878, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 10, 'OT', 'Og þú skalt varðveita þetta lagaákvæði á tilsettri hátíð sinni, frá degi til dags.'),
(1879, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 11, 'OT', 'Og þegar Jahve leiðir þig inn í land Kanaaníta, eins og hann sór þér og feðrum þínum, og gefur þér það,'),
(1880, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 12, 'OT', 'Þú skalt láta hvern frumburð sem opnar móðurlíf fara til Jahve, og hvern frumburð af skepnum þínum sem er karlkyns skal vera Jahve.'),
(1881, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 13, 'OT', 'Og hvert frumburð asna skalt þú leysa með lambi. Ef þú leysir hann ekki, þá skalt þú brjóta háls hans. Og hvern frumgetinn mann af sonum þínum skalt þú leysa.'),
(1882, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 14, 'OT', 'Og þegar sonur þinn spyr þig á morgun: Hvað er þetta? þá skalt þú segja honum: Með styrk handar leiddi Jahve okkur út af Egyptalandi, úr húsi þjóna.'),
(1883, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 15, 'OT', 'Og þegar Faraó harðnaði í að láta okkur fara, drap Jahve alla frumgetna í Egyptalandi, frá frumgetnum manni til frumgetinnar skepnu. Þess vegna fórna ég Jahve öllum frumburðum karlkyns, en frumgetna sona minna leysi ég.'),
(1884, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 16, 'OT', 'Og það skal vera þér tákn á hendi þinni og enniband á milli augna þinna, því að með styrk handar leiddi Jahve okkur út af Egyptalandi.'),
(1885, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 17, 'OT', 'Og þegar Faraó hafði látið lýðinn fara, leiddi Guð hann ekki um veg landsins Filista, því að hann var nálægt. Guð hugsaði: Lýðurinn gæti iðrast, þegar hann sér stríð, og snúið aftur til Egyptalands.'),
(1886, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 18, 'OT', 'Og Guð lét lýðinn fara um veg eyðimerkur að Rauðahafi, og synir Ísraels fóru vopnaðir út af Egyptalandi.'),
(1887, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 19, 'OT', 'Og Móses tók bein Jósefs með sér, því að hann hafði svarið sonum Ísraels eið og sagt: Guð mun vitja yðar, og þá skuluð þér flytja bein mín héðan með yður.'),
(1888, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 20, 'OT', 'Og þeir lögðu af stað frá Súkkót og settu tjöld sín í Etam, við enda eyðimerkurinnar.'),
(1889, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 21, 'OT', 'Og Jahve gekk fyrir andliti þeirra um daginn í súlu úr skýi til að leiða þá á vegi, og um nóttina í súlu úr eldi til að lýsa þeim, svo að þeir gætu ferðast dag og nótt.'),
(1890, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 13, 22, 'OT', 'Súlan úr skýinu vék ekki um daginn og súlan úr eldinum ekki um nóttina, fyrir andliti lýðsins.'),
(1891, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(1892, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 2, 'OT', 'Tala við sonum Ísraels: Þeir skulu snúa við og setjast að fyrir framan Pí-Hahírót, milli Migdóls og hafsins, andspænis Baal-Sefon. Fyrir andliti þess skuluð þér setjast að við hafið.'),
(1893, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 3, 'OT', 'Og Faraó mun segja um sonu Ísraels: Þeir eru ráðvilltir í landinu; eyðimörkin hefur lokað þá inni.'),
(1894, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 4, 'OT', 'Og ég mun herða hjarta Faraós, og hann mun elta þá. Ég mun auðsýna dýrð mína á Faraó og öllum styrk hans, og Egyptar skulu vita að ég er Jahve. Og þeir gerðu svo.'),
(1895, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 5, 'OT', 'Og það var sagt við konung Egyptalands að lýðurinn væri flúinn. Þá sneri hjarta Faraós og þjóna hans sér gegn lýðnum, og þeir sögðu: Hvað höfum við gert, að við höfum látið Ísrael fara frá þjónustu okkar?'),
(1896, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 6, 'OT', 'Og hann lét beisla vagn sinn og tók lýð sinn með sér.'),
(1897, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 7, 'OT', 'Og hann tók sex hundruð úrvals vagna og alla vagna Egyptalands, og þriðji maður var á þeim öllum.'),
(1898, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 8, 'OT', 'Og Jahve herti hjarta Faraós, konungs Egyptalands, og hann elti sonu Ísraels, en synir Ísraels fóru út með upplyftri hendi.'),
(1899, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 9, 'OT', 'Og Egyptar eltu þá og náðu þeim, þar sem þeir höfðu tjaldað við hafið: allir hestar og vagnar Faraós, riddarar hans og allur styrkur hans, við Pí-Hahírót, andspænis Baal-Sefon.'),
(1900, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 10, 'OT', 'Og Faraó nálgaðist, og synir Ísraels hófu upp augu sín, og sjá, Egyptar héldu á eftir þeim. Þeir óttuðust mjög og hrópuðu til Jahve.'),
(1901, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 11, 'OT', 'Og þeir sögðu við Móses: Var það vegna þess að engar grafir voru í Egyptalandi, að þú tókst okkur til að deyja í eyðimörkinni? Hvað er þetta sem þú hefur gert okkur, að leiða okkur út af Egyptalandi?'),
(1902, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 12, 'OT', 'Var þetta ekki orðið sem við sögðum þér í Egyptalandi: Lát af okkur, og við munum þjóna Egyptum, því að betra er fyrir okkur að þjóna Egyptum en að deyja í eyðimörkinni?'),
(1903, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 13, 'OT', 'Og Móses sagði við lýðinn: Óttist ekki. Standið kyrr og sjáið hjálpræði Jahve, sem hann mun veita yður í dag. Því að Egypta, sem þér sjáið í dag, munuð þér aldrei sjá framar, um eilífð.'),
(1904, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 14, 'OT', 'Jahve mun berjast fyrir yður, og þér skuluð þegja.'),
(1905, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 15, 'OT', 'Og Jahve sagði við Móses: Hví hrópar þú til mín? Talaðu við sonum Ísraels, að þeir leggi af stað.'),
(1906, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 16, 'OT', 'Og þú, lyftu staf þínum og réttu út hönd þína yfir hafið og kljúf það, svo að synir Ísraels fari í gegnum hafið á þurrlendi.'),
(1907, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 17, 'OT', 'Og sjá, ég mun herða hjarta Egypta, og þeir munu elta þá. Ég mun auðsýna dýrð mína á Faraó og öllum styrk hans, á vögnum hans og riddurum hans.'),
(1908, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 18, 'OT', 'Og Egyptar skulu vita að ég er Jahve, þegar ég hef auðsýnt dýrð mína á Faraó, á vögnum hans og riddurum hans.'),
(1909, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 19, 'OT', 'Og sendiboði Guðs, sem fór á undan herbúðum Ísraels, færði sig og fór á eftir þeim. Súlan úr skýinu færði sig frá andliti þeirra og stóð að baki þeim.'),
(1910, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 20, 'OT', 'Og hann kom á milli herbúða Egyptalands og herbúða Ísraels. Skýið og myrkrið voru þar, og það lýsti nóttina, og annar nálgaðist ekki hinn alla nóttina.'),
(1911, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 21, 'OT', 'Og Móses rétti út hönd sína yfir hafið, og Jahve lét hafið víkja undan með sterkum anda úr austri alla nóttina og gerði hafið að þurrlendi, og vötnin klofnuðu.'),
(1912, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 22, 'OT', 'Og synir Ísraels gengu inn í miðju hafsins á þurrlendi, og vötnin voru þeim múr til hægri handar og til vinstri handar.'),
(1913, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 23, 'OT', 'Og Egyptar eltu þá og fóru inn á eftir þeim, allir hestar Faraós, vagnar hans og riddarar hans, inn í miðju hafsins.'),
(1914, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 24, 'OT', 'Og undir morgni, á næturvöku, leit Jahve til herbúða Egyptalands, í súlu úr eldi og skýi, og ruglaði herbúðir Egypta.'),
(1915, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 25, 'OT', 'Og hann tók hjólin af vögnum þeirra, og þeir óku þá með erfiðismunum. Og Egyptar sögðu: Við skulum flýja frá andliti Ísraels, því að Jahve berst fyrir þá gegn Egyptalandi.'),
(1916, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 26, 'OT', 'Og Jahve sagði við Móses: Réttu út hönd þína yfir hafið, svo að vötnin snúi aftur yfir Egyptaland, yfir vagna þeirra og riddara þeirra.'),
(1917, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 27, 'OT', 'Og Móses rétti út hönd sína yfir hafið, og hafið snerist aftur undir morgun til síns fyrra horfs, en Egyptar flýðu á móti því. Og Jahve steypti Egyptum í miðju hafinu.'),
(1918, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 28, 'OT', 'Og vötnin sneru aftur og huldu vagna og riddara, allan styrk Faraós, sem höfðu fylgt þeim inn í hafið. Ekki einn af þeim varð eftir.'),
(1919, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 29, 'OT', 'En synir Ísraels gengu á þurrlendi inn í miðju hafsins, og vötnin voru þeim múr til hægri handar og til vinstri handar.'),
(1920, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 30, 'OT', 'Þann dag frelsaði Jahve Ísrael úr hendi Egyptalands, og Ísrael sá Egypta dauða á vör hafsins.'),
(1921, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 14, 31, 'OT', 'Og Ísrael sá hina miklu hönd, sem Jahve gerði í Egyptalandi. Lýðurinn óttaðist Jahve, og hann trúði á Jahve og á Móses þjón hans.'),
(1922, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 1, 'OT', 'Þá söng Móses og synir Ísraels þetta söng fyrir Jahve, og þeir sögðu: Ég vil syngja Jahve, því að hann er mjög upphafinn. Hest og riddara hans hefur hann kastað í hafið.'),
(1923, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 2, 'OT', 'Styrkur minn og söngur minn er Jah, og hann er orðinn mér að hjálpræði. Hann er Guð minn, og ég mun prísa hann, Guð föður míns, og ég mun upphefja hann.'),
(1924, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 3, 'OT', 'Jahve er maður stríðs; Jahve er nafn hans.'),
(1925, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 4, 'OT', 'Vagna Faraós og styrk hans kastaði hann í hafið, og úrvalið af þriðju mönnum hans sökk í Rauðahafið.'),
(1926, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 5, 'OT', 'Undirdjúpin huldu þá; þeir sukku í djúpið eins og steinn.'),
(1927, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 6, 'OT', 'Hægri hönd þín, Jahve, er dýrðleg í krafti. Hægri hönd þín, Jahve, molar óvininn.'),
(1928, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 7, 'OT', 'Í mikilli hátign þinni steypir þú þeim sem rísa gegn þér; þú sendir brennandi reiði þína, sem eyðir þeim eins og hálmstrá.'),
(1929, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 8, 'OT', 'Og fyrir andardrætti nefs þíns hrúguðust vötnin; rennandi vötnin stóðu upp eins og haugur, og undirdjúpin storknuðu í hjarta hafsins.'),
(1930, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 9, 'OT', 'Óvinurinn sagði: Ég mun elta, ég mun ná, ég mun skipta herfangi. Sál mín mun fyllast af þeim. Ég mun bregða sverði mínu, hönd mín mun eyða þeim.'),
(1931, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 10, 'OT', 'Þú blést með anda þínum, hafið huldi þá; þeir sukku eins og blý í voldugum vötnum.'),
(1932, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 11, 'OT', 'Hver er þér líkur meðal guða, Jahve? Hver er þér líkur, dýrlegur í helgi, ógnvekjandi í lofgjörðum, sá sem gerir undur?'),
(1933, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 12, 'OT', 'Þú réttir út hægri hönd þína, og jörðin gleypti þá.'),
(1934, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 13, 'OT', 'Þú hefur í miskunn þinni leitt lýð þennan, sem þú hefur leyst; þú hefur í styrk þínum leitt hann til bústaðar helgi þíns.'),
(1935, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 14, 'OT', 'Lýðirnir heyrðu og skulfu; kvöl greip íbúa Filisteu.'),
(1936, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 15, 'OT', 'Þá skelfdust höfðingjar Edóms og hrútar Móabs; skjálfti greip þá, og allir íbúar Kanaans bráðnuðu.'),
(1937, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 16, 'OT', 'Skelfing og ótti falli yfir þá; við mikinn mátt arms þíns verði þeir hreyfingarlausir eins og steinn, þangað til lýður þinn fer yfir, Jahve, þangað til þessi lýður, sem þú hefur eignast, fer yfir.'),
(1938, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 17, 'OT', 'Þú munt leiða þá inn og gróðursetja þá á fjalli arfleifðar þinnar, þar sem þú hefur gert undirstöðu bústaðar þíns, Jahve. Helgidómur Drottins, sem hendur þínar hafa staðfest.'),
(1939, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 18, 'OT', 'Jahve mun ríkja um eilífð og ævinlega.'),
(1940, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 19, 'OT', 'Því að hestur Faraós með vögnum sínum og riddurum fór í hafið, og Jahve lét vötn hafsins snúa aftur yfir þá; en synir Ísraels gengu á þurrlendi inn í miðju hafsins.'),
(1941, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 20, 'OT', 'Þá tók Mirjam spákonan, systir Arons, bumbu í hönd sína, og allar konurnar fóru á eftir henni með bumbum og dansi.'),
(1942, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 21, 'OT', 'Og Mirjam svaraði þeim: Syngið Jahve, því að hann er mjög upphafinn. Hest og riddara hans hefur hann kastað í hafið.'),
(1943, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 22, 'OT', 'Og Móses lét Ísrael fara frá Rauðahafinu, og þeir fóru út í eyðimörk Súr. Í þrjá daga gengu þeir í eyðimörkinni og fundu ekki vatn.'),
(1944, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 23, 'OT', 'Og þeir komu til Möru, en gátu ekki drukkið vatnið úr Möru, því að það var beiskt; þess vegna var nafnið á staðnum kallað Mara.'),
(1945, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 24, 'OT', 'Og lýðurinn kvartaði við Móses og sagði: Hvað eigum við að drekka?'),
(1946, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 25, 'OT', 'Og hann hrópaði til Jahve, og Jahve sýndi honum tré. Hann kastaði því í vatnið, og vatnið varð sætt. Þar setti hann honum lög og dóm, og þar reyndi hann hann.'),
(1947, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 26, 'OT', 'Og hann sagði: Ef þú hlýðir rödd Jahve Guðs þíns og gerir það sem rétt er í augum hans, hlýðir boðorðum hans og varðveitir öll lög hans, þá mun ég ekki láta yfir þig koma neinn af þeim sjúkdómum sem ég lét koma yfir Egyptaland, því að ég er Jahve, sem græðir þig.'),
(1948, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 15, 27, 'OT', 'Og þeir komu til Elím, og þar voru tólf augu vatns og sjötíu döðlupálmar. Þeir settu þar tjöld sín við vatnið.'),
(1949, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 1, 'OT', 'Og þeir fóru frá Elím, og allur söfnuður sona Ísraels kom í eyðimörkina Sín, sem er milli Elím og Sínaí, á fimmtánda degi annars mánaðar eftir að þeir fóru út úr landi Egyptalands.'),
(1950, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 2, 'OT', 'Og allur söfnuður sona Ísraels kvartaði gegn Mósesi og Aroni í eyðimörkinni.'),
(1951, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 3, 'OT', 'Og synir Ísraels sögðu við þá: Ó, að vér hefðum dáið af hendi Jahve í Egyptalandi, þegar vér sátum yfir kjötpottinum og átum brauð til saðningar! En þér hafið leitt oss út í þessa eyðimörk til þess að deyða allan þennan söfnuð af hungursneyð.'),
(1952, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 4, 'OT', 'Þá sagði Jahve við Móses: Sjá, ég mun láta brauð rigna yfir yður af himni. Lýðurinn skal ganga út og safna daglegum skammti sínum á hverjum degi, til þess að ég reyni hann, hvort hann gangi eftir lögmáli mínu eða ekki.'),
(1953, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 5, 'OT', 'Og á sjötta degi skulu þeir búa til það sem þeir koma með, og það skal verða tvöfalt afrit af því sem þeir safna dag frá degi.'),
(1954, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 6, 'OT', 'Og Móses og Aron sögðu við alla sonu Ísraels: Að kvöldi munuð þér vita að Jahve hefur leitt yður út úr Egyptalandi.'),
(1955, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 7, 'OT', 'Og að morgni munuð þér sjá dýrð Jahve, þegar hann heyrir murr yðar gegn Jahve. Hvað erum vér, að þér murrið gegn oss?'),
(1956, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 8, 'OT', 'Og Móses sagði: Þegar Jahve gefur yður hold að eta um kvöldið og brauð að morgni til saðningar, þegar Jahve heyrir murr yðar, sem þér murrið gegn honum, hvað erum vér þá? Murr yðar er ekki gegn oss, heldur gegn Jahve.'),
(1957, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 9, 'OT', 'Og Móses sagði við Aron: Seg við allan söfnuð sona Ísraels: Gangið fram fyrir andlit Jahve, því að hann hefur heyrt murr yðar.'),
(1958, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 10, 'OT', 'Og það var, þegar Aron talaði við allan söfnuð sona Ísraels, að þeir sneru sér að eyðimörkinni, og sjá, dýrð Jahve birtist í skýinu.'),
(1959, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 11, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(1960, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 12, 'OT', 'Ég hef heyrt murr sona Ísraels. Seg við þá: Í kvöldhúminu skuluð þér eta hold, og að morgni skuluð þér seðjast af brauði. Þá munuð þér vita að ég er Jahve, Guð yðar.'),
(1961, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 13, 'OT', 'Um kvöldið komu kornhænur og huldu herbúðirnar, og að morgni lá dögg umhverfis herbúðirnar.'),
(1962, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 14, 'OT', 'Þegar dögginni var lyft, sjá, þá lá á andliti eyðimerkurinnar eitthvað smágert og hrjúft, fínt eins og hrím á jörðinni.'),
(1963, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 15, 'OT', 'Og synir Ísraels sáu það og sögðu hver maður við bróður sinn: Hvað er þetta? Því að þeir vissu ekki hvað það var. Og Móses sagði við þá: Þetta er brauðið sem Jahve hefur gefið yður að eta.'),
(1964, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 16, 'OT', 'Þetta er það sem Jahve hefur boðið: Safnið af því, hver maður, eftir munni sínum, eitt knippi fyrir hvert höfuð, eftir tölu sála yðar; hver maður skal taka það í tjaldi sínu.'),
(1965, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 17, 'OT', 'Og synir Ísraels gerðu svo, og sumir söfnuðu meira, aðrir minna.'),
(1966, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 18, 'OT', 'Þeir mældu með knippinu, og sá sem hafði safnað meira hafði ekki of mikið, og sá sem hafði safnað minna hafði ekki of lítið; hver maður hafði safnað eftir munni sínum og mat.'),
(1967, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 19, 'OT', 'Og Móses sagði við þá: Enginn maður skal láta neitt af því verða eftir til morguns.'),
(1968, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 20, 'OT', 'En þeir hlýddu ekki Mósesi, og nokkrir menn létu eftir af því til morguns; þá gaus upp í því maðkur og það ódaunaði. Og Móses varð reiður við þá.'),
(1969, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 21, 'OT', 'Þeir söfnuðu því að morgni, hvern morgun, hver maður eftir munni sínum; og þegar sólin hitnaði, bráðnaði það.'),
(1970, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 22, 'OT', 'En á sjötta degi söfnuðu þeir tvöföldu afriti af brauði, tveimur knippum fyrir hvern mann; og allir höfðingjar söfnuðarins komu og sögðu Móses það.'),
(1971, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 23, 'OT', 'Og hann sagði við þá: Þetta er það sem Jahve hefur talað: Á morgun er hvíldardagur, helgi hvíldardagur Jahve. Það sem þér bakið, bakið, og það sem þér sjóðið, sjóðið; en allt það sem umfram er, leggið til varðstöðu fram til morguns.'),
(1972, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 24, 'OT', 'Og þeir geymdu það til morguns, eins og Móses bauð, og það varð ekki ódaunsamt, og var enginn ormur í því.'),
(1973, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 25, 'OT', 'Og Móses sagði: Etið það í dag, því að í dag er hvíldardagur fyrir Jahve; í dag munuð þér ekki finna það á akrinum.'),
(1974, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 26, 'OT', 'Í sex daga skuluð þér safna því, en á sjöunda degi, sem er hvíldardagur, þá mun ekkert af því vera.'),
(1975, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 27, 'OT', 'Og svo bar við á sjöunda degi, að nokkrir af lýðnum fóru út til að safna, en fundu ekkert.'),
(1976, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 28, 'OT', 'Og Jahve sagði við Móses: Hversu lengi neitið þér að varðveita boðorð mín og lögmál mín?'),
(1977, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 29, 'OT', 'Sjáið, því að Jahve hefur gefið yður hvíldardaginn; þess vegna gefur hann yður á sjötta degi brauð fyrir tvo daga. Sitjið hver maður kyrr á sínum stað; enginn maður fari út af sínum stað á sjöunda degi.'),
(1978, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 30, 'OT', 'Og lýðurinn hvíldist á sjöunda degi.'),
(1979, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 31, 'OT', 'Og hús Ísraels kallaði nafn þess manna; og það var eins og sæði kóríanders, hvítt, og bragð þess var eins og flatkaka með hunangi.'),
(1980, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 32, 'OT', 'Og Móses sagði: Þetta er það sem Jahve hefur boðið: Fyllið eitt knippi af því til varðstöðu fyrir kynslóðir yðar, svo að þær sjái brauðið sem ég gaf yður að eta í eyðimörkinni, þegar ég leiddi yður út úr Egyptalandi.'),
(1981, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 33, 'OT', 'Og Móses sagði við Aron: Tak einn pott og lát í hann eitt knippi af manna, og legg hann fyrir Jahve til varðstöðu fyrir kynslóðir yðar.'),
(1982, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 34, 'OT', 'Eins og Jahve bauð Mósesi, lagði Aron það fyrir andliti vitnisburðarins til varðstöðu.'),
(1983, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 35, 'OT', 'Og synir Ísraels átu manna í fjörutíu ár, þar til þeir komu til byggilegrar jarðar; þeir átu manna þar til þeir komu til enda jarðar Kanaans.'),
(1984, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 16, 36, 'OT', 'Knippið er tíundi hluti efu.'),
(1985, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 1, 'OT', 'Og allur söfnuður sona Ísraels fór frá eyðimörkinni Sín eftir ferðum sínum, eftir munni Jahve, og þeir tjölduðu í Refídím, og ekkert vatn var fyrir lýðinn að drekka.'),
(1986, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 2, 'OT', 'Og lýðurinn deildi við Móses og sagði: Gefið oss vatn, svo að vér megum drekka. Og Móses sagði við þá: Hvers vegna deilið þér við mig? Hvers vegna freistið þér Jahve?'),
(1987, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 3, 'OT', 'Og lýðurinn þyrsti þar eftir vatni, og lýðurinn mælti gegn Móses og sagði: Hvers vegna leiddir þú oss upp frá Egyptalandi, til að deyða mig, sonu mína og fénað minn af þorsta?'),
(1988, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 4, 'OT', 'Og Móses hrópaði til Jahve og sagði: Hvað á ég að gera við þennan lýð? Lítið vantar á að þeir grýti mig.'),
(1989, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 5, 'OT', 'Og Jahve sagði við Móses: Gakk fram fyrir andlit lýðsins og tak með þér nokkra af öldungum Ísraels. Tak í hönd þína staf þinn, sem þú slóst Níl með, og far þú.'),
(1990, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 6, 'OT', 'Sjá, ég mun standa þar fyrir andliti þínu á klettinum í Hóreb. Þú skalt slá á klettinn, og vatn mun koma úr honum, og lýðurinn mun drekka. Og Móses gerði svo fyrir augum öldunga Ísraels.'),
(1991, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 7, 'OT', 'Og hann gaf staðnum nafnið Massa og Meríba vegna þrætunnar sona Ísraels og vegna þess að þeir freistuðu Jahve og sögðu: Er Jahve meðal vor eða ekki?'),
(1992, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 8, 'OT', 'Þá kom Amalek og barðist við Ísrael í Refídím.'),
(1993, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 9, 'OT', 'Og Móses sagði við Jósúa: Velj oss menn og far út og berst við Amalek. Á morgun mun ég standa á höfði hæðarinnar með staf Guðs í hendi minni.'),
(1994, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 10, 'OT', 'Og Jósúa gerði eins og Móses hafði sagt honum, til að berjast við Amalek; en Móses, Aron og Húr stigu upp á höfuð hæðarinnar.'),
(1995, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 11, 'OT', 'Og svo bar við, þegar Móses lyfti hendi sinni, þá sigraði Ísrael; og þegar hann lét hönd sína síga, þá sigraði Amalek.'),
(1996, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 12, 'OT', 'En hendur Mósesar urðu þungar; þá tóku þeir stein og lögðu undir hann, og hann settist á hann; og Aron og Húr studdu hendur hans, annar hér og annar þar; og hendur hans voru í trúfesti til sólarlags.'),
(1997, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 13, 'OT', 'Og Jósúa felldi Amalek og lýð hans fyrir munni sverðsins.'),
(1998, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 14, 'OT', 'Og Jahve sagði við Móses: Skrifaðu þetta í bók til minningar og flyt það í eyru Jósúa, því að ég mun afmá minningu Amaleks undir himninum.'),
(1999, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 15, 'OT', 'Og Móses reisti altari og kallaði nafn þess Jahve-Nissí.'),
(2000, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 17, 16, 'OT', 'Og hann sagði: Hönd er á hásæti Jah. Jahve mun eiga stríð við Amalek frá kynslóð til kynslóðar.'),
(2001, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 1, 'OT', 'Jetró, prestur Midíans, tengdafaðir Móses, frétti allt það sem Guð hafði gert fyrir Mósesi og Ísrael, lýð sinn, þegar Jahve leiddi Ísrael út úr Egyptalandi.'),
(2002, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 2, 'OT', 'Og Jetró, tengdafaðir Móses, tók Sippóru, konu Móses, eftir að hann hafði sent hana burt.'),
(2003, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 3, 'OT', 'Og tvo sonu hennar; nafn annars var Gersom, því að hann sagði: Útlendingur hef ég verið á framandi jörð.'),
(2004, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 4, 'OT', 'Og nafn hins var Elíeser, því að Guð föður míns var mér hjálp og bjargaði mér undan sverði Faraós.'),
(2005, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 5, 'OT', 'Og Jetró, tengdafaðir Móses, kom með sonu hans og konu hans til Móses í eyðimörkina, þar sem hann tjaldaði við fjall Guðs.'),
(2006, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 6, 'OT', 'Og hann sagði við Móses: Ég, Jetró, tengdafaðir þinn, kem til þín, og kona þín og synir hennar tveir með henni.'),
(2007, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 7, 'OT', 'Og Móses gekk út til móts við tengdaföður sinn, laut honum og kyssti hann; og þeir spurðu hver annan um frið og gengu inn í tjaldið.'),
(2008, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 8, 'OT', 'Og Móses sagði tengdaföður sínum allt það sem Jahve hafði gert við Faraó og Egyptaland vegna Ísraels, allt það erfiði sem þeir höfðu mætt á veginum, og Jahve bjargaði þeim.'),
(2009, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 9, 'OT', 'Og Jetró gladdist yfir öllum gæðunum sem Jahve hafði gert Ísrael, þar sem hann hafði frelsað hann af hendi Egyptalands.'),
(2010, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 10, 'OT', 'Og Jetró sagði: Lofaður sé Jahve, sem frelsaði yður af hendi Egyptalands og af hendi Faraós, sem frelsaði lýðinn undan hendi Egyptalands.'),
(2011, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 11, 'OT', 'Nú veit ég að Jahve er mestur allra guða, því að í því máli sem þeir drýgðu hroka gegn þeim.'),
(2012, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 12, 'OT', 'Og Jetró, tengdafaðir Móses, tók brennifórn og sláturfórnir handa Guði; og Aron kom og allir öldungar Ísraels til að neyta brauðs með tengdaföður Móses fyrir andliti Guðs.'),
(2013, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 13, 'OT', 'Og daginn eftir sat Móses til að dæma lýðinn; og lýðurinn stóð fyrir Móses frá morgni til kvölds.'),
(2014, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 14, 'OT', 'Og tengdafaðir Móses sá allt sem hann gerði fyrir lýðinn, og sagði: Hvað er þetta sem þú gerir fyrir lýðinn? Hvers vegna situr þú einn, og allur lýðurinn stendur hjá þér frá morgni til kvölds?'),
(2015, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 15, 'OT', 'Og Móses sagði við tengdaföður sinn: Því að lýðurinn kemur til mín til að leita Guðs.'),
(2016, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 16, 'OT', 'Þegar þeir eiga orð saman, koma þeir til mín, og ég dæmi milli manns og náunga hans, og ég kunngeri lög Guðs og lögmál hans.'),
(2017, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 17, 'OT', 'Og tengdafaðir Móses sagði við hann: Það er ekki gott þetta mál sem þú ert að gera.'),
(2018, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 18, 'OT', 'Þú munt vissulega visna, bæði þú og þessi lýður sem er með þér, því að þetta orð er þér of þungt; þú getur ekki gert það einn.'),
(2019, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 19, 'OT', 'Nú, hlýð þú á rödd mína, og ég mun ráðleggja þér, og Guð mun vera með þér. Vertu þú fulltrúi lýðsins fyrir Guði, og flyt þú orðin fyrir Guð.'),
(2020, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 20, 'OT', 'Og þú skalt áminna þá um lögin og lögmálin, og kunngera þeim veginn sem þeir eiga að ganga og verkið sem þeir eiga að vinna.'),
(2021, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 21, 'OT', 'En þú skalt velja úr öllum lýðnum menn af styrk, sem óttast Guð, menn sannleika, sem hata ábata; og setja yfir þá höfðingja: höfðingja yfir þúsundir, höfðingja yfir hundruð, höfðingja yfir fimmtíu og höfðingja yfir tíu.'),
(2022, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 22, 'OT', 'Og þeir skulu dæma lýðinn á öllum tímum; hvert stórt mál skulu þeir bera fyrir þig, en hvert smærra mál skulu þeir dæma sjálfir; og létta þú þá af þér, og þeir skulu bera byrðina með þér.'),
(2023, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 23, 'OT', 'Ef þú gerir þetta orð, og Guð býður þér það, þá muntu geta staðist, og allur þessi lýður mun einnig fara heim til staðar síns í friði.'),
(2024, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 24, 'OT', 'Og Móses hlýddi á rödd tengdaföður síns og gerði allt sem hann sagði.'),
(2025, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 25, 'OT', 'Og Móses valdi menn af styrk úr öllum Ísrael og setti þá sem höfuð yfir lýðinn: höfðingja yfir þúsundir, höfðingja yfir hundruð, höfðingja yfir fimmtíu og höfðingja yfir tíu.'),
(2026, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 26, 'OT', 'Og þeir skulu dæma lýðinn á öllum tímum; hið harða orð skulu þeir bera fyrir Móses, en hvert smærra orð skulu þeir dæma sjálfir.'),
(2027, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 18, 27, 'OT', 'Og Móses sendi tengdaföður sinn burt, og hann fór til jarðar sinnar.'),
(2028, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 1, 'OT', 'Á þriðja mánuði eftir að synir Ísraels fóru út af Egyptalandi, á þessum degi komu þeir í eyðimörkina Sínaí.'),
(2029, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 2, 'OT', 'Þeir fóru frá Refídím og komu í eyðimörkina Sínaí og tjölduðu í eyðimörkinni; og Ísrael tjaldaði þar andspænis fjallinu.'),
(2030, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 3, 'OT', 'Og Móses fór upp til Guðs; og Jahve kallaði til hans af fjallinu og sagði: Svo skalt þú segja húsi Jakobs og kunngera sonum Ísraels.'),
(2031, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 4, 'OT', 'Þér hafið séð hvað ég gerði Egyptalandi, og hvernig ég bar yður á vængjum arnarins og leiddi yður til mín.'),
(2032, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 5, 'OT', 'Og nú, ef þér hlýðið á rödd mína og haldið sáttmála minn, þá munuð þér vera mín eign umfram alla lýði, því að öll jörðin er mín.'),
(2033, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 6, 'OT', 'Og þér skuluð vera mér ríki presta og heilög þjóð. Þetta eru orðin sem þú skalt segja við sonu Ísraels.'),
(2034, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 7, 'OT', 'Og Móses kom og kallaði á öldunga lýðsins og lagði fyrir andliti þeirra öll þessi orð sem Jahve hafði boðið honum.'),
(2035, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 8, 'OT', 'Og allur lýðurinn svaraði í einu og sagði: Allt sem Jahve hefur talað viljum vér gera. Og Móses bar orð lýðsins fyrir Jahve.'),
(2036, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 9, 'OT', 'Og Jahve sagði við Móses: Sjá, ég kem til þín í þykku skýi, svo að lýðurinn heyri þegar ég tala við þig og trúi þér um eilífð. Og Móses bar orð lýðsins fyrir Jahve.'),
(2037, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 10, 'OT', 'Og Jahve sagði við Móses: Far til lýðsins og helga hann í dag og á morgun, og lát þá þvo skikkjur sínar.'),
(2038, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 11, 'OT', 'Og þeir skulu vera viðbúnir á þriðja degi, því að á þriðja degi mun Jahve stíga niður fyrir augum alls lýðsins á Sínaífjalli.'),
(2039, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 12, 'OT', 'Og þú skalt setja mörk fyrir lýðinn allt um kring og segja: Gætið yðar að stíga ekki upp á fjallið og snertið ekki endimörk þess; hver sem snertir fjallið skal sannarlega deyja.'),
(2040, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 13, 'OT', 'Engin hönd skal snerta hann, heldur skal hann grýttur verða eða skotinn; hvort sem það er skepna eða maður, skal það ekki lifa. Þegar fagnaðarárs-hornið hljómar, skulu þeir ganga upp á fjallið.'),
(2041, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 14, 'OT', 'Og Móses gekk niður af fjallinu til lýðsins og helgaði lýðinn, og þeir þvoðu skikkjur sínar.'),
(2042, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 15, 'OT', 'Og hann sagði við lýðinn: Verið viðbúnir í þrjá daga; komið ekki nálægt konu.'),
(2043, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 16, 'OT', 'Og það var á þriðja degi, þegar komið var að morgni, að þrumur, þrumuraddir og eldingar urðu og þykkt ský var á fjallinu, og hljóð lúðurs mjög sterkt; og allur lýðurinn í herbúðunum skalf.'),
(2044, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 17, 'OT', 'Og Móses leiddi lýðinn út úr herbúðunum til móts við Guð, og þeir námu staðar við neðri hluta fjallsins.'),
(2045, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 18, 'OT', 'Og Sínaífjall var allt reykt, fyrir andliti Jahve, því að Jahve steig niður á það í eldi; reykur þess steig upp eins og reykur úr ofni, og allt fjallið skalf mjög.'),
(2046, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 19, 'OT', 'Og rödd lúðursins jókst og varð mjög sterk; Móses talaði, og Guð svaraði honum með rödd.'),
(2047, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 20, 'OT', 'Og Jahve steig niður á Sínaífjall, á höfuð fjallsins; og Jahve kallaði Móses upp á höfuð fjallsins, og Móses fór upp.'),
(2048, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 21, 'OT', 'Og Jahve sagði við Móses: Far niður og vara lýðinn við, svo að þeir ryðjist ekki inn til Jahve til að sjá, og margir þeirra falli.'),
(2049, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 22, 'OT', 'Og líka prestarnir, sem nálgast Jahve, skulu helgast, svo að Jahve brjótist ekki út gegn þeim.'),
(2050, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 23, 'OT', 'Og Móses sagði við Jahve: Lýðurinn getur ekki farið upp á Sínaífjall, því að þú varaðir oss við og sagðir: Settu mörk um fjallið og helgaðu það.'),
(2051, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 24, 'OT', 'Og Jahve sagði við hann: Far, gakk niður, og þú skalt koma aftur upp, þú og Aron með þér; en prestarnir og lýðurinn skulu ekki ryðjast inn til að ganga upp til Jahve, svo að hann brjótist ekki út gegn þeim.'),
(2052, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 19, 25, 'OT', 'Og Móses gekk niður til lýðsins og sagði við þá.'),
(2053, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 1, 'OT', 'Og Guð talaði öll þessi orð og sagði:'),
(2054, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 2, 'OT', 'Ég er Jahve, Guð þinn, sem leiddi þig út úr Egyptalandi, út af húsi þjóna.'),
(2055, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 3, 'OT', 'Þú skalt ekki eiga aðra guði frammi fyrir andliti mínu.'),
(2056, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 4, 'OT', 'Þú skalt ekki gera þér goðalíkan, né neina mynd af því sem er á himni uppi, eða á jörðinni niðri, eða í vatninu undir jörðinni.'),
(2057, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 5, 'OT', 'Þú skalt ekki beygja þig fyrir þeim né þjóna þeim; því að ég, Jahve, Guð þinn, er vandlátur Guð, sem vitja misgjörða feðra á sonum allt til þriðja ættliðar og fjórðungs þeirra sem hata mig.'),
(2058, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 6, 'OT', 'En ég sýni miskunn þúsundum þeirra sem elska mig og varðveita boðorð mín.'),
(2059, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 7, 'OT', 'Þú skalt ekki taka nafn Jahve, Guðs þíns, til hégóma, því að Jahve mun ekki sýkna þann sem tekur nafn hans til hégóma.'),
(2060, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 8, 'OT', 'Minnstu dagsins hvíldardags til að helga hann.'),
(2061, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 9, 'OT', 'Sex daga skalt þú vinna og vinna allt starf þitt.'),
(2062, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 10, 'OT', 'En sjöundi dagurinn er hvíldardagur Jahve, Guðs þíns; þá skalt þú ekki vinna nokkurt starf, þú né sonur þinn né dóttir þín, þjónn þinn né ambátt þín, skepnu þína né útlendinginn sem er innan hliða þinna.'),
(2063, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 11, 'OT', 'Því að á sex dögum gerði Jahve himininn og jörðina, hafið og allt sem í þeim er; en á sjöunda degi hvíldist hann; þess vegna blessaði Jahve hvíldardaginn og helgaði hann.'),
(2064, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 12, 'OT', 'Heiðra föður þinn og móður þína, til þess að dagar þínir verði langir á jörðinni sem Jahve, Guð þinn, gefur þér.'),
(2065, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 13, 'OT', 'Þú skalt ekki myrða.'),
(2066, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 14, 'OT', 'Þú skalt ekki drýgja hór.'),
(2067, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 15, 'OT', 'Þú skalt ekki stela.'),
(2068, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 16, 'OT', 'Þú skalt ekki bera ljúgvott gegn náunga þínum.'),
(2069, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 17, 'OT', 'Þú skalt ekki girnast hús náunga þíns; þú skalt ekki girnast konu náunga þíns, né þjón hans, né ambátt hans, né naut hans, né asna hans, né neitt sem náunga þínum tilheyrir.'),
(2070, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 18, 'OT', 'Og allur lýðurinn sá raddirnar, kyndla og rödd lúðursins, og fjallið var reykjandi; og lýðurinn sá það, skalf og stóð í fjarlægð.'),
(2071, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 19, 'OT', 'Og þeir sögðu við Móses: Tala þú við oss, og vér munum hlýða; en láttu Guð ekki tala við oss, svo að vér deyjum ekki.'),
(2072, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 20, 'OT', 'Og Móses sagði við lýðinn: Óttist ekki; því að Guð er kominn til að reyna yður, og til þess að ótti hans sé fyrir andliti yðar, svo að þér syndgið ekki.'),
(2073, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 21, 'OT', 'Og lýðurinn stóð í fjarlægð, en Móses gekk nær þykku myrkri, þar sem Guð var.'),
(2074, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 22, 'OT', 'Og Jahve sagði við Móses: Svo skalt þú segja við sonu Ísraels: Þér hafið séð að af himni hef ég talað við yður.'),
(2075, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 23, 'OT', 'Þér skuluð ekki gera með mér guði úr silfri, og guði úr gulli skuluð þér ekki gera yður.'),
(2076, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 24, 'OT', 'Altari úr jörð skalt þú gera mér, og fórna á því brennifórnum þínum og þakkarfórnum þínum, sauðfé þínu og nautum þínum; á hverjum þeim stað þar sem ég læt nafn mitt minnast, mun ég koma til þín og blessa þig.'),
(2077, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 25, 'OT', 'En ef þú gerir mér altari úr steinum, skalt þú ekki byggja það úr höggnum steinum; því að þú hefur brugðið sverði þínu yfir það, og þú hefur vanhelgað það.'),
(2078, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 20, 26, 'OT', 'Og þú skalt ekki ganga upp að altari mínu um þrep, til þess að nekt þín verði ekki sýnd á því.'),
(2079, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 1, 'OT', 'Og þetta eru dómarnir sem þú skalt leggja fyrir andliti þeirra.'),
(2080, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 2, 'OT', 'Ef þú kaupir þjón Hebrea, skal hann þjóna í sex ár; en á sjöunda ári skal hann fara frjáls út, án endurgjalds.'),
(2081, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 3, 'OT', 'Ef hann kom einn, skal hann fara einn út; ef hann var herra konu, þá skal kona hans fara út með honum.'),
(2082, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 4, 'OT', 'Ef herra hans gefur honum konu og hún elur honum sonu eða dætur, skulu konan og börn hennar vera herra hennar, en hann skal fara út einn.'),
(2083, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 5, 'OT', 'En ef þjónninn segir: Ég elska herra minn, konu mína og sonu mína; ég vil ekki fara út frjáls.'),
(2084, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 6, 'OT', 'Þá skal herra hans leiða hann fyrir Guð, leiða hann að hurðinni eða dyrastafnum; og herra hans skal stinga eyra hans með ali, og hann skal vera þjónn hans til eilífðar.'),
(2085, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 7, 'OT', 'Og þegar maður selur dóttur sína sem ambátt, skal hún ekki fara út eins og þjónarnir fara út.'),
(2086, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 8, 'OT', 'Ef hún er illa séð í augum herra síns, sem ekki hefur gert hana að brúði sinni, þá skal hann láta leysa hana; hann má ekki selja hana til útlends lýðs, þar sem hann hefur svikið hana.'),
(2087, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 9, 'OT', 'En ef hann ætlar hana syni sínum, skal hann fara með hana eftir dómi dætra.'),
(2088, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 10, 'OT', 'Ef hann tekur sér aðra konu, skal hann ekki skerða hold hennar, klæði hennar og hjúskaparskyldu.'),
(2089, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 11, 'OT', 'Og ef hann gerir henni ekki þessa þrjá hluti, þá skal hún fara út án endurgjalds, án silfurs.'),
(2090, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 12, 'OT', 'Sá sem slær mann svo að hann deyr, skal sannarlega deyja.'),
(2091, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 13, 'OT', 'En ef hann lagði ekki í launsát, heldur Guð lét það koma í hendi hans, þá skal ég setja þér stað þangað sem hann má flýja.'),
(2092, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 14, 'OT', 'Og ef maður drepur náunga sinn af ráðnum hug og í slægð, skalt þú taka hann frá altari mínu til að deyja.'),
(2093, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 15, 'OT', 'Sá sem slær föður sinn eða móður sína, skal sannarlega deyja.'),
(2094, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 16, 'OT', 'Sá sem stelur mann og selur hann, og finnst hann í hendi hans, skal sannarlega deyja.'),
(2095, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 17, 'OT', 'Sá sem bölvar föður sínum eða móður sinni, skal sannarlega deyja.'),
(2096, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 18, 'OT', 'Og ef menn deila og maður slær náunga sinn með steini eða hnefa, og hann deyr ekki en leggst í hvílu;'),
(2097, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 19, 'OT', 'Ef hann rís upp og gengur úti á staf sínum, þá skal sá sem sló vera sýknaður; hann skal aðeins greiða fyrir legu hans og láta lækna hann.'),
(2098, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 20, 'OT', 'Og ef maður slær þjón sinn eða ambátt sína með staf, og hann deyr undir hendi hans, þá skal hann sannarlega hefndur verða.'),
(2099, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 21, 'OT', 'En ef hann lifir einn dag eða tvo daga, þá skal ekki hefna hans, því að hann er silfur hans.'),
(2100, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 22, 'OT', 'Og ef menn deila og slá ófríska konu, svo að drengirnir fari út en ekkert slys verði, þá skal hann refsaður verða eins og herra konunnar leggur á hann, og hann skal greiða eftir úrskurði dómara.'),
(2101, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 23, 'OT', 'En ef slys verður, þá skalt þú gefa sál fyrir sál.'),
(2102, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 24, 'OT', 'Auga fyrir auga, tönn fyrir tönn, hönd fyrir hönd, fót fyrir fót.'),
(2103, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 25, 'OT', 'Brunasár fyrir brunasár, sár fyrir sár, strípu fyrir strípu.'),
(2104, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 26, 'OT', 'Ef maður slær auga þjóns síns eða auga ambáttar sinnar og eyðir því, þá skal hann láta hann lausan til frelsis fyrir augað.'),
(2105, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 27, 'OT', 'Ef hann slær út tönn þjóns síns eða tönn ambáttar sinnar, þá skal hann láta hann lausan til frelsis fyrir tönnina.'),
(2106, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 28, 'OT', 'Ef naut stangar mann eða konu svo að hann eða hún deyi, þá skal grýta nautið og ekki eta hold þess, en herra nautsins er saklaus.'),
(2107, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 29, 'OT', 'En ef naut var vant að stanga áður, og það hafði verið vottað hjá herra þess, en hann gætti þess ekki, og það drepur mann eða konu, þá skal grýta nautið og herra þess skal einnig deyja.'),
(2108, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 30, 'OT', 'Ef lausnargjald er lagt á hann, þá skal hann greiða lausnargjald fyrir sál sína, eftir öllu því sem á hann er lagt.'),
(2109, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 31, 'OT', 'Hvort sem það stangar son eða dóttur, skal fara með hann eftir þessum dómi.'),
(2110, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 32, 'OT', 'Ef naut stangar þjón eða ambátt, þá skal eigandinn greiða herra þjónsins þrjátíu sikla silfur, og nautið skal grýtt verða.'),
(2111, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 33, 'OT', 'Ef maður opnar brunn eða grefur brunn og breiðir ekki yfir hann, og naut eða asni fellur þar ofan í.'),
(2112, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 34, 'OT', 'Herra brunnsins skal bæta það; silfur skal hann skila til herra þess, en hið dauða skal verða hans.'),
(2113, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 35, 'OT', 'Ef naut eins manns stangar naut náunga síns og það deyr, þá skulu þeir selja lifandi nautið og skipta silfrinu, og dauða nautið skulu þeir líka skipta.'),
(2114, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 21, 36, 'OT', 'En ef það var kunnugt að naut var vant að stanga áður, og herra þess gætti þess ekki, þá skal hann greiða naut fyrir nautið, og hið dauða skal verða hans.'),
(2115, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 1, 'OT', 'Ef maður stelur naut eða lamb og slátrar því eða selur, þá skal hann greiða fimm naut fyrir nautið og fjögur sauðfé fyrir lambið.'),
(2116, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 2, 'OT', 'Ef þjófurinn finnst í sundurbroti og er sleginn og deyr, þá verður ekki blóðs krafist af honum.'),
(2117, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 3, 'OT', 'Ef sólin hefur risið yfir hann, þá er blóðsök á honum. Hann skal greiða fullt, en ef hann á ekkert, þá skal hann verða seldur fyrir þjófnað sinn.'),
(2118, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 4, 'OT', 'Ef þjófnaðurinn finnst lifandi í hendi hans, hvort sem um er að ræða naut, asna eða lamb, þá skal hann greiða tvöfalt.'),
(2119, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 5, 'OT', 'Ef maður brennir akur eða víngarð og sleppir fénaðinum svo að hann brenni á akri annars, þá skal hann greiða með úrvali af akri sínum og úrvali af víngarði sínum.'),
(2120, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 6, 'OT', 'Ef eldur kemst út og finnur þyrna, og brennir kornbundinn, stöngulinn eða akurinn, þá skal sá sem kveikti eldinn greiða bætur fyrir bruna.'),
(2121, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 7, 'OT', 'Ef maður afhendir náunga sínum silfur eða áhöld til varðveislu, og það er stolið úr húsi mannsins, og þjófurinn finnst, þá skal þjófurinn greiða tvöfalt.'),
(2122, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 8, 'OT', 'Ef þjófurinn finnst ekki, þá skal herra hússins ganga fyrir Guð, til þess að sjá hvort hann hafi ekki lagt hönd á starf náunga síns.'),
(2123, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 9, 'OT', 'Hvert sem afbrotið er, um naut, asna, lamb, klæði eða hvers kyns glötun, sem einhver segir að sé þetta, skal orð þeirra beggja koma fyrir Guð, og þann sem Guð dæmir sekan skal greiða tvöfalt til náunga síns.'),
(2124, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 10, 'OT', 'Ef maður afhendir náunga sínum asna, naut, lamb eða aðra skepnu til geymslu, og hún deyr, brotnar eða er tekin án þess að nokkur sjái það.'),
(2125, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 11, 'OT', 'Þá skal eiður Jahve vera á milli þeirra beggja, að hann hafi ekki lagt hönd á starf náunga síns; og herra þess skal taka við, og hann skal ekki greiða.'),
(2126, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 12, 'OT', 'En ef því er stolið frá honum, þá skal hann greiða til herra þess.'),
(2127, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 13, 'OT', 'Ef það er rifið af villidýri, þá skal hann færa vott, og bráðina skal hann ekki greiða.'),
(2128, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 14, 'OT', 'Ef maður tekur að láni hjá náunga sínum, og það brotnar eða deyr, án þess að herra þess sé viðstaddur, þá skal hann fullkomlega greiða.'),
(2129, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 15, 'OT', 'Ef herra þess er með því, þá skal hann ekki greiða. Ef hann er leigumaður, þá skal hann koma með laun sín.'),
(2130, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 16, 'OT', 'Ef maður tælir mey sem ekki er heitin og liggur með henni, þá skal hann kaupa hana sér til konu.'),
(2131, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 17, 'OT', 'Ef faðir hennar neitar alfarið að gefa hana honum, þá skal hann greiða silfur eftir brúðarverði meyja.'),
(2132, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 18, 'OT', 'Galdrakonu skalt þú ekki láta lifa.'),
(2133, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 19, 'OT', 'Hver sem leggst með skepnu skal deyja.'),
(2134, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 20, 'OT', 'Sá sem fórnar guðum, nema Jahve einum, skal vera helgaður banni.'),
(2135, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 21, 'OT', 'Útlendinginn skalt þú hvorki kúga né þjaka, því að þér voruð útlendingar á jörð Egyptalands.'),
(2136, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 22, 'OT', 'Ekkju og munaðarleysingja skalt þú ekki þjaka.'),
(2137, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 23, 'OT', 'Ef þú þjakar hann og hann hrópar til mín, þá mun ég vissulega heyra neyðaróp hans.'),
(2138, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 24, 'OT', 'Þá mun nef mitt upptendrast, og ég mun drepa yður með sverði, og konur yðar verða ekkjur og synir yðar munaðarleysingjar.'),
(2139, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 25, 'OT', 'Ef þú lánar silfur lýð mínum, þeim fátæka hjá þér, þá skalt þú ekki vera honum eins og okrari, og ekki leggja á hann okur.'),
(2140, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 26, 'OT', 'Ef þú tekur klæði náunga þíns að veði, þá skalt þú skila honum því áður en sólin sest.'),
(2141, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 27, 'OT', 'Því að það er eina klæði hans, skikkja hans fyrir skinn hans; í hverju á hann að sofa? Og verði það að hann hrópar til mín, þá mun ég heyra, því að ég er náðugur.'),
(2142, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 28, 'OT', 'Guð skalt þú ekki lastmæla, og höfðingja í lýð þínum skalt þú ekki formæla.'),
(2143, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 29, 'OT', 'Fyllingu þína og vökva þinn skalt þú ekki draga á langinn; frumgetinn sona þinna skalt þú gefa mér.'),
(2144, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 30, 'OT', 'Þannig skalt þú gera við naut þitt og sauðfé þitt; sjö daga skal það vera með móður sinni, en á áttunda degi skalt þú gefa mér það.'),
(2145, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 22, 31, 'OT', 'Og þér skuluð vera mér menn af helgi. Hold sem er bráð á akri skuluð þér ekki eta; þér skuluð kasta því hundum.'),
(2146, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 1, 'OT', 'Þú skalt ekki bera út orðróm hégóma. Ekki skalt þú rétta hönd þína með hinum óguðlega til að vera vottur ofbeldis.'),
(2147, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 2, 'OT', 'Þú skalt ekki fylgja fjöldanum til ills, og ekki skalt þú bera vitni í þrætu svo að þú hallist með fjöldanum og snúir réttinum.'),
(2148, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 3, 'OT', 'Og fátækum skalt þú ekki hlífa í þrætu hans.'),
(2149, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 4, 'OT', 'Ef þú hittir naut óvinar þíns eða asna hans villtan, þá skalt þú skila því aftur til hans.'),
(2150, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 5, 'OT', 'Ef þú sérð asna þess sem hatar þig liggja undir byrði sinni og vilt ganga framhjá, þá skalt þú samt hjálpa honum með byrðinni.'),
(2151, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 6, 'OT', 'Þú skalt ekki halla dómi fátæks manns þíns í þrætu hans.'),
(2152, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 7, 'OT', 'Haltu þig fjarri orði lygi. Saklausan og réttlátan skalt þú ekki deyða, því að ég réttlæti ekki hinn óguðlega.'),
(2153, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 8, 'OT', 'Mútur skalt þú ekki þiggja, því að mútur blinda hina sjáandi og snúa orðum hinna réttlátu.'),
(2154, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 9, 'OT', 'Útlendinginn skalt þú ekki kúga. Þér þekkið sál útlendingsins, því að þér voruð útlendingar á jörð Egyptalands.'),
(2155, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 10, 'OT', 'Sex ár skalt þú sá jörðinni þinni og safna afurð hennar.'),
(2156, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 11, 'OT', 'En hið sjöunda skalt þú láta hana hvílast og sleppa henni, og fátæklingar lýðs þíns skulu eta, og það sem þeir láta eftir sig skal dýr akursins eta. Svo skalt þú gera við víngarð þinn og olíutré þitt.'),
(2157, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 12, 'OT', 'Sex daga skalt þú vinna verk þín, en sjöunda daginn skalt þú hvílast, til þess að naut þitt og asni þinn fái hvíld, og sonur ambáttar þinnar og útlendingurinn endurnærist.'),
(2158, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 13, 'OT', 'Og varðveitið allt sem ég hef sagt yður, og nafn annarra guða skuluð þér ekki nefna; það skal ekki heyrast af munni yðar.'),
(2159, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 14, 'OT', 'Þrisvar á ári skalt þú halda mér hátíð, og ferðast til hennar á fótum.'),
(2160, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 15, 'OT', 'Þú skalt halda hátíð ósýrðra brauða. Sjö daga skalt þú eta ósýrt brauð, eins og ég bauð þér, á tíma mánuðinum Abíb, því að í honum fórst þú út af Egyptalandi. Enginn skal koma fyrir andliti mínu tómhentur.'),
(2161, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 16, 'OT', 'Og hátíð uppskeru, frumgróða verka þinna sem þú sáir á akri. Og hátíð safnsins við árslok, þegar þú hefur safnað verkum þínum af akrinum.'),
(2162, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 17, 'OT', 'Þrisvar sinn á ári skal allt karlkyn þitt birtast fyrir andliti Drottins Jahve.'),
(2163, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 18, 'OT', 'Þú skalt ekki fórna blóði sláturfórnar minnar með súrdeigi, og fitu hátíðar minnar skal ekki vera eftir til morguns.'),
(2164, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 19, 'OT', 'Hið fyrsta af upphafi frumgróða jarðar þinnar skalt þú færa í hús Jahve Guðs þíns. Þú skalt ekki sjóða kið í mjólk móður hans.'),
(2165, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 20, 'OT', 'Sjá, ég sendi engil, sendiboða minn, fyrir andliti þínu, til að gæta þín á veginum og leiða þig til staðarins sem ég hef búið.'),
(2166, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 21, 'OT', 'Gættu þín frá andliti hans og hlýð röddu hans. Ekki skalt þú þrjóskast gegn honum, því að hann mun ekki fyrirgefa afbrot yðar, því að nafn mitt er í honum.'),
(2167, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 22, 'OT', 'En ef þú hlýðir röddu hans og gerir allt sem ég tala, þá mun ég vera óvinur óvina þinna og andstæðingur andstæðinga þinna.'),
(2168, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 23, 'OT', 'Því að sendiboði minn skal fara fyrir andliti þínu og leiða þig til Amorita, Hetíta, Peresíta, Kanaanita, Hevíta og Jebúsíta, og ég mun útrýma þeim.'),
(2169, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 24, 'OT', 'Þú skalt ekki falla fram fyrir guðum þeirra og ekki þjóna þeim, og ekki gera eftir verkum þeirra. Heldur skalt þú rífa þá niður og brjóta í sundur steinsúlur þeirra.'),
(2170, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 25, 'OT', 'Þér skuluð þjóna Jahve Guði yðar, og hann mun blessa brauð yðar og vatn yðar, og ég mun taka sjúkdóm burt frá yður.'),
(2171, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 26, 'OT', 'Engin ófrjó eða óbyrja skal vera á jörð þinni; ég mun fylla tölu daga þinna.'),
(2172, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 27, 'OT', 'Ég mun senda skelfingu mína fyrir andliti þínu, og ég mun tortíma öllum lýðnum sem þú kemur til, og ég mun láta alla óvini þína snúa hálsi undan þér.'),
(2173, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 28, 'OT', 'Ég mun senda háhyrninginn fyrir andliti þínu, og hann mun reka Hevíta, Kanaanita og Hetíta burt frá andliti þínu.'),
(2174, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 29, 'OT', 'Ég mun ekki reka þá burt frá andliti þínu á einu ári, svo að jörðin verði að auðn og villidýr akursins fjölgi sér gegn þér.'),
(2175, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 30, 'OT', 'Smám saman mun ég reka þá burt frá andliti þínu, uns þú fjölgar og munt erfa jörðina.'),
(2176, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 31, 'OT', 'Ég mun setja landamæri þín frá Rauðahafinu til Filistahafs, og frá eyðimörk til fljótsins, því að ég mun gefa í hendur yðar íbúa jarðarinnar, og þú skalt reka þá burt frá andliti þínu.'),
(2177, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 32, 'OT', 'Þú skalt ekki gera sáttmála við þá, né heldur við guði þeirra.'),
(2178, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 23, 33, 'OT', 'Þeir skulu ekki búa á jörð þinni, svo að þeir fái þig ekki til að syndga gegn mér; því að ef þú þjónar guðum þeirra, þá verður það þér að snöru.'),
(2179, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 1, 'OT', 'Og hann sagði við Móses: Stíg upp til Jahve, þú og Aron, Nadab og Abíhú og sjötíu af öldungum Ísraels; og þér skuluð tilbiðja í fjarlægð.'),
(2180, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 2, 'OT', 'Móses einn skal nálgast Jahve, en hinir skulu ekki nálgast, og lýðurinn skal ekki stíga upp með honum.'),
(2181, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 3, 'OT', 'Og Móses kom og sagði lýðnum öll orð Jahve og öll dóma; þá svaraði allur lýðurinn einni röddu og sagði: Öll orð sem Jahve hefur talað viljum vér gera.'),
(2182, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 4, 'OT', 'Móses skráði öll orð Jahve, reis árla á morgni og reisti altari undir fjallinu og tólf steinsúlur fyrir tólf ættkvíslir Ísraels.'),
(2183, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 5, 'OT', 'Og hann sendi unga sveina af sonum Ísraels, og þeir færðu brennifórnir og fórnuðu sláturfórnir og þakkarfórnir af ungnautum handa Jahve.'),
(2184, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 6, 'OT', 'Móses tók helming blóðsins og setti í skálar, og helminginn af blóðinu stökkti hann á altarið.'),
(2185, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 7, 'OT', 'Hann tók sáttmálabókina og las hana upp fyrir eyrum lýðsins, og þeir sögðu: Allt sem Jahve hefur mælt viljum vér gera og hlýða.'),
(2186, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 8, 'OT', 'Og Móses tók blóðið og stökkti á lýðinn og sagði: Sjá, þetta er blóð sáttmálans sem Jahve hefur gert við yður um öll þessi orð.'),
(2187, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 9, 'OT', 'Þá fóru Móses og Aron, Nadab og Abíhú og sjötíu af öldungum Ísraels upp.'),
(2188, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 10, 'OT', 'Og þeir sáu Guð Ísraels, og undir fótum hans var eins og verk af steinlögðu gólfi úr safír, og eins og bein himinsins í hreinleika.'),
(2189, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 11, 'OT', 'Hann lagði ekki hönd sína á tignarmenn Ísraels sona; þeir sáu Guð, og þeir átu og drukku.'),
(2190, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 12, 'OT', 'Og Jahve sagði við Móses: Stíg upp til mín á fjallið og vertu þar, og ég mun gefa þér töflurnar úr steini, lögmálið og boðorðin sem ég hef skrifað til að kenna þeim.'),
(2191, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 13, 'OT', 'Móses reis upp og Jósúa, þjónn hans; og Móses gekk upp á fjall Guðs.'),
(2192, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 14, 'OT', 'Og við öldungana sagði hann: Bíðið hér fyrir oss þar til vér komum aftur til yðar; og sjá, Aron og Húr eru hjá yður; hver sem er herra í orðum sínum gangi til þeirra.'),
(2193, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 15, 'OT', 'Og Móses gekk upp á fjallið, og skýið huldi fjallið.'),
(2194, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 16, 'OT', 'Og dýrð Jahve hvíldi á Sínaífjalli, og skýið huldi það í sex daga; og á sjöunda degi kallaði hann á Móses úr miðju skýinu.'),
(2195, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 17, 'OT', 'Og útlit dýrðar Jahve var eins og eldur sem eyðir á höfði fjallsins, fyrir augum Ísraels sona.'),
(2196, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 24, 18, 'OT', 'Og Móses gekk inn í skýið og klifraði upp á fjallið; og Móses var á fjallinu fjörutíu daga og fjörutíu nætur.'),
(2197, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2198, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 2, 'OT', 'Tala þú við Ísraels sonu, og þeir skulu taka fyrir mig framlag; af hverjum manni sem hjarta hans hvetur, þá skuluð þér taka framlag mitt.'),
(2199, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 3, 'OT', 'Og þetta er framlagið sem þér skuluð taka af þeim: gull, silfur og eir.'),
(2200, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 4, 'OT', 'Bláma, purpura, skarlat, língarn og hár geita.'),
(2201, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 5, 'OT', 'Og rauðlituð hrútaskinn, selskinn og akasíutré.'),
(2202, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 6, 'OT', 'Olía til ljóssins, ilmjurtir til smurningarolíunnar og reykelsi til ilmefnanna.'),
(2203, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 7, 'OT', 'Steinar ónyx og aðrir steinar til vígslu fyrir hökulinn og brjóstskjöldinn.'),
(2204, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 8, 'OT', 'Og þeir skulu gera mér helgidóm, svo að ég búi meðal þeirra.'),
(2205, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 9, 'OT', 'Eftir öllu því sem ég sýni þér, eftir fyrirmynd bústaðarins og fyrirmynd allra áhalda hans, þannig skuluð þér gera.'),
(2206, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 10, 'OT', 'Og þeir skulu gera örk úr akasíutré, tvær álnir og helming að lengd, ein alin og helming að breidd og ein alin og helming að vexti.'),
(2207, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 11, 'OT', 'Og þú skalt gylla hana skíru gulli, bæði innan húss og utan skalt þú gylla hana, og gera á hana kórónu úr gulli allt um kring.'),
(2208, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 12, 'OT', 'Og steypa skalt þú fyrir hana fjóra hringi úr gulli og setja þá á fjóra fætur hennar: tvo hringi á annað rif hennar og tvo hringi á hitt rifið.'),
(2209, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 13, 'OT', 'Og þú skalt gera stengur úr akasíutré og gylla þær gulli.'),
(2210, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 14, 'OT', 'Og þú skalt leiða stengurnar í hringina við rifin arkarinnar, til að bera örkina með þeim.'),
(2211, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 15, 'OT', 'Stengurnar skulu vera í hringjum arkarinnar; þær skulu ekki losna frá henni.'),
(2212, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 16, 'OT', 'Og þú skalt leggja vitnisburðinn í örkina sem ég mun gefa þér.'),
(2213, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 17, 'OT', 'Og þú skalt gera náðarstól úr skíru gulli: tvær álnir og helming að lengd, og ein alin og helming að breidd.'),
(2214, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 18, 'OT', 'Og þú skalt gera tvo kerúba úr gulli, úr útsmíðuðu verki skalt þú gera þá, af báðum röndum náðarstólsins.'),
(2215, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 19, 'OT', 'Gerðu einn kerúb á annarri röndinni og annan kerúb á hinni röndinni; úr náðarstólnum skuluð þér gera kerúbana á báðum röndum hans.'),
(2216, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 20, 'OT', 'Og kerúbarnir skulu breiða út vængi sína upp á við, skýla náðarstólnum með vængjum sínum, og andlit þeirra skulu snúa hvert að öðru, hvert að bróður sínum; andlit kerúbanna skulu snúa að náðarstólnum.'),
(2217, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 21, 'OT', 'Og þú skalt setja náðarstólinn ofan á örkina, og í örkina skalt þú leggja vitnisburðinn sem ég gef þér.'),
(2218, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 22, 'OT', 'Þar mun ég hitta þig og tala við þig frá náðarstólnum, á milli kerúbanna tveggja sem eru á örkinni vitnisburðarins, og allt sem ég mun bjóða þér til Ísraels sona.'),
(2219, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 23, 'OT', 'Og þú skalt gera borð úr akasíutré: tvær álnir að lengd, ein alin að breidd og ein alin og helming að vexti.'),
(2220, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 24, 'OT', 'Og þú skalt gylla það skíru gulli og gera á það kórónu úr gulli allt um kring.'),
(2221, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 25, 'OT', 'Og þú skalt gera á það umgjörð á breidd handarbreiddar allt um kring, og gera gullkórónu um umgjörðina allt um kring.'),
(2222, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 26, 'OT', 'Og þú skalt gera fyrir það fjóra hringi úr gulli og setja hringina á fjögur horn sem eru við fætur þess.'),
(2223, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 27, 'OT', 'Hringirnir skulu vera við umgjörðina sem hús fyrir stengurnar, til að bera borðið.'),
(2224, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 28, 'OT', 'Og þú skalt gera stengurnar úr akasíutré og gylla þær gulli, og með þeim skal bera borðið.'),
(2225, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 29, 'OT', 'Og þú skalt gera diska þess og skeiðar þess, lófa þess, bikara þess og skálar þess til að hella með; úr skíru gulli skalt þú gera þá.'),
(2226, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 30, 'OT', 'Og þú skalt setja á borðið sýnibrauð fyrir andliti mínu til stöðugleika.'),
(2227, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 31, 'OT', 'Og þú skalt gera ljósastiku úr skíru gulli; ljósastikan skal gerð úr útsmíðuðu verki: læri hennar og reyrinn hennar, bikarar hennar, súluhöfuð hennar og blóm hennar skulu vera úr henni.'),
(2228, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 32, 'OT', 'Og sex reyrar skulu ganga út frá hliðum hennar: þrjár reyrar ljósastikunnar úr annarri hliðinni og þrjár reyrar ljósastikunnar úr hinni hliðinni.'),
(2229, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 33, 'OT', 'Þrír bikarar mótaðir sem möndlublóm í einni reyr, með súluhöfði og blómi; og þrír bikarar mótaðir sem möndlublóm í annarri reyr, með súluhöfði og blómi; svo fyrir sex reyrar sem ganga út frá ljósastikunni.'),
(2230, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 34, 'OT', 'Og í ljósastikunni fjórir bikarar mótaðir sem möndlublóm, með súluhöfðum sínum og blómum sínum.'),
(2231, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 35, 'OT', 'Súluhöfuð skal vera undir tveimur reyrum úr henni; súluhöfuð undir tveimur reyrum úr henni, og súluhöfuð undir tveimur reyrum úr henni, fyrir sex reyrar sem ganga út frá ljósastikunni.'),
(2232, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 36, 'OT', 'Súluhöfuð þeirra og reyrar skulu vera úr henni; allt skal vera eitt útsmíðað verk úr skíru gulli.'),
(2233, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 37, 'OT', 'Og þú skalt gera sjö lampa hennar, og þú skalt kveikja lampana, svo að þeir lýsi fram á móti andliti hennar.'),
(2234, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 38, 'OT', 'Og tengur hennar og eldpönnur hennar skulu vera úr skíru gulli.'),
(2235, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 39, 'OT', 'Úr einni talentu skírs gulls skalt þú gera hana, ásamt öllum þessum áhöldum.'),
(2236, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 25, 40, 'OT', 'Og gæt þess og gerðu það eftir fyrirmynd sinni, sem þér er sýnd á fjallinu.'),
(2237, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 1, 'OT', 'Og bústaðinn skalt þú gera úr tíu tjöldum af tvinnuðu hörlíni, bláma, purpura og skarlati, með kerúbum; verk útsaumaðs listamanns skalt þú gera þau.'),
(2238, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 2, 'OT', 'Lengd hvers tjalds skal vera tuttugu og átta álnir, og breidd hvers tjalds fjórar álnir; öll tjöldin skulu vera af sama máli.'),
(2239, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 3, 'OT', 'Fimm tjöld skulu vera tengd saman, hvert við systur sína; og fimm tjöld, hvert við systur sína.'),
(2240, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 4, 'OT', 'Og þú skalt gera lykkjur úr bláma á vör tjaldsins sem er á röndinni í samskeytinu; og eins skalt þú gera á vör hins tjaldsins sem er í hinu samskeytinu.'),
(2241, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 5, 'OT', 'Fimmtíu lykkjur skalt þú gera á hinu eina tjaldi, og fimmtíu lykkjur skalt þú gera á enda tjaldsins sem er í hinu samskeytinu; lykkjurnar skulu vera hver á móti annarri.'),
(2242, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 6, 'OT', 'Og þú skalt gera fimmtíu spangir úr gulli og tengja tjöldin hvert við systur sína með spöngunum, og bústaðurinn skal verða einn.'),
(2243, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 7, 'OT', 'Og þú skalt gera tjöld úr geitahári yfir bústaðinn; ellefu tjöld skalt þú gera þau.'),
(2244, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 8, 'OT', 'Lengd hvers tjalds skal vera þrjátíu álnir, og breidd hvers tjalds fjórar álnir; tjöldin ellefu skulu vera af sama máli.'),
(2245, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 9, 'OT', 'Og þú skalt tengja fimm tjöldin saman og sex tjöldin saman, og þú skalt tvöfalda sjötta tjaldið yfir andliti tjaldsins.'),
(2246, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 10, 'OT', 'Og þú skalt gera fimmtíu lykkjur á vör eins tjalds, hins ytra í samskeytinu, og fimmtíu lykkjur á vör hins tjaldsins sem er í hinu samskeytinu.'),
(2247, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 11, 'OT', 'Og þú skalt gera fimmtíu spangir úr eir og leiða spangirnar í lykkjurnar og tengja tjaldið, svo að það verði eitt.'),
(2248, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 12, 'OT', 'Og leifin af tjöldunum, helmingurinn af tjaldinu sem eftir verður, skal hanga niður á bakhlið bústaðarins.'),
(2249, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 13, 'OT', 'Og alinin hér og alinin þar, sem eftir verður af lengd tjaldanna, skal hanga niður á hliðum bústaðarins, hér og þar, til að hylja hann.'),
(2250, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 14, 'OT', 'Og þú skalt gera hlíf fyrir tjaldið úr rauðlituðum hrútskinnum, og hlíf úr selskinnum ofan yfir.'),
(2251, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 15, 'OT', 'Og þú skalt gera borðin fyrir bústaðinn úr akasíutrjám, standandi.'),
(2252, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 16, 'OT', 'Lengd hvers borðs skal vera tíu álnir, og breidd þess ein alin og helmingur.'),
(2253, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 17, 'OT', 'Tvær hendur skulu vera á hverju borði, hver tengd við systur sína. Svo skalt þú gera við öll borð bústaðarins.'),
(2254, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 18, 'OT', 'Og þú skalt gera borðin fyrir bústaðinn, tuttugu borð að suðurlandi.'),
(2255, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 19, 'OT', 'Fjörutíu undirstöður úr silfri skalt þú gera undir tuttugu borðunum, tvær undirstöður undir hvert borð fyrir hendur þess, og tvær undirstöður undir hvert borð fyrir hendur þess.'),
(2256, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 20, 'OT', 'Og á hinum rifi bústaðarins, í norðurátt, tuttugu borð.'),
(2257, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 21, 'OT', 'Og fjörutíu undirstöður þeirra úr silfri, tvær undirstöður undir hvert borð, og tvær undirstöður undir hvert borð.'),
(2258, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 22, 'OT', 'Og að lendum bústaðarins, til hafs, skalt þú gera sex borð.'),
(2259, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 23, 'OT', 'Og tvö borð skalt þú gera fyrir horn bústaðarins, í lendum.'),
(2260, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 24, 'OT', 'Þau skulu vera tvíburar neðan frá, og saman skulu þau vera heil upp að höfði þess, í einum hring; þannig skal vera um bæði þeirra, fyrir bæði hornin skulu þau vera.'),
(2261, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 25, 'OT', 'Átta borð skulu vera, og undirstöður þeirra úr silfri, sextán undirstöður, tvær undirstöður undir hvert borð og tvær undirstöður undir hvert borð.'),
(2262, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 26, 'OT', 'Og þú skalt gera slár úr akasíutrjám, fimm fyrir borðin á einu rifi bústaðarins.'),
(2263, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 27, 'OT', 'Og fimm slár fyrir borðin á hinu rifi bústaðarins, og fimm slár fyrir borðin á öðru rifi bústaðarins, í lendum til hafs.'),
(2264, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 28, 'OT', 'Miðslá, sem stendur í miðju borðanna, skal ná frá einum enda til annars enda.'),
(2265, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 29, 'OT', 'Og borðin skalt þú gylla gulli, og hringi þeirra skalt þú gera úr gulli, sem hús fyrir slárnar, og slárnar skalt þú hylja gulli.'),
(2266, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 30, 'OT', 'Og þú skalt reisa bústaðinn eftir dómi hans, sem þér var sýndur á fjallinu.'),
(2267, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 31, 'OT', 'Og þú skalt gera fortjald úr bláma, purpura, skarlat og fínum hör, ofið verk hagleiksmanns, með kerúbum.'),
(2268, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 32, 'OT', 'Og þú skalt hengja það á fjórar súlur úr akasíutré, hlaðnar gulli, og krókar þeirra úr gulli, á fjórum undirstöðum úr silfri.'),
(2269, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 33, 'OT', 'Og þú skalt hengja fortjaldið undir spöngunum, og þangað inn fyrir fortjaldið skalt þú flytja örk vitnisburðarins; og fortjaldið skal skilja á milli helgi og hins allrahelga.'),
(2270, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 34, 'OT', 'Og þú skalt setja náðarstólinn ofan á örk vitnisburðarins í helgi helganna.'),
(2271, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 35, 'OT', 'Og þú skalt setja borðið utan fortjaldsins, og ljósastikuna gegnt borðinu, á rifi bústaðarins sunnan megin, og borðið skalt þú setja á norðurrifið.'),
(2272, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 36, 'OT', 'Og þú skalt gera tjald fyrir innganginn að tjaldinu, úr bláma, purpura, skarlat og fínum hör, verk útsaumarans.'),
(2273, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 26, 37, 'OT', 'Og þú skalt gera fimm súlur úr akasíutré fyrir tjaldið, hlaðnar gulli, og krókar þeirra úr gulli, og steypa fyrir þær fimm undirstöður úr eiri.'),
(2274, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 1, 'OT', 'Og þú skalt gera altarið úr akasíutré, fimm álnir á lengd og fimm álnir á breidd. Altarið skal vera ferhyrnt, og þrjár álnir að vexti.'),
(2275, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 2, 'OT', 'Og þú skalt gera horn á fjórum hornsúlum þess; hornin skulu vera úr sama efni, og þú skalt hylja það með eiri.'),
(2276, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 3, 'OT', 'Og þú skalt gera potta hans til að taka af ösku, skóflur hans, skálar hans, kjötkróka hans og eldpönnur hans; öll áhöld hans skalt þú gera úr eiri.'),
(2277, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 4, 'OT', 'Og þú skalt gera grind fyrir það, verk úr eirneti, og á netið skalt þú gera fjóra hringi úr eiri, á fjórum hornum þess.'),
(2278, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 5, 'OT', 'Og þú skalt setja hana undir snúningi altarisins að neðan, og netið skal ná upp að helmingi altarisins.'),
(2279, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 6, 'OT', 'Og þú skalt gera stangir fyrir altarið úr akasíutré, og þú skalt hylja þær eiri.'),
(2280, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 7, 'OT', 'Og stengurnar skulu bornar í hringina, og stengurnar skulu vera á rifjum altarisins, þegar það er borið.'),
(2281, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 8, 'OT', 'Holt skalt þú gera það, úr borðum, eins og þér var sýnt á fjallinu, svo skulu þeir gera það.'),
(2282, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 9, 'OT', 'Og þú skalt gera forgarð bústaðarins; að suðurhorni skulu vera slöngvur úr fínum hör, hundrað álnir á lengd, fyrir eina hliðina.'),
(2283, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 10, 'OT', 'Súlur þeirra eru tuttugu og undirstöður þeirra tuttugu úr eiri; krókar súlnanna og lykkjur þeirra úr silfri.'),
(2284, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 11, 'OT', 'Og eins að norðurhorninu eftir endilöngu, slöngvur hundrað álnir á lengd, og súlur þeirra tuttugu og undirstöður þeirra tuttugu úr eiri, krókar súlnanna og lykkjur þeirra úr silfri.'),
(2285, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 12, 'OT', 'Og breidd forgarðsins til hafs: slöngvur fimmtíu álnir, súlur þeirra tíu og undirstöður þeirra tíu.'),
(2286, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 13, 'OT', 'Og breidd forgarðsins að austurhorni, til austurs, fimmtíu álnir.'),
(2287, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 14, 'OT', 'Fimmtán álnir slöngvur við aðra öxl: súlur þeirra þrjár og undirstöður þeirra þrjár.'),
(2288, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 15, 'OT', 'Og við hina öxlina fimmtán slöngvur; súlur þeirra þrjár og undirstöður þeirra þrjár.'),
(2289, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 16, 'OT', 'Og fyrir hlið forgarðsins: tjald tuttugu álnir af bláma, purpura, skarlat og fínum hör, verk útsaumarans; súlur þeirra fjórar og undirstöður þeirra fjórar.'),
(2290, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 17, 'OT', 'Allar súlur forgarðsins umhverfis skulu vera bundnar silfri; krókar þeirra úr silfri og undirstöður þeirra úr eiri.'),
(2291, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 18, 'OT', 'Lengd forgarðsins skal vera hundrað álnir, breidd fimmtíu á fimmtíu, og hæð fimm álnir af fínum hör; undirstöður þeirra úr eiri.'),
(2292, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 19, 'OT', 'Öll áhöld bústaðarins, til allrar þjónustu, og allar hælur hans og allar hælur forgarðsins skulu vera úr eiri.'),
(2293, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 20, 'OT', 'Og þú skalt bjóða Ísraelssonum að færa þér hreina ólífuolíu, pressaða, til ljóss, að láta lampa loga stöðugt.'),
(2294, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 27, 21, 'OT', 'Í samfundatjaldinu, utan fortjaldsins sem er fyrir vitnisburði, skulu Aron og synir hans sjá um það frá kvöldi til morguns fyrir andlit Jahve; það er eilíft lagaákvæði fyrir kynslóðir þeirra af Ísraelssonum.'),
(2295, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 1, 'OT', 'Og þú skalt leiða til þín Aron, bróður þinn, og sonu hans með honum, úr hópi Ísraelssona, til að þjóna mér sem prestar: Aron, Nadab og Abíhú, Eleasar og Ítamar, synir Arons.'),
(2296, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 2, 'OT', 'Og þú skalt gera heilög klæði handa Aroni, bróður þínum, til dýrðar og prýði.'),
(2297, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 3, 'OT', 'Og þú skalt tala við alla hagfróða í hjarta, sem ég hef fyllt anda speki, og þeir skulu gera klæði Arons, til að helga hann og þjóna mér sem presti.'),
(2298, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 4, 'OT', 'Og þetta eru klæðin sem þeir skulu gera: brjóstskjöld, hökul, yfirhöfn, kyrtil úr ofnum vefnaði, vefjarhött og belti; og þeir skulu gera heilög klæði fyrir Aron, bróður þinn, og sonu hans, til að þjóna mér sem prestar.'),
(2299, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 5, 'OT', 'Og þeir skulu taka gull, bláma, purpura, skarlat og fínan hör.'),
(2300, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 6, 'OT', 'Og þeir skulu gera hökulinn úr gulli, bláma, purpura, skarlati og fínum hör, verk hagleiksmanns.'),
(2301, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 7, 'OT', 'Tvær axlir skulu vera á því, tengdar saman við tveimur röndum þess, og það skal vera bundið saman.'),
(2302, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 8, 'OT', 'Og vefnað á hökul, sem á honum er, eins og verk þess, skal vera úr gulli, bláma, purpura, skarlati og fínum hör.'),
(2303, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 9, 'OT', 'Og þú skalt taka tvo steina úr ónyx og grafa á þá nöfn sona Ísraels.'),
(2304, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 10, 'OT', 'Sex af nöfnum þeirra á annan steininn, og nöfn hinna sex sem eftir eru á hinn steininn, eftir ættartölu þeirra.'),
(2305, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 11, 'OT', 'Verk smiðs, útskurður eins og innsigli, skalt þú grafa á hina tvo steinana eftir nöfnum sona Ísraels; þú skalt gera þá í greyptri umgjörð úr gulli.'),
(2306, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 12, 'OT', 'Og þú skalt setja þessa tvo steina á axlir hökulsins til minningar um sonu Ísraels, og Aron skal bera nöfn þeirra fyrir andlit Jahve á báðum öxlum sínum til minningar.'),
(2307, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 13, 'OT', 'Og þú skalt gera greypta umgjörð úr gulli.'),
(2308, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 14, 'OT', 'Og tvær keðjur úr hreinu gulli skalt þú gera, fléttaðar eins og reipi, og þú skalt festa keðjurnar fléttuðu á greypta umgjörð.'),
(2309, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 15, 'OT', 'Og þú skalt gera brjóstskjöld dómsins, verk hagleiksmanns, eins og verk hökulsins skalt þú gera hann; úr gulli, bláma, purpura, skarlati og fínum hör skalt þú gera hann.'),
(2310, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 16, 'OT', 'Hann skal vera ferhyrndur, tvöfaldur; lengd hans ein spönn og breidd hans ein spönn.'),
(2311, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 17, 'OT', 'Og þú skalt setja í hann fjórar raðir steina: fyrsta röð rúbín, tópas og karbunkúl; það er fyrsta röðin.'),
(2312, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 18, 'OT', 'Önnur röðin er smaragð, safír og demantur.'),
(2313, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 19, 'OT', 'Þriðja röðin er ligúr, ametýst og agat.'),
(2314, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 20, 'OT', 'Fjórða röðin er tarsisteinn, ónyx og jaspis; þeir skulu vera settir í greypta umgjörð úr gulli.'),
(2315, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 21, 'OT', 'Og steinar skulu vera eftir nöfnum sona Ísraels, tólf, eftir nöfnum þeirra; með útskurði eins og innsigli, hver eftir nafni sínu, skulu þeir vera fyrir tólf ættkvíslirnar.'),
(2316, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 22, 'OT', 'Og þú skalt gera á brjóstskjöldinn keðjur, fléttaðar eins og reipi, úr hreinu gulli.'),
(2317, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 23, 'OT', 'Og þú skalt gera á brjóstskjöldinn tvo hringi úr gulli, og setja hringina tvo á tvær randir brjóstskjaldarins.'),
(2318, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 24, 'OT', 'Og þú skalt setja reipin tvö úr gulli á hringina tvo, við röndum brjóstskjaldarins.'),
(2319, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 25, 'OT', 'Og endana á reipunum tveimur skalt þú setja á greyptu umgjarðirnar tvær, og þú skalt setja þær á axlir hökulsins fyrir andlit hans.'),
(2320, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 26, 'OT', 'Og þú skalt gera tvo hringi úr gulli og setja þá á randir brjóstskjaldarins, á vörina sem snýr innvið hökli.'),
(2321, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 27, 'OT', 'Og þú skalt gera tvo hringi úr gulli og setja þá á axlir hökulsins að neðan, fyrir andlit samskeytanna, ofan við vefnaði hökulsins.'),
(2322, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 28, 'OT', 'Og þeir skulu binda brjóstskjöldinn með hringjum sínum við hringi hökulsins með bandi úr bláma, þannig að hann sitji á vefnaði hökulsins, og brjóstskjöldurinn skal ekki losna frá hökli.'),
(2323, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 29, 'OT', 'Og Aron skal bera nöfn sona Ísraels í brjóstskildi dómsins á hjarta sínu, þegar hann gengur inn í helgidóminn, til minningar fyrir Jahve ævinlega.'),
(2324, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 30, 'OT', 'Og þú skalt setja í brjóstskjöld dómsins Úrím og Túmmím, og þeir skulu vera á hjarta Arons, þegar hann gengur inn fyrir andlit Jahve; og Aron skal bera dóm sona Ísraels á hjarta sínu fyrir andlit Jahve ævinlega.'),
(2325, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 31, 'OT', 'Og þú skalt gera yfirhöfnina við hökulinn, alla úr bláma.'),
(2326, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 32, 'OT', 'Og munnur hennar skal vera á höfði hennar í miðju; vör skal vera um munn hennar, verk ofið eins og brynju, svo að hún rifni ekki.'),
(2327, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 33, 'OT', 'Og þú skalt gera á faldinn hennar granatepli úr bláma, purpura og skarlati, allt um faldinn, og bjöllur úr gulli á milli þeirra allt um kring.'),
(2328, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 34, 'OT', 'Bjalla úr gulli og granatepli, bjalla úr gulli og granatepli, allt um faldinn á yfirhöfninni.'),
(2329, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 35, 'OT', 'Og hann skal vera á Aroni til þjónustu, og rödd hans skal heyrast þegar hann gengur inn í helgidóminn fyrir andlit Jahve og þegar hann gengur út, svo að hann deyi ekki.'),
(2330, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 36, 'OT', 'Og þú skalt gera blóm úr hreinu gulli og grafa á það útskurð eins og innsigli: Heilagt Jahve.'),
(2331, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 37, 'OT', 'Og þú skalt festa það á band úr bláma, og það skal vera á vefjarhettinum fyrir andliti vefjarhettisins.'),
(2332, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 38, 'OT', 'Og það skal vera á enni Arons, og Aron skal bera misgjörð helgidóma sem synir Ísraels helga, allar heilagar gjafir þeirra; og það skal vera á enni hans ævinlega til velþóknunar þeim fyrir andlit Jahve.'),
(2333, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 39, 'OT', 'Og þú skalt vefa kyrtilinn úr fínum hör, gera vefjarhött úr fínum hör og belti, verk útsaumarans.'),
(2334, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 40, 'OT', 'Handa sonum Arons skalt þú gera kyrtla, og þú skalt gera þeim belti og vefjarhetti, til dýrðar og prýði.'),
(2335, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 41, 'OT', 'Og þú skalt klæða með þeim Aron, bróður þinn, og syni hans með honum; og þú skalt smyrja þá, fylla hendur þeirra, helga þá, og þeir skulu þjóna mér sem prestar.'),
(2336, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 42, 'OT', 'Og gerðu þeim nærbuxur úr hör til að hylja nekt holds; þær skulu ná frá lendum og niður á læri.'),
(2337, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 28, 43, 'OT', 'Og þeir skulu vera á Aroni og sonum hans, þegar þeir ganga inn í tjaldið, eða þegar þeir nálgast altarið til að þjóna í helgidóminum, svo að þeir beri ekki misgjörð og deyi; það er eilíft lagaákvæði fyrir hann og sæði hans eftir hann.'),
(2338, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 1, 'OT', 'Og þetta er orðið sem þú skalt gera þeim til að helga þá, til að þjóna mér sem prestar: Tak einn ungnaut úr nautum og tvo hrúta, gallalausa.'),
(2339, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 2, 'OT', 'Og ósýrt brauð, og ósýrðar kökur hrærðar í olíu, og ósýrð brauð smurð í olíu; úr fínu mjöli, hveiti, skalt þú gera þær.'),
(2340, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 3, 'OT', 'Og þú skalt setja þær í körfu og bera þær fram í körfunni, ásamt ungnauti og hrútum tveimur.'),
(2341, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 4, 'OT', 'Og þú skalt leiða Aron og sonu hans að innganginum á samfundatjaldinu og þvo þá í vatni.'),
(2342, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 5, 'OT', 'Og þú skalt taka klæðin og klæða Aron í kyrtilinn, yfirhöfnina, hökulinn og brjóstskjöldinn, og spenna hann með belti hökulsins.'),
(2343, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 6, 'OT', 'Og þú skalt setja vefjarhött á höfuð hans og setja heilaga kórónu á vefjarhöttinn.'),
(2344, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 7, 'OT', 'Og þú skalt taka olíu til smurningar og hella á höfuð hans og smyrja hann.'),
(2345, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 8, 'OT', 'Og þú skalt færa sonu hans fram og klæða þá kyrtlum.'),
(2346, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 9, 'OT', 'Og þú skalt gyrða þá, Aron og sonu hans, belti, og þú skalt binda þeim vefjarhettur; og prestsembættið skal vera þeirra með eilífu lagaákvæði; og þú skalt fylla hendur Arons og hendur sona hans.'),
(2347, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 10, 'OT', 'Og þú skalt leiða fram ungnaut fyrir andlit samfundatjaldsins, og Aron og synir hans skulu leggja hendur sínar á höfuð ungnautsins.'),
(2348, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 11, 'OT', 'Og þú skalt slátra ungnautinu frammi fyrir Jahve við dyr samfundatjaldsins.'),
(2349, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 12, 'OT', 'Og þú skalt taka af blóði ungnauts og setja á horn altarisins með fingri þínum, og allt blóðið skalt þú hella niður við undirstöðu altaris.'),
(2350, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 13, 'OT', 'Og þú skalt taka alla fitu sem hylur innyflin, og lifrarbjúga, lifur, nýru tvö og fitu á þeim, og brenna á altari.'),
(2351, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 14, 'OT', 'En hold ungnauts, skinn þess og saur skalt þú brenna í eldi fyrir utan herbúðirnar; það er fórn fyrir synd.'),
(2352, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 15, 'OT', 'Og þú skalt taka annan hrút, og Aron og synir hans skulu leggja hendur sínar á höfuð hrútsins.'),
(2353, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 16, 'OT', 'Og slátra hrút, og tak blóð hans og stökk á altari allt um kring.'),
(2354, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 17, 'OT', 'Og hrútinn skalt þú kryfja í stykki, þvo innyflin og leggi, og leggja á stykkin og á höfuð.'),
(2355, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 18, 'OT', 'Og brenn allan hrút á altari; það er brennifórn, eldfórn, þægilegur ilmur fyrir Jahve.'),
(2356, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 19, 'OT', 'Og þú skalt taka hinn hrútinn, og Aron og synir hans skulu leggja hendur sínar á höfuð hrútsins.'),
(2357, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 20, 'OT', 'Og slátra hrútnum, og tak af blóði hans og set á hægri eyrnasnepil Arons og á hægri eyrnasnepil sona hans, og á þumalfingur hægri handar þeirra og á stóru tá hægri fótar þeirra, og stökk blóðinu á altarið allt um kring.'),
(2358, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 21, 'OT', 'Og þú skalt taka af blóðinu sem er á altari og af olíu smurningar, og stökkva á Aron og klæði hans, og á syni hans og klæði sona hans með honum; og hann skal helgast, hann og klæði hans, synir hans og klæði sona hans með honum.'),
(2359, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 22, 'OT', 'Og þú skalt taka af hrúti fitu og rófu, fitu sem hylur innyflin, lifrarbjúga og lifur, nýru tvö og fitu á þeim, og hægra læri; því þetta er hrútur vígslunnar.'),
(2360, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 23, 'OT', 'Og eitt talentubrauð og eitt brauð úr hveiti, eina köku hrærða í olíu og eina þunna köku, ósýrt brauð úr körfunni, fyrir andliti Jahve.'),
(2361, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 24, 'OT', 'Og þú skalt leggja allt þetta á lófa Arons og lófa sona hans og lyfta því upp sem veifufórn fyrir andlit Jahve.'),
(2362, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 25, 'OT', 'Og þú skalt taka það af höndum þeirra og brenna á altari ofan á brennifórninni, sem þægilegan ilm fyrir andlit Jahve; það er eldfórn fyrir Jahve.'),
(2363, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 26, 'OT', 'Og þú skalt taka bringu af hrúti vígslunnar, sem var Arons, og veifa henni sem veifufórn fyrir andlit Jahve; og hún skal verða þinn hlutur.'),
(2364, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 27, 'OT', 'Og þú skalt helga bringu veifufórnarinnar og læri framlagsins, sem veifað var og upp lyft, af hrúti vígslunnar, af því sem er Arons og sona hans.'),
(2365, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 28, 'OT', 'Og það skal vera Aroni og sonum hans að eilífum lögum frá sonum Ísraels, því þetta er framlag; og framlag skal vera frá sonum Ísraels af þakkarfórnum þeirra, framlag þeirra fyrir Jahve.'),
(2366, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 29, 'OT', 'Og heilög klæði Arons skulu vera sona hans eftir hann, til að smyrja þá í þeim og fylla hendur þeirra.'),
(2367, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 30, 'OT', 'Sjö daga skal presturinn, sá sem er í hans stað af sonum hans, klæðast þeim, þann sem gengur inn í samfundatjaldið til að þjóna í helgidóminum.'),
(2368, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 31, 'OT', 'Og hrút vígslu skalt þú taka og sjóða hold hans á helgum stað.'),
(2369, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 32, 'OT', 'Og Aron og synir hans skulu eta hold hrúts og brauðið sem er í körfunni við inngang tjaldsins.'),
(2370, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 33, 'OT', 'Og þeir skulu eta það, sem friðþægt var fyrir þá með, til að fylla hendur þeirra og helga þá; en enginn óviðkomandi skal eta það, því það er heilagt.'),
(2371, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 34, 'OT', 'Og ef eitthvað verður eftir af holdi vígslunnar og af brauði til morguns, þá skalt þú brenna leifarnar í eldi; þær skulu ekki etnar, því þær eru heilagar.'),
(2372, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 35, 'OT', 'Og þannig skalt þú gera við Aron og sonu hans, samkvæmt öllu því sem ég hef boðið þér; í sjö daga skalt þú fylla hendur þeirra.'),
(2373, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 36, 'OT', 'Og þú skalt fórna ungnaut sem syndafórn á hverjum degi til friðþægingar, og þú skalt hreinsa altari með friðþægingu og smyrja það til að helga það.'),
(2374, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 37, 'OT', 'Í sjö daga skalt þú friðþægja fyrir altari og helga það; og altarið skal vera heilagt, hver sem snertir altarið skal helgast.'),
(2375, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 38, 'OT', 'Og þetta er það sem þú skalt færa á altari: tvö lömb, ára gömul, á hverjum degi, stöðugt.'),
(2376, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 39, 'OT', 'Annað lambið skalt þú færa að morgni, og hitt lambið skalt þú færa á milli kvölda.'),
(2377, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 40, 'OT', 'Og tíunda hluta af fínu mjöli hrærðu í olíu, fjórðung hínsins; og dreypifórn, fjórðung hínsins af víni, fyrir eitt lamb.'),
(2378, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 41, 'OT', 'Og hitt lambið skalt þú færa á milli kvölda, eins og fórn að morgni og eins og dreypifórnina, sem þægilegan ilm, eldfórn fyrir Jahve.'),
(2379, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 42, 'OT', 'Stöðug brennifórn um kynslóðir yðar við inngang samfundatjaldsins fyrir andliti Jahve, þar sem ég mun hitta yður og tala þar við þig.'),
(2380, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 43, 'OT', 'Þar mun ég hitta sonu Ísraels, og það skal helgast af dýrð minni.'),
(2381, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 44, 'OT', 'Og ég mun helga samfundatjaldið og altarið, og Aron og sonu hans mun ég helga, til að þjóna mér sem prestar.'),
(2382, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 45, 'OT', 'Og ég mun búa meðal sona Ísraels og vera þeim Guð.'),
(2383, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 29, 46, 'OT', 'Og þeir munu vita að ég er Jahve, Guð þeirra, sá sem leiddi þá út úr Egyptalandi til að búa meðal þeirra; ég er Jahve, Guð þeirra.'),
(2384, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 1, 'OT', 'Og þú skalt gera altari til reykelsisfórnar, úr akasíutré, til að brenna reykelsi.'),
(2385, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 2, 'OT', 'Ein alin á lengd og ein alin á breidd, ferhyrnt skal það vera; og tvær álnir að vexti; hornin skulu vera úr því sama.'),
(2386, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 3, 'OT', 'Og þú skalt hylja það gulli, þak þess og veggi þess allt um kring og hornin; og þú skalt gera á það kórónu úr gulli allt um kring.'),
(2387, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 4, 'OT', 'Og þú skalt gera tvo hringi úr gulli undir kórónu, á báðum hliðum þess; þeir skulu vera handföng fyrir stengurnar til að bera það með.'),
(2388, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 5, 'OT', 'Og þú skalt gera stangirnar úr akasíutré og hylja þær gulli.'),
(2389, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 6, 'OT', 'Og þú skalt setja það fyrir fortjaldið sem er yfir örk vitnisburðarins, fyrir andlit náðarstólsins sem er yfir vitnisburðinum, þar sem ég mun hitta þig.'),
(2390, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 7, 'OT', 'Og Aron skal brenna á því reykelsi af ilmjurtum á hverjum morgni; þegar hann snyrtir lampa skal hann brenna það.'),
(2391, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 8, 'OT', 'Og þegar Aron kveikir lampana að kvöldi, skal hann brenna það; reykelsi stöðugt fyrir andliti Jahve um kynslóðir yðar.'),
(2392, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 9, 'OT', 'Þér skuluð ekki bera fram annað reykelsi á það, né brennifórn, né fórn, né dreypifórn skuluð þér hella á það.'),
(2393, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 10, 'OT', 'Og Aron skal friðþægja á hornum þess einu sinni á ári; með blóði syndafórnar friðþægingarinnar skal hann friðþægja á því einu sinni á ári um kynslóðir yðar; það er afar heilagt fyrir Jahve.'),
(2394, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 11, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2395, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 12, 'OT', 'Þegar þú telur höfuð sona Ísraels til manntals, þá skal hver maður gefa lausnargjald fyrir sál sína Jahve þegar þeir eru taldir, til að engin plága verði meðal þeirra þegar þeir eru taldir.'),
(2396, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 13, 'OT', 'Allir sem fara yfir talninguna skulu gefa helming sikils, eftir helgu sikli; sikillinn er tuttugu gera; helmingur sikils skal vera framlag fyrir Jahve.'),
(2397, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 14, 'OT', 'Hver sá sem fer yfir talninguna, frá tuttugu ára aldri og eldri, skal gefa framlag Jahve.'),
(2398, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 15, 'OT', 'Hinn ríki skal ekki auka og hinn fátæki ekki minnka frá helmingi sikilsins, til að gefa framlag Jahve til friðþægingar fyrir sálir yðar.'),
(2399, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 16, 'OT', 'Og þú skalt taka silfur til friðþægingar frá sonum Ísraels og láta það í þjónustu samfundatjaldsins; og það skal vera sonum Ísraels til minningar fyrir andlit Jahve, til að friðþægja fyrir sálir yðar.'),
(2400, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 17, 'OT', 'Og Jahve talaði aftur við Móses og sagði:'),
(2401, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 18, 'OT', 'Þú skalt einnig gera þvottaker úr eir og stall þess úr eir til þvotta, og setja það á milli samfundatjaldsins og altarisins og láta vatn í það.'),
(2402, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 19, 'OT', 'Aron og synir hans skulu þvo í því hendur sínar og fætur.'),
(2403, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 20, 'OT', 'Þegar þeir ganga inn í samfundatjaldið skulu þeir þvo sig í vatni, svo að þeir deyi ekki, eða þegar þeir ganga að altarinu til að þjóna og fórna eldfórn Jahve.'),
(2404, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 21, 'OT', 'Þeir skulu þvo sér hendur og fætur, svo að þeir deyi ekki. Það skal vera þeim lög um eilífð, bæði honum og sæði hans í kynslóðum þeirra.'),
(2405, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 22, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2406, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 23, 'OT', 'Þú skalt taka þér ilmjurtir, höfuð ilmjurta: fimm hundruð sikla af fljótandi myrru, og helming þess, tvö hundruð og fimmtíu sikla af ilmandi kanil og tvö hundruð og fimmtíu sikla af ilmreyr.'),
(2407, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 24, 'OT', 'Og fimm hundruð sikla af kassíu, mældum eftir helgisikli, og eitt hín af olíu úr olíutré.'),
(2408, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 25, 'OT', 'Þú skalt gera úr henni smurningarolíu af helgi, smyrsl, verk smyrslagerðarmanns; hún skal vera smurningarolía af helgi.'),
(2409, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 26, 'OT', 'Og þú skalt smyrja með henni samfundatjaldið og örkina vitnisburðarins.'),
(2410, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 27, 'OT', 'Og borðið ásamt öllum áhöldum þess, og ljósastikuna ásamt áhöldum hennar, og altari reykelsisins.'),
(2411, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 28, 'OT', 'Og altari brennifórnarinnar ásamt öllum áhöldum þess, og þvottakerið og stall þess.'),
(2412, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 29, 'OT', 'Þú skalt helga þau, og þau skulu vera helgi helgra; hvað sem snertir þau skal helgað verða.'),
(2413, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 30, 'OT', 'Þú skalt smyrja Aron og syni hans og helga þá, til þess að þeir þjóni mér sem prestar.'),
(2414, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 31, 'OT', 'Og þú skalt tala við Ísraels sonu og segja: Þessi smurningarolía skal vera mér af helgi í kynslóðum yðar.'),
(2415, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 32, 'OT', 'Hún skal ekki smurð á hold manns, og eftir mælikvarða hennar skuluð þér ekki gera slíka. Hún er af helgi og skal vera yður af helgi.'),
(2416, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 33, 'OT', 'Hver maður sem blandar slíka og hver sem setur af henni á ókunnugan, sá skal upprættur verða úr lýð sínum.'),
(2417, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 34, 'OT', 'Og Jahve sagði við Móses: Tak þér ilmjurtir: dropa, ónykseitan ilm og galbanum, ilmjurtir og hreint reykelsi; hvort tveggja skal vera jafnt.'),
(2418, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 35, 'OT', 'Og þú skalt gera úr því reykelsi, smyrsl gert af kunnáttu, verk ilmgerðarmanns; salt, hreint og af helgi.'),
(2419, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 36, 'OT', 'Og þú skalt mylja af því smátt og setja það fyrir andliti vitnisburðarins í samfundatjaldinu, þar sem ég mun birtast þér; það skal vera yður helgi helgra.'),
(2420, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 37, 'OT', 'Reykelsið sem þú gerir eftir mælikvarða þess skuluð þér ekki gera handa yður sjálfum; það skal vera þér af helgi Jahve.'),
(2421, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 30, 38, 'OT', 'Hver maður sem gerir slíkt til að finna ilminn af því, sá skal upprættur verða úr lýð sínum.'),
(2422, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2423, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 2, 'OT', 'Sjá, ég hef kallað Besalel með nafni, son Úrís, sonar Húrs, af ættkvísl Júda.'),
(2424, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 3, 'OT', 'Og ég hef fyllt hann anda Guðs, með speki, skilningi og þekkingu, og í öllu starfi.'),
(2425, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 4, 'OT', 'Til að hanna ráðagerðir, til að vinna í gulli, silfri og eiri.'),
(2426, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 5, 'OT', 'Og til útskurðar á steina til greypingar og útskurðar á tré, til að vinna í öllu starfi.'),
(2427, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 6, 'OT', 'Og sjá, ég hef sett með honum Oholíab, son Akísamaks, af ættkvísl Dan, og í hjarta hvers hygginnar manns hef ég lagt speki, svo að þeir gjöri allt það sem ég hef boðið þér.'),
(2428, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 7, 'OT', 'Samfundatjaldið, örkina vitnisburðarins, náðarstólinn sem er yfir henni, og öll áhöld tjaldsins.'),
(2429, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 8, 'OT', 'Og borðið og áhöld þess, og hreinu ljósastikuna og áhöld hennar, og altari reykelsisins.'),
(2430, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 9, 'OT', 'Og altari brennifórnarinnar með öllum áhöldum þess, og þvottakerið og stall þess.'),
(2431, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 10, 'OT', 'Og klæði þjónustunnar og klæði af helgi fyrir Aron prest, og klæði sona hans til að þjóna sem prestar.'),
(2432, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 11, 'OT', 'Og smurningarolíuna og reykelsið af ilmjurtum, til þjónustu af helgi; eins og ég hef boðið þér skulu þeir gjöra.'),
(2433, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 12, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2434, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 13, 'OT', 'Þú skalt tala við Ísraels sonu og segja: Þér skuluð halda hvíldardaga mína, því að hann er tákn milli mín og yðar um allar kynslóðir yðar, til þess að þér vitið að ég er Jahve, sem helga yður.'),
(2435, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 14, 'OT', 'Þér skuluð halda hvíldardaginn, því að hann er yður af helgi. Hver sem vanhelgar hann skal líflátinn verða, því að hver sem vinnur nokkurt starf á honum, sú sál skal upprætt verða úr lýð sínum.'),
(2436, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 15, 'OT', 'Sex daga skal vinna starf, en á sjöunda degi er hvíldardagur, hvíld af helgi, helguð Jahve; hver sem vinnur starf á hvíldardegi skal líflátinn verða.'),
(2437, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 16, 'OT', 'Og Ísraels synir skulu halda hvíldardaginn og gjöra hvíldardaginn kynslóð fram af kynslóð sem sáttmála um eilífð.'),
(2438, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 17, 'OT', 'Hann er tákn milli mín og Ísraels sona um eilífð, því að á sex dögum skapaði Jahve himin og jörð, en á sjöunda degi hvíldist hann og hresstist.'),
(2439, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 31, 18, 'OT', 'Og er hann hafði lokið við að tala við Móses á fjallinu Sínaí, gaf hann honum tvær töflur vitnisburðarins, töflur úr steini, ritaðar með fingri Guðs.'),
(2440, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 1, 'OT', 'Þegar lýðurinn sá að Móses dróst á að koma niður af fjallinu, safnaðist lýðurinn saman gegn Aroni og sagði við hann: Rís upp, gjör oss Guð sem gangi fyrir andliti vors, því að þessi maður Móses, sem leiddi oss úr jörð Egyptalands, vitum vér ekki hvað um hann er orðið.'),
(2441, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 2, 'OT', 'Og Aron sagði við þá: Takið gulleyrnalokkana af eyrum kvenna yðar, sona yðar og dætra yðar og færið mér þá.'),
(2442, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 3, 'OT', 'Þá tók lýðurinn gulleyrnalokkana af eyrum sér og færði Aroni þá.'),
(2443, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 4, 'OT', 'Og hann tók það af hendi þeirra, mótaði það með griffli og gjörði af því steypt líkneski í kálfslíki. Þá sögðu þeir: Þetta er Guð þinn, Ísrael, sem leiddi þig út af Egyptalandi.'),
(2444, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 5, 'OT', 'Aron sá það og reisti altari fyrir andliti þess. Og Aron kallaði og sagði: Á morgun er hátíð Jahve.'),
(2445, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 6, 'OT', 'Morguninn eftir risu þeir árla, færðu brennifórnir og báru fram þakkarfórnir; og lýðurinn settist niður til að eta og drekka, og stóð upp til að leika sér.'),
(2446, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 7, 'OT', 'Og Jahve talaði við Móses: Far og gakk niður, því að lýð þinn, sem þú leiddir úr jörð Egyptalands, hefur spillt sér.'),
(2447, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 8, 'OT', 'Þeir hafa skjótt vikið af veginum sem ég bauð þeim; þeir hafa gjört sér steypt líkneski í kálfslíki, tilbeðið það, fært því fórnir og sagt: Þetta er Guð þinn, Ísrael, sem leiddi þig úr jörð Egyptalands.'),
(2448, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 9, 'OT', 'Og Jahve sagði við Móses: Ég hef séð þennan lýð, og sjá, hann er stífhálsaður lýður.'),
(2449, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 10, 'OT', 'Og nú, lát mig í friði, svo að reiði mín brenni gegn þeim og ég eyði þeim; og ég mun gjöra þig að mikilli þjóð.'),
(2450, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 11, 'OT', 'Og Móses leitaði náðar fyrir andliti Jahve Guðs síns og sagði: Hví, Jahve, mun reiði þín brenna gegn lýð þínum, sem þú leiddir úr jörð Egyptalands með miklum krafti og sterkri hendi?'),
(2451, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 12, 'OT', 'Hvers vegna ættu Egyptar að segja: Hann leiddi þá út með illu, til að drepa þá á fjöllum og afmá þá af jörð? Snú frá brennandi reiði þinni og iðrastu hins ills sem þú hefur ætlað lýð þínum.'),
(2452, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 13, 'OT', 'Minnstu Abrahams, Ísaks og Ísraels, þjóna þinna, sem þú sórst við sjálfan þig og sagðir við þá: Ég mun fjölga sæði yðar eins og stjörnum himins, og alla þessa jörð sem ég hef talað um mun ég gefa sæði yðar, og þeir munu erfa hana um eilífð.'),
(2453, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 14, 'OT', 'Og Jahve iðraðist hins ills sem hann hafði hótað að gjöra lýð sínum.'),
(2454, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 15, 'OT', 'Þá sneri Móses sér og fór ofan af fjalli með tvær töflur vitnisburðar í hendi sinni; töflur þessar voru ritaðar báðum megin, á þessa hlið og hina.'),
(2455, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 16, 'OT', 'Töflur voru verk Guðs, og rit Guðs var grafið á töflur.'),
(2456, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 17, 'OT', 'Jósúa heyrði rödd lýðs með hávaða, og hann sagði við Móses: Rödd stríðs heyrist í herbúðum.'),
(2457, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 18, 'OT', 'Hann sagði: Hvorki er þetta rödd máttar né rödd yfirbugunar; rödd söngs heyri ég.'),
(2458, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 19, 'OT', 'Og svo bar við er hann kom nær herbúðum og sá kálf og dans, að reiði Mósesar upptendraðist; hann kastaði töflum úr höndum sér og braut þær undir fjalli.'),
(2459, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 20, 'OT', 'Og hann tók kálf þann sem þeir höfðu gjört, brenndi hann í eldi og muldi hann þar til hann varð að dufti; stráði því á andlit vatns og lét Ísraels sonu drekka.'),
(2460, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 21, 'OT', 'Og Móses sagði við Aron: Hvað hefur þetta lýð gjört þér, að þú leiddir yfir hann svo mikla synd?'),
(2461, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 22, 'OT', 'Og Aron sagði: Reiðst ekki, herra minn. Þú veist sjálfur að lýður er illur.'),
(2462, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 23, 'OT', 'Þeir sögðu við mig: Gjör oss guði sem fari fyrir andliti vors; því að þessi maður Móses, sem leiddi oss úr jörð Egyptalands, vitum vér ekki hvað um hann er orðið.'),
(2463, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 24, 'OT', 'Og ég sagði við þá: Hver sem á gull, slíti það af sér. Þeir fengu mér það, og ég kastaði því í eldi, og út kom þessi kálfur.'),
(2464, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 25, 'OT', 'Móses sá að lýður var óbeislaður, því að Aron hafði gjört hann óbeislaðan til skammar meðal fjenda sinna.'),
(2465, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 26, 'OT', 'Móses stóð í hliði herbúða og sagði: Hver er með Jahve? Komi hann til mín! Og allir synir Leví söfnuðust til hans.'),
(2466, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 27, 'OT', 'Og hann sagði við þá: Svo segir Jahve, Guð Ísraels: Hver maður gyrði sverð sitt um læri sér, farið fram og aftur frá hliði til hliðs um herbúðir, og drepi hver bróður sinn og hver náunga sinn.'),
(2467, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 28, 'OT', 'Synir Leví gjörðu eftir orði Mósesar, og á þeim degi féllu af lýð þrjú þúsund manna.'),
(2468, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 29, 'OT', 'Og Móses sagði: Vígið hendur yðar fyrir Jahve í dag, því að hver maður var gegn syni sínum og bróður sínum, til þess að hann gefi yður blessun í dag.'),
(2469, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 30, 'OT', 'Næsta dag sagði Móses við lýð: Þér hafið syndgað mikla synd; en nú vil ég fara upp til Jahve; kannski get ég friðþægt fyrir synd yðar.'),
(2470, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 31, 'OT', 'Og Móses sneri aftur til Jahve og sagði: Æ, þessi lýður hefur syndgað mikla synd og gjört sér guði úr gulli.'),
(2471, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 32, 'OT', 'Og nú, ef þú vilt fyrirgefa þeim synd, en ef ekki, þurrkaðu mig út úr bók þinni, sem þú hefur ritað.'),
(2472, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 33, 'OT', 'Og Jahve sagði við Móses: Sá sem hefur syndgað gegn mér, hann mun ég afmá úr bók minni.'),
(2473, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 34, 'OT', 'Og nú, far þú og leið lýð þangað sem ég hef talað við þig. Sjá, sendiboði minn skal fara fyrir andliti þínu, og á þeim degi sem ég vitja, skal ég vitja synd þeirra.'),
(2474, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 32, 35, 'OT', 'Og Jahve sló lýð, af því að þeir höfðu gjört kálf þann sem Aron hafði gjört.'),
(2475, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 1, 'OT', 'Og Jahve talaði við Móses: Far, gakk héðan upp, þú og lýð þann sem þú leiddir út af Egyptalandi, í jörð þá sem ég sór Abraham, Ísak og Jakob og sagði: Sæði þínu vil ég gefa hana.'),
(2476, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 2, 'OT', 'Ég mun senda sendiboða fyrir andliti þínu og reka burt Kanaanita, Amorita, Hetíta, Peresíta, Hevíta og Jebúsíta.'),
(2477, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 3, 'OT', 'Í jörð sem flýtur í mjólk og hunangi; því að ég vil ekki fara upp meðal þín, því að þú ert lýður, háls þinn er stífur, til þess að ég tortími þér ekki á vegi.'),
(2478, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 4, 'OT', 'Þegar lýður heyrði þetta illa orð, syrgði hann, og enginn maður setti skart sitt á sig.'),
(2479, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 5, 'OT', 'Og Jahve sagði við Móses: Seg við Ísraels syni: Þér eruð lýður, háls yðar er stífur; ef ég færi eitt augnablik upp meðal yðar, myndi ég eyða yður. Tak nú skart þitt af þér, og ég skal vita hvað ég á að gjöra við þig.'),
(2480, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 6, 'OT', 'Og synir Ísraels tóku af sér skart sitt frá fjalli Hóreb.'),
(2481, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 7, 'OT', 'Móses tók tjald og reisti það fyrir utan herbúðir, langt frá herbúðum, og kallaði það samfundatjaldið; og hver sem leitaði Jahve fór út að samfundatjaldinu sem var fyrir utan herbúðir.'),
(2482, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 8, 'OT', 'Og svo bar við, þegar Móses gekk út í tjald, reis lýður upp og stóð hver maður í inngangi tjalds síns og horfði á eftir Mósesi, þar til hann kom inn í tjald.'),
(2483, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 9, 'OT', 'Og þegar Móses kom inn í tjald, sté súla skýs niður og stóð í inngangi tjalds, og hann talaði við Móses.'),
(2484, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 10, 'OT', 'Og lýður allur sá súlu skýs standa í inngangi tjalds, og lýður allur reis upp og laut hver maður í inngangi tjalds síns.'),
(2485, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 11, 'OT', 'Og Jahve talaði við Móses andliti til andlitis, eins og maður talar við náunga sinn. Og hann sneri aftur í herbúðir, en þjónn hans Jósúa, sonur Núns, sveinn, vék ekki úr tjaldi.'),
(2486, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 12, 'OT', 'Og Móses sagði við Jahve: Sjá, þú segir við mig: Far með þetta lýð upp; en þú hefur ekki látið mig vita hvern þú sendir með mér. Og þú sagðir: Ég þekki þig með nafni, og þú hefur fundið hylli í augum mínum.'),
(2487, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 13, 'OT', 'Og nú, ef ég hef fundið hylli í augum þínum, kunngjör mér nú veg þinn, svo að ég megi þekkja þig og finna hylli í augum þínum; og lít á að þessi þjóð er þinn lýður.'),
(2488, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 14, 'OT', 'Og hann sagði: Andlit mitt mun fara með þér, og ég mun gefa þér hvíld.'),
(2489, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 15, 'OT', 'Og hann sagði við hann: Ef andlit þitt fer ekki með okkur, lát okkur þá ekki fara héðan upp.'),
(2490, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 16, 'OT', 'Og á hverju skal það þá verða þekkt, að ég og lýður þinn höfum fundið hylli í augum þínum? Er það ekki þegar þú ferð með okkur, svo að ég og lýður þinn verðum aðgreindir frá öllum lýð sem er á andliti jarðar?'),
(2491, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 17, 'OT', 'Og Jahve sagði við Móses: Ég mun einnig gjöra þetta orð sem þú hefur talað, því að þú hefur fundið hylli í augum mínum, og ég þekki þig með nafni.'),
(2492, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 18, 'OT', 'Og hann sagði: Sýn mér dýrð þína.'),
(2493, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 19, 'OT', 'Og hann sagði: Ég mun láta öll gæði mín fara fram hjá andliti þínu og kalla fram nafn Jahve fyrir andliti þínu; og ég mun sýna náð þeim sem ég sýni náð og miskunna þeim sem ég miskunna.'),
(2494, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 20, 'OT', 'Og hann sagði: Þú getur ekki séð andlit mitt, því að enginn maður getur séð mig og lifað.'),
(2495, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 21, 'OT', 'Og Jahve sagði: Sjá, hjá mér er staður; þú skalt standa á kletti.'),
(2496, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 22, 'OT', 'Og þegar dýrð mín fer fram hjá, mun ég setja þig í skoru í kletti og byrgja lófa minn yfir þér þar til ég er farinn fram hjá.'),
(2497, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 33, 23, 'OT', 'Og ég mun taka lófa minn burt, og þú munt sjá bak mitt; en andlit mitt sést ekki.'),
(2498, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 1, 'OT', 'Og Jahve sagði við Móses: Höggva þú þér tvær töflur úr steini eins og hinar fyrri, og ég mun rita á töflum þau orð sem voru á hinum fyrri töflum sem þú braust.'),
(2499, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 2, 'OT', 'Vertu viðbúinn að morgni, og gakk upp á fjall Sínaí að morgni og bíð mín þar á höfði fjalls.'),
(2500, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 3, 'OT', 'Enginn maður skal fara upp með þér, og enginn maður skal sjást um allt fjall; hvorki sauðfé né naut skulu beita fyrir framan þetta fjall.'),
(2501, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 4, 'OT', 'Hann hjó tvær töflur úr steini eins og hinar fyrri, og Móses reis snemma að morgni og gekk upp á fjall Sínaí eins og Jahve hafði boðið honum, og tók í hendi sér tvær töflur úr steini.'),
(2502, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 5, 'OT', 'Og Jahve steig niður í skýi, stóð þar hjá honum og kallaði á nafni Jahve.'),
(2503, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 6, 'OT', 'Og Jahve gekk fram fyrir andliti hans og kallaði: Jahve, Jahve, Guð miskunnsamur og náðugur, seinn til reiði, ríkur af miskunn og sannleika.'),
(2504, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 7, 'OT', 'Hann varðveitir miskunn fyrir þúsundir, ber misgjörð, afbrot og synd, en sýknar þó ekki; hann vitjar misgjörðar feðra á sonum og á sonum sona, á þriðja ættlið og fjórðung.'),
(2505, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 8, 'OT', 'Móses flýtti sér, laut til jarðar og tilbað.'),
(2506, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 9, 'OT', 'Og hann sagði: Ef ég hef nú fundið hylli í augum þínum, Drottinn, þá gakk nú, Drottinn, meðal vor, því að þetta er lýður með stífan háls; fyrirgef þú misgjörð vora og synd vora, og tak oss til eignar.'),
(2507, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 10, 'OT', 'Og hann sagði: Sjá, ég geri sáttmála. Frammi fyrir öllum lýð þínum mun ég gjöra undur, þau sem ekki hafa verið gjörð í allri jörð né meðal þjóðum; og allur lýður sá sem þú ert á meðal mun sjá verk Jahve, því að það er ógnvekjandi sem ég gjöri við þig.'),
(2508, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 11, 'OT', 'Gæt þess sem ég býð þér í dag: Sjá, ég rek burt frá andliti þínu Amorita, Kanaanita, Hetíta, Peresíta, Hevíta og Jebúsíta.'),
(2509, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 12, 'OT', 'Gæt þín, að þú gjörir ekki sáttmála við íbúa jarðar sem þú kemur til, svo að hann verði ekki snara meðal þín.'),
(2510, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 13, 'OT', 'Heldur skuluð þér rífa niður altari þeirra, brjóta í sundur steinsúlur þeirra og höggva niður aserur þeirra.'),
(2511, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 14, 'OT', 'Þú skalt ekki sveigja þig fyrir öðrum guði; því að Jahve, nafn hans er Vandlátur, er vandlátur Guð.'),
(2512, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 15, 'OT', 'Gættu þess að þú gjörir ekki sáttmála við íbúa jarðar, því að þeir munu hórast eftir guði sína og færa guðum sínum sláturfórnir, og einhver býður þér og þú etur af sláturfórn hans.'),
(2513, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 16, 'OT', 'Þú tekur dætur hans handa sonum þínum, og dætur hans hórast eftir guði sína og lokka sonu þína til að hórast eftir guði sína.'),
(2514, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 17, 'OT', 'Þú skalt ekki gjöra þér steypt líkneski af guðum.'),
(2515, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 18, 'OT', 'Hátíð ósýrt brauð skalt þú halda; sjö daga skalt þú eta ósýrt brauð, eins og ég bauð þér, á tilsettri hátíð í mánuði Abíb, því að í mánuði Abíb fórst þú út af Egyptalandi.'),
(2516, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 19, 'OT', 'Allt frumburð af móðurlífi er mitt, og allan fénað þinn, frumburð naut og lamb, skalt þú helga.'),
(2517, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 20, 'OT', 'En frumburð asna skalt þú leysa með lambi; og ef þú leysir hann ekki, þá skalt þú brjóta háls hans. Hvern frumgetinn af sonum þínum skalt þú leysa, og enginn skal birtast fyrir andliti mínu tómhentur.'),
(2518, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 21, 'OT', 'Sex daga skalt þú vinna, en á sjöunda degi skalt þú hvílast; á plægingartíma og uppskerutíma skalt þú hvílast.'),
(2519, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 22, 'OT', 'Og hátíð vikna skalt þú halda, með frumgróða af hveiti; og hátíð uppskeru í lok árs.'),
(2520, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 23, 'OT', 'Þrisvar sinn á ári skal hvert karlkyn þitt birtast fyrir andliti Drottins Jahve, Guðs Ísraels.'),
(2521, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 24, 'OT', 'Því að ég mun reka þjóðir burt frá þér og víkka landamæri þín, og enginn maður skal girnast jörð þína þegar þú ferð upp til að birtast frammi fyrir andliti Jahve Guðs þíns þrisvar sinn á ári.'),
(2522, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 25, 'OT', 'Þú skalt ekki fórna blóði sláturfórnar minnar með súrdeigi, og sláturfórn hátíðar páska skal ekki liggja til morguns.'),
(2523, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 26, 'OT', 'Upphaf frumgróða jarðar þinnar skalt þú flytja í húsi Jahve Guðs þíns. Þú skalt ekki sjóða kið í mjólk móður sinnar.'),
(2524, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 27, 'OT', 'Og Jahve sagði við Móses: Skrifa þú þessi orð, því að eftir þessum orðum hef ég gjört sáttmála við þig og Ísrael.'),
(2525, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 28, 'OT', 'Og hann var þar hjá Jahve í fjörutíu daga og fjörutíu nætur; hann át ekki brauð og drakk ekki vatn. Og hann skrifaði á töflur orð sáttmála, tíu orð.'),
(2526, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 29, 'OT', 'Og svo bar við, þegar Móses steig niður af Sínaí fjalli með tvær töflur vitnisburðar í hendi sér, vissi Móses ekki að skinn andlits hans geislaði af því að hann hafði talað við hann.'),
(2527, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 30, 'OT', 'Og Aron og allir synir Ísraels sáu Móses, og sjá, skinn á andliti hans geislaði, og þeir óttuðust að nálgast hann.'),
(2528, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 31, 'OT', 'Móses kallaði á þá, og Aron og höfðingjar í söfnuði sneru aftur til hans, og Móses talaði við þá.'),
(2529, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 32, 'OT', 'Og eftir það komu synir Ísraels nær, og hann bauð þeim allt sem Jahve hafði talað við hann á fjalli Sínaí.'),
(2530, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 33, 'OT', 'Og þegar Móses hafði lokið við að tala við þá, lagði hann hulu á andlit sitt.'),
(2531, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 34, 'OT', 'En þegar Móses gekk fyrir andliti Jahve til að tala við hann, tók hann af sér hulu þar til hann kom út; og hann gekk út og talaði við Ísraels sonu það sem honum var boðið.'),
(2532, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 34, 35, 'OT', 'Og synir Ísraels sáu andlit Mósesar, að skinn andlits Mósesar geislaði; og Móses setti hulu aftur á andlit sitt þar til hann kom aftur til að tala við hann.'),
(2533, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 1, 'OT', 'Og Móses kallaði saman allan söfnuð Ísraels sona og sagði við þá: Þetta eru þau orð sem Jahve bauð að gjöra.'),
(2534, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 2, 'OT', 'Sex daga skal vinna starf, en á sjöunda degi skal vera yður hvíldardagur, af helgi, hvíld Jahve; hver sem vinnur starf á honum skal líflátinn verða.'),
(2535, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 3, 'OT', 'Þér skuluð ekki kveikja eld í neinum bústöðum yðar á hvíldardegi.'),
(2536, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 4, 'OT', 'Og Móses sagði við allan söfnuð Ísraels sona: Þetta er orð sem Jahve bauð og sagði:'),
(2537, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 5, 'OT', 'Takið af yður framlag handa Jahve; hver sem hefur fúst hjarta, komi með framlag Jahve: gull, silfur og eir.'),
(2538, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 6, 'OT', 'Bláma, purpura, skarlat, lín og geitur.'),
(2539, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 7, 'OT', 'Rauð skinn hrúta, skinn sela og akasíutré.'),
(2540, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 8, 'OT', 'Olíu fyrir ljós, ilmjurtir til smurningu og til reykelsis.'),
(2541, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 9, 'OT', 'Ónyx steinar og steinar til vígslu fyrir hökul og brjóstskjöld.'),
(2542, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 10, 'OT', 'Og hver sá meðal yðar sem er hagur í hjarta skal koma og gjöra allt sem Jahve hefur boðið.'),
(2543, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 11, 'OT', 'Bústað, tjald hennar og hlíf hennar, spangir hennar, borð hennar, slár hennar, súlur hennar og undirstöður hennar.'),
(2544, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 12, 'OT', 'Örk og slár hennar, náðarstól og fortjald fyrir tjaldi.'),
(2545, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 13, 'OT', 'Borð og slár þess og öll áhöld þess og brauð andlita.'),
(2546, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 14, 'OT', 'Ljósastiku og áhöld hennar og lampa hennar og olíu fyrir ljósi.'),
(2547, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 15, 'OT', 'Altari reykelsis og slár þess, smurningu og olíu, reykelsi af ilmjurtum, og tjald fyrir inngangi bústaðar.'),
(2548, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 16, 'OT', 'Altari brennifórnar og grind úr eir sem þar er, slár þess og öll áhöld þess, þvottaker og stall þess.'),
(2549, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 17, 'OT', 'Slöngvur forgarðs, súlur þeirra og undirstöður þeirra, og tjald fyrir hliði forgarðs.'),
(2550, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 18, 'OT', 'Hælar bústaðar, hælar forgarðs og strengir þeirra.'),
(2551, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 19, 'OT', 'Hin ofnu klæði til þjónustu í helgidóminum, hin heilögu klæði Arons prests og klæði sona hans til prestsþjónustu.'),
(2552, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 20, 'OT', 'Og allur söfnuður sona Ísraels gekk út frá andliti Mósesi.'),
(2553, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 21, 'OT', 'Og allir menn, hver sem hjarta hans hvatti, og allir þeir sem andi hans hreyfði, komu og færðu framlag Jahve til starfsins við samfundatjaldið, til allrar þjónustu þess og til hinna heilögu klæða.'),
(2554, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 22, 'OT', 'Menn komu ásamt konum, og allir sem voru fúsir í hjarta færðu króka, eyrnalokka, hringi og skartgripi, öll áhöld úr gulli; og sérhver maður sem færði veifufórn fyrir Jahve.'),
(2555, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 23, 'OT', 'Og sérhver maður sem átti bláma, purpura, skarlat, fínan hör, geitahár, rauðlituð skinn hrúta og selskinn kom með það.'),
(2556, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 24, 'OT', 'Hver sem bar fram framlag úr silfri og eir, færði framlag Jahve; og hver sem átti akasíutré, færði það til alls starfsins í þjónustunni.'),
(2557, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 25, 'OT', 'Og sérhver kona sem hafði hjarta hugvits spann með höndum sínum; þær færðu spunnið garn, bláma, purpura, skarlat og fínan hör.'),
(2558, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 26, 'OT', 'Og allar konur sem hjarta þeirra hvatti spunnu í speki geitahár.'),
(2559, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 27, 'OT', 'Höfðingjarnir færðu ónyxsteina og aðra steina til vígslu, fyrir hökulinn og brjóstskjöldinn.'),
(2560, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 28, 'OT', 'Og ilmjurtir og olíu fyrir ljósið og smurningarolíuna og reykelsi úr ilmjurtum.'),
(2561, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 29, 'OT', 'Sérhver maður og kona sem hjarta þeirra fýsti að færa til hvers starfs sem Jahve hafði boðið með hendi Mósesar, færðu synir Ísraels sjálfviljafórn fyrir Jahve.'),
(2562, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 30, 'OT', 'Og Móses sagði við sonu Ísraels: Sjáið, Jahve hefur kallað með nafni Besalel son Úrí, son Húrs, af ættkvísl Júda.'),
(2563, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 31, 'OT', 'Og anda Guðs fyllti hann, með speki, skilningi, þekkingu og í öllu starfi.'),
(2564, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 32, 'OT', 'Og til að semja ráðagerðir, til að vinna í gulli, silfri og eir.'),
(2565, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 33, 'OT', 'Og til útskurðar á steinum til að setja þá í, og til útskurðar á tré, í öllu hugvitsstarfi ráðagerðar.'),
(2566, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 34, 'OT', 'Hann lagði í hjarta sitt að kenna, bæði hann og Oholíab, sonur Akísamaks, af ættkvísl Dan.'),
(2567, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 35, 35, 'OT', 'Hann fyllti þá speki í hjarta til að vinna allt starf smiða og hönnuða, og vefara í bláma, purpura, skarlati og fínum hör, sem vinna allt verk og hanna ráðagerðir.'),
(2568, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 1, 'OT', 'Og Besalel og Oholíab, og sérhver hugvitssamur maður sem Jahve hafði gefið speki og skilning í hjarta, til að kunna að vinna allt starf í helgidómsþjónustu, eftir öllu sem Jahve hafði boðið.'),
(2569, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 2, 'OT', 'Og Móses kallaði á Besalel og Oholíab og á alla hugvitssama menn í hjarta, sem Jahve hafði gefið speki, og alla þá sem hjarta þeirra hvatti til að ganga að starfinu og vinna það.'),
(2570, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 3, 'OT', 'Og þeir tóku við öllu framlaginu frá andliti Mósesi sem synir Ísraels höfðu fært til að vinna starfið í þjónustu helgidómsins. Og þeir færðu honum enn sjálfviljafórnir á hverjum morgni.'),
(2571, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 4, 'OT', 'Og allir hugvitsmenn sem unnu allt starfið í helgidóminum komu, sérhver maður frá starfi sínu sem þeir unnu.'),
(2572, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 5, 'OT', 'Og þeir sögðu við Móses: Lýður færir meira en nóg til starfsins í þjónustu, sem Jahve bauð að gera.'),
(2573, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 6, 'OT', 'Og Móses bauð, og lét rödd ganga um herbúðirnar: Enginn maður og engin kona skal framar gera starf til framlags helgidómsins. Og lýður var hindraður frá að færa.'),
(2574, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 7, 'OT', 'Og starfið var nægð fyrir allt til að gera það, og afgangur varð.'),
(2575, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 8, 'OT', 'Og allir hugvitsmenn í hjarta meðal þeirra sem unnu starfinu gerðu bústaðinn: tíu tjöld úr fínum hör, bláma, purpura og skarlati, með kerúbum, verk hönnuðar.'),
(2576, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 9, 'OT', 'Lengd hvers tjalds var tuttugu og átta álnir, og breidd fjórar álnir; sama mál var fyrir öll tjöldin.'),
(2577, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 10, 'OT', 'Og hann tengdi saman fimm tjöldin, eitt við annað, og fimm önnur tjöld tengdi hann saman, eitt við annað.'),
(2578, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 11, 'OT', 'Og hann gerði lykkjur úr bláma á vör eins tjaldsins, á rönd við enda samskeytisins; og eins gerði hann á vör hins tjaldsins sem var við seinna samskeyti.'),
(2579, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 12, 'OT', 'Fimmtíu lykkjur gerði hann á einu tjaldinu og fimmtíu lykkjur gerði hann á enda hins tjaldsins sem var í seinna samskeyti; lykkjurnar stóðu hver á móti annarri.'),
(2580, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 13, 'OT', 'Og hann gerði fimmtíu spangir úr gulli og tengdi tjöldin saman, eitt við annað, með spöngunum, og bústaðurinn varð einn.'),
(2581, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 14, 'OT', 'Og hann gerði tjöld úr geitahári sem tjald yfir bústaðinn; ellefu tjöld gerði hann alls.'),
(2582, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 15, 'OT', 'Lengd hvers tjalds var þrjátíu álnir, og fjórar álnir breidd hvers tjalds; eins mál var fyrir öll ellefu tjöldin.'),
(2583, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 16, 'OT', 'Og hann tengdi fimm tjöld út af fyrir sig og sex tjöld út af fyrir sig.'),
(2584, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 17, 'OT', 'Og hann gerði fimmtíu lykkjur á vör tjaldsins í fremra samskeyti, og fimmtíu lykkjur á vör hins tjaldsins í seinna samskeyti.'),
(2585, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 18, 'OT', 'Og hann gerði fimmtíu spangir úr eiri til að tengja tjaldbúðina saman, svo hún yrði ein heild.'),
(2586, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 19, 'OT', 'Og hann gerði hlíf á tjaldbúðina úr rauðlituðum skinnum hrúta, og aðra hlíf úr skinnum seli yfir það að ofan.'),
(2587, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 20, 'OT', 'Og hann gerði borðin fyrir bústaðinn úr akasíutré, uppréttandi.'),
(2588, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 21, 'OT', 'Lengd hvers borðs var tíu álnir, og breidd hvers borðs var ein alin og helmingur.'),
(2589, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 22, 'OT', 'Á hverju borði voru tvær hendur, tengdar hver við aðra; eins gerði hann við öll borðin í bústaðnum.'),
(2590, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 23, 'OT', 'Og hann gerði tuttugu borð fyrir bústaðinn að suðurhorninu, í suðurlandi.'),
(2591, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 24, 'OT', 'Og fjörutíu silfurundirstöður gerði hann undir tuttugu borðin: tvær undirstöður undir hvert borð fyrir báðar hendurnar og tvær undirstöður undir hvert borð fyrir báðar hendurnar.'),
(2592, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 25, 'OT', 'Og fyrir hitt rifið á bústaðnum, að norðurhorninu, gerði hann tuttugu borð.'),
(2593, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 26, 'OT', 'Og fjörutíu silfurundirstöður: tvær undirstöður undir hvert borð og tvær undirstöður undir hvert borð.'),
(2594, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 27, 'OT', 'Og í lendum bústaðarins til hafs gerði hann sex borð.'),
(2595, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 28, 'OT', 'Og tvö borð gerði hann fyrir hornin á bústaðnum í lendum hans.'),
(2596, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 29, 'OT', 'Þau voru tvíburar neðst og jöfn efst, á höfði sér, við einn hring; eins gerði hann báðum hornunum.'),
(2597, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 30, 'OT', 'Og borðin voru átta, og silfurundirstöðurnar sextán: tvær undirstöður undir hvert borð fyrir báðar hendurnar.'),
(2598, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 31, 'OT', 'Og hann gerði slár úr akasíutré, fimm fyrir borðin á öðru rifi bústaðarins.'),
(2599, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 32, 'OT', 'Og fimm slár fyrir borðin á hinu rifinu bústaðarins, og fimm slár fyrir borðin í lendum bústaðarins til hafs.'),
(2600, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 33, 'OT', 'Og hann gerði miðslána til að renna í miðju borðanna frá enda til enda.'),
(2601, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 34, 'OT', 'Og hann klæddi borð gulli, og gerði hringi úr gulli sem hús fyrir slár, og klæddi slár gulli.'),
(2602, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 35, 'OT', 'Og hann gerði fortjald úr bláma, purpura, skarlati og fínum hör, með kerúbum, verk hönnuðar.'),
(2603, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 36, 'OT', 'Og hann gerði fjórar súlur úr akasíutré, klæddi þær gulli, og krókar þeirra úr gulli; og hann steypti fyrir þær fjórar undirstöður úr silfri.'),
(2604, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 37, 'OT', 'Og hann gerði tjald fyrir inngang tjaldsins, úr bláma, purpura, skarlati og fínum hör, verk hönnuðar.'),
(2605, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 36, 38, 'OT', 'Og fimm súlur þeirra og krókar þeirra; höfuð þeirra og lykkjur þeirra klæddi hann gulli, og undirstöður þeirra fimm úr eiri.'),
(2606, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 1, 'OT', 'Og Besalel gerði örk úr akasíutré: tvær álnir og helmingur var lengd hennar, ein alin og helmingur breidd hennar, og ein alin og helmingur vöxtur hennar.'),
(2607, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 2, 'OT', 'Og hann klæddi hana gulli, hreinu gulli, innan og utan, og gerði kórónu úr gulli allt í kring.'),
(2608, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 3, 'OT', 'Og hann steypti fjóra hringi úr gulli og setti þá við fjóra fætur hennar; tveir hringir á öðru rifi og tveir hringir á hinu rifi.'),
(2609, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 4, 'OT', 'Og hann gerði stangir úr akasíutré og klæddi þær gulli.'),
(2610, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 5, 'OT', 'Og hann setti stangirnar í hringjum við rif arkarinnar til að bera örk.'),
(2611, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 6, 'OT', 'Og hann gerði náðarstól úr skíru gulli: tvær álnir og helmingur var lengd hennar, og alin og helmingur var breidd hennar.'),
(2612, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 7, 'OT', 'Og hann gerði tvo kerúba úr gulli; úr hamruðu verki gerði hann þá á báðum röndum náðarstóls.'),
(2613, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 8, 'OT', 'Eitt kerúb var á annarri rönd og annað kerúb á hinni rönd; úr náðarstóls gerði hann kerúba við báða enda hans.'),
(2614, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 9, 'OT', 'Kerúbar breiddu út vængi sína upp á við, skýldu náðarstólnum með vængjum sínum, og andlit þeirra sneru hvert að öðru, hver til síns bróður; andlit kerúbanna sneru að náðarstólnum.'),
(2615, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 10, 'OT', 'Og hann gerði borð úr akasíutré: lengd þess var tvær álnir, breidd þess ein alin, og vöxtur þess ein alin og helmingur.'),
(2616, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 11, 'OT', 'Og hann klæddi það gulli, hreinu gulli, og gerði kórónu úr gulli allt í kring.'),
(2617, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 12, 'OT', 'Og hann gerði umgjörð fyrir það, handarbreidd, allt í kring, og gerði kórónu úr gulli fyrir umgjörð þess allt í kring.'),
(2618, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 13, 'OT', 'Og hann steypti fjóra hringi úr gulli og setti hringi á fjögur horn sem voru við fætur hans.'),
(2619, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 14, 'OT', 'Hringir voru við umgjörð, sem hús fyrir stangirnar til að bera borð.'),
(2620, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 15, 'OT', 'Og hann gerði stangir úr akasíutré og klæddi þær gulli, til að bera borð.'),
(2621, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 16, 'OT', 'Og hann gerði áhöldin sem voru á borði: skálar þess, lófa þess, skálar þess og bikara þess, sem skyldi hella úr; úr skíru gulli.'),
(2622, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 17, 'OT', 'Og hann gerði ljósastiku úr skíru gulli; úr hamruðu verki gerði hann hana, læri hennar og reyr; bikara hennar, súluhöfuð hennar og blóm voru af sama efni.'),
(2623, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 18, 'OT', 'Og sex reyrar gengu út úr hliðum hennar, þrír reyrar ljósastiku úr annarri hlið og þrír reyrar úr hinni hlið.'),
(2624, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 19, 'OT', 'Þrír bikarar voru á hverri grein, eins og möndlublóm, með súluhöfði og blómi, og þrír bikarar á annarri grein, eins og möndlublóm, með súluhöfði og blómi; svo var um sex reyra sem gengu út úr ljósastiku.'),
(2625, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 20, 'OT', 'Og á ljósastiku voru fjórir bikarar, eins og möndlublóm, með súluhöfðum sínum og blómum.'),
(2626, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 21, 'OT', 'Og súluhöfuð var undir tveimur reyrum úr henni, og súluhöfuð undir tveimur reyrum, og súluhöfuð undir tveimur reyrum; fyrir sex reyra sem gengu út úr henni.'),
(2627, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 22, 'OT', 'Súluhöfuð þeirra og reyrar voru úr henni; allt var það eitt verk úr hreinu gulli.'),
(2628, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 23, 'OT', 'Og hann gerði sjö lampa, og töng þeirra og eldpönnur úr skíru gulli.'),
(2629, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 24, 'OT', 'Hann gerði hana úr einni talentu af hreinu gulli, og öll áhöld hennar.'),
(2630, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 25, 'OT', 'Og hann gerði altari fyrir reykelsi úr akasíutré: lengd þess ein alin, breidd þess ein alin, ferkantað, og vöxtur þess tvær álnir; horn þess voru af því.'),
(2631, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 26, 'OT', 'Og hann klæddi það gulli, hreinu gulli: þak þess, veggi þess allt í kring og horn þess; og hann gerði kórónu úr gulli allt í kring.'),
(2632, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 27, 'OT', 'Og hann gerði tvo hringi úr gulli undir kórónu, á öðru rifi, og tvo hringi á hinu rifi, á báðum hliðum þess, til að vera hús fyrir stangirnar.'),
(2633, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 28, 'OT', 'Og hann gerði stangir úr akasíutré og klæddi þær gulli.'),
(2634, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 37, 29, 'OT', 'Og hann gerði heilaga olíu til smurningu og hreint reykelsi úr ilmjurtum, verk ilmgerðarmanns.'),
(2635, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 1, 'OT', 'Og hann gerði altari brennifórnar úr akasíutré: lengd þess fimm álnir, breidd þess fimm álnir, ferkantað, og vöxtur þess þrjár álnir.'),
(2636, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 2, 'OT', 'Og hann gerði horn á fjórum hornsúlum þess; horn þess voru af því, og hann klæddi það eiri.'),
(2637, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 3, 'OT', 'Og hann gerði öll áhöld fyrir altari: pottar, skóflur, skálar, kjötkrókar og eldpönnur; öll áhöld þess gerði hann úr eiri.'),
(2638, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 4, 'OT', 'Og hann gerði grind fyrir altari, verk úr neti úr eiri, undir snúningi þess neðan frá, upp að helmingi.'),
(2639, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 5, 'OT', 'Og hann steypti fjóra hringi á fjóra enda grindar úr eiri, sem hús fyrir stangirnar.'),
(2640, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 6, 'OT', 'Og hann gerði stangir úr akasíutré og klæddi þær eiri.'),
(2641, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 7, 'OT', 'Og hann setti stangirnar í hringjum á rifum altarisins til að bera það; hann gerði það holt, úr töflum.'),
(2642, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 8, 'OT', 'Og hann gerði þvottaker úr eiri, og stall þess úr eiri, úr sjónum kvennanna sem þjónuðu við inngang samfundatjaldsins.'),
(2643, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 9, 'OT', 'Og hann gerði forgarð; í suðurlandi voru slöngvur úr fínu hör, hundrað álnir.'),
(2644, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 10, 'OT', 'Súlur þeirra voru tuttugu, og undirstöður þeirra tuttugu úr eiri; krókar og lykkjur úr silfri.'),
(2645, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 11, 'OT', 'Og fyrir norðurhliðina: hundrað álnir, súlur tuttugu og undirstöður tuttugu úr eiri; krókar og lykkjur úr silfri.'),
(2646, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 12, 'OT', 'Og að hafi: slöngvur, fimmtíu álnir, tíu súlur og tíu undirstöður; krókar og lykkjur úr silfri.'),
(2647, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 13, 'OT', 'Og fyrir austurhornið, til sólarupprásar, fimmtíu álnir.'),
(2648, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 14, 'OT', 'Slöngvur voru fimmtán álnir við öxl, súlur þeirra þrjár og undirstöður þeirra þrjár.'),
(2649, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 15, 'OT', 'Og hinum megin við öxl, báðum megin við hlið forgarðs: slöngvur fimmtán álnir, súlur þeirra þrjár og undirstöður þeirra þrjár.'),
(2650, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 16, 'OT', 'Allar slöngvur forgarðs voru umhverfis úr fínu hör.'),
(2651, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 17, 'OT', 'Undirstöður fyrir súlur voru úr eiri; krókar og lykkjur úr silfri, og klæðning á höfuð þeirra úr silfri; allar súlur forgarðs voru bundnar silfri.'),
(2652, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 18, 'OT', 'Tjald fyrir hlið forgarðs var verk úr bláma, purpura, skarlati og fínum hör, saumað; lengd þess tuttugu álnir, vöxtur þess fimm álnir og breidd þess fimm álnir, eins og slöngvur forgarðs.'),
(2653, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 19, 'OT', 'Súlur þeirra voru fjórar, og undirstöður þeirra fjórar úr eiri; krókar þeirra úr silfri, og klæðning á höfuð þeirra og lykkjur þeirra úr silfri.'),
(2654, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 20, 'OT', 'Allir hælar bústaðar og forgarðs allt í kring voru úr eiri.'),
(2655, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 21, 'OT', 'Þetta eru reikningar bústaðar og vitnisburðar, eftir munni Mósesar; þjónusta Levíta undir hendi Ítamars, sonar Arons prests.'),
(2656, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 22, 'OT', 'Og Besalel, sonur Úrí, sonur Húrs, af ættkvísl Júda, gerði allt sem Jahve bauð Mósesi.'),
(2657, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 23, 'OT', 'Og með honum var Oholíab, sonur Akísamaks, af ættkvísl Dan, smiður og hönnuður og útsaumari í bláma, purpura, skarlati og fínum hör.'),
(2658, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 24, 'OT', 'Allt gull sem notað var til verksins, gull veifufórnar, var níu og tuttugu talentur og sjö hundruð og þrjátíu siklar, eftir sikli helgi.'),
(2659, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 25, 'OT', 'Silfur þeirra sem taldir voru af söfnuðinum var hundrað talentur og þúsund sjö hundruð sjötíu og fimm siklar, eftir helgisikli.'),
(2660, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 26, 'OT', 'Bekah á mann, það er helmingur sikils eftir helgisikli, á höfuðkúpu fyrir alla sem skráðir voru af sonum tuttugu ára og eldri: sex hundruð þúsund og þrjú þúsund og fimm hundruð og fimmtíu.'),
(2661, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 27, 'OT', 'Hundrað talentur af silfri voru notaðar til að steypa undirstöður helgidómsins og undirstöður fortjalds: hundrað undirstöður úr hundrað talentum, ein talenta fyrir hverja undirstöðu.'),
(2662, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 28, 'OT', 'Og af þúsund sjö hundruð og fimm og sjötíu siklum gerði hann króka fyrir súlur, og klæddi höfuð þeirra og gerði þá að lykkjum.'),
(2663, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 29, 'OT', 'Eir veifufórnar var sjötíu talentur og tvö þúsund og fjögur hundruð siklar.'),
(2664, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 30, 'OT', 'Og hann gerði undirstöður fyrir inngang samfundatjaldsins, og altari úr eiri, og grind úr eiri, sem hann átti, og öll áhöld fyrir altari.'),
(2665, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 38, 31, 'OT', 'Og undirstöður forgarðs allt í kring og undirstöður hlið forgarðs, og allir hælar bústaðar og allir hælar forgarðs allt í kring.'),
(2666, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 1, 'OT', 'Úr bláma, purpura og skarlati gerðu þeir klæði til þjónustu í helgidóminum, og þeir gerðu heilög klæði Arons, eins og Jahve bauð Mósesi.'),
(2667, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 2, 'OT', 'Hann gerði hökul úr gulli, bláma, purpura, skarlati og fínum hör.'),
(2668, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 3, 'OT', 'Og þeir sléttuðu plötur úr gulli og skáru í bönd til að vefa í bláma, purpura, skarlati og fínum hör, verk hönnuðar.'),
(2669, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 4, 'OT', 'Þeir gerðu axlir á hökul, tengdar saman við enda hans, á báðum röndum.'),
(2670, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 5, 'OT', 'Og listilega ofna belti hökuls, sem var á honum, var úr sama verki: gull, bláma, purpura, skarlat og fínn hör, eins og Jahve bauð Mósesi.'),
(2671, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 6, 'OT', 'Og þeir gerðu ónyx steina, innrammaða í umgjörð úr gulli, með útskurð innsigla, eftir nöfnum sona Ísraels.'),
(2672, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 7, 'OT', 'Og hann setti þá á axlir hökuls sem steina til minningar fyrir sonum Ísraels, eins og Jahve bauð Mósesi.'),
(2673, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 8, 'OT', 'Og hann gerði brjóstskjöld, verk hönnuðar, eins og verk hökuls, úr gulli, bláma, purpura, skarlati og fínum hör.'),
(2674, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 9, 'OT', 'Hann var ferhyrndur; þeir gerðu brjóstskjöld tvöfaldan; spönn var lengd hans og spönn breidd hans.'),
(2675, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 10, 'OT', 'Og þeir settu í hann fjórar raðir steina: fyrsta röð var rúbín, tópas og karbunkúl.'),
(2676, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 11, 'OT', 'Önnur röð var smaragð, safír og demantur.'),
(2677, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 12, 'OT', 'Þriðja röð var ligúr, agat og ametýst.'),
(2678, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 13, 'OT', 'Fjórða röð var tarsisteinn, ónyx og jaspis, greypt í greyptri umgjörð úr gulli.'),
(2679, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 14, 'OT', 'Steinar voru tólf, eftir nöfnum sona Ísraels; útskurð innsigla, hver maður eftir nafni sínu, fyrir tólf ættkvíslir.'),
(2680, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 15, 'OT', 'Og þeir gerðu á brjóstskjöld keðjur, fléttaðar eins og reipi, verk úr hreinu gulli.'),
(2681, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 16, 'OT', 'Og þeir gerðu tvær umgjarðir úr gulli og tvo hringi úr gulli, og settu hringi á tvær randir á brjóstskjöld.'),
(2682, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 17, 'OT', 'Og þeir settu tvö reipi úr gulli á hringi tvo, á randir á brjóstskjöld.'),
(2683, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 18, 'OT', 'Og enda reipanna tveggja settu þeir á umgjörð tvær, og lögðu þær á axlir hökuls fyrir framan andliti þess.'),
(2684, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 19, 'OT', 'Og þeir gerðu tvo hringi úr gulli og settu þá á rönd brjóstskjaldarins, á vör hans, sem snýr að hökli, að húsi.'),
(2685, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 20, 'OT', 'Og þeir gerðu tvo hringi úr gulli og settu þá á axlir hökuls neðan frá, fyrir framan andliti þess, við samskeyti þess ofan við hökli.'),
(2686, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 21, 'OT', 'Og þeir bundu brjóstskjöld með hringjum sínum við hringi hökuls með bandi úr bláma, til að vera ofan á belti hökuls, og brjóstskjöldur skyldi ekki losna frá hökli, eins og Jahve bauð Mósesi.'),
(2687, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 22, 'OT', 'Og hann gerði yfirhöfn hökuls, verk vefara, alla úr bláma.'),
(2688, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 23, 'OT', 'Og það var munn á yfirhöfn, eins og munn á brynju, með vör umhverfis munn, svo hann mætti ekki rifna.'),
(2689, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 24, 'OT', 'Og á fald yfirhafnar gerðu þeir granatepli úr bláma, purpura og skarlat, og fínum hör.'),
(2690, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 25, 'OT', 'Og þeir gerðu bjöllur úr hreinu gulli og settu bjöllur á milli granatepli á fald yfirhafnar allt í kring.'),
(2691, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 26, 'OT', 'Bjalla og granatepli, bjalla og granatepli, á fald yfirhafnar allt í kring, til að þjóna, eins og Jahve bauð Mósesi.'),
(2692, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 27, 'OT', 'Og þeir gerðu kyrtla úr fínum hör, verk vefara, fyrir Aron og sonu hans.'),
(2693, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 28, 'OT', 'Og vefjarhött úr fínum hör, höfuðskart úr hör og nærbuxur úr hör.'),
(2694, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 29, 'OT', 'Og belti úr fínum hör, bláma, purpura og skarlat, verk hönnuðar, eins og Jahve bauð Mósesi.'),
(2695, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 30, 'OT', 'Og þeir gerðu blóm, heilagt nasír, úr hreinu gulli, og rituðu á það rit útskurðar innsiglis: helgi fyrir Jahve.'),
(2696, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 31, 'OT', 'Og þeir settu á það band úr bláma til að festa það á vefjarhött að ofan, eins og Jahve bauð Mósesi.'),
(2697, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 32, 'OT', 'Öll þjónusta bústaðar og samfundatjaldið var fullgerð; og synir Ísraels gerðu allt eins og Jahve bauð Mósesi, svo gerðu þeir.'),
(2698, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 33, 'OT', 'Og þeir færðu bústað til Mósesar, tjald, öll áhöld þess, spangir, borð, slár, súlur og undirstöður.'),
(2699, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 34, 'OT', 'Og hlíf úr rauðlituðum skinnum hrúta, og hlíf úr skinnum seli, og fortjald tjalds.'),
(2700, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 35, 'OT', 'Örk vitnisburðar með stöngum sínum og náðarstól.'),
(2701, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 36, 'OT', 'Borðið og öll áhöld þess og brauð andlitanna.'),
(2702, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 37, 'OT', 'Ljósastikuna hreinu, lampa hennar, lampana í fylkingu sinni, öll áhöld hennar og olíuna fyrir ljósið.'),
(2703, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 38, 'OT', 'Altarið úr gulli, olíuna til smurningarinnar, reykelsið úr ilmjurtum og tjaldið fyrir inngangi tjaldsins.'),
(2704, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 39, 'OT', 'Altarið úr eiri og eirgrindina sem því tilheyrir, öll áhöld þess, þvottakerið og stallinn undir því.'),
(2705, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 40, 'OT', 'Tjaldhengin í forgarðinum, súlur þess og undirstöður þeirra, og tjaldið fyrir hliði forgarðsins, strengi þess og hæla, og öll áhöld þjónustu bústaðarins fyrir samfundatjaldið.'),
(2706, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 41, 'OT', 'Klæði þjónustunnar til að þjóna í helgidóminum, hin heilögu klæði handa Aroni presti og klæði sona hans til að gegna prestsembætti.'),
(2707, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 42, 'OT', 'Eins og Jahve hafði boðið Mósesi, svo gerðu synir Ísraels alla þjónustuna.'),
(2708, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 39, 43, 'OT', 'Móses sá allt starfið, og sjá, þeir höfðu gert það eins og Jahve hafði boðið. Og Móses blessaði þá.'),
(2709, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 1, 'OT', 'Jahve talaði við Móses og mælti:'),
(2710, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 2, 'OT', 'Á fyrsta degi fyrsta mánaðarins skalt þú reisa bústað samfundatjaldsins.'),
(2711, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 3, 'OT', 'Þar skalt þú setja örk vitnisburðarins og hengja fortjaldið upp yfir örkinni.'),
(2712, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 4, 'OT', 'Þú skalt bera inn borðið og raða á það, og bera inn ljósastikuna og kveikja lampana.'),
(2713, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 5, 'OT', 'Þú skalt setja altarið úr gulli fyrir reykelsi fyrir framan örk vitnisburðarins, og hengja tjaldið fyrir inngangi bústaðarins.'),
(2714, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 6, 'OT', 'Altari brennifórnarinnar skalt þú setja fyrir framan inngang bústaðar samfundatjaldsins.'),
(2715, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 7, 'OT', 'Þvottakerið skalt þú setja milli samfundatjaldsins og altarisins og láta vatn í það.'),
(2716, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 8, 'OT', 'Þú skalt reisa forgarðinn umhverfis og hengja tjald fyrir hlið forgarðsins.'),
(2717, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 9, 'OT', 'Þú skalt taka smurningarolíuna og smyrja bústaðinn og allt sem í honum er, og helga hann og öll áhöld hans, og hann skal vera helgur.'),
(2718, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 10, 'OT', 'Þú skalt smyrja brennifórnaraltarið og öll áhöld þess og helga altarið, og altarið skal vera háheilagt.'),
(2719, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 11, 'OT', 'Þú skalt smyrja þvottakerið og stallinn undir því og helga það.'),
(2720, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 12, 'OT', 'Þú skalt leiða Aron og syni hans að inngangi samfundatjaldsins og þvo þá með vatni.'),
(2721, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 13, 'OT', 'Þú skalt klæða Aron í hin heilögu klæði og smyrja hann og helga hann, og hann skal gegna prestsembætti fyrir mig.'),
(2722, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 14, 'OT', 'Sonu hans skalt þú leiða fram og klæða þá í kyrtla.'),
(2723, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 15, 'OT', 'Þú skalt smyrja þá eins og þú smurðir föður þeirra, og þeir skulu gegna mér sem prestar, og smurning þeirra skal vera þeim prestsembætti um eilífð um allar kynslóðir þeirra.'),
(2724, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 16, 'OT', 'Móses gerði allt eins og Jahve hafði boðið honum, svo gerði hann.'),
(2725, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 17, 'OT', 'Í fyrsta mánuði á öðru ári, á fyrsta degi mánaðarins, var bústaðurinn reistur.'),
(2726, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 18, 'OT', 'Móses reisti bústaðinn, lagði undirstöður hans, setti borðin hans og slárnar og reisti súlurnar hans.'),
(2727, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 19, 'OT', 'Hann breiddi tjaldið yfir bústaðinn og lagði hlíf tjaldsins yfir hann að ofan, eins og Jahve hafði boðið Mósesi.'),
(2728, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 20, 'OT', 'Hann tók vitnisburðinn og lagði hann í örkina, setti stangirnar á örkina og setti náðarstólinn yfir örkina að ofan.'),
(2729, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 21, 'OT', 'Hann bar örkina inn í bústaðinn og hengdi upp fortjaldið og tjaldið fyrir örk vitnisburðarins, eins og Jahve hafði boðið Mósesi.'),
(2730, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 22, 'OT', 'Hann setti borðið í samfundatjaldinu, við norðurlæri bústaðarins, utan við fortjaldið.'),
(2731, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 23, 'OT', 'Hann raðaði brauði á það fyrir Jahve, eins og Jahve hafði boðið Mósesi.'),
(2732, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 24, 'OT', 'Hann setti ljósastikuna í samfundatjaldinu, gegnt borðinu, við suðurlæri bústaðarins.'),
(2733, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 25, 'OT', 'Hann kveikti lampana fyrir Jahve, eins og Jahve hafði boðið Mósesi.'),
(2734, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 26, 'OT', 'Hann setti gullaltarið í samfundatjaldinu fyrir framan fortjaldið.'),
(2735, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 27, 'OT', 'Hann brenndi á því reykelsi úr ilmjurtum, eins og Jahve hafði boðið Mósesi.'),
(2736, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 28, 'OT', 'Hann hengdi tjaldið fyrir inngang bústaðarins.'),
(2737, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 29, 'OT', 'Hann setti brennifórnaraltarið við inngang bústaðar samfundatjaldsins og fórnaði á því brennifórninni og matfórninni, eins og Jahve hafði boðið Mósesi.'),
(2738, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 30, 'OT', 'Hann setti þvottakerið milli samfundatjaldsins og altarisins og lét vatn í það til þvottar.'),
(2739, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 31, 'OT', 'Móses og Aron og synir hans þvoðu úr því hendur sínar og fætur.'),
(2740, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 32, 'OT', 'Þegar þeir gengu inn í samfundatjaldið og nálguðust altarið, þvoðu þeir sig, eins og Jahve hafði boðið Mósesi.'),
(2741, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 33, 'OT', 'Hann reisti forgarðinn umhverfis bústaðinn og altarið og hengdi tjaldið fyrir hlið forgarðsins. Þannig lauk Móses starfinu.'),
(2742, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 34, 'OT', 'Skýið huldi samfundatjaldið, og dýrð Jahve fyllti bústaðinn.'),
(2743, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 35, 'OT', 'Móses gat ekki gengið inn í samfundatjaldið, því að skýið hvíldi yfir því, og dýrð Jahve fyllti bústaðinn.'),
(2744, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 36, 'OT', 'Þegar skýið lyftist frá bústaðnum, héldu synir Ísraels af stað í öllum ferðum sínum.'),
(2745, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 37, 'OT', 'En ef skýið lyftist ekki, lögðu þeir ekki af stað fyrr en þann dag sem það lyftist.'),
(2746, 2, 'GOI_Is', 'GOI_Is', 'is', 'EXO', 40, 38, 'OT', 'Ský Jahve var yfir bústaðnum um daga, og eldur var þar um nætur, fyrir augum alls Ísraels húss á öllum ferðum þeirra.'),
(2747, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 1, 'OT', 'Hann kallaði á Móses, og Jahve talaði við hann úr samfundatjaldinu og sagði:'),
(2748, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 2, 'OT', 'Tala þú við sonu Ísraels og seg við þá: Þegar maður af yður vill færa Jahve fórnargjöf af skepnu, úr nautgripunum eða sauðfénu, skuluð þér færa fórnargjöf yðar.'),
(2749, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 3, 'OT', 'Ef fórnargjöf hans er brennifórn af nautgripum, skal hann færa karldýr gallalaust að inngangi samfundatjaldsins, sér til velþóknunar fyrir andliti Jahve.'),
(2750, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 4, 'OT', 'Hann skal leggja hönd sína á höfuð brennifórnarinnar, og hún skal verða honum til velþóknunar, til að friðþægja fyrir hann.'),
(2751, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 5, 'OT', 'Hann skal slátra nautinu fyrir andliti Jahve, og synir Arons, prestarnir, skulu bera blóðið fram og skvetta blóðinu á altarið allt í kring, við inngang samfundatjaldsins.'),
(2752, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 6, 'OT', 'Hann skal flá brennifórnina og skera hana í stykki.'),
(2753, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 7, 'OT', 'Synir Arons, prestarnir, skulu leggja eld á altarið og raða tré á eldinn.'),
(2754, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 8, 'OT', 'Synir Arons, prestarnir, skulu raða stykkin, höfuðið og fituna á trén, sem eru á eldinum, á altarinu.'),
(2755, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 9, 'OT', 'Innyflin og leggi hans skal hann þvo í vatni, og presturinn skal brenna allt á altarinu. Það er brennifórn, eldfórn, þægilegan ilm fyrir Jahve.'),
(2756, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 10, 'OT', 'Ef fórnargjöf hans er af sauðfénu, af lömbum eða geitum sem brennifórn, skal hann færa karldýr gallalaust.'),
(2757, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 11, 'OT', 'Hann skal slátra því við norðurlæri altarisins, fyrir andliti Jahve, og synir Arons, prestarnir, skulu skvetta blóði þess á altarið allt í kring.'),
(2758, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 12, 'OT', 'Hann skal skera það í stykki, höfuðið og fituna, og presturinn skal raða þeim á trén sem eru á eldinum á altarinu.'),
(2759, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 13, 'OT', 'Innyflin og leggina skal hann þvo í vatni, og presturinn skal bera allt fram og brenna á altarinu. Það er brennifórn, eldfórn, þægilegan ilm fyrir Jahve.'),
(2760, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 14, 'OT', 'Ef fórnargjöf hans er brennifórn af fuglum fyrir Jahve, skal hann færa fórnargjöf sína af turtildúfum eða dúfum.'),
(2761, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 15, 'OT', 'Presturinn skal bera hana fram að altarinu, kreista af henni höfuðið og brenna á altarinu, og blóð hennar skal renna út á vegg altarisins.'),
(2762, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 16, 'OT', 'Hann skal taka burt sarpinn með strútsfjöðrum sínum og varpa henni hjá altarinu, austanmegin, á stað ösku.'),
(2763, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 1, 17, 'OT', 'Hann skal rífa hana við vængina, en ekki slíta hana í sundur, og presturinn skal brenna hana á altarinu, á trénu sem er á eldinum. Það er brennifórn, eldfórn, þægilegan ilm fyrir Jahve.'),
(2764, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 1, 'OT', 'Þegar sál færir Jahve fórnargjöf sem matfórn, skal hún vera af fínu mjöli, og hann skal hella olíu yfir hana og setja reykelsi á hana.'),
(2765, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 2, 'OT', 'Hann skal færa það sonum Arons, prestunum, og presturinn skal taka þaðan fulla lúku af fínu mjölinu og olíunni, ásamt öllu reykelsinu, og brenna minningarhluta á altarinu, eldfórn, þægilegan ilm fyrir Jahve.'),
(2766, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 3, 'OT', 'Það sem eftir verður af matfórninni skal vera Aroni og sonum hans; það er helgidómur helgidómanna af eldfórnum Jahve.'),
(2767, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 4, 'OT', 'Ef þú færir matfórn, bakað brauð í ofni, skal hún vera af fínu mjöli: kökur af ósýrðu brauði hnoðaðar með olíu og þynnur af ósýrðu brauði smurðar með olíu.'),
(2768, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 5, 'OT', 'Ef fórnargjöf þín er matfórn steikt á pönnu, skal hún vera af fínu mjöli, hnoðuð með olíu, ósýrt brauð.'),
(2769, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 6, 'OT', 'Brjóttu hana í brauðbita og hell olíu yfir hana; það er matfórn.'),
(2770, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 7, 'OT', 'Ef fórnargjöf þín er matfórn steikt í steikarpönnu, skal hún vera af fínu mjöli hnoðuðu með olíu.'),
(2771, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 8, 'OT', 'Þú skalt færa matfórnina, sem gerð er af þessu, fyrir Jahve, og bera hana fram fyrir prestinn, og hann skal færa hana að altarinu.'),
(2772, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 9, 'OT', 'Presturinn skal taka af matfórninni minningarhluta hennar og brenna hann á altarinu, eldfórn, þægilegan ilm fyrir Jahve.'),
(2773, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 10, 'OT', 'Það sem eftir verður af matfórninni skal vera Aroni og sonum hans; það er helgidómur helgidómanna af eldfórnum Jahve.'),
(2774, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 11, 'OT', 'Sérhver matfórn, sem þér færið Jahve, skal ekki gerð með súrdeigi, því að hvorki súrdeig né hunang skal brenna af henni sem eldfórn fyrir Jahve.'),
(2775, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 12, 'OT', 'Fórnargjöf upphafsins skuluð þið færa Jahve; en ekki skal bera hana upp á altarið til þægilegs ilms.'),
(2776, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 13, 'OT', 'Sérhver fórnargjöf matfórnar þinnar skal kryddast með salti, og þú skalt ekki láta vanta salt sáttmála Guðs þíns í matfórn þína; með allar fórnargjafir þínar skalt þú færa salt.'),
(2777, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 14, 'OT', 'Ef þú færir Jahve matfórn af frumgróðanum, skalt þú færa ristað abíb í eldi og kornflögu úr nýkorni, sem matfórn frumgróða þinna.'),
(2778, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 15, 'OT', 'Þú skalt hella olíu yfir hana og setja reykelsi á hana; það er matfórn.'),
(2779, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 2, 16, 'OT', 'Presturinn skal brenna minningarhlutann af kornflögunum og olíunni, ásamt öllu reykelsinu, sem eldfórn fyrir Jahve.'),
(2780, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 1, 'OT', 'Ef fórnargjöf hans er þakkarfórn af nautgripum, hvort sem hún er af karlkyni eða kvenkyni, skal hann færa það gallalaust fyrir andliti Jahve.'),
(2781, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 2, 'OT', 'Hann skal leggja hönd sína á höfuð fórnargjafarinnar og slátra henni við inngang samfundatjaldsins, og synir Arons, prestarnir, skulu skvetta blóðinu á altarið allt í kring.'),
(2782, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 3, 'OT', 'Af þakkarfórninni skal hann færa eldfórn fyrir Jahve: fituna sem hylur innyflin og alla fituna sem er á innyflunum.'),
(2783, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 4, 'OT', 'Hann skal taka nýru tvö og fituna sem er á þeim, sem er á lendunum, og lifrarbjúgað sem er á lifur, ásamt nýrum.'),
(2784, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 5, 'OT', 'Synir Arons skulu brenna það á altarinu ofan á brennifórninni, sem er á trénu, á eldinum, eldfórn, þægilegan ilm fyrir Jahve.'),
(2785, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 6, 'OT', 'Ef fórnargjöf hans er af sauðfénu sem þakkarfórn fyrir Jahve, hvort sem það er af karlkyni eða kvenkyni, skal hann færa það gallalaust.'),
(2786, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 7, 'OT', 'Ef fórnargjöf hans er lamb, skal hann færa það fram fyrir andliti Jahve.'),
(2787, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 8, 'OT', 'Hann skal leggja hönd sína á höfuð fórnargjafarinnar og slátra henni við inngang samfundatjaldsins, og synir Arons skulu skvetta blóðinu á altarið allt í kring.'),
(2788, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 9, 'OT', 'Af þakkarfórninni skal hann færa eldfórn fyrir Jahve: fituna, rófuna óskemmda við hrygginn, og fituna sem hylur innyflin og alla fituna sem er á innyflunum.'),
(2789, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 10, 'OT', 'Hann skal taka nýru tvö og fituna sem er á þeim, sem er á lendunum, og lifrarbjúgað sem er á lifur, ásamt nýrum.'),
(2790, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 11, 'OT', 'Presturinn skal brenna það á altarinu sem brauð eldfórnar fyrir Jahve.'),
(2791, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 12, 'OT', 'Ef fórnargjöf hans er geit, skal hann færa hana fyrir andliti Jahve.'),
(2792, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 13, 'OT', 'Hann skal leggja hönd sína á höfuð hennar og slátra henni við inngang samfundatjaldsins, og synir Arons skulu skvetta blóði hennar á altarið allt í kring.'),
(2793, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 14, 'OT', 'Af henni skal hann færa fórnargjöf sína sem eldfórn fyrir Jahve: fituna sem hylur innyflin og alla fituna sem er á innyflunum.'),
(2794, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 15, 'OT', 'Hann skal taka nýru tvö og fituna sem er á þeim, sem er á lendunum, og lifrarbjúgað sem er á lifur, ásamt nýrum.'),
(2795, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 16, 'OT', 'Presturinn skal brenna þetta á altarinu sem brauð eldfórnar til þægilegs ilms; öll fita tilheyrir Jahve.'),
(2796, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 3, 17, 'OT', 'Þetta er lagaákvæði um eilífð fyrir kynslóðir yðar í öllum bústöðum yðar: þér skuluð ekki eta neina fitu né neitt blóð.'),
(2797, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 1, 'OT', 'Jahve talaði við Móses og sagði:'),
(2798, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 2, 'OT', 'Tala þú við sonu Ísraels og seg: Ef sál syndgar í óviljaverki gegn einhverju af boðorðum Jahve, sem ekki má gera, og gerir eitthvað af þeim:'),
(2799, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 3, 'OT', 'Ef hinn smurði presturinn syndgar svo að lýðurinn verði sekur, þá skal hann færa Jahve fyrir synd sína ungnaut, gallalaust, sem syndafórn.'),
(2800, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 4, 'OT', 'Hann skal færa ungnautið að inngangi samfundatjaldsins fyrir andliti Jahve, og leggja hönd sína á höfuð ungnautsins og slátra ungnautinu fyrir andliti Jahve.'),
(2801, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 5, 'OT', 'Smurður prestur skal taka af blóði ungnautsins og færa það að samfundatjaldinu.'),
(2802, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 6, 'OT', 'Presturinn skal dýfa fingri sínum í blóðið og strá af blóðinu sjö sinnum fyrir andliti Jahve, fyrir framan fortjald helgidómsins.'),
(2803, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 7, 'OT', 'Presturinn skal setja af blóðinu á horn reykelsisaltarisins, sem er fyrir andliti Jahve í samfundatjaldinu, og hella öllu blóði ungnautsins niður við undirstöðu brennifórnaraltarisins, sem er við inngang samfundatjaldsins.'),
(2804, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 8, 'OT', 'Alla fitu syndafórnarnautsins skal hann taka burt: fituna sem hylur innyflin og alla fituna sem er á innyflunum.'),
(2805, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 9, 'OT', 'Hann skal taka burt nýru tvö og fituna sem er á þeim, sem er á lendunum, og lifrarbjúgað sem er á lifur, ásamt nýrum.'),
(2806, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 10, 'OT', 'Presturinn skal brenna þetta á altari brennifórnarinnar, eins og það er tekið af nautinu af þakkarfórninni.'),
(2807, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 11, 'OT', 'Hann skal brenna skinn nautsins, allt hold þess, höfuð þess, leggi þess, innyflin og saur.'),
(2808, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 12, 'OT', 'Hann skal bera allt nautið út fyrir herbúðir á hreinan stað, á ösku, og brenna það á trjám í eldi; á ösku skal það brennt.'),
(2809, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 13, 'OT', 'Ef allur söfnuður Ísraels villist og málið er hulið augum safnaðarins, og þeir gera eitt af öllum boðorðum Jahve sem ekki má gera og verða sekir:'),
(2810, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 14, 'OT', 'Þá verður synd þeirra kunn, og söfnuður skal færa ungnaut í syndafórn og bera það fram fyrir samfundatjaldið.'),
(2811, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 15, 'OT', 'Öldungar safnaðarins skulu leggja hendur sínar á höfuð ungnautsins fyrir andliti Jahve, og slátra ungnautinu fyrir andliti Jahve.'),
(2812, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 16, 'OT', 'Smurður prestur skal bera af blóði ungnautsins inn í samfundatjaldið.'),
(2813, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 17, 'OT', 'Presturinn skal dýfa fingri sínum í blóðið og strá því sjö sinnum fyrir andliti Jahve, fyrir framan fortjaldið.'),
(2814, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 18, 'OT', 'Af blóðinu skal hann setja á horn altarisins, sem er fyrir andliti Jahve í samfundatjaldinu, og hella öllu blóðinu við undirstöðu brennifórnaraltarisins, sem er við inngang samfundatjaldsins.'),
(2815, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 19, 'OT', 'Alla fituna skal hann taka burt og brenna hana á altarinu.'),
(2816, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 20, 'OT', 'Hann skal gera við ungnautið eins og hann gerði við syndafórnarnautið; þannig skal hann gera við það. Presturinn skal friðþægja fyrir þá, og þeim skal fyrirgefið verða.'),
(2817, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 21, 'OT', 'Hann skal bera ungnautið út fyrir herbúðir og brenna það eins og hann brenndi hitt, fyrra ungnautið; það er syndafórn safnaðarins.'),
(2818, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 22, 'OT', 'Ef höfðingi syndgar í óviljaverki og gerir eitt af öllum boðorðum Jahve Guðs síns, sem ekki má gera, og verður sekur:'),
(2819, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 23, 'OT', 'Eða ef honum verður kunnug synd hans, skal hann færa fórnargjöf sína, geithafur, karldýr gallalaust.'),
(2820, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 24, 'OT', 'Hann skal leggja hönd sína á höfuð geithafursins og slátra honum á þeim stað þar sem brennifórnin er slátrað fyrir andliti Jahve. Það er syndafórn.'),
(2821, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 25, 'OT', 'Presturinn skal taka af blóði syndafórnarinnar með fingri sínum og setja á horn brennifórnaraltarisins, og hella blóðinu niður við undirstöðu brennifórnaraltarisins.'),
(2822, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 26, 'OT', 'Alla fituna skal hann brenna á altarinu eins og fitu þakkarfórnarinnar, og presturinn skal friðþægja fyrir hann vegna syndar hans, og honum skal fyrirgefið verða.'),
(2823, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 27, 'OT', 'Ef sál af lýðnum syndgar í óviljaverki og gerir eitt af boðorðum Jahve, sem ekki má gera, og verður sekur:'),
(2824, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 28, 'OT', 'Eða ef honum verður kunnug synd hans, skal hann færa fórnargjöf sína, kvenkyns geit gallalausa, fyrir synd sína sem hann drýgði.'),
(2825, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 29, 'OT', 'Hann skal leggja hönd sína á höfuð syndafórnarinnar og slátra henni á þeim stað þar sem brennifórnin er slátrað.'),
(2826, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 30, 'OT', 'Presturinn skal taka af blóði hennar með fingri sínum og setja á horn brennifórnaraltarisins, en allt blóð hennar skal hella niður við undirstöðu altarisins.'),
(2827, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 31, 'OT', 'Alla fituna skal hann taka burt, eins og fitan var tekin af þakkarfórninni, og presturinn skal brenna hana á altarinu, þægilegan ilm fyrir Jahve. Presturinn skal friðþægja fyrir hann, og honum skal fyrirgefið verða.'),
(2828, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 32, 'OT', 'Ef fórnargjöf hans er lamb sem syndafórn, skal hann færa lambsgimbur gallalausa.'),
(2829, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 33, 'OT', 'Hann skal leggja hönd sína á höfuð syndafórnarinnar og slátra henni sem syndafórn á þeim stað þar sem brennifórnin er slátrað.'),
(2830, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 34, 'OT', 'Presturinn skal taka af blóði syndafórnarinnar með fingri sínum og setja á horn brennifórnaraltarisins, og allt blóð hennar skal hella niður við undirstöðu altarisins.'),
(2831, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 4, 35, 'OT', 'Alla fituna skal hann taka burt, eins og fitan af lambi þakkarfórnarinnar var tekin, og presturinn skal brenna hana á altarinu sem eldfórn Jahve. Presturinn skal friðþægja fyrir hann vegna syndar hans, og honum skal fyrirgefið verða.'),
(2832, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 1, 'OT', 'Ef sál syndgar og heyrir bölvun, og er vottur, hvort sem hann hefur séð eða vitað, og segir ekki frá, þá skal hann bera misgjörð sína.'),
(2833, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 2, 'OT', 'Eða ef sál snertir eitthvað óhreint, hvort sem það er hræ af óhreinu dýri, hræ af óhreinni skepnu eða hræ af óhreinu skriðdýri, og það er hulið honum, þá er hann óhreinn og sekur.'),
(2834, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 3, 'OT', 'Eða ef einhver snertir óhreinleika manns, hvers konar óhreinleika hans sem gerir hann óhreinan, og það er hulið honum, en hann veit það og er sekur.'),
(2835, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 4, 'OT', 'Eða ef sál sver í gáleysi að gera illt eða gott, hvað sem maður sver með eið, og það er hulið honum, en hann veit það, þá er hann sekur í einhverju af þessu.'),
(2836, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 5, 'OT', 'Þegar hann verður sekur í einhverju af þessu, skal hann játa það sem hann hefur syndgað í.'),
(2837, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 6, 'OT', 'Hann skal færa sektarfórn sína fyrir Jahve vegna syndarinnar sem hann drýgði, kvenkyns af sauðfé, lamb eða kið sem syndafórn; og presturinn skal friðþægja fyrir hann vegna syndar hans.'),
(2838, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 7, 'OT', 'Ef hönd hans nær ekki til lambs, skal hann færa sektarfórn sína fyrir það sem hann syndgaði: tvær turtildúfur eða tvær dúfur fyrir Jahve, aðra sem syndafórn og hina sem brennifórn.'),
(2839, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 8, 'OT', 'Hann skal færa þær presti, og presturinn skal fyrst bera fram þá sem er syndafórn, og slíta höfuð af hálsinum, en ekki kljúfa hana.'),
(2840, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 9, 'OT', 'Hann skal strá af blóði syndafórnarinnar á vegg altarisins, og það sem eftir er af blóðinu skal renna út við undirstöðu altarisins. Það er syndafórn.'),
(2841, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 10, 'OT', 'Hitt skal hann gera að brennifórn eins og fyrirskrifað er, og presturinn skal friðþægja fyrir hann vegna syndar hans, og honum skal fyrirgefið verða.'),
(2842, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 11, 'OT', 'Ef hönd hans nær ekki til tveggja turtildúfna eða tveggja dúfna, skal hann færa fórnargjöf sína fyrir það sem hann syndgaði: tíundu úr efu af fínu mjöli sem syndafórn. Hann skal ekki hella olíu á hana né láta reykelsi á hana, því að hún er syndafórn.'),
(2843, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 12, 'OT', 'Hann skal færa það presti, og presturinn skal taka af því fulla lúku og brenna minningarhluta þess á altarinu sem eldfórn fyrir Jahve. Það er syndafórn.'),
(2844, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 13, 'OT', 'Þannig skal presturinn friðþægja fyrir hann vegna syndar hans, sem hann hefur drýgt í einhverju þessara, og honum skal fyrirgefið verða. Afgangurinn skal vera presti, eins og matfórnin.'),
(2845, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 14, 'OT', 'Jahve talaði við Móses og mælti:'),
(2846, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 15, 'OT', 'Ef sál brýtur trúnað og syndgar óviljandi í hlutum helgum Jahve, þá skal hann færa Jahve sektarfórn sína: hrút gallalausan af sauðfé, metinn í silfursiklum eftir helgisikli, sem sektarfórn.'),
(2847, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 16, 'OT', 'Hann skal bæta fyrir það sem hann hefur misgert í helgidóminum, og leggja fimmtung við það og gefa presti; og presturinn skal friðþægja fyrir hann með hrútnum sektarfórnarinnar, og honum skal fyrirgefið verða.'),
(2848, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 17, 'OT', 'Ef sál syndgar og gerir eitt af boðorðum Jahve, sem ekki má gera, án þess að vita það, og verður sekur og ber misgjörð sína.'),
(2849, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 18, 'OT', 'Hann skal færa hrút gallalausan af sauðfé, metinn sem sektarfórn, til prestsins, og presturinn skal friðþægja fyrir hann vegna óviljaverks hans sem hann villtist í, án þess að hann vissi það, og honum skal fyrirgefið verða.'),
(2850, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 5, 19, 'OT', 'Þetta er sektarfórn; hann er sekur fyrir Jahve.'),
(2851, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2852, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 2, 'OT', 'Ef sál syndgar og sýnir ótrúmennsku gagnvart Jahve, með því að svíkja náunga sinn um umsjón, um samfélag í hendi, eða með því að taka rán af náunga sínum eða kúga hann;'),
(2853, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 3, 'OT', 'Eða ef hann finnur glötun, neitar henni og sver lygi um eitthvað af því sem maðurinn gerir og syndgar með.'),
(2854, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 4, 'OT', 'Og verði hann sekur og syndgi, þá skal hann skila ráninu sem hann rændi, eða kúguninni, eða umsjóninni sem honum var trúað fyrir, eða glötuninni sem hann fann.'),
(2855, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 5, 'OT', 'Eða hvað sem hann sver lygi um, skal hann skila því að fullu, leggja fimmtung ofan á höfuðstólinn og gefa það þeim sem það tilheyrir á þeim degi sem hann færir sektarfórn sína.'),
(2856, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 6, 'OT', 'Og sektarfórn sína skal hann færa Jahve: hrút gallalausan úr sauðfé, metinn að verði, sem sektarfórn, til prestsins.'),
(2857, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 7, 'OT', 'Og presturinn skal friðþægja fyrir hann frammi fyrir andliti Jahve, og honum skal fyrirgefið verða fyrir hvert það sem hann gerir og leiðir til sektarfórnar.'),
(2858, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 8, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2859, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 9, 'OT', 'Bjóð Aroni og sonum hans og seg: Þetta er lögmál brennifórnarinnar: brennifórnin skal liggja á bruna sínum á altarinu alla nóttina til morguns, og eldurinn á altarinu skal brenna á því.'),
(2860, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 10, 'OT', 'Presturinn skal klæðast hörklæði og hafa nærbuxur úr hör á holdi sínu, taka upp ösku þá sem eldurinn hefur étið af brennifórninni á altarinu og leggja hana hjá altarinu.'),
(2861, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 11, 'OT', 'Hann skal afklæðast klæðum sínum og klæðast öðrum klæðum og bera öskuna út fyrir herbúðirnar á hreinan stað.'),
(2862, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 12, 'OT', 'Eldurinn á altarinu skal loga á því og ekki slokkna. Presturinn skal kynda undir honum tré á hverjum morgni, raða brennifórninni á hann og brenna á honum fitu þakkarfórnanna.'),
(2863, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 13, 'OT', 'Eldur skal loga stöðugt á altarinu og aldrei slokkna.'),
(2864, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 14, 'OT', 'Þetta er lögmál matfórnarinnar: synir Arons skulu færa hana fram fyrir andlit Jahve, fyrir altarið.'),
(2865, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 15, 'OT', 'Hann skal taka með lúku sinni af fínu mjöli matfórnarinnar og af olíu hennar, og allt reykelsið sem er á matfórninni, og brenna það á altarinu sem þægilegan ilm, sem minningarhluta fyrir Jahve.'),
(2866, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 16, 'OT', 'Afganginn af henni skulu Aron og synir hans eta; hann skal etinn sem ósýrt brauð á helgum stað, í forgarði samfundatjaldsins.'),
(2867, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 17, 'OT', 'Hún skal ekki bökuð með súrdeigi; ég hef gefið hana sem þeirra hlut af eldfórnum mínum. Hún er mikil helgi, eins og syndafórnin og sektarfórnin.'),
(2868, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 18, 'OT', 'Sérhver karlmaður meðal sona Arons skal eta hana, sem lög um eilífð fyrir kynslóðir ykkar; af eldfórnum Jahve, hver sem snertir þær, verður helgur.'),
(2869, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 19, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2870, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 20, 'OT', 'Þetta er fórnargjöf Arons og sona hans, sem þeir skulu færa Jahve á þeim degi sem hann verður smurður: tíundi hluti úr efu af fínu mjöli sem stöðuga fórn, helmingur hennar að morgni og helmingur hennar að kvöldi.'),
(2871, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 21, 'OT', 'Á pönnu skal það vera steikt með olíu; þú skalt bera það fram blandað, og brauðbita fórnarinnar, bakaða í stykkjum, skalt þú færa fram sem þægilegan ilm fyrir Jahve.'),
(2872, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 22, 'OT', 'Presturinn, smurður í hans stað af sonum hans, skal gera þetta. Það eru lög um eilífð fyrir Jahve; það skal brennt algjörlega.'),
(2873, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 23, 'OT', 'Sérhver fórn prests skal vera brennd algjörlega; hún skal ekki etin.'),
(2874, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 24, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2875, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 25, 'OT', 'Tala við Aron og sonu hans og seg: Þetta er lögmál syndafórnarinnar. Á þeim stað þar sem brennifórnin er slátrað skal syndafórnin slátrað verða fyrir Jahve. Hún er mikil helgi.'),
(2876, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 26, 'OT', 'Presturinn sem færir hana í syndafórn skal eta hana; hún skal etin á helgum stað, í forgarði samfundatjaldsins.'),
(2877, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 27, 'OT', 'Hvað sem snertir hold hennar skal verða helgað, og það blóð hennar sem slettist á klæðið skal þvegið verða á helgum stað.'),
(2878, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 28, 'OT', 'Leirker sem hún er soðin í skal brotið verða; en ef hún er soðin í eiri áhaldi skal það skrúbbað og skolað í vatni.'),
(2879, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 29, 'OT', 'Sérhver karlmaður meðal prestanna skal eta hana; hún er mikil helgi.'),
(2880, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 6, 30, 'OT', 'Sérhver syndafórn sem blóð hennar er borið inn í samfundatjaldið til friðþægingar í helgidóminum skal ekki etin verða; hún skal brennd í eldi.'),
(2881, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 1, 'OT', 'Þetta er lögmál sektarfórnarinnar; hún er mikil helgi.'),
(2882, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 2, 'OT', 'Á þeim stað þar sem brennifórnin er slátrað skal sektarfórnin slátrað verða, og blóð hennar skal stökkva á altarið allt í kring.'),
(2883, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 3, 'OT', 'Alla fituna hennar skal færa fram af henni: rófuna og fituna sem hylur innyflin.'),
(2884, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 4, 'OT', 'Nýru tvö og fituna sem er á þeim, sú sem er við lendarnar, og lifrarbjúguna á lifrinni ásamt nýrunum skal hann taka burt.'),
(2885, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 5, 'OT', 'Presturinn skal brenna þetta á altarinu sem eldfórn fyrir Jahve; það er sektarfórn.'),
(2886, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 6, 'OT', 'Sérhver karlmaður meðal prestanna skal eta það; það skal etið á helgum stað, það er mikil helgi.'),
(2887, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 7, 'OT', 'Sektarfórnin og syndafórnin hafa eitt lögmál: presturinn sem friðþægir með þeim skal eiga hana.'),
(2888, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 8, 'OT', 'Og presturinn sem færir brennifórn manns skal eiga skinn brennifórnarinnar sem hann færði.'),
(2889, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 9, 'OT', 'Sérhver fórn sem bökuð er í ofni, og sérhver sem gerð er á steikarpönnu eða á pönnu, skal tilheyra prestinum sem færir hana.'),
(2890, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 10, 'OT', 'Og sérhver fórn sem blönduð er í olíu og þurr skal tilheyra öllum sonum Arons, hverjum manni jafnt sem bróður sínum.'),
(2891, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 11, 'OT', 'Þetta er lögmál þakkarfórnarinnar sem færð er Jahve.'),
(2892, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 12, 'OT', 'Ef hann færir hana sem þakkargjörð, skal hann færa með sláturfórn þakkargjörðarinnar ósýrð brauð blönduð olíu, og ósýrðar kökur smurðar olíu, og kökur úr fínu mjöli blandaðar olíu.'),
(2893, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 13, 'OT', 'Með kökum úr súrdeigi skal hann færa fórnargjöf sína, með sláturfórn þakkargjörðar sinnar og þakkarfórnum sínum.'),
(2894, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 14, 'OT', 'Og hann skal færa af hverri fórnargjöf eitt framlag til Jahve; það skal tilheyra prestinum sem stökkvir blóði þakkarfórnanna.'),
(2895, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 15, 'OT', 'Holdið af sláturfórn þakkargjörðar hans og þakkarfórna skal etið verða á þeim degi sem hann er færður; hann skal ekki skilja neitt eftir til morguns.'),
(2896, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 16, 'OT', 'En ef fórn hans er heit eða sjálfviljafórn, skal hún etin verða á þeim degi sem hann færir sláturfórn sína, og það sem eftir er skal etið verða á morgundeginum.'),
(2897, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 17, 'OT', 'Og það sem eftir er af holdi sláturfórnarinnar skal brennt verða í eldi á þriðja degi.'),
(2898, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 18, 'OT', 'Ef einhver etur af holdi þakkarfórnar sinnar á þriðja degi, verður hún ekki þóknanleg; þeim sem færir hana skal hún ekki reiknast. Hún er viðurstyggilegur matur, og sálin sem etur af henni skal bera misgjörð sína.'),
(2899, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 19, 'OT', 'Holdið sem snertir eitthvað óhreint skal ekki etið verða, heldur brennt í eldi; en hvert hreint hold skal etið verða.'),
(2900, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 20, 'OT', 'Sálin sem etur hold af sláturfórn þakkarfórnanna, sem tilheyra Jahve, meðan óhreinleiki hennar er yfir henni, skal upprætt verða úr lýð sínum.'),
(2901, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 21, 'OT', 'Og sál sem snertir eitthvað óhreint, hvort sem það er óhreinleiki manns, óhreinleiki óhreinnar skepnu eða einhver óhrein viðurstyggð, og etur af holdi þakkarfórna sem tilheyra Jahve, sú sál skal upprætt verða úr lýð sínum.'),
(2902, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 22, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2903, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 23, 'OT', 'Tala við Ísraels sonu og seg: Þið skuluð ekki eta neina fitu nautsins, lambsins eða geitarinnar.'),
(2904, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 24, 'OT', 'Fita hræs og fita bráðar má nota til hvers starfs, en þið skuluð ekki eta hana.'),
(2905, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 25, 'OT', 'Því sérhver sem etur fitu af skepnunni, sem færð er Jahve sem eldfórn, sú sál skal upprætt verða úr lýð sínum.'),
(2906, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 26, 'OT', 'Blóð skuluð þið ekki eta í neinum bústöðum ykkar, hvorki af fugli né skepnu.'),
(2907, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 27, 'OT', 'Sérhver sál sem etur blóð, sú sál skal upprætt verða úr lýð sínum.'),
(2908, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 28, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2909, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 29, 'OT', 'Tala við Ísraels sonu og seg: Sá sem færir Jahve sláturfórn þakkarfórnar sinnar, skal færa Jahve fórnargjöf sína af þakkarfórn sinni.'),
(2910, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 30, 'OT', 'Hendur sínar skal hann bera fram með eldfórnum Jahve: fitu ásamt bringu, og bringu sjálfa skal hann veifa sem veifufórn fyrir Jahve.'),
(2911, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 31, 'OT', 'Presturinn skal brenna fitu á altari, en bringan skal vera Aroni og sonum hans.'),
(2912, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 32, 'OT', 'Læri á hægri hönd skuluð þið gefa presti sem framlag af sláturfórnum ykkar og þakkarfórnum.'),
(2913, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 33, 'OT', 'Sá af sonum Arons sem fórnar blóði þakkarfórna og fitu, skal eiga læri á hægri hönd sem sinn hlut.'),
(2914, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 34, 'OT', 'Því að bringu af veifufórn og læri af framlagi hef ég tekið af sonum Ísraels, af sláturfórnum þeirra og þakkarfórnum, og gefið það Aroni presti og sonum hans sem lög um eilífð meðal Ísraels sona.'),
(2915, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 35, 'OT', 'Þetta er smurning Arons og sona hans af eldfórnum Jahve á þeim degi sem hann leiddi þá fram til að þjóna Jahve sem prestar.'),
(2916, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 36, 'OT', 'Þetta er það sem Jahve bauð að gefa þeim á þeim degi sem þeir voru smurðir, af sonum Ísraels, sem lagaákvæði um eilífð til kynslóða þeirra.'),
(2917, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 37, 'OT', 'Þetta er lögmál brennifórnar, fórnar, syndar, sektarfórnar, vígslu og þakkarfórnar.'),
(2918, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 7, 38, 'OT', 'Þetta er það sem Jahve bauð Mósesi á fjalli Sínaí, á þeim degi sem hann bauð Ísraels sonum að færa Jahve fórnargjöf sína í eyðimörk Sínaí.'),
(2919, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(2920, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 2, 'OT', 'Tak Aron og sonu hans með þér, klæði þeirra, olíu til smurningar, ungnaut til syndar, hrúta tvo og körfu ósýrðra brauða.'),
(2921, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 3, 'OT', 'Safnaðu öllum söfnuð saman við inngang samfundatjaldsins.'),
(2922, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 4, 'OT', 'Móses gerði eins og Jahve hafði boðið honum, og söfnuðurinn safnaðist saman við inngang samfundatjaldsins.'),
(2923, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 5, 'OT', 'Móses sagði við söfnuð: Þetta er orð sem Jahve bauð að gera.'),
(2924, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 6, 'OT', 'Móses leiddi Aron og sonu hans fram og þvoði þá með vatni.'),
(2925, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 7, 'OT', 'Hann setti kyrtil á hann, gyrti hann belti, klæddi hann yfirhöfn, lagði hökul á hann og gyrti hann belti úr vefnaði og festi það á hann.'),
(2926, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 8, 'OT', 'Hann lagði brjóstskjöld á hann og setti í brjóstskildi Úrím og Túmmím.'),
(2927, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 9, 'OT', 'Hann setti vefjarhött á höfuð hans og fyrir framan vefjarhött setti hann gull og blóm, nasír helgi, eins og Jahve hafði boðið Mósesi.'),
(2928, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 10, 'OT', 'Móses tók olíu til smurningar og smurði bústað og allt sem í honum var og helgaði það.'),
(2929, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 11, 'OT', 'Hann stökkti af henni sjö sinnum á altari, smurði altari og öll áhöld þess, þvottaker og stall, til að helga þau.'),
(2930, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 12, 'OT', 'Hann hellti olíu smurningar á höfuð Arons og smurði hann til að helga hann.'),
(2931, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 13, 'OT', 'Móses leiddi sonu Arons fram, klæddi þá kyrtlum, gyrti þá belti og batt á þá vefjarhöttum, eins og Jahve hafði boðið Mósesi.'),
(2932, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 14, 'OT', 'Hann leiddi fram ungnaut sem fórn til syndar, og Aron og sonu hans lögðu hendur sínar á höfuð ungnauts.'),
(2933, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 15, 'OT', 'Hann slátraði því, og Móses tók blóð og setti það á horn á altari allt í kring með fingri sínum, hreinsaði altari og hellti blóði við undirstöðu altaris og helgaði það til að friðþægja fyrir það.'),
(2934, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 16, 'OT', 'Hann tók alla fitu sem var á innyflunum, lifrarbjúga, nýru tvö og fitu þeirra, og Móses brenndi það á altari.'),
(2935, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 17, 'OT', 'Ungnautið, skinn þess, hold og saur brenndi hann í eldi fyrir utan herbúðir, eins og Jahve hafði boðið Mósesi.'),
(2936, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 18, 'OT', 'Hann færði fram hrút til brennifórnar, og Aron og sonu hans lögðu hendur sínar á höfuð hrúts.'),
(2937, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 19, 'OT', 'Hann slátraði honum, og Móses stökkti blóði á altari allt í kring.'),
(2938, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 20, 'OT', 'Hrút skar hann í stykki, og Móses brenndi höfuð, stykkin og fitu.'),
(2939, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 21, 'OT', 'Innyfli og leggi þvoði hann í vatni. Móses brenndi allan hrút á altari sem brennifórn, þægilegan ilm, eldfórn fyrir Jahve, eins og Jahve hafði boðið Mósesi.'),
(2940, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 22, 'OT', 'Hann færði fram annan hrút, hrút vígslu, og Aron og sonu hans lögðu hendur sínar á höfuð hrúts.'),
(2941, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 23, 'OT', 'Hann slátraði honum, og Móses tók af blóði hans og setti það á hægri eyrnasnepil Arons, á þumalfingur hægri handar hans og á stóru tá hægri fótar hans.'),
(2942, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 24, 'OT', 'Móses færði fram sonu Arons, og setti af blóðinu á hægri eyrnasnepil þeirra, á þumalfingur hægri handar þeirra og á stóru tá hægri fótar þeirra; síðan stökkti hann blóðinu á altarið allt í kring.'),
(2943, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 25, 'OT', 'Hann tók fitu, rófu, alla fitu sem var á innyflunum, lifrarbjúga, nýru tvö, fitu þeirra og læri á hægri hönd.'),
(2944, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 26, 'OT', 'Úr körfu ósýrðra brauða, sem var fyrir andliti Jahve, tók hann eina ósýrða köku, eina köku með olíu úr fínu mjöli og eina þunna köku, og lagði þær á fitu og læri á hægri hönd.'),
(2945, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 27, 'OT', 'Hann lagði allt þetta á lófa Arons og á lófa sona hans og veifaði þeim sem veifufórn fyrir Jahve.'),
(2946, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 28, 'OT', 'Móses tók þetta af lófum þeirra og brenndi það á altari ofan á brennifórn; þetta var vígslufórn til ilms, eldfórn fyrir Jahve.'),
(2947, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 29, 'OT', 'Móses tók bringu og veifaði henni sem veifufórn fyrir Jahve; hún var hans hlutur af hrút vígslu, eins og Jahve hafði boðið Mósesi.'),
(2948, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 30, 'OT', 'Móses tók olíu smurningar og blóð af altari og stökkti á Aron, á klæði hans, á sonu hans og á klæði sona hans með honum. Hann helgaði Aron, klæði hans, sonu hans og klæði sona hans með honum.'),
(2949, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 31, 'OT', 'Móses sagði við Aron og sonu hans: Sjóðið hold við inngang samfundatjaldsins og etið það þar ásamt brauði úr körfu vígslu, eins og ég hef boðið: Aron og sonu hans skulu eta það.'),
(2950, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 32, 'OT', 'Það sem eftir verður af holdi og brauði skal brennt í eldi.'),
(2951, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 33, 'OT', 'Við inngang samfundatjaldsins skuluð þið dvelja í sjö daga, þar til dagar vígslu ykkar eru liðnir, því að í sjö daga mun hann fylla hendur ykkar.'),
(2952, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 34, 'OT', 'Eins og gert hefur verið þann dag, bauð Jahve að gera það til að friðþægja fyrir ykkur.'),
(2953, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 35, 'OT', 'Við inngang samfundatjaldsins skuluð þið dvelja nótt og dag í sjö daga og gæta varðstöðu Jahve, svo að þið deyið ekki, því að svo hefur mér verið boðið.'),
(2954, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 8, 36, 'OT', 'Aron og sonu hans gerðu öll þau orð sem Jahve bauð fyrir hendi Mósesar.'),
(2955, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 1, 'OT', 'Á áttunda degi kallaði Móses á Aron og sonu hans og Ísrael.'),
(2956, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 2, 'OT', 'Hann sagði við Aron: Tak þér kálf, ungt naut, til syndar, og hrút til brennifórnar, gallalausa, og færðu þá fram fyrir andlit Jahve.'),
(2957, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 3, 'OT', 'Og talaðu við Ísraels sonu: Tak geithafur til syndar, kálf og lamb, eins árs gamalt, gallalaus, til brennifórnar.'),
(2958, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 4, 'OT', 'Naut og hrút til þakkarfórnar fyrir andlit Jahve, og fórn blandaða olíu, því að í dag birtist Jahve.'),
(2959, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 5, 'OT', 'Móses bauð, og allt var fært fyrir samfundatjaldið; og allur söfnuðurinn kom og stóð fyrir andliti Jahve.'),
(2960, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 6, 'OT', 'Móses sagði: Þetta er orð sem Jahve bauð; gerið það, og dýrð Jahve mun birtast ykkur.'),
(2961, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 7, 'OT', 'Móses sagði við Aron: Gakk að altari, og færðu syndafórn þína og brennifórn þína og friðþægðu fyrir þig og lýð; færðu fórnargjöf lýðsins og friðþægðu fyrir hann, eins og Jahve hefur boðið.'),
(2962, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 8, 'OT', 'Aron gekk að altari og slátraði kálf syndafórnarinnar, sem var fyrir hann sjálfan.'),
(2963, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 9, 'OT', 'Synir Arons færðu honum blóð; hann dýfði fingri í blóði og setti á horn altaris, og hellti blóði við undirstöðu altaris.'),
(2964, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 10, 'OT', 'Fitu, nýru, lifrarbjúga og lifur af fórn syndar brenndi hann á altari, eins og Jahve hafði boðið Mósesi.'),
(2965, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 11, 'OT', 'Hold og skinn brenndi hann í eldi fyrir utan herbúðir.'),
(2966, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 12, 'OT', 'Hann slátraði brennifórn, og synir Arons færðu honum blóð; hann stökkti því á altari allt í kring.'),
(2967, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 13, 'OT', 'Brennifórn skar hann í stykki og brenndi þau ásamt höfði á altari.'),
(2968, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 14, 'OT', 'Innyfli og leggi þvoði hann í vatni og brenndi á altari sem brennifórn.'),
(2969, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 15, 'OT', 'Hann færði fram fórnargjöf lýðsins: geithafur til syndar, sem var fyrir lýð, og slátraði honum og færði hann eins og hinn fyrri.'),
(2970, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 16, 'OT', 'Brennifórn færði hann fram samkvæmt dómi.'),
(2971, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 17, 'OT', 'Fórn færði hann fram, fyllti lófa sinn af henni og brenndi á altari, auk brennifórnar morguns.'),
(2972, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 18, 'OT', 'Naut og hrút til þakkarfórnar fyrir lýð; synir Arons færðu honum blóð, og hann stökkti því á altari allt í kring.'),
(2973, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 19, 'OT', 'Fitu af nauti og hrút, rófu, nýru, lifrarbjúga og lifur, og fitu sem hylur innyflin.'),
(2974, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 20, 'OT', 'Fitu lögðu þeir á bringur, og fitan var brennd á altari.'),
(2975, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 21, 'OT', 'Bringur og læri á hægri hönd veifaði Aron sem veifufórn fyrir Jahve, eins og Móses hafði boðið.'),
(2976, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 22, 'OT', 'Aron hóf hendur sínar og blessaði lýð, og steig niður eftir að hafa fært fórn syndar, brennifórn og þakkarfórn.'),
(2977, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 23, 'OT', 'Móses og Aron gengu inn í samfundatjaldið, komu út og blessuðu lýð; og dýrð Jahve birtist öllum lýð.'),
(2978, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 9, 24, 'OT', 'Eldur kom út frá andliti Jahve og át brennifórn og fitu á altari; og allt lýð sá það, hrópaði og féll fram á andlit sín.'),
(2979, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 1, 'OT', 'Synir Arons, Nadab og Abíhú, tóku hvor sína eldpönnu, settu eld í hana, lögðu reykelsi á og báru fram framandi eld fyrir andlit Jahve, sem hann hafði ekki boðið.'),
(2980, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 2, 'OT', 'Eldur kom út frá andliti Jahve og át þá, og þeir dóu fyrir andliti Jahve.'),
(2981, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 3, 'OT', 'Móses sagði við Aron: Þetta er það sem Jahve talaði og sagði: Ég mun helgast þeim sem nálægt mér eru, og fyrir lýð allan mun ég vegsamast. Aron þagði.'),
(2982, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 4, 'OT', 'Móses kallaði á Mísael og Elísafan, sonu Ússíels, föðurbróður Arons, og sagði við þá: Gangið fram, berið bróður ykkar frá helgidóminum út fyrir herbúðir.'),
(2983, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 5, 'OT', 'Þeir gengu fram, báru þá í kyrtli sínum út fyrir herbúðir, eins og Móses hafði sagt.'),
(2984, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 6, 'OT', 'Móses sagði við Aron og Eleasar og Ítamar, sonu hans: Höfuð ykkar skuluð þið ekki losa, né klæði ykkar rífa, til þess að þið deyið ekki og reiði komi yfir allan söfnuð; en bræður ykkar, allt hús Ísraels, skulu gráta bruna þann sem Jahve hefur kveikt.'),
(2985, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 7, 'OT', 'Þið skuluð ekki fara út frá inngangi samfundatjaldsins, því að olía smurningar Jahve er yfir ykkur. Þeir gerðu eftir orði Mósesar.'),
(2986, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 8, 'OT', 'Og Jahve talaði við Aron og sagði:'),
(2987, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 9, 'OT', 'Hvorki vín né áfengi skuluð þið drekka, þú og synir þínir með þér, þegar þið gangið inn í samfundatjaldið, svo að þið deyið ekki; það eru lög um eilífð fyrir kynslóðum ykkar.'),
(2988, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 10, 'OT', 'Til að greina milli helgi og vanhelgs hlutar, og milli hreins og óhreins.'),
(2989, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 11, 'OT', 'Og til að kenna Ísraels sonum öll lög sem Jahve hefur talað við þá fyrir hendi Mósesar.'),
(2990, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 12, 'OT', 'Móses sagði við Aron, Eleasar og Ítamar, sonu hans sem eftir voru: Takið fórn þá sem eftir er af eldfórnum Jahve og etið hana ósýrða við altari, því að hún er helgi.'),
(2991, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 13, 'OT', 'Á helgum stað skuluð þið eta hana, þú og synir þínir, því að það eru lög þín og lög sona þinna af eldfórnum Jahve.'),
(2992, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 14, 'OT', 'Bringu veifufórnar og læri framlag skuluð þið eta á hreinum stað, þú og synir þínir og dætur þínar með þér, því að þau eru lög þín og lög sona þinna, af sláturfórnum þakkarfórna Ísraels sona.'),
(2993, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 15, 'OT', 'Læri framlag og bringu veifufórnar, eldfórnir af fitu, skalt þú veifa sem veifufórn fyrir andlit Jahve; og það skal vera þitt og sona þinna lög um eilífð, eins og Jahve hefur boðið.'),
(2994, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 16, 'OT', 'Móses leitaði að geithafur syndar og sá að hann var brenndur; hann reiddist Eleasar og Ítamar, sonum Arons sem eftir voru.'),
(2995, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 17, 'OT', 'Hvers vegna hafið þið ekki etið fórn syndar á helgum stað, því að hún er mikil helgi? Hann gaf ykkur hana til að bera misgjörð og friðþægja fyrir söfnuð fyrir andlit Jahve.'),
(2996, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 18, 'OT', 'Sjá, blóð hennar var ekki borið inn í helgi; þið áttuð að eta hana í helgi, eins og ég bauð.'),
(2997, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 19, 'OT', 'Aron sagði við Móses: Sjá, í dag færðu þeir fórn syndar sína og brennifórn sína fyrir andlit Jahve, og þó hefur þetta komið fyrir mig; ef ég hefði etið fórn syndar í dag, hefði það þóknast í augum Jahve?'),
(2998, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 10, 20, 'OT', 'Móses heyrði það og það þóknaðist honum í augum hans.'),
(2999, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 1, 'OT', 'Og Jahve talaði við Móses og Aron og sagði:'),
(3000, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 2, 'OT', 'Talið við Ísraels sonu og segið: Þetta eru þær skepnur sem þið megið eta meðal allra dýra jarðar.'),
(3001, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 3, 'OT', 'Allt sem hefur klaufar, klofnar klaufar og jórtrar meðal skepna, það megið þér eta.'),
(3002, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 4, 'OT', 'En þetta skulið þér ekki eta af því sem jórtrar eða hefur klaufar: úlfalda, því hann jórtrar en klýfur ekki klaufar; hann er óhreinn fyrir yður.'),
(3003, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 5, 'OT', 'Einnig stökkhéra, því hún jórtrar en klýfur ekki klaufar; hún er óhrein fyrir yður.'),
(3004, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 6, 'OT', 'Og héra, því hann jórtrar en hefur ekki klaufar; hann er óhreinn fyrir yður.'),
(3005, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 7, 'OT', 'Og svínið, því það klýfur klaufar og hefur klofnar klaufar, en jórtrar ekki; það er óhreint fyrir yður.'),
(3006, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 8, 'OT', 'Af holdi þeirra skuluð þér ekki eta, og hræ þeirra skuluð þér ekki snerta; þau eru óhrein fyrir yður.'),
(3007, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 9, 'OT', 'Þetta megið þér eta af öllu sem er í vötnum, í höfum og í lækjum: allt sem hefur uggar og hreistur.'),
(3008, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 10, 'OT', 'En allt sem hvorki hefur ugga né hreistur í höfum eða lækjum, af öllu skriðdýri vatnsins og allri sál sem lifir í vötnum, það er viðurstyggð fyrir yður.'),
(3009, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 11, 'OT', 'Þær skulu vera yður viðurstyggð; af holdi þeirra skuluð þér ekki eta, og hræ þeirra skuluð þér hafa í viðurstyggð.'),
(3010, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 12, 'OT', 'Allt í vötnum sem hefur hvorki ugga né hreistur, það er viðurstyggð fyrir yður.'),
(3011, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 13, 'OT', 'Af fuglunum skuluð þér hafa þessa í viðurstyggð og ekki eta þá: örn, klær og ránfugl; þeir eru viðurstyggð.'),
(3012, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 14, 'OT', 'Og hrægamm og uglu, hvort um sig eftir sinni tegund.'),
(3013, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 15, 'OT', 'Og hvern hrafn eftir sinni tegund.'),
(3014, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 16, 'OT', 'Og strút, næturhauku, gauk og hauk eftir sinni tegund.'),
(3015, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 17, 'OT', 'Og bikar, skarf og uglutegund.'),
(3016, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 18, 'OT', 'Og uglu, sjófugl og hrægamm.'),
(3017, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 19, 'OT', 'Og stork og hegra eftir sinni tegund, þyrilvæng og leðurblöku.'),
(3018, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 20, 'OT', 'Allt skriðdýr fugla sem gengur á fjórum fótum er viðurstyggð fyrir yður.'),
(3019, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 21, 'OT', 'En þetta megið þér eta af öllu skriðdýri fugla sem gengur á fjórum: það sem hefur leggi ofan fóta sinna til að hoppa með á jörðinni.'),
(3020, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 22, 'OT', 'Af þessu megið þér eta: engisprettu af sinni tegund, engisprettu af sinni tegund, bjöllu af sinni tegund og engisprettu af sinni tegund.'),
(3021, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 23, 'OT', 'En allt skriðdýr fugla sem hefur fjóra fætur er viðurstyggð fyrir yður.'),
(3022, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 24, 'OT', 'En af þessu skuluð þér verða óhreinir; hver sem snertir hræ þeirra verður óhreinn allt til kvölds.'),
(3023, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 25, 'OT', 'Og hver sem ber af hræi þeirra skal þvo klæði sín og vera óhreinn til kvölds.'),
(3024, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 26, 'OT', 'Hver sú skepna sem hefur klaufar, en er ekki klofin og jórtrar ekki, er óhrein fyrir yður; hver sem snertir hana verður óhreinn.'),
(3025, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 27, 'OT', 'Og allt sem gengur á lófum sínum, meðal allra dýra sem ganga á fjórum fótum, er óhreint fyrir yður; hver sem snertir hræ þeirra verður óhreinn til kvölds.'),
(3026, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 28, 'OT', 'Og sá sem ber hræ þeirra skal þvo klæði sín og vera óhreinn til kvölds; þau eru óhrein fyrir yður.'),
(3027, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 29, 'OT', 'Og þetta er óhreint fyrir yður af skriðdýri sem skríður á jörð: læðingur, mús og eðla eftir sinni tegund.'),
(3028, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 30, 'OT', 'Þessi eru óhrein: eðlu, kraft, eðlu, snigil og uglu.'),
(3029, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 31, 'OT', 'Þessi eru óhrein fyrir yður meðal alls skriðdýrs; hver sem snertir þau í dauða þeirra verður óhreinn til kvölds.'),
(3030, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 32, 'OT', 'Og hvað sem fellur á eitthvað af þeim í dauða þeirra skal verða óhreint, hvort sem það er áhald úr tré, klæði, skinn eða hærusekk; hvert áhald sem notað er til starfs skal sett í vatn og verða óhreint til kvölds, og síðan hreint.'),
(3031, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 33, 'OT', 'Og sérhvert leirker sem eitthvað af þeim fellur í, allt sem í því er verður óhreint, og það skal brjóta.'),
(3032, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 34, 'OT', 'Af öllum mat sem etinn er og vatn kemst yfir skal verða óhreint, og sérhvern drykk sem drukkinn er í hverju áhaldi skal verða óhreinn.'),
(3033, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 35, 'OT', 'Og allt sem fellur af hræi þeirra á ofn eða eldstæði skal brjóta niður; þau eru óhrein og skulu vera óhrein fyrir yður.'),
(3034, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 36, 'OT', 'En lind og brunn, vatnssafn, skal vera hreint; en sá sem snertir hræ þeirra verður óhreinn.'),
(3035, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 37, 'OT', 'Og ef hræ þeirra fellur á sæði sem í sáningu er, þá er það hreint.'),
(3036, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 38, 'OT', 'Og ef vatn er látið á sæði og eitthvað af hræi þeirra fellur á það, er það óhreint fyrir yður.'),
(3037, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 39, 'OT', 'Og ef skepna deyr, sú sem er yður til fæðu, þá verður sá óhreinn til kvölds sem snertir hræ hennar.'),
(3038, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 40, 'OT', 'Sá sem etur af hræi hennar skal þvo klæði sín og verða óhreinn til kvölds; og sá sem ber hræ hennar skal þvo klæði sín og verða óhreinn til kvölds.'),
(3039, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 41, 'OT', 'Og allt skriðdýr sem skríður á jörð er viðurstyggð og má ekki eta.'),
(3040, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 42, 'OT', 'Allt sem gengur á kviði og allt sem gengur á fjórum fótum eða hefur marga fætur, af öllu sem skríður á jörð, það skuluð þér ekki eta; það er viðurstyggð.'),
(3041, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 43, 'OT', 'Gerið ekki sálum yðar viðurstyggð með neinu skriðdýri sem skríður, og saurgið yður ekki á þeim, svo að þér verðið óhreinir.'),
(3042, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 44, 'OT', 'Því að ég er Jahve, Guð yðar. Helgið yður og verið heilagir, því að ég er heilagur. Saurgið ekki sálum yðar með neinu skriðdýri sem skríður á jörð.'),
(3043, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 45, 'OT', 'Því að ég er Jahve, sá sem leiddi yður upp af Egyptalandi til þess að vera yðar Guð; þér skuluð vera heilagir, því að ég er heilagur.'),
(3044, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 46, 'OT', 'Þetta er lögmálið um skepnuna og fuglinn, um allt lifandi sem hrærist í vötnum, og um sérhverja sál sem skríður á jörð.'),
(3045, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 11, 47, 'OT', 'Til að greina á milli hins óhreina og hins hreina, og milli lífverunnar sem eta má og lífverunnar sem ekki má eta.'),
(3046, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 12, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(3047, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 12, 2, 'OT', 'Tala til Ísraels barna og seg við þau: Ef kona verður þunguð og elur son, þá skal hún vera óhrein í sjö daga, eins og á dögum óhreinleika hennar.'),
(3048, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 12, 3, 'OT', 'Og á áttunda degi skal umskera hold yfirhúðar hans.'),
(3049, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 12, 4, 'OT', 'Og þrjátíu og þrjá daga skal hún sitja í blóði hreinsunar sinnar; hún skal ekki snerta neitt helgt og ekki ganga inn í helgidóminn, fyrr en dögum hreinsunar hennar er lokið.'),
(3050, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 12, 5, 'OT', 'Ef hún elur kvenkyns barn, skal hún vera óhrein tvær vikur, eins og á óhreinleika sínum; og sextíu og sex daga skal hún sitja í blóði hreinsunar.'),
(3051, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 12, 6, 'OT', 'Og þegar dagar hreinsunar hennar eru liðnir, fyrir son eða dóttur, skal hún færa lamb veturgamalt til brennifórnar og unga dúfu eða turtildúfu til syndar, að dyrum samfundatjaldsins, til prestsins.'),
(3052, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 12, 7, 'OT', 'Og hann skal bera það fram fyrir andliti Jahve og friðþægja fyrir hana, og hún hreinsast af uppsprettu blóðs síns. Þetta er lögmálið um þá sem fæðir, hvort sem það er karlkyns eða kvenkyns.'),
(3053, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 12, 8, 'OT', 'En ef hún hefur ekki nægt fé til lambs og hendi hennar nær ekki til þess, þá skal hún taka tvær turtildúfur eða tvær ungar dúfur, eina til brennifórnar og aðra til syndar, og presturinn skal friðþægja fyrir hana og hún skal hreinsast.'),
(3054, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 1, 'OT', 'Og Jahve talaði við Móses og við Aron og sagði:'),
(3055, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 2, 'OT', 'Ef maður hefur á skinni holds síns upphleypt, kláða eða bjartan blett, og það verður að holdsveiki á skinni holds síns, þá skal hann leiddur til Arons prests eða til eins af sonum hans, prestanna.'),
(3056, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 3, 'OT', 'Og presturinn skal skoða plágu á skinni holdsins; ef hárið í plágunni er orðið hvítt og sýnin á plágunni er dýpri en skinn holdsins, þá er það holdsveiki; og presturinn skal úrskurða hann óhreinan.'),
(3057, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 4, 'OT', 'En ef blettur er hvítur á skinni holds hans, og útlit hans er ekki dýpra en skinnið og hárið hefur ekki snúist hvítt, þá skal presturinn loka plágunni inni í sjö daga.'),
(3058, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 5, 'OT', 'Og presturinn skal skoða hann á sjöunda degi, og ef plágan er óbreytt í augum hans og hefur ekki breiðst út á skinninu, þá skal hann loka hann inni í sjö daga í annað sinn.'),
(3059, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 6, 'OT', 'Og presturinn skal skoða hann aftur á sjöunda degi, og sjá, ef plágan er daufari og hefur ekki breiðst út á skinninu, þá skal presturinn úrskurða hann hreinan; það er útbrot. Hann skal þvo klæði sín og vera hreinn.'),
(3060, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 7, 'OT', 'En ef útbrotið breiðist út á skinninu eftir að hann hefur sýnt sig presti til hreinsunar sinnar, skal hann sýna sig presti aftur.'),
(3061, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 8, 'OT', 'Og presturinn skal skoða, og sjá, ef útbrotið hefur breiðst út á skinninu, þá skal presturinn úrskurða hann óhreinan; það er holdsveiki.'),
(3062, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 9, 'OT', 'Þegar plága holdsveikinnar er á manni, skal hann leiddur til prestsins.'),
(3063, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 10, 'OT', 'Og presturinn skal skoða, og sjá, ef hvít upphefð er á skinninu og hún hefur snúið hárinu hvítt og lifandi hold er í upphefðinni.'),
(3064, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 11, 'OT', 'Það er langvinn holdsveiki í skinni holdsins; presturinn skal úrskurða hann óhreinan, og ekki loka hann inni, því að hann er óhreinn.'),
(3065, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 12, 'OT', 'En ef holdsveikin brýst út á skinninu og hylur allt skinn plágunnar frá höfði til fóta, eins og augu prestsins sjá.'),
(3066, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 13, 'OT', 'Þá skal presturinn skoða, og sjá, ef holdsveikin hefur hulið allt hold hans, þá skal hann úrskurða plágunnar hreina, því hún hefur öll snúist hvít; hann er hreinn.'),
(3067, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 14, 'OT', 'Á þeim degi sem lifandi hold sést á honum, skal hann verða óhreinn.'),
(3068, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 15, 'OT', 'Og presturinn skal skoða lifandi holdið og úrskurða það óhreint; lifandi holdið er óhreint, það er holdsveiki.'),
(3069, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 16, 'OT', 'Eða ef lifandi holdið snýr aftur og verður hvítt, þá skal hann koma til prestsins.'),
(3070, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 17, 'OT', 'Og presturinn skal skoða hann, og sjá, ef plágan hefur snúist hvít, þá skal presturinn úrskurða plágunnar hreina; hún er hrein.'),
(3071, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 18, 'OT', 'Ef á holdinu er kýli í skinninu og það grær,'),
(3072, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 19, 'OT', 'og ef á staðnum þar sem kýlið var kemur hvít upphefð eða hvítur rauðleitur blettur, þá skal hann koma til prestsins.'),
(3073, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 20, 'OT', 'Og presturinn skal skoða, og sjá, ef útlit hennar er lægra en skinnið og hárið hefur snúist hvítt, þá skal presturinn úrskurða hann óhreinan; holdsveiki er brotin út úr kýlinu.'),
(3074, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 21, 'OT', 'En ef presturinn sér að ekki er hvítt hár í henni og hún er ekki lægri en skinnið og er dauf, þá skal hann loka hann inni í sjö daga.'),
(3075, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 22, 'OT', 'Og ef hún breiðist út á skinninu, þá skal presturinn úrskurða hann óhreinan; það er plága.'),
(3076, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 23, 'OT', 'En ef blettur stendur kyrr undir kýlinu og breiðist ekki út, þá er það bruni eftir kýlið, og presturinn skal úrskurða hann hreinan.'),
(3077, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 24, 'OT', 'Eða ef hold er með bruna af eldi á skinninu, og lifandi holdið í brunanum verður að hvítum, rauðleitum bletti eða hvítum bletti.'),
(3078, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 25, 'OT', 'Og presturinn skal skoða hann, og sjá, ef hárið í blettinum er orðið hvítt og útlitið er dýpra en skinnið, þá er það holdsveiki sem brotist hefur út í brunanum; presturinn skal úrskurða hann óhreinan; það er plága holdsveikinnar.'),
(3079, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 26, 'OT', 'En ef presturinn sér að ekki er hvítt hár í blettinum og hann er ekki lægri en skinnið og er dauf, þá skal hann loka hann inni í sjö daga.'),
(3080, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 27, 'OT', 'Og presturinn skal skoða hann á sjöunda degi, og ef hann hefur breiðst út á skinninu, þá skal presturinn úrskurða hann óhreinan; það er holdsveiki.'),
(3081, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 28, 'OT', 'En ef blettur stendur kyrr og breiðist ekki út á skinninu og er dauf, þá er það upphefð brunans; presturinn skal úrskurða hann hreinan, því að það er bruni.'),
(3082, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 29, 'OT', 'Ef maður eða kona hefur plágu á höfði eða skeggi.'),
(3083, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 30, 'OT', 'Og presturinn skal skoða plágu, og sjá, ef hún er dýpri en skinnið og gult þunnt hár er í henni, þá skal presturinn úrskurða hann óhreinan; það er hrúður, holdsveiki á höfði eða skeggi.'),
(3084, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 31, 'OT', 'Og ef presturinn sér plágu hrúðursins, og hún er ekki dýpri en skinnið og enginn svartur hár er í henni, þá skal presturinn loka plágu hrúðursins inni í sjö daga.'),
(3085, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 32, 'OT', 'Og presturinn skal skoða plágu á sjöunda degi, og ef hrúðrið hefur ekki breiðst út og ekkert gult hár er í því, og útlit hrúðursins er ekki dýpra en skinnið,'),
(3086, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 33, 'OT', 'þá skal hann raka sig, en hrúðrið skal hann ekki raka; og presturinn skal loka hrúðrinu inni í sjö daga í annað sinn.'),
(3087, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 34, 'OT', 'Og presturinn skal skoða hrúðrið á sjöunda degi, og sjá, ef hrúðrið hefur ekki breiðst út á skinninu og útlit þess er ekki dýpra en skinnið, þá skal presturinn úrskurða hann hreinan, og hann skal þvo klæði sín og verða hreinn.'),
(3088, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 35, 'OT', 'En ef hrúðrið breiðist út á skinninu eftir hreinsun hans,'),
(3089, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 36, 'OT', 'þá skal presturinn skoða hann, og sjá, ef hrúðrið hefur breiðst út á skinninu; þá skal presturinn ekki leita að gulu hári, því hann er óhreinn.'),
(3090, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 37, 'OT', 'En ef hrúðrið er kyrrt í augum hans og svart hár hefur vaxið í því, þá hefur hrúðrið gróið; hann er hreinn, og presturinn skal úrskurða hann hreinan.'),
(3091, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 38, 'OT', 'Ef maður eða kona hefur á skinni holds síns bletti, bjarta, hvíta bletti.'),
(3092, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 39, 'OT', 'Og presturinn skal skoða, og sjá, ef á skinni holds þeirra eru daufir hvítir blettir, þá er það freknublett, sem sprottið hefur upp á skinninu; hann er hreinn.'),
(3093, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 40, 'OT', 'Og ef maður missir hár á höfði sínu, þá er hann sköllóttur; hann er hreinn.'),
(3094, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 41, 'OT', 'Og ef hann missir hár frá horni andlitsins á höfði sínu, þá er hann skalli á enni; hann er hreinn.'),
(3095, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 42, 'OT', 'En ef á skallanum á höfði eða á skallanum á enni er hvít rauðleit plága, þá er það holdsveiki sem sprottin er upp úr skallanum.'),
(3096, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 43, 'OT', 'Og presturinn skal skoða hann, og sjá, ef upphefðin á skallanum á höfði eða enni er hvítrauð, eins og útlit holdsveikinnar á skinni holdsins;'),
(3097, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 44, 'OT', 'maðurinn er holdsveikur, hann er óhreinn; presturinn skal úrskurða hann óhreinan; plágan er á höfði hans.'),
(3098, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 45, 'OT', 'Hinn holdsveiki, sem plágan er á, skal hafa rifin klæði sín, höfuðið ber og hylja yfirskeggið, og hrópa: Óhreinn, óhreinn!'),
(3099, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 46, 'OT', 'Allan þann tíma sem plágan er á honum skal hann vera óhreinn; hann skal búa í einveru, utan herbúðanna, bústað sinn.'),
(3100, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 47, 'OT', 'Og ef í klæði er plága holdsveikinnar, í klæði úr ull eða úr hör,'),
(3101, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 48, 'OT', 'Eða í ívafi eða í blönduðum lýð, í hör eða ull, eða í skinni, eða í sérhverju skinnastarfi.'),
(3102, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 49, 'OT', 'Og ef plágan er grænleit eða rauðleit í klæði, í skinni, í ívafi, í blönduðum lýð eða í sérhverju skinnáhaldi, þá er það holdsveiki; skal sýna prestinum það.'),
(3103, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 50, 'OT', 'Og presturinn skal skoða plágu og loka henni inni í sjö daga.'),
(3104, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 51, 'OT', 'Og á sjöunda degi skal hann skoða plágu, og ef plágan hefur breiðst út í klæðinu, ívafinu, blönduðum lýð, skinninu eða sérhverju starfi úr skinni, þá er það illkynja holdsveiki; plágan er óhrein.'),
(3105, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 52, 'OT', 'Og hann skal brenna klæðið eða ívafið eða blandaðan lýð, hvort sem það er úr ull eða hör, eða sérhvert skinnáhald sem plágan er á; því að það er illkynja holdsveiki; það skal brenna í eldi.'),
(3106, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 53, 'OT', 'En ef presturinn sér að plágan hefur ekki breiðst út í klæðinu, ívafinu, blönduðum lýð eða í sérhverju skinnáhaldi,'),
(3107, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 54, 'OT', 'þá skal presturinn skipa að þvo það sem plágan er á, og loka því inni í sjö daga í annað sinn.'),
(3108, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 55, 'OT', 'Og presturinn skal skoða eftir að það hefur verið þvegið, og sjá, ef plágan hefur ekki breytt um útlit í auga hans, og plágan hefur ekki breiðst út, þá er hún óhrein; þú skalt brenna hana í eldi; það er dæld, hvort sem er á skalla hans eða enni.'),
(3109, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 56, 'OT', 'Og ef presturinn sér að plágan er daufari eftir að hún hefur verið þvegin, þá skal hann rífa hana úr klæðinu, skinninu, ívafinu eða blönduðum lýð.'),
(3110, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 57, 'OT', 'En ef hún sést aftur í klæðinu, ívafinu, blönduðum lýð eða í sérhverju skinnáhaldi, þá er hún útbrot; þú skalt brenna í eldi það sem plágan er á.'),
(3111, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 58, 'OT', 'Og klæðið eða ívafið eða blandaðan lýð eða sérhvert skinnáhald sem þú þværð, og ef plágan víkur frá því, skal þvo það aftur, og þá er það hreint.'),
(3112, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 13, 59, 'OT', 'Þetta er lögmálið um plágu holdsveikinnar í klæði af ull eða hör, í ívafi eða blönduðum lýð, eða í sérhverju skinnáhaldi, til að úrskurða það hreint eða óhreint.'),
(3113, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(3114, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 2, 'OT', 'Þetta skal vera lögmálið um hinn holdsveika á hreinsunardegi hans: hann skal leiddur til prestsins.'),
(3115, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 3, 'OT', 'Og presturinn skal ganga út fyrir herbúðirnar og skoða, og sjá, ef plága holdsveikinnar hefur gróið á hinum holdsveika.'),
(3116, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 4, 'OT', 'Og presturinn skal skipa að taka fyrir þann sem hreinsast skal tvo lifandi hreina fugla, tré úr sedrusviði, skarlat og ísóp.'),
(3117, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 5, 'OT', 'Og presturinn skal skipa að slátra öðrum fuglinum í áhaldi úr leirkeri, yfir lifandi vatni.'),
(3118, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 6, 'OT', 'Hinn lifandi fugl skal hann taka, tréð úr sedrusviði, skarlatið og ísópinn, og dýfa þeim og lifandi fuglinum í blóð hins slátraða fugls yfir lifandi vatni.'),
(3119, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 7, 'OT', 'Og hann skal stökkva á þann sem hreinsast skal af holdsveikinni sjö sinnum, og lýsa hann hreinan, og láta lifandi fuglinn lausan út á andlit akursins.'),
(3120, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 8, 'OT', 'Og sá sem hreinsast skal þvo klæði sín, raka af sér allt hár og þvo sig í vatni, og verða hreinn; eftir það skal hann koma inn í herbúðirnar og búa sjö daga utan við tjald sitt.'),
(3121, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 9, 'OT', 'Og á sjöunda degi skal hann raka af sér allt hár: höfuðið, skeggið, augabrúnirnar og allt hár sitt. Hann skal þvo klæði sín og þvo hold sitt í vatni, og verða hreinn.'),
(3122, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 10, 'OT', 'Og á áttunda degi skal hann taka tvö gallalaus lömb og eina veturgamla lambsgimbur, gallalausa, og þrjá tíunda hluta af fínu mjöli, blönduðu með olíu, sem matfórn, og einn log olíu.'),
(3123, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 11, 'OT', 'Og presturinn sem hreinsar skal leiða manninn sem hreinsast skal og þessa hluti fyrir andliti Jahve, að inngangi tjaldsins.'),
(3124, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 12, 'OT', 'Og presturinn skal taka annað lambið og færa það sem sektarfórn ásamt logi olíu; hann skal veifa þeim sem veifufórn fyrir andliti Jahve.'),
(3125, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 13, 'OT', 'Og hann skal slátra lambinu þar sem slátrað er syndafórn og brennifórn, á helgum stað; því að eins og synd er sektarfórnin hlutur prestsins; hún er helgi.'),
(3126, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 14, 'OT', 'Og presturinn skal taka af blóði sektarfórnarinnar og setja á hægri eyrnasnepil þess sem hreinsast skal, á þumalfingur hægri handar hans og á stóru tá hægri fótar hans.'),
(3127, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 15, 'OT', 'Og presturinn skal taka af logi olíunnar og hella á vinstri lófa prestsins.'),
(3128, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 16, 'OT', 'Og presturinn skal dýfa hægri fingri sínum í olíuna sem er á vinstri lófa hans og stökkva af olíunni með fingrinum sjö sinnum fyrir andliti Jahve.'),
(3129, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 17, 'OT', 'Af þeirri olíu sem eftir er á lófa hans skal presturinn setja á hægri eyrnasnepil þess sem hreinsast skal, á þumalfingur hægri handar hans og á stóru tá hægri fótar hans, ofan á blóðið af sektarfórninni.'),
(3130, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 18, 'OT', 'Og það sem eftir er af olíunni á lófa prestsins skal hann setja á höfuð þess sem hreinsast skal; og presturinn skal friðþægja fyrir hann fyrir andliti Jahve.'),
(3131, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 19, 'OT', 'Og presturinn skal færa fórn fyrir synd og friðþægja fyrir þann sem hreinsast skal af óhreinleika hans; að því loknu skal hann slátra brennifórninni.'),
(3132, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 20, 'OT', 'Og presturinn skal færa brennifórnina og fórnina ásamt matfórninni á altari, og friðþægja fyrir hann; og hann verður hreinn.'),
(3133, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 21, 'OT', 'En ef hann er fátækur og hönd hans nær ekki til, þá skal hann taka eitt lamb sem sektarfórn, veifa því sem veifufórn og friðþægja fyrir sig, og tíunda hluta af fínu mjöli blönduðu með olíu sem fórn, og einn log olíu.'),
(3134, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 22, 'OT', 'Og tvær turtildúfur eða tvær ungar dúfur, sem hönd hans nær til; önnur skal vera fórn fyrir synd og hin brennifórn.'),
(3135, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 23, 'OT', 'Og hann skal færa þær á áttunda degi til hreinsunar sinnar, til prestsins, að inngangi tjaldsins, fyrir andliti Jahve.'),
(3136, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 24, 'OT', 'Og presturinn skal taka lamb sektarfórnarinnar og logi olíu og veifa þeim fyrir andliti Jahve sem veifufórn.'),
(3137, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 25, 'OT', 'Og hann skal slátra lambi sektarfórnarinnar, og presturinn skal taka af blóðinu af sektarfórninni og setja á hægri eyrnasnepil þess sem hreinsast skal, á þumalfingur hægri handar hans og á stóru tá hægri fótar hans.'),
(3138, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 26, 'OT', 'Og af olíunni skal presturinn hella á vinstri lófa prestsins.'),
(3139, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 27, 'OT', 'Og presturinn skal stökkva með hægri fingri sínum af olíunni sem er á vinstri lófa hans sjö sinnum fyrir andliti Jahve.'),
(3140, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 28, 'OT', 'Og presturinn skal setja af olíunni sem er á lófa hans á hægri eyrnasnepil þess sem hreinsast skal, á þumalfingur hægri handar hans og á stóru tá hægri fótar hans, á stað blóðs sektarfórnarinnar.'),
(3141, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 29, 'OT', 'Og það sem eftir er af olíunni á lófa prestsins skal hann setja á höfuð þess sem hreinsast skal, til að friðþægja fyrir hann fyrir andliti Jahve.'),
(3142, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 30, 'OT', 'Og hann skal færa aðra af turtildúfum eða af ungum dúfum, eftir því sem hönd hans nær.'),
(3143, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 31, 'OT', 'Eins og hönd hans nær, aðra sem fórn fyrir synd og hina sem brennifórn ásamt fórninni; og presturinn skal friðþægja fyrir þann sem hreinsast skal fyrir andliti Jahve.'),
(3144, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 32, 'OT', 'Þetta er lögmálið um þann sem hefur plágu holdsveiki og hönd hans nær ekki til hreinsunar sinnar.'),
(3145, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 33, 'OT', 'Og Jahve talaði við Móses og við Aron og sagði:'),
(3146, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 34, 'OT', 'Þegar þér komið inn í landið Kanaan, sem ég gef yður til eignar, þá legg ég plágu holdsveikinnar á hús í jörð eignar yðar.'),
(3147, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 35, 'OT', 'Og sá sem húsið á skal koma og segja prestinum: Eins og plága hefur birst mér í húsinu.'),
(3148, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 36, 'OT', 'Og presturinn skal skipa að tæma húsið áður en presturinn kemur til að skoða plágu, svo að ekkert sem í húsinu er verði óhreint; og eftir það skal presturinn koma til að skoða húsið.'),
(3149, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 37, 'OT', 'Og hann skal skoða plágu, og sjá, ef á veggjum hússins eru grænleitar eða rauðleitar dældir, og útlit þeirra er lægra en veggurinn.'),
(3150, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 38, 'OT', 'Og presturinn skal ganga út úr húsinu að inngangi hússins og loka húsinu inni í sjö daga.'),
(3151, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 39, 'OT', 'Og presturinn skal koma aftur á sjöunda degi og líta eftir, og sjá, plágan hefur breiðst út á veggjum hússins.'),
(3152, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 40, 'OT', 'Presturinn býður að menn losi steinana þar sem plágan er og kasti þeim út fyrir borgina á óhreinan stað.'),
(3153, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 41, 'OT', 'Húsið skal skafið allt í kring að innanverðu, og moldina sem skafin er af skulu þeir hella út fyrir borgina á óhreinan stað.'),
(3154, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 42, 'OT', 'Þeir skulu taka aðra steina og setja í stað steinanna, og taka aðra mold og pússa húsið.'),
(3155, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 43, 'OT', 'En ef plágan kemur aftur og breiðist út í húsinu eftir að steinarnir hafa verið teknir út og eftir að húsið hefur verið skafið og pússað,'),
(3156, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 44, 'OT', 'Þá skal presturinn koma og líta eftir, og sjá, plágan hefur breiðst út í húsinu. Þetta er skæð holdsveiki í húsinu; það er óhreint.'),
(3157, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 45, 'OT', 'Hann skal rífa niður húsið, steina þess, tré þess og alla moldina úr húsinu, og fara með það út fyrir borgina á óhreinan stað.'),
(3158, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 46, 'OT', 'Sá sem gengur inn í húsið alla þá daga sem það er lokað skal vera óhreinn til kvölds.'),
(3159, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 47, 'OT', 'Sá sem sefur í húsinu skal þvo klæði sín, og sá sem etur í húsinu skal þvo klæði sín.'),
(3160, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 48, 'OT', 'En ef presturinn kemur og lítur eftir, og sjá, plágan hefur ekki breiðst út í húsinu eftir að húsið var pússað, þá skal presturinn lýsa húsið hreint, því að plágan er læknuð.'),
(3161, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 49, 'OT', 'Til að hreinsa húsið skal hann taka tvo fugla, sedrusvið, skarlat og ísóp.'),
(3162, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 50, 'OT', 'Hann skal slátra annan fuglinn í leirkeri yfir lifandi vatni.'),
(3163, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 51, 'OT', 'Hann skal taka sedrusviðinn, ísópinn, skarlatið og lifandi fuglinn og dýfa þeim í blóð slátraða fuglsins og í lifandi vatn, og strá því sjö sinnum á húsið.'),
(3164, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 52, 'OT', 'Hann skal hreinsa húsið með blóði fuglsins, með lifandi vatninu, með lifandi fuglinum, með sedrusviði, ísóp og skarlati.'),
(3165, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 53, 'OT', 'Hann skal láta lifandi fuglinn fljúga út fyrir borgina, út á akurinn frammi fyrir andliti akursins, og gera friðþægingu fyrir húsið, og það skal vera hreint.'),
(3166, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 54, 'OT', 'Þetta er lögmálið um hverja plágu holdsveikinnar og hrúðrið,'),
(3167, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 55, 'OT', 'og um holdsveiki í klæði og í húsi,'),
(3168, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 56, 'OT', 'og um upphefð, kláða og blett.'),
(3169, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 14, 57, 'OT', 'Þetta er lögmálið um holdsveiki, til að kenna á óhreinum degi og á hreinum degi.'),
(3170, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 1, 'OT', 'Og Jahve talaði við Móses og Aron og sagði:'),
(3171, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 2, 'OT', 'Talið við sonu Ísraels og segið við þá: Ef einhver maður hefur útferð úr holdi sínu, er útferð hans óhrein.'),
(3172, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 3, 'OT', 'Þetta er óhreinleiki hans vegna útferðar hans: hvort sem hold hans lekur af útferð sinni eða hold hans stíflast af útferð hans, þá er það óhreinleiki hans.'),
(3173, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 4, 'OT', 'Sérhver hvíla sem sá sem hefur útferð liggur á er óhrein, og sérhvert áhald sem hann situr á er óhreint.'),
(3174, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 5, 'OT', 'Maðurinn sem snertir hvílu hans skal þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3175, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 6, 'OT', 'Sá sem situr á áhaldi sem hinn óhreini hefur setið á skal þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3176, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 7, 'OT', 'Sá sem snertir hold hins óhreina skal þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3177, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 8, 'OT', 'Ef sá sem hefur útferðina hrækir á hreinan mann, skal hann þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3178, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 9, 'OT', 'Sérhver vagn sem sá sem hefur útferð ekur í er óhreinn.'),
(3179, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 10, 'OT', 'Sá sem snertir eitthvað sem var undir honum skal vera óhreinn til kvölds, og sá sem ber það skal þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3180, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 11, 'OT', 'Sá sem hinn óhreini snertir, án þess að hafa þvegið hendur sínar í vatni, skal þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3181, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 12, 'OT', 'Leirkerið sem hinn óhreini snertir skal brotið; hvert áhald úr tré skal þvegið í vatni.'),
(3182, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 13, 'OT', 'Þegar hinn óhreini hreinsast af útferð sinni, skal hann telja sjö daga til hreinsunar sinnar, þvo klæði sín og baða hold sitt í lifandi vatni, og þá er hann hreinn.'),
(3183, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 14, 'OT', 'Á áttunda degi skal hann taka tvær turtildúfur eða tvo unga dúfna, koma frammi fyrir andliti Jahve að inngangi tjaldsins, samfundatjaldsins, og afhenda prestinum þær.'),
(3184, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 15, 'OT', 'Presturinn skal færa annan sem fórn fyrir synd og hinn sem brennifórn, og gera friðþægingu fyrir hann frammi fyrir andliti Jahve vegna útferðar hans.'),
(3185, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 16, 'OT', 'Ef maður losar samræði sæðis úr sér, skal hann þvo allt hold sitt í vatni og vera óhreinn til kvölds.'),
(3186, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 17, 'OT', 'Hvert klæði og hvert skinn sem sæði er á skal þvegið í vatni og er óhreint til kvölds.'),
(3187, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 18, 'OT', 'Ef maður liggur með konu og sæði fer úr honum, skulu þau baða sig í vatni og vera óhrein til kvölds.'),
(3188, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 19, 'OT', 'Ef kona hefur blóð sem rennur úr holdi hennar, skal hún vera í óhreinleika sínum sjö daga; hver sem snertir hana er óhreinn til kvölds.'),
(3189, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 20, 'OT', 'Allt sem hún leggst á í óhreinleika sínum er óhreint, og allt sem hún situr á er óhreint.'),
(3190, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 21, 'OT', 'Sá sem snertir hvílu hennar skal þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3191, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 22, 'OT', 'Sá sem snertir hvað sem er á áhaldi sem hún situr á skal þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3192, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 23, 'OT', 'Ef hann er á hvílu eða áhaldi sem hún situr á, þegar hann snertir það, er hann óhreinn til kvölds.'),
(3193, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 24, 'OT', 'Ef maður liggur með henni og óhreinleiki hennar kemst á hann, skal hann vera óhreinn í sjö daga, og sérhver hvíla sem hann liggur á er óhrein.'),
(3194, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 25, 'OT', 'Ef kona fær blóðrás í marga daga utan tíma tíða sinna, eða yfir tíðir sínar, þá er hún óhrein alla daga blóðrásar sinnar eins og á dögum tíða sinna.'),
(3195, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 26, 'OT', 'Sérhver hvíla sem hún liggur á alla daga blóðrásar sinnar skal vera eins og hvílan á dögum tíða hennar, og sérhvert áhald sem hún situr á skal vera óhreint eins og óhreinleiki tíða hennar.'),
(3196, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 27, 'OT', 'Sá sem snertir þessa skal vera óhreinn; hann skal þvo klæði sín og baða sig í vatni og vera óhreinn til kvölds.'),
(3197, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 28, 'OT', 'Og ef hún hreinsast af útferð sinni, skal hún telja sér sjö daga, og eftir það er hún hrein.'),
(3198, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 29, 'OT', 'Á áttunda degi skal hún taka tvær turtildúfur eða tvo unga dúfna og færa þær prestinum að inngangi tjaldsins, samfundatjaldsins.'),
(3199, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 30, 'OT', 'Presturinn skal færa annan sem fórn fyrir synd og hinn sem brennifórn, og gera friðþægingu fyrir hana frammi fyrir andliti Jahve vegna útferðar og óhreinleika hennar.'),
(3200, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 31, 'OT', 'Þannig skuluð þið aðskilja sonu Ísraels frá óhreinleika þeirra, svo að þeir deyi ekki í óhreinleika sínum, ef þeir saurga bústað minn sem er meðal þeirra.'),
(3201, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 32, 'OT', 'Þetta er lögmálið um þann sem hefur útferð og um þann sem samræði sæðis fer úr, svo að hann verði óhreinn af því.'),
(3202, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 15, 33, 'OT', 'Þetta gildir um konu í óhreinleika hennar, um þann sem hefur útferð, bæði um karlkyns og kvenkyns, og um mann sem liggur með óhreinni konu.'),
(3203, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 1, 'OT', 'Og Jahve talaði við Móses eftir dauða tveggja sona Arons, þegar þeir nálguðust fyrir andlit Jahve og dóu.'),
(3204, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 2, 'OT', 'Og Jahve sagði við Móses: Talaðu við Aron bróður þinn, og hann skal ekki ganga á hverjum tíma inn í helgidóminn innan fortjaldsins, fyrir framan náðarstólinn sem er á örkinni, svo að hann deyi ekki; því að í skýi mun ég birtast yfir náðarstólnum.'),
(3205, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 3, 'OT', 'Þannig skal Aron ganga inn í helgidóminn: með ungnauti sem fórn fyrir synd, og með hrút sem brennifórn.'),
(3206, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 4, 'OT', 'Hann skal klæðast kyrtli úr hör, og nærbuxur úr hör skulu vera á holdi hans; hann skal gyrða sig belti úr hör og binda vefjarhött úr hör á höfuðið; þetta eru hin helgu klæði. Hann skal þvo hold sitt í vatni og klæðast þeim.'),
(3207, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 5, 'OT', 'Og af söfnuði Ísraels skal hann taka tvo geithafra sem fórn fyrir synd og einn hrút sem brennifórn.'),
(3208, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 6, 'OT', 'Aron skal færa ungnautið sem fórn fyrir synd, sem er hans, og gera friðþægingu fyrir sjálfan sig og fyrir hús sitt.'),
(3209, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 7, 'OT', 'Hann skal taka geithafrana tvo og stilla þeim fyrir andlit Jahve við inngangi tjaldsins, samfundatjaldsins.'),
(3210, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 8, 'OT', 'Aron skal kasta hlutkesti á geithafrana tvo: eitt hlutkesti fyrir Jahve og eitt hlutkesti fyrir Asasel.'),
(3211, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 9, 'OT', 'Aron skal færa geithafurinn sem hlutkestið féll á fyrir Jahve og gera hann að fórn fyrir synd.'),
(3212, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 10, 'OT', 'En geithafurinn sem hlutkestið féll á til Asasels skal standa lifandi fyrir andliti Jahve, til að gera friðþægingu með honum, og senda hann út í eyðimörkina til Asasels.'),
(3213, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 11, 'OT', 'Aron skal færa ungnautið, fórn fyrir synd sem er hans, og gera friðþægingu fyrir sjálfan sig og fyrir hús sitt, og slátra ungnautið sem er fórn fyrir synd hans.'),
(3214, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 12, 'OT', 'Hann skal taka eldpönnu fulla af glóðum elds af altarinu frammi fyrir andliti Jahve, og fullan lófa af reykelsi úr ilmjurtum, og bera það innan fortjaldsins.'),
(3215, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 13, 'OT', 'Hann skal leggja reykelsið á eldinn frammi fyrir andliti Jahve, og skýið af reykelsinu skal hylja náðarstólinn sem er yfir vitnisburðinum, svo að hann deyi ekki.'),
(3216, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 14, 'OT', 'Hann skal taka af blóði ungnautsins og strá með fingri sínum á framhlið náðarstólsins; frammi fyrir andliti náðarstólsins skal hann strá af blóðinu sjö sinnum með fingri sínum.'),
(3217, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 15, 'OT', 'Hann skal slátra geithafurinn sem fórn fyrir synd fyrir lýðinn og flytja blóð hans inn fyrir fortjaldið, og gera við blóð hans eins og hann gerði við blóð ungnautsins, og strá því á náðarstólinn og frammi fyrir andliti náðarstólsins.'),
(3218, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 16, 'OT', 'Svo skal hann friðþægja helgidóminn vegna óhreinleika Ísraels og vegna afbrota þeirra og allra synda þeirra; og eins skal hann gera fyrir tjaldið, samfundatjaldið, sem er hjá þeim meðal óhreinleika þeirra.'),
(3219, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 17, 'OT', 'Enginn maður skal vera í tjaldinu, samfundatjaldinu, þegar hann gengur inn til að friðþægja í helgidóminum, þar til hann kemur út; og hann skal friðþægja fyrir sjálfan sig, fyrir hús sitt og fyrir allan söfnuð Ísraels.'),
(3220, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 18, 'OT', 'Og hann skal ganga út að altarinu sem er fyrir andliti Jahve og friðþægja fyrir það, og taka af blóði ungnautsins og blóði geithafursins og setja á horn altarisins allt í kring.'),
(3221, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 19, 'OT', 'Og hann skal strá á það af blóðinu með fingri sínum sjö sinnum, hreinsa það og helga það frá óhreinleika Ísraelsmanna.'),
(3222, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 20, 'OT', 'Þegar hann hefur lokið friðþægingu fyrir helgidóminn, tjaldið, samfundatjaldið og altarið, skal hann færa lifandi geithafurinn.'),
(3223, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 21, 'OT', 'Aron skal leggja báðar hendur sínar á höfuð lifandi geithafursins, játa yfir honum allar misgjörðir Ísraels og allt afbrot þeirra og allar syndir þeirra, og leggja þær á höfuð geithafursins og senda hann með manni, sem hefur verið valinn, út í eyðimörkina.'),
(3224, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 22, 'OT', 'Og geithafurinn skal bera á sér allar misgjörðir þeirra til óbyggðrar jarðar, og hann skal senda geithafurinn út í eyðimörkina.'),
(3225, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 23, 'OT', 'Aron skal ganga inn í tjaldið, samfundatjaldið, og skal fara úr klæðum úr hör sem hann var í þegar hann gekk inn í helgidóminn, og leggja þau þar.'),
(3226, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 24, 'OT', 'Hann skal þvo hold sitt í vatni á helgum stað, klæðast klæðum sínum og fara út, og færa brennifórn sína og brennifórn lýðsins, og gera friðþægingu fyrir sjálfan sig og fyrir lýðinn.'),
(3227, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 25, 'OT', 'Og fitu fórnarinnar fyrir synd skal hann brenna á altarinu.'),
(3228, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 26, 'OT', 'Sá sem sendir geithafurinn til Asasels skal þvo klæði sín og þvo hold sitt í vatni, og eftir það skal hann ganga inn í herbúðirnar.'),
(3229, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 27, 'OT', 'Ungnautið og geithafurinn, sem fórn fyrir synd, sem blóð þeirra var borið inn í helgidóminn til friðþægingar, skulu færð út fyrir herbúðirnar, og skinn þeirra, hold þeirra og saur þeirra skulu brennd í eldi.'),
(3230, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 28, 'OT', 'Sá sem brennir þá skal þvo klæði sín og þvo hold sitt í vatni, og eftir það skal hann ganga inn í herbúðirnar.'),
(3231, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 29, 'OT', 'Þetta skal vera ykkur lagaákvæði til eilífðar: í sjöunda mánuði, á tíunda degi mánaðarins, skuluð þið þjá sálir ykkar, og ekkert starf skal unnið, hvorki af innfæddum manni né útlendingnum sem dvelur meðal ykkar.'),
(3232, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 30, 'OT', 'Því að á þessum degi skal hann friðþægja fyrir ykkur, til að hreinsa ykkur af öllum syndum ykkar; frammi fyrir andliti Jahve munuð þið hreinsast.'),
(3233, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 31, 'OT', 'Það er ykkur hvíldardagur, hvíldardagur, og þið skuluð þjá sálir ykkar; það er lagaákvæði til eilífðar.'),
(3234, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 32, 'OT', 'Presturinn sem er smurður og sá sem fyllir hönd sína til að gegna prestsembætti í stað föður síns skal friðþægja og klæðast klæðum úr hör, hinum helgu klæðum.'),
(3235, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 33, 'OT', 'Hann skal friðþægja helgidóminn, tjaldið, samfundatjaldið og altarið, og fyrir prestana og allan lýðinn, og fyrir söfnuðinn.'),
(3236, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 16, 34, 'OT', 'Þetta skal vera ykkur lagaákvæði til eilífðar, til að friðþægja fyrir sonu Ísraels af öllum syndum þeirra einu sinni á ári. Og Móses gerði eins og Jahve bauð.'),
(3237, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(3238, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 2, 'OT', 'Talaðu við Aron og sonu hans og alla sonu Ísraels og segðu við þá: Þetta er orðið sem Jahve bauð og sagði:'),
(3239, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 3, 'OT', 'Sérhver maður af húsi Ísraels sem slátrar naut, lamb eða geit í herbúðum eða utan herbúðanna,'),
(3240, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 4, 'OT', 'Sá sem færir ekki það að inngangi tjaldsins, samfundatjaldsins, til að færa fórnargjöf fyrir Jahve frammi fyrir andliti bústaðar Jahve, honum skal blóð reiknast; hann hefur úthellt blóði, og maðurinn skal upprættur úr lýð sínum.'),
(3241, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 5, 'OT', 'Til þess að synir Ísraels færi sláturfórnir sínar, sem þeir færa á akrinum, og færi þær Jahve að inngangi tjaldsins, samfundatjaldsins, til prestsins, og fórni þakkarfórnir Jahve.'),
(3242, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 6, 'OT', 'Og presturinn skal stökkva blóðinu á altari Jahve við inngangi tjaldsins, samfundatjaldsins, og brenna fitu sem ljúfan ilm fyrir Jahve.'),
(3243, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 7, 'OT', 'Og þeir skulu ekki framar færa sláturfórnum sínum til geithafra sem þeir leika sér við; þetta skal vera þeim lagaákvæði til eilífðar, frá kynslóð til kynslóðar.'),
(3244, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 8, 'OT', 'Og þú skalt segja við þá: Sérhver maður af húsi Ísraels og útlendingurinn sem dvelur meðal þeirra, sem færir brennifórn eða sláturfórn,'),
(3245, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 9, 'OT', 'og færir hana ekki að inngangi tjaldsins, samfundatjaldsins, til að gera hana Jahve, þá skal maðurinn upprættur úr lýð sínum.'),
(3246, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 10, 'OT', 'Og hvern þann mann af húsi Ísraels og útlendings sem dvelur meðal þeirra og etur nokkurt blóð, gegn þeirri sál sem etur blóðið mun ég snúa andliti mínu og uppræta hana úr lýð sínum.'),
(3247, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 11, 'OT', 'Því að sál holdsins er í blóðinu, og ég hef gefið ykkur það á altarið til að friðþægja fyrir sálir ykkar, því að það er blóðið sem friðþægir með sálinni.'),
(3248, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 12, 'OT', 'Þess vegna hef ég sagt við sonu Ísraels: Engin sál af ykkur skal eta blóð, og útlendingurinn sem dvelur meðal ykkar skal ekki eta blóð.'),
(3249, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 13, 'OT', 'Og hver sá maður af sonum Ísraels eða af útlendingnum sem dvelur meðal þeirra, sem veiðir veiði eða fugl sem má eta, hann skal úthella blóði hans og hylja það með mold.'),
(3250, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 14, 'OT', 'Því að sál alls holds er blóð þess í sálinni, og ég sagði við sonu Ísraels: Þér skuluð ekki eta blóð alls holds, því að sál alls holds er blóð þess; sérhver sem etur það skal upprættur.'),
(3251, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 15, 'OT', 'Sérhver sál sem etur hræ eða bráð, hvort sem er af innfæddum manni eða útlendingi, skal þvo klæði sín og baða sig í vatni og vera óhrein til kvölds; síðan er hún hrein.'),
(3252, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 17, 16, 'OT', 'En ef hann þvær ekki klæði sín og baðar ekki hold sitt, skal hann bera misgjörð sína.'),
(3253, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(3254, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 2, 'OT', 'Talaðu við sonu Ísraels og segðu við þá: Ég er Jahve, Guð ykkar.'),
(3255, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 3, 'OT', 'Þið skuluð ekki breyta eftir verkum landsins Egyptalands þar sem þið bjugguð, og ekki eftir verkum landsins Kanaans þangað sem ég leiði ykkur, og þið skuluð ekki ganga í lagaákvæðum þeirra.'),
(3256, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 4, 'OT', 'Þið skuluð gera dóma mína og varðveita lagaákvæði mín og ganga eftir þeim; ég er Jahve, Guð ykkar.'),
(3257, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 5, 'OT', 'Og þið skuluð varðveita lagaákvæði mín og dóma mína; maðurinn sem gerir þá lifir í þeim. Ég er Jahve.'),
(3258, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 6, 'OT', 'Enginn maður skal nálgast neinn af sínu nánasta holdi til að afhjúpa nekt; ég er Jahve.'),
(3259, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 7, 'OT', 'Nekt föður þíns og nekt móður þinnar skalt þú ekki afhjúpa; hún er móðir þín, þú skalt ekki afhjúpa nekt hennar.'),
(3260, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 8, 'OT', 'Nekt konu föður þíns skalt þú ekki afhjúpa; það er nekt föður þíns.'),
(3261, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 9, 'OT', 'Nekt systur þinnar, dóttur föður þíns eða dóttur móður þinnar, hvort sem hún er fædd í húsi eða fædd úti, skalt þú ekki afhjúpa nekt hennar.'),
(3262, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 10, 'OT', 'Nekt dóttur sonar þíns og dóttur dóttur þinnar skalt þú ekki afhjúpa, því að það er þín nekt.'),
(3263, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 11, 'OT', 'Nekt dóttur konu föður þíns, sem fæddist föður þínum, hún er systir þín; þú skalt ekki afhjúpa nekt hennar.'),
(3264, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 12, 'OT', 'Nekt systur föður þíns skalt þú ekki afhjúpa; hún er hold föður þíns.'),
(3265, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 13, 'OT', 'Nekt systur móður þinnar skalt þú ekki afhjúpa, því að hún er hold móður þinnar.'),
(3266, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 14, 'OT', 'Nekt bróður föður þíns skalt þú ekki afhjúpa; þú skalt ekki nálgast konu hans; hún er föðursystir þín.'),
(3267, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 15, 'OT', 'Nekt brúðar þinnar skalt þú ekki afhjúpa; hún er kona sonar þíns; þú skalt ekki afhjúpa nekt hennar.'),
(3268, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 16, 'OT', 'Nekt konu bróður þíns skalt þú ekki afhjúpa; það er nekt bróður þíns.'),
(3269, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 17, 'OT', 'Nekt konu og dóttur hennar skalt þú ekki afhjúpa; dóttur sonar hennar og dóttur dóttur hennar skalt þú ekki taka til að afhjúpa nekt þeirra; þetta er náskyld kona; það er svívirða.'),
(3270, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 18, 'OT', 'Og konu skalt þú ekki taka til systur hennar, til að vera henni mótstæð, til að afhjúpa nekt hennar meðan hún lifir.'),
(3271, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 19, 'OT', 'Og þú skalt ekki nálgast konu í óhreinleika hennar, til að afhjúpa nekt hennar.'),
(3272, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 20, 'OT', 'Og þú skalt ekki láta legu þína í konu náunga þíns, svo að þú sáir sæði í hana og verðir óhreinn af henni.'),
(3273, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 21, 'OT', 'Og af sæði þínu skalt þú ekki láta neinn ganga í gegnum eld til Mólok, og þú skalt ekki vanhelga nafn Guðs þíns; ég er Jahve.'),
(3274, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 22, 'OT', 'Þú skalt ekki liggja með karlmanni í hvílum konu; það er viðurstyggð.'),
(3275, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 23, 'OT', 'Og þú skalt ekki gefa legu þína neinni skepnu og ekki verða óhreinn af henni; og kona skal ekki standa frammi fyrir andliti skepnu til að makast við hana; það er siðspilling.'),
(3276, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 24, 'OT', 'Þið skuluð ekki saurga ykkur með neinu af þessu, því að með þessu öllu hafa þjóðirnar saurgað sig, sem ég rek burt frammi fyrir andliti ykkar.'),
(3277, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 25, 'OT', 'Og jörðin saurgaðist, og ég vitjaði misgjörðar hennar á henni; og jörðin ældi út íbúa sína.'),
(3278, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 26, 'OT', 'Þið skuluð varðveita lagaákvæði mín og dóma mína og ekki gera neitt af þessum viðurstyggðum, hvorki innfæddur maður né útlendingur sem dvelur meðal ykkar.'),
(3279, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 27, 'OT', 'Því að allar þessar viðurstyggðir hafa mennirnir í jörðinni gert, sem voru frammi fyrir andliti ykkar, og jörðin saurgaðist.'),
(3280, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 28, 'OT', 'Og jörðin skal ekki æla ykkur út, þegar þið saurgið hana, eins og hún ældi út þjóðina sem var frammi fyrir andliti ykkar.'),
(3281, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 29, 'OT', 'Því að hver sá sem gerir eitthvað af þessum viðurstyggðum, þær sálir sem gera þær skulu upprættar úr lýð sínum.'),
(3282, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 18, 30, 'OT', 'Þið skuluð gæta varðstöðu minnar og ekki breyta eftir neinum af viðurstyggðum lagaákvæðum sem voru frammi fyrir andliti ykkar, og ekki saurga ykkur með þeim; ég er Jahve, Guð ykkar.'),
(3283, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(3284, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 2, 'OT', 'Talaðu við allan söfnuð sona Ísraels og segðu við þá: Verið heilagir, því að ég er heilagur, Jahve, Guð ykkar.'),
(3285, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 3, 'OT', 'Hver maður skal óttast móður sína og föður sinn, og halda hvíldardaga mína; ég er Jahve, Guð ykkar.'),
(3286, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 4, 'OT', 'Snúið ykkur ekki að hégómaguðum og gerið ykkur ekki steypt líkneski; ég er Jahve, Guð ykkar.'),
(3287, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 5, 'OT', 'Og þegar þið færið Jahve sláturfórn sem þakkarfórn, skuluð þið færa hana þannig að hún verði til velþóknunar.'),
(3288, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 6, 'OT', 'Á þeim degi sem þið færið hana skal hún etin, og á morgundegi; það sem eftir er af sláturfórninni til þriðja dags skal brennt í eldi.'),
(3289, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 7, 'OT', 'Og ef hún er etin á þriðja degi, er hún viðurstyggilegur matur; hún verður ekki þóknuð.'),
(3290, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 8, 'OT', 'Hver sem etur hana skal bera misgjörð sína, því að hann hefur vanhelgað helgi Jahve; sú sál skal upprætt úr lýð sínum.'),
(3291, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 9, 'OT', 'Og þegar þið uppskerið uppskeru jarðar ykkar, skuluð þið ekki uppskera alla leiðina út í horn akursins, og ekki tína eftirtíning uppskeru ykkar.'),
(3292, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 10, 'OT', 'Og víngarð þinn skalt þú ekki tæma, og vínber víngarðs þíns skalt þú ekki tína; þú skalt láta þau eftir fátækum og útlendingum; ég er Jahve, Guð ykkar.'),
(3293, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 11, 'OT', 'Þið skuluð ekki stela, ekki ljúga og ekki blekkja mann, náunga sinn.'),
(3294, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 12, 'OT', 'Og þið skuluð ekki sverja við nafn mitt með lygi, og vanhelga ekki nafn Guðs þíns; ég er Jahve.'),
(3295, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 13, 'OT', 'Þú skalt ekki kúga náunga þinn og ekki ræna; laun af verki skulu ekki dvelja hjá þér til morguns.'),
(3296, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 14, 'OT', 'Þú skalt ekki bölva heyrnarlausum og ekki leggja hneyksli frammi fyrir andliti blinds; þú skalt óttast Guð þinn; ég er Jahve.'),
(3297, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 15, 'OT', 'Þið skuluð ekki fremja ranglæti í dómi; þú skalt hvorki taka andlit fátæks né virða andlit hins mikla; í rétti skalt þú dæma náunga þinn.'),
(3298, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 16, 'OT', 'Þú skalt ekki ganga um sem rógberi meðal lýðs þíns, og þú skalt ekki standa gegn blóði náunga þíns; ég er Jahve.'),
(3299, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 17, 'OT', 'Þú skalt ekki hata bróður þinn í hjarta þínu; þú skalt áminna náunga þinn, og ekki bera synd á hann.'),
(3300, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 18, 'OT', 'Þú skalt ekki hefna þín né geyma reiði gegn sonum lýðs þíns; þú skalt elska náunga þinn eins og sjálfan þig; ég er Jahve.'),
(3301, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 19, 'OT', 'Lagaákvæði mín skuluð þér varðveita. Skepnu þína skalt þú ekki láta para sig við aðra tegund, og akur þinn skalt þú ekki sá með tvíblöndun; og klæði úr tvíblöndun, ullar- og línblöndu, skalt þú ekki bera.'),
(3302, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 20, 'OT', 'Ef maður hefur samræði við konu og lætur sæði sitt í hana, þar sem hún er ambátt ætluð öðrum manni og hefur hvorki verið leyst né henni veitt frelsi, þá skal refsa þeim með húðstrýkingu; þau skulu ekki deyja, því að hún var ekki frjáls.'),
(3303, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 21, 'OT', 'Hann skal bera sektarfórn sína fram fyrir Jahve, að inngangi samfundatjaldsins, hrút sem sektarfórn.'),
(3304, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 22, 'OT', 'Presturinn skal friðþægja fyrir hann með hrúti sem sektarfórn frammi fyrir Jahve vegna syndar hans; og honum skal fyrirgefið sú synd sem hann drýgði.'),
(3305, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 23, 'OT', 'Þegar þér komið inn í jörðina og gróðursetjið hvert tré sem gefur fæðu, þá skuluð þér telja ávöxt þess óumskorinn; þrjú ár skal hann vera yður óumskorinn og ekki etinn.'),
(3306, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 24, 'OT', 'En á fjórða ári skal allur ávöxtur þess vera helgi, lofgjörð fyrir Jahve.'),
(3307, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 25, 'OT', 'En á fimmta ári skuluð þér eta ávöxt þess, til þess að afurð hans aukist fyrir yður; ég er Jahve, Guð yðar.'),
(3308, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 26, 'OT', 'Þér skuluð ekki eta með blóði; þér skuluð ekki stunda galdra né seið.'),
(3309, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 27, 'OT', 'Þér skuluð ekki skera hárið við horn höfuðs yðar, og ekki eyða horn skeggs þíns.'),
(3310, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 28, 'OT', 'Þér skuluð ekki gera skurð í holdi yðar vegna sálar, og ekki gera á yður skriftarmerki. Ég er Jahve.'),
(3311, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 29, 'OT', 'Þú skalt ekki láta dóttur þína verða skækju, svo að jörðin falli ekki í saurlifnað og jörðin fyllist af svívirðu.'),
(3312, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 30, 'OT', 'Þér skuluð halda hvíldardaga mína og bera virðingu fyrir helgidómi mínum. Ég er Jahve.'),
(3313, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 31, 'OT', 'Snúið yður ekki til særingaanda og leitið ekki til spásagnarmanna, svo að þér óhreinkið yður við þá. Ég er Jahve, Guð yðar.'),
(3314, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 32, 'OT', 'Rís þú upp fyrir gráu hári og virð andlit gamals manns, og óttast Guð þinn. Ég er Jahve.'),
(3315, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 33, 'OT', 'Þegar útlendingur dvelur hjá yður í jörð yðar, skuluð þér ekki kúga hann.'),
(3316, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 34, 'OT', 'Útlendingurinn sem dvelur hjá yður skal vera yður eins og innfæddur maður meðal yðar, og þú skalt elska hann eins og sjálfan þig, því að þér voruð útlendingar í Egyptalandi. Ég er Jahve, Guð yðar.'),
(3317, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 35, 'OT', 'Þér skuluð ekki fremja ranglæti í dómi, í máli, í vigt og í mælingu.'),
(3318, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 36, 'OT', 'Réttar vogir, réttir steinar, rétt efu og rétt hín skulu vera yður. Ég er Jahve, Guð yðar, sem leiddi yður út frá Egyptalandi.'),
(3319, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 19, 37, 'OT', 'Þér skuluð halda öll lagaákvæði mín og öll dóma mína og gera þau. Ég er Jahve.'),
(3320, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 1, 'OT', 'Jahve talaði við Móses og sagði:'),
(3321, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 2, 'OT', 'Seg við Ísraels syni: Hver maður af Ísraels sonum og útlendingurinn sem dvelst í Ísrael, sem gefur af sæði sínu Mólok, skal líflátinn verða; lýður jarðarinnar skal grýta hann með steinum.'),
(3322, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 3, 'OT', 'Og ég mun snúa andliti mínu gegn þeim manni og uppræta hann frá meðal lýðs síns, því að hann hefur gefið af sæði sínu Mólok, til þess að saurga helgidóm minn og vanhelga heilagt nafn mitt.'),
(3323, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 4, 'OT', 'Og ef lýður jarðarinnar hylur augu sín fyrir þeim manni, þegar hann gefur af sæði sínu Mólok, og drepur hann ekki,'),
(3324, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 5, 'OT', 'Og ég mun snúa andliti mínu gegn þeim manni og ætt hans, og uppræta hann og alla þá sem fylgja honum í hórdómi með Mólok, frá meðal lýðs þeirra.'),
(3325, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 6, 'OT', 'Og sú sál sem snýr sér til særingaanda og til spásagnarmanna, til að hórast með þeim, á þá sál mun ég snúa andliti mínu og uppræta hana frá meðal lýðs hennar.'),
(3326, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 7, 'OT', 'Helgið yður og verið heilagir, því að ég er Jahve, Guð yðar.'),
(3327, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 8, 'OT', 'Haldið lagaákvæði mín og gerið þau; ég er Jahve, sem helgar yður.'),
(3328, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 9, 'OT', 'Ef maður formælir föður sínum eða móður sinni, skal hann deyja; blóð hans er á honum.'),
(3329, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 10, 'OT', 'Og ef maður drýgir hór með konu annars manns, sem drýgir hór með konu náunga síns, skulu bæði hórdómsmaðurinn og hórkonan deyja.'),
(3330, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 11, 'OT', 'Og ef maður leggst með konu föður síns, hefur hann afhjúpað nekt föður síns; báðir skulu deyja, blóð þeirra er á þeim.'),
(3331, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 12, 'OT', 'Og ef maður leggst með brúði sinni, skulu báðir deyja; þeir hafa framið siðspillingu, blóð þeirra er á þeim.'),
(3332, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 13, 'OT', 'Og ef maður leggst með karlmanni eins og í hvílu konu, hafa þeir báðir framið viðurstyggð; þeir skulu deyja, blóð þeirra er á þeim.'),
(3333, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 14, 'OT', 'Og ef maður tekur konu og móður hennar, þá er það svívirða; þau skulu brennd í eldi, bæði hann og þær, og engin svívirða skal vera meðal yðar.'),
(3334, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 15, 'OT', 'Og ef maður hefur legu sína með skepnu, skal hann deyja; og skepnuna skuluð þér drepa.'),
(3335, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 16, 'OT', 'Og ef kona nálgast nokkra skepnu til að makast við hana, þá skalt þú drepa konuna og skepnuna; þær skulu deyja, blóð þeirra er á þeim.'),
(3336, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 17, 'OT', 'Og ef maður tekur systur sína, dóttur föður síns eða dóttur móður sinnar, og sér nekt hennar og hún sér nekt hans, þá er það skömm; þau skulu upprætt fyrir augum lýðs síns; hann hefur afhjúpað nekt systur sinnar og skal bera misgjörð sína.'),
(3337, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 18, 'OT', 'Og ef maður leggst með konu á tíðum og afhjúpar nekt hennar, opnar uppsprettu blóðs hennar, og hún afhjúpar uppsprettu blóðs síns; þá skulu báðir upprættir verða meðal lýðs síns.'),
(3338, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 19, 'OT', 'Nekt systur móður þinnar og systur föður þíns skalt þú ekki afhjúpa, því að hann hefur afhjúpað hold sitt; þeir skulu bera misgjörð sína.'),
(3339, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 20, 'OT', 'Og ef maður leggst með föðursystur sinni, hefur hann afhjúpað nekt föðurbróður síns; þeir skulu bera synd sína, þeir munu deyja barnlausir.'),
(3340, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 21, 'OT', 'Og ef maður tekur konu bróður síns, þá er það óhreinleiki; hann hefur afhjúpað nekt bróður síns; þeir skulu verða barnlausir.'),
(3341, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 22, 'OT', 'Haldið öll lagaákvæði mín og öll dóma mína og gerið eftir þeim, svo að jörðin spýti yður ekki út, þangað sem ég leiði yður til að búa þar.'),
(3342, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 23, 'OT', 'Og þér skuluð ekki ganga eftir lagaákvæðum þjóðarinnar sem ég rek út fyrir andliti yðar, því að þeir gerðu allt þetta, og ég hafði andstyggð á þeim.'),
(3343, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 24, 'OT', 'Og ég sagði yður: Þér skuluð erfa jörð þeirra, og ég gef yður hana til eignar, jörð sem flýtur af mjólk og hunangi. Ég er Jahve, Guð yðar, sem skildi yður frá lýðum.'),
(3344, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 25, 'OT', 'Greinið þér milli hreinna skepna og óhreinna, og milli óhreinna fugla og hreinna; gerið ekki sálir yðar óhreinar með skepnu, fugli eða öllu sem skríður á jörðinni, sem ég hef aðgreint sem óhreint fyrir yður.'),
(3345, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 26, 'OT', 'Og þér skuluð vera mér heilagir, því að ég er heilagur, Jahve; og ég hef aðgreint yður frá lýðum, til þess að þér séuð mínir.'),
(3346, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 20, 27, 'OT', 'Ef maður eða kona hefur með sér særingaanda eða spásagnarmann, skulu þeir deyja; þeir skulu grýttir verða með steinum, blóð þeirra er á þeim.'),
(3347, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 1, 'OT', 'Jahve sagði við Móses: Seg við presta, syni Arons, og seg þeim að engin sál skuli óhreinka sig fyrir dauðum meðal lýðs síns.'),
(3348, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 2, 'OT', 'Nema fyrir hold sitt sem er honum næst, móður sína og föður, son sinn og dóttur sína og bróður sinn.'),
(3349, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 3, 'OT', 'Og fyrir systur sína sem er mey og ekki hefur verið gefin manni, fyrir hana má hann óhreinkast.'),
(3350, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 4, 'OT', 'Enginn herra skal óhreinka sig meðal lýðs síns til að saurga sig.'),
(3351, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 5, 'OT', 'Þeir skulu ekki gera skalla á höfði sínu, og ekki raka horn skeggs síns, og ekki gera skurð á holdi sínu.'),
(3352, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 6, 'OT', 'Þeir skulu vera heilagir Guði sínum og ekki vanhelga nafn Guðs síns; því að þeir færa eldfórnir Jahve, brauð Guðs síns; þess vegna skulu þeir vera heilagir.'),
(3353, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 7, 'OT', 'Hóru eða svívirta konu skal hann ekki taka; og ekki konu sem er skilin frá manni sínum, því að hann er heilagur Guði sínum.'),
(3354, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 8, 'OT', 'Þú skalt helga hann, því að hann færir brauð Guðs þíns; hann skal vera heilagur þér, því að ég, Jahve, er heilagur, sem helga yður.'),
(3355, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 9, 'OT', 'Og dóttir manns sem er prestur, ef hún saurgar sig með hórdómi, saurgar föður sinn; hún skal brennd í eldi.'),
(3356, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 10, 'OT', 'Sá prestur sem er æðstur meðal bræðra sinna, á höfuð hans er hellt olíu smurningar, og sem er vígður til að fylla hendur sínar og klæðast klæðum, skal ekki láta hár sitt ganga laust né rífa klæði sín.'),
(3357, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 11, 'OT', 'Hann skal ekki saurga sig fyrir neina sál, ekki fyrir föður sinn né móður sína.'),
(3358, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 12, 'OT', 'Hann skal ekki ganga út úr helgidóminum, né vanhelga helgidóm Guðs síns, því að hann er nasír, og olía smurningar Guðs síns er á honum; ég er Jahve.'),
(3359, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 13, 'OT', 'Hann skal taka sér konu í meydómi sínum.'),
(3360, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 14, 'OT', 'Ekkju, fráskilda eða hóru skal hann ekki taka, heldur skal hann taka sér mey af sínum lýð sem konu.'),
(3361, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 15, 'OT', 'Hann skal ekki saurga sæði sitt meðal lýðs síns; ég er Jahve, sem helga hann.'),
(3362, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 16, 'OT', 'Jahve talaði við Móses og sagði:'),
(3363, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 17, 'OT', 'Seg við Aron: Enginn maður af sæði þínu í kynslóðum þínum, sem hefur lýti, skal færa brauð Guðs síns.'),
(3364, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 18, 'OT', 'Enginn maður með lýti skal nálgast: hvorki blindur maður né haltur né sá sem hefur afmyndað andlit.'),
(3365, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 19, 'OT', 'Eða sá maður sem hefur brot á fæti eða brot á hendi.'),
(3366, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 20, 'OT', 'Eða sá sem er krypplingur, dvergur, eða hefur lýti á auga, eða kláðaskán, eða er hrúðurugur maður, eða hefur skemmdar eista.'),
(3367, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 21, 'OT', 'Enginn maður af sæði Arons prests sem hefur lýti skal færa eldfórn Jahve; hann hefur lýti; hann skal ekki færa brauð Guðs síns.'),
(3368, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 22, 'OT', 'Brauð Guðs síns, af hinu allra helgasta og af helgi, skal hann eta.'),
(3369, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 23, 'OT', 'Hann skal ekki ganga inn fyrir fortjald né nálgast altari, því að hann hefur lýti; hann skal ekki vanhelga helgidóm minn, því að ég er Jahve, sem helga hann.'),
(3370, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 21, 24, 'OT', 'Móses talaði þetta við Aron og syni hans og alla Ísraels sonu.'),
(3371, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 1, 'OT', 'Jahve talaði við Móses:'),
(3372, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 2, 'OT', 'Seg við Aron og syni hans að þeir skuli halda sig fjarri helgi Ísraels sona, sem þeir helga mér, svo að þeir vanhelgi ekki heilagt nafn mitt; ég er Jahve.'),
(3373, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 3, 'OT', 'Á öllum kynslóðum yðar skal hver maður af sæði yðar sem er óhreinn og hefur óhreinleika, og nálgast helga hluti Ísraels sona sem þeir helga Jahve, sú sál skal upprætt verða frá andliti mínu; ég er Jahve.'),
(3374, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 4, 'OT', 'Hver maður af sæði Arons sem er holdsveikur eða hefur samræði sæðis skal ekki eta af helgi hlutanna uns hann er hreinn. Hver sá sem snertir sál óhreinleika skal ekki eta.'),
(3375, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 5, 'OT', 'Hver sem snertir skriðdýr sem gerir hann óhreinan, eða mann, hvaða óhreinleika sem hann hefur.'),
(3376, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 6, 'OT', 'Sál sem snertir slíkt er óhrein til kvöldi; hún skal ekki eta af helgi nema hún hafi þvegið hold sitt í vatni.'),
(3377, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 7, 'OT', 'Þegar sól gengur undir, er hann hreinn, og þá má hann eta af helgi, því að það er brauð hans.'),
(3378, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 8, 'OT', 'Hræ og bráð skal hann ekki eta, svo að hann verði óhreinn af því; ég er Jahve.'),
(3379, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 9, 'OT', 'Þeir skulu varðveita varðstöðu mína, svo að þeir beri ekki synd og deyi fyrir að vanhelga hana; ég er Jahve, sem helga þá.'),
(3380, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 10, 'OT', 'Enginn útlendingur skal eta af helgi, hvorki gestur prests né daglaunamaður.'),
(3381, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 11, 'OT', 'En ef prestur kaupir sál fyrir silfur sitt sem eign, þá má hún eta; og börn sem fæðast í húsi hans mega eta af brauði hans.'),
(3382, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 12, 'OT', 'Og dóttir prests, ef hún giftist manni sem er ekki prestur, skal ekki eta af framlagi helgi.'),
(3383, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 13, 'OT', 'En dóttir prests, sem er ekkja eða fráskilin og hefur ekkert sæði, og er komin aftur í hús föður síns eins og í æsku sinni, má eta af brauði föður síns; en enginn útlendingur skal eta þar af.'),
(3384, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 14, 'OT', 'Og ef maður etur helgi fyrir óviljaverki, skal hann leggja fimmtung við og greiða prestinum helgi.'),
(3385, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 15, 'OT', 'Þeir skulu ekki vanhelga helgi Ísraels sona, sem þeir færa Jahve.'),
(3386, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 16, 'OT', 'Þeir kynnu þá að bera misgjörð og sektarfórn ef þeir ætu helgi þeirra; ég er Jahve, sem helga þá.'),
(3387, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 17, 'OT', 'Jahve talaði við Móses:'),
(3388, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 18, 'OT', 'Seg við Aron og syni hans og alla Ísraels sonu: Sérhver maður af Ísraels húsi eða útlendingur í Ísrael, sem færir fórnargjöf sína af heitum eða sjálfviljafórnum, til brennifórnar fyrir Jahve.'),
(3389, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 19, 'OT', 'Til þess að þér hljótið velþóknun, skuluð þér færa nauti, lambi eða geit sem er gallalaust.'),
(3390, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 20, 'OT', 'Ekkert sem hefur lýti skuluð þér færa, því að það hlýtur ekki velþóknunar.'),
(3391, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 21, 'OT', 'Og ef maður færir sláturfórn og þakkarfórn fyrir Jahve, til að efna heit eða sem sjálfviljafórn, af nautum eða sauðfé, skal hún vera til velþóknunar; hún má ekki hafa neitt lýti.'),
(3392, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 22, 'OT', 'Blinda, brotna, með kýli, kláðaskán eða hrúðurugur maður, slíkt skuluð þér ekki færa Jahve; og ekki brenna eldfórn á altari fyrir Jahve.'),
(3393, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 23, 'OT', 'Naut eða lamb sem hefur of stóra eða of litla limi má færa sem sjálfviljafórn, en fyrir heiti verður það ekki þóknanlegt.'),
(3394, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 24, 'OT', 'Hvorki skuluð þér færa Jahve slíkt, né gera það í jörð yðar.'),
(3395, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 25, 'OT', 'Og af hendi útlendings skuluð þér ekki færa brauð Guðs yðar af neinu slíku, því að spilling er í þeim og lýti; þeir verða ekki þóknanlegir.'),
(3396, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 26, 'OT', 'Jahve talaði við Móses:'),
(3397, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 27, 'OT', 'Naut, lamb eða geit skal vera sjö daga hjá móður sinni; og frá áttunda degi og áfram skal það vera þóknanleg fórnargjöf, eldfórn fyrir Jahve.'),
(3398, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 28, 'OT', 'Naut eða lamb ásamt syni sínum skuluð þér ekki slátra á sama degi.'),
(3399, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 29, 'OT', 'Þegar þér færið þakkargjörðar sláturfórn fyrir Jahve, skuluð þér færa hana svo að hún hljóti velþóknun yðar.'),
(3400, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 30, 'OT', 'Hún skal etin á sama degi; þér skuluð ekki láta neitt eftir til morguns. Ég er Jahve.'),
(3401, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 31, 'OT', 'Varðveitið boðorð mín og gerið þau; ég er Jahve.'),
(3402, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 32, 'OT', 'Og þér skuluð ekki vanhelga heilagt nafn mitt, heldur skal ég helgast meðal Ísraels sona; ég er Jahve, sem helga yður.'),
(3403, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 22, 33, 'OT', 'Sem leiddi yður út af jarðar Egyptalands til þess að vera Guð yðar; ég er Jahve.'),
(3404, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 1, 'OT', 'Jahve talaði við Móses:'),
(3405, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 2, 'OT', 'Talaðu við Ísraels syni og seg við þá: Þetta eru hátíðir Jahve, sem þér skuluð kalla helgar samkomur; þær eru mínar hátíðir.'),
(3406, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 3, 'OT', 'Sex daga skal vinna, en sjöunda dag er hvíldardagur, helg samkoma; þá skuluð þér ekki vinna neitt starf. Hann er hvíldardagur Jahve í öllum bústöðum yðar.'),
(3407, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 4, 'OT', 'Þetta eru hátíðir Jahve, helgar samkomur, sem þér skuluð boða á tilsettum hátíðum sínum.'),
(3408, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 5, 'OT', 'Í fyrsta mánuði, á fjórtánda degi mánaðar í kvöldi, eru páskar Jahve.'),
(3409, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 6, 'OT', 'Og á fimmtánda degi þessa mánaðar er hátíð Jahve, hátíð ósýrðs brauðs; í sjö daga skuluð þér eta ósýrt brauð.'),
(3410, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 7, 'OT', 'Fyrsta daginn skal vera helg samkoma; þá skuluð þér ekki vinna neitt starf né gera neina þjónustu.'),
(3411, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 8, 'OT', 'Í sjö daga skuluð þér færa eldfórn fyrir Jahve; sjöunda dag skal vera helg samkoma; þá skuluð þér ekki vinna neitt starf né gera neina þjónustu.'),
(3412, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 9, 'OT', 'Jahve talaði við Móses:'),
(3413, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 10, 'OT', 'Talaðu við Ísraels syni og seg við þá: Þegar þér komið inn í jörð sem ég gef yður og uppskerið hana, skuluð þér færa fyrsta knippi uppskeru yðar til prests.'),
(3414, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 11, 'OT', 'Hann skal veifa knippi fyrir andliti Jahve, til þess að þér hljótið velþóknun; á morgun eftir hvíldardag skal presturinn veifa því.'),
(3415, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 12, 'OT', 'Á þeim degi þegar knippi er veifað skuluð þér færa eins árs gamalt lamb án lýtis sem brennifórn fyrir Jahve.'),
(3416, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 13, 'OT', 'Matfórn hans skal vera tvo tíunda hluta af fínu mjöli blandað olíu, eldfórn fyrir Jahve, þægilegan ilm; og dreypifórn af víni, fjórðung hín.'),
(3417, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 14, 'OT', 'Brauð, ristað korn og nýkorn skuluð þér ekki eta fyrr en sama dag og þér færið fórnargjöf Guðs yðar; það er eilíft lagaákvæði um kynslóðir yðar í öllum bústöðum yðar.'),
(3418, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 15, 'OT', 'Frá morgni eftir hvíldardaginn, frá þeim degi er þér færið knippið til veifufórnar, skuluð þér telja sjö hvíldardaga; þeir skulu vera heilir.'),
(3419, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 16, 'OT', 'Og fram að morgni eftir sjöunda hvíldardaginn skuluð þér telja fimmtíu daga, og þá skuluð þér færa nýja fórn fyrir Jahve.'),
(3420, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 17, 'OT', 'Frá bústöðum yðar skuluð þér færa brauð sem veifufórn, tvo tíunda hluta, fínt mjöl bakað með súrdeigi sem frumgróði fyrir Jahve.'),
(3421, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 18, 'OT', 'Og með brauði skuluð þér færa sjö lömb, eins árs gömul, og eitt ungnaut og tvo hrúta sem brennifórn fyrir Jahve, ásamt fórn þeirra og dreypifórnum, sem eldfórn, þægilegan ilm fyrir Jahve.'),
(3422, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 19, 'OT', 'Og einn geithafur, til syndar, og tvö lömb eins árs gömul sem þakkarfórn.'),
(3423, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 20, 'OT', 'Og presturinn skal veifa þeim fyrir andliti Jahve ásamt brauði frumgróða sem veifufórn, með tveimur lömbum; helgi er Jahve; það skal tilheyra prestinum.'),
(3424, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 21, 'OT', 'Á þessum sama degi skuluð þér kalla saman helga samkomu; þá skuluð þér ekki vinna neitt starf né gera neina þjónustu. Það er lagaákvæði til eilífðar í öllum bústöðum yðar, um kynslóðir yðar.'),
(3425, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 22, 'OT', 'Þegar þér uppskerið jarðar yðar, skuluð þér ekki slá horn akurs yðar né tína eftirtíning uppskeru yðar; þér skuluð láta það eftir fátækum og útlendingi. Ég er Jahve, Guð yðar.'),
(3426, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 23, 'OT', 'Jahve talaði við Móses:'),
(3427, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 24, 'OT', 'Talaðu við Ísraels syni og seg við þá: Á fyrsta degi sjöunda mánaðar skal vera hvíldardagur fyrir yður, minning með fagnaðarópi, helg samkoma.'),
(3428, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 25, 'OT', 'Ekkert starf né þjónustu skuluð þér vinna, en færið eldfórn fyrir Jahve.'),
(3429, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 26, 'OT', 'Jahve talaði við Móses:'),
(3430, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 27, 'OT', 'Tíunda dag þessa sjöunda mánaðar skal vera dagur friðþægingar; hann skal vera helg samkoma, og þér skuluð þjá sálir yðar og færa eldfórn fyrir Jahve.'),
(3431, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 28, 'OT', 'Ekkert starf skuluð þér vinna á þessum degi, því að þetta er dagur friðþægingar til að friðþægja yður fyrir andliti Jahve Guðs yðar.'),
(3432, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 29, 'OT', 'Sérhver sál sem ekki þjáir sig þennan dag skal upprætt verða frá lýð sínum.'),
(3433, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 30, 'OT', 'Og sérhver sál sem vinnur nokkurt starf þennan dag, þá mun ég tortíma henni úr lýð hennar.'),
(3434, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 31, 'OT', 'Ekkert starf skuluð þér vinna; þetta er lagaákvæði til eilífðar um kynslóðir yðar í öllum bústöðum yðar.'),
(3435, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 32, 'OT', 'Það skal vera yður hvíldardagur, og þér skuluð þjá sálir yðar; á níunda degi mánaðar að kvöldi, frá kvöldi til kvölds skuluð þér halda hvíldardag yðar.'),
(3436, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 33, 'OT', 'Jahve talaði við Móses:'),
(3437, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 34, 'OT', 'Talaðu við Ísraels syni og seg þeim: Á fimmtánda degi þessa sjöunda mánaðar er hátíð laufskála fyrir Jahve, í sjö daga.'),
(3438, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 35, 'OT', 'Fyrsta daginn skal vera helg samkoma; þá skuluð þér ekki vinna neitt starf né gera neina þjónustu.'),
(3439, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 36, 'OT', 'Í sjö daga skuluð þér færa eldfórn fyrir Jahve; á áttunda degi skal vera helg samkoma, og þér skuluð færa eldfórn fyrir Jahve; það er hátíðarsamkoma; þá skuluð þér ekki vinna neitt starf né gera neina þjónustu.'),
(3440, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 37, 'OT', 'Þetta eru hátíðir Jahve, helgar samkomur, sem þér skuluð kalla til að færa eldfórn, brennifórn, fórn, sláturfórn og dreypifórnir, hver á sínum degi.'),
(3441, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 38, 'OT', 'Auk hvíldardaga Jahve, auk gjafa yðar, auk allra heita yðar og allra sjálfviljafórna yðar, sem þér gefið Jahve.'),
(3442, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 39, 'OT', 'Fimmtánda dag sjöunda mánaðar, þegar þér hafið safnað afurð jarðar, skuluð þér halda hátíð Jahve í sjö daga; á fyrsta degi skal vera hvíldardagur, og á áttunda degi skal vera hvíldardagur.'),
(3443, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 40, 'OT', 'Og þér skuluð taka á fyrsta degi ávöxt af fögru tré, greinar döðlupálma, greinar af þykkum trjám og pílvið af læk, og gleðjast fyrir andliti Jahve Guðs yðar í sjö daga.'),
(3444, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 41, 'OT', 'Þér skuluð halda hana sem hátíð fyrir Jahve í sjö daga á ári; það er lagaákvæði til eilífðar um kynslóðir yðar; í sjöunda mánuði skuluð þér halda hana.'),
(3445, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 42, 'OT', 'Í sjö daga skuluð þér búa í laufskálum; hver innfæddur maður í Ísrael skal búa í laufskálum.'),
(3446, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 43, 'OT', 'Til þess að kynslóðir yðar viti að ég lét Ísraels syni búa í laufskálum, þegar ég leiddi þá út af jarðar Egyptalands; ég er Jahve, Guð yðar.'),
(3447, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 23, 44, 'OT', 'Móses talaði þannig við Ísraels syni um hátíðir Jahve.'),
(3448, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 1, 'OT', 'Jahve talaði við Móses:'),
(3449, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 2, 'OT', 'Bjóð Ísraels sonum að færa þér hreina olíu af olíutrjám til ljóss, til að láta lampa loga að stöðugleika.'),
(3450, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 3, 'OT', 'Utan við fortjald vitnisburðarins í samfundatjaldinu skal Aron hafa það í röð frá kvöldi til morguns fyrir andliti Jahve; það er lagaákvæði um kynslóðir yðar til eilífðar.'),
(3451, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 4, 'OT', 'Á hinni hreinu ljósastiku skal hann raða lampa frammi fyrir andliti Jahve stöðugt.'),
(3452, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 5, 'OT', 'Og þú skalt taka fínt mjöl og baka úr því tólf kökur; tvö tíunda hluta skal hver kaka vera.'),
(3453, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 6, 'OT', 'Og þú skalt raða þeim í tvær fylkingar, sex í hverri röð, á hreint borð frammi fyrir andliti Jahve.'),
(3454, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 7, 'OT', 'Og þú skalt setja hreint reykelsi á hverja röð, og það skal vera brauðinu til minningarhluta, eldfórn handa Jahve.'),
(3455, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 8, 'OT', 'Á hverjum hvíldardegi, dag eftir dag, skal hann raða því frammi fyrir andliti Jahve stöðugt, af hálfu sona Ísraels, sem sáttmáli um eilífð.'),
(3456, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 9, 'OT', 'Og þetta skal tilheyra Aroni og sonum hans, og þeir skulu eta það á helgum stað, því að það er helgi af helgum meðal eldfórnum Jahve; það eru lög um eilífð.'),
(3457, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 10, 'OT', 'Þá gekk út sonur Ísraelítu konu, en faðir hans var Egypti meðal Ísraelsmanna. Og sonur Ísraelítu konu og Ísraelíti einn börðust í herbúðum.'),
(3458, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 11, 'OT', 'Og sonur Ísraelítu konu smánaði nafn Jahve og formælti; og þeir leiddu hann til Mósesar. Nafn móður hans var Selómít, dóttir Dibrís, af staf Dan.'),
(3459, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 12, 'OT', 'Og þeir settu hann í varðstöðu, til að skera úr fyrir þeim eftir munni Jahve.'),
(3460, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 13, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(3461, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 14, 'OT', 'Leiddu þann sem formælti út fyrir herbúðir; og allir sem heyrðu skulu leggja hendur sínar á höfuð hans, og allur söfnuður grýti hann.'),
(3462, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 15, 'OT', 'Og þú skalt tala við sonu Ísraels og segja: Ef einhver maður formælir Guði sínum, þá skal hann bera synd sína.'),
(3463, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 16, 'OT', 'Sá sem formælir nafn Jahve skal deyja dauða; allur söfnuður skal grýta hann. Jafnt útlendingur sem innfæddur maður, þegar hann nefnir nafn Jahve, skal deyja.'),
(3464, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 17, 'OT', 'Og ef maður drepur sál manns, skal hann deyja.'),
(3465, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 18, 'OT', 'Sá sem drepur skepnu skal bæta hana; sál fyrir sál.'),
(3466, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 19, 'OT', 'Og ef maður veldur lýti á náunga sínum, þá skal við hann gert eins og hann gerði.'),
(3467, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 20, 'OT', 'Brot fyrir brot, auga fyrir auga, tönn fyrir tönn. Eins og hann veldur lýti á manni, svo skal við hann gert.'),
(3468, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 21, 'OT', 'Sá sem drepur skepnu skal bæta hana, en sá sem drepur mann skal deyja.'),
(3469, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 22, 'OT', 'Einn dómur skal gilda fyrir ykkur: útlendingur skal vera eins og innfæddur maður, því að ég er Jahve Guð ykkar.'),
(3470, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 24, 23, 'OT', 'Móses talaði þá við sonu Ísraels, og þeir leiddu þann sem formælti út fyrir herbúðir og grýttu hann með steinum. Og synir Ísraels gerðu eins og Jahve bauð Mósesi.'),
(3471, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 1, 'OT', 'Og Jahve talaði við Móses á fjalli Sínaí og sagði:'),
(3472, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 2, 'OT', 'Tala við sonu Ísraels og seg við þá: Þegar þér komið inn í landið sem ég gef yður, þá skal landið halda hvíldardag handa Jahve.'),
(3473, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 3, 'OT', 'Í sex ár skalt þú sá akur þinn, og í sex ár skalt þú klippa víngarð þinn og safna afurð hennar.'),
(3474, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 4, 'OT', 'Á sjöunda ári skal vera hvíldardagur fyrir landið, hvíldardagur handa Jahve; akur þinn skalt þú ekki sá, og víngarð þinn skalt þú ekki klippa.'),
(3475, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 5, 'OT', 'Það sem vex sjálfsáð af uppskeru þinni skalt þú ekki skera, og vínber nasírea þinna skalt þú ekki tína; það skal vera hvíldarár fyrir landið.'),
(3476, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 6, 'OT', 'Hvíldardagur landsins skal verða ykkur til fæðu: þér sjálfum, þjóni þínum og ambátt þinni, leigjanda þínum, útlendingi þínum og útlendingum sem dvelja hjá þér.'),
(3477, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 7, 'OT', 'Og fyrir skepnum þínum og dýrunum í landi þínu skal öll afurð hennar vera til átu.'),
(3478, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 8, 'OT', 'Þú skalt telja þér sjö hvíldardaga ára, það er sjö sinnum sjö ár, og dagar sjö hvíldardaga ára skulu verða þér níu og fjörutíu ár.'),
(3479, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 9, 'OT', 'Þá skalt þú láta lúður og fagnaðaróp gjalla í sjöunda mánuði, á tíunda degi mánaðarins; á degi friðþægingar skuluð þér láta lúðurhljóð gjalla um allt land yðar.'),
(3480, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 10, 'OT', 'Og þér skuluð helga fimmtugasta ár og kunngjöra frelsi um allt landið öllum íbúum þess. Það skal vera fagnaðarár fyrir yður, og hver maður skal hverfa aftur til eignar sinnar og hver til ættar sinnar.'),
(3481, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 11, 'OT', 'Það er fagnaðarár; fimmtugasta ár skal vera yður. Þá skuluð þér ekki sá, og ekki uppskera útsprungið korn, og ekki tína nasírea þinna.'),
(3482, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 12, 'OT', 'Því að það er fagnaðarár; það skal vera yður helgi. Af akri skuluð þér eta afurð hennar.'),
(3483, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 13, 'OT', 'Á þessu fagnaðarári skuluð þér hverfa aftur hver til eignar sinnar.'),
(3484, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 14, 'OT', 'Og þegar þér gerið sölu til náunga þíns eða kaupið af hendi náunga þíns, skuluð þér ekki kúga hver bróður sinn.'),
(3485, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 15, 'OT', 'Eftir tölu ára frá fagnaðarári skalt þú kaupa af náunga þínum; eftir tölu afurða skal hann selja þér.'),
(3486, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 16, 'OT', 'Eftir því sem ár eru fleiri skalt þú auka kaup hans, og eftir því sem ár eru færri skalt þú minnka kaup hans, því að eftir tölu afurða selur hann þér.'),
(3487, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 17, 'OT', 'Og þér skuluð ekki kúga náunga yðar, heldur óttast Guð yðar, því að ég er Jahve Guð yðar.'),
(3488, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 18, 'OT', 'Þér skuluð halda lagaákvæði mín og varðveita dóma mína og fara eftir þeim; þá munuð þér búa í öryggi í landinu.'),
(3489, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 19, 'OT', 'Og jörð mun gefa ávöxt sinn, og þér munuð eta yður til saðningar og búa í öryggi þar.'),
(3490, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 20, 'OT', 'Og ef þér segið: Hvað eigum við að eta á sjöunda ári? Sjá, við megum ekki sá og ekki uppskera afurð okkar.'),
(3491, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 21, 'OT', 'Þá mun ég bjóða yður blessun mína í sjötta ári, og hún mun gefa afurð þriggja ára.'),
(3492, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 22, 'OT', 'Þér munuð sá áttunda ár og eta gamalt korn allt til níunda ára; allt þar til afurð þess kemur, munuð þér eta gamalt.'),
(3493, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 23, 'OT', 'Landið má ekki selja að eilífu, því að landið er mitt; þér eruð útlendingar og gestir hjá mér.'),
(3494, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 24, 'OT', 'Og í öllu landi eignar yðar skuluð þér veita endurlausn.'),
(3495, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 25, 'OT', 'Ef bróðir þinn verður fátækur og selur af eign sinni, þá skal nánasti lausnari hans koma og leysa sölu hans.'),
(3496, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 26, 'OT', 'Ef maður á engan lausnara, en hönd hans nær þangað og hann finnur nægt fyrir endurlausn sinni.'),
(3497, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 27, 'OT', 'Þá skal hann reikna ár frá sölu sinni og endurgreiða manni þann mismun sem eftir er, og hann skal hverfa aftur til eignar sinnar.'),
(3498, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 28, 'OT', 'En ef hann finnur ekki nægt til að endurgreiða, þá skal sala hans vera í hendi kaupanda síns allt til fagnaðarárs; á fagnaðarári skal hann fara út og hverfa aftur til eignar sinnar.'),
(3499, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 29, 'OT', 'Og ef maður selur hús bústaðar í borg með múr, þá skal endurlausn hans vera til loka árs frá sölu hans; í heilt ár skal hann hafa endurlausn sína.'),
(3500, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 30, 'OT', 'En ef það er ekki leyst innan fullrar árs, þá skal hús í borg með múr verða að fullu eign þess sem keypti það, kynslóð fram af kynslóð; það skal ekki ganga út á fagnaðarári.'),
(3501, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 31, 'OT', 'En hús í forgörðum sem hafa engan múr umhverfis skulu teljast sem akur jarðar; þau skulu eiga endurlausn og út ganga á fagnaðarári.'),
(3502, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 32, 'OT', 'En borgir Levíta, og hús í borgum eignar þeirra, eiga endurlausn um eilífð handa Levítum.'),
(3503, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 33, 'OT', 'Og ef einhver af Levítum leysir, þá skal sala húss og borgar eignar hans út ganga á fagnaðarári, því að hús borga Levíta er eign þeirra meðal sona Ísraels.'),
(3504, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 34, 'OT', 'En akur í beitilandi borga þeirra skal ekki seldur verða, því að hann er þeirra eign um eilífð.'),
(3505, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 35, 'OT', 'Og ef bróðir þinn verður fátækur og hönd hans bregst hjá þér, þá skalt þú styðja hann eins og útlending eða gest, og hann skal lifa hjá þér.'),
(3506, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 36, 'OT', 'Ekki skalt þú taka af honum okur né okurvexti, og þú skalt óttast Guð þinn, og bróðir þinn skal lifa hjá þér.'),
(3507, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 37, 'OT', 'Silfur þitt skalt þú ekki lána honum með okri, og ekki gefa honum mat þinn með meirihluta.'),
(3508, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 38, 'OT', 'Ég er Jahve Guð yðar, sem leiddi yður út af Egyptalandi til að gefa yður jörð Kanaans og vera yðar Guð.'),
(3509, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 39, 'OT', 'Og ef bróðir þinn sem býr hjá þér selur sig þér, þá skalt þú ekki láta hann inna af hendi þjónustu þjóns.'),
(3510, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 40, 'OT', 'Eins og leigjandi og útlendingur skal hann vera hjá þér; allt til fagnaðarárs skal hann vinna hjá þér.'),
(3511, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 41, 'OT', 'Þá skal hann fara frá þér, hann og synir hans með honum, og hverfa aftur til ættar sinnar og til eignar feðra sinna.'),
(3512, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 42, 'OT', 'Því að þeir eru þjónar mínir, sem ég leiddi út af Egyptalandi; þeir skulu ekki seldir verða til sölu eins og þrælar.'),
(3513, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 43, 'OT', 'Þú skalt ekki drottna yfir honum með harðýðgi, og þú skalt óttast Guð þinn.'),
(3514, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 44, 'OT', 'Þjónn þinn og ambátt þín, sem þú átt, skulu vera frá þjóðum umhverfis þig; af þeim skalt þú kaupa þjón og ambátt.'),
(3515, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 45, 'OT', 'Og einnig af sonum útlendinga sem dvelja hjá yður skuluð þér kaupa, og af ættum þeirra sem eru hjá yður, þeim sem fæddust í landi yðar; þeir skulu vera yðar eign.'),
(3516, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 46, 'OT', 'Og þú skalt láta þá erfast af sonum yðar eftir yður sem eign; um eilífð skuluð þér þjóna þeim. En yfir bræðrum yðar, sonum Ísraels, skal enginn maður drottna með harðýðgi.'),
(3517, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 47, 'OT', 'Ef hönd útlendings eða gests hjá þér nær velsæld, og bróðir þinn sem er hjá honum verður fátækur og selur sig útlendingi eða gesti hjá þér eða stofni ættar útlendings.'),
(3518, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 48, 'OT', 'Eftir að hann er seldur skal honum vera endurlausn; einn af bræðrum hans skal leysa hann.'),
(3519, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 49, 'OT', 'Eða frændi hans eða sonur frænda hans skal leysa hann; eða einhver af holdi hans af ætt hans skal leysa hann; eða ef hönd hans nær því, þá verður hann leystur.'),
(3520, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 50, 'OT', 'Og hann skal reikna við kaupanda sinn frá ári sölu sinnar til fagnaðarárs; silfur sölu hans skal reiknast eftir tölu ára, og dagar hans skulu vera eins og dagar launamanns hjá honum.'),
(3521, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 51, 'OT', 'Ef enn eru mörg ár eftir, þá skal hann greiða endurlausn sína úr silfri kaups síns.'),
(3522, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 52, 'OT', 'En ef lítið er eftir af árum til fagnaðarárs, þá skal hann reikna það við sig og endurgreiða endurlausn sína eftir árum sínum.'),
(3523, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 53, 'OT', 'Eins og árslaunamaður skal hann vera hjá honum, ár frá ári; hann skal ekki drottna yfir honum með harðýðgi fyrir augum þínum.'),
(3524, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 54, 'OT', 'Og ef hann leysist ekki með þessu, þá skal hann út ganga á fagnaðarári, hann og synir hans með honum.'),
(3525, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 25, 55, 'OT', 'Því að synir Ísraels eru mínir þjónar, þjónar mínir sem ég leiddi út af Egyptalandi; ég er Jahve Guð yðar.'),
(3526, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 1, 'OT', 'Þér skuluð ekki gera yður hégómaguð, og ekki reisa upp goðalíkan né steinsúlu, og ekki setja upp útskorna mynd úr steini í landi yðar til að lúta henni; því að ég er Jahve Guð yðar.'),
(3527, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 2, 'OT', 'Þér skuluð halda hvíldardaga mína og bera virðingu fyrir helgidómi mínum; ég er Jahve.'),
(3528, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 3, 'OT', 'Ef þér gangið í lagaákvæðum mínum og varðveitið boðorð mín og gerið þau.'),
(3529, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 4, 'OT', 'Þá mun ég gefa yður skúri á tíma þeirra; jörð mun gefa uppskeru sína og tré akurs ávöxt sinn.'),
(3530, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 5, 'OT', 'Þreskingu mun ná til vínuppskeru, og vínuppskeru mun ná til sæðis; og þér munuð eta brauð yðar til saðningar og búa í öryggi í landi yðar.'),
(3531, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 6, 'OT', 'Og ég mun gefa frið í landi yðar, og þér munuð leggjast til hvílu og enginn mun hræða; ég mun láta illt dýr hverfa úr landinu, og sverð mun ekki fara um landið yðar.'),
(3532, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 7, 'OT', 'Þér munuð elta óvini yðar, og þeir munu falla fyrir sverði frammi fyrir andliti yðar.'),
(3533, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 8, 'OT', 'Fimm af yður munu elta hundrað, og hundrað af yður munu elta tíuþúsund; óvinir yðar munu falla frammi fyrir andliti yðar fyrir sverði.'),
(3534, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 9, 'OT', 'Og ég mun snúa mér að yður, gera yður frjósöm og fjölga yður, og ég mun staðfesta sáttmála minn við yður.'),
(3535, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 10, 'OT', 'Og þér munuð eta gamalt korn sem geymt er, og ryðja gömlu burt frá andliti hins nýja.'),
(3536, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 11, 'OT', 'Og ég mun setja bústað minn meðal yðar, og sál mín mun ekki hafna yður.'),
(3537, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 12, 'OT', 'Og ég mun ganga meðal yðar og verða yður að Guði, og þér munuð vera mínum lýð.'),
(3538, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 13, 'OT', 'Ég er Jahve Guð yðar, sem leiddi yður út af Egyptalandi svo að þér væruð ekki þjónar þeirra; ég braut ok yðar og lét yður ganga uppréttir.'),
(3539, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 14, 'OT', 'En ef þér hlýðið mér ekki og gerið ekki öll þessi boðorð.'),
(3540, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 15, 'OT', 'Og ef þér fyrirlítið lagaákvæði mín og hafnið dómum mínum, og ef sál yðar fyrirlítur boðorð mín, svo að þér rjúfið sáttmála minn.'),
(3541, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 16, 'OT', 'Þá mun ég senda yfir yður skelfingu, tæringu og brennandi hita, sem gera augu yðar örvæntingarfull og sál yðar örmagna; þér munuð sá til hégóma, og óvinir yðar munu eta sæði yðar.'),
(3542, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 17, 'OT', 'Ég mun snúa andliti mínu gegn yður, og þér munuð sigraðir verða frammi fyrir óvinum yðar; hatarar yðar munu drottna yfir yður, og þér munuð flýja án þess að neinn elti yður.'),
(3543, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 18, 'OT', 'Og ef þér þrátt fyrir þetta hlýðið mér ekki, þá mun ég bæta við yður sjöfalt vegna synda yðar.'),
(3544, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 19, 'OT', 'Ég mun brjóta dramb styrks yðar, og ég mun gera himin yðar sem járn og jörð yðar sem eir.'),
(3545, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 20, 'OT', 'Kraftur yðar mun eyðast til hégóma; jörð yðar mun ekki gefa uppskeru sína, og tré jarðar mun ekki gefa ávöxt sinn.'),
(3546, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 21, 'OT', 'Og ef þér gangið með mér í andstöðu og viljið ekki hlýða mér, þá mun ég auka yfir yður högg, sjöfalt eftir syndum yðar.'),
(3547, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 22, 'OT', 'Ég mun senda meðal yðar villidýr akurs, sem skulu svipta yður börnum og tortíma skepnum yðar og gera yður fáa, og vegir yðar munu verða auðir.'),
(3548, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 23, 'OT', 'Og ef þér látið ekki leiðrétta yður með þessu, og gangið í andstöðu við mig.'),
(3549, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 24, 'OT', 'Þá mun ég einnig ganga í andstöðu við yður og berja yður sjöfalt vegna synda yðar.'),
(3550, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 25, 'OT', 'Og ég mun leiða yfir yður sverð sem framkvæmir hefnd sáttmála; og þér munuð safnast í borgir yðar, og ég mun senda drepsótt meðal yðar, og þér munuð gefast í hendur óvinar.'),
(3551, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 26, 'OT', 'Þegar ég brýt yður staf brauðs, skulu tíu konur baka brauð yðar í einum ofni og skila brauði yðar eftir vigt; og þér munuð eta, en ekki verða saddir.'),
(3552, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 27, 'OT', 'Og ef þér hlýðið mér ekki í þessu, og gangið í andstöðu við mig.'),
(3553, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 28, 'OT', 'Þá mun ég ganga í andstöðu við yður í reiði, og ég mun aga yður sjöfalt vegna synda yðar.'),
(3554, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 29, 'OT', 'Og þér munuð eta hold sona yðar, og hold dætra yðar munuð þér eta.'),
(3555, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 30, 'OT', 'Ég mun eyða fórnarhæðir yðar og höggva sólstyttur yðar, og ég mun leggja hræ yðar á hræi skurðgoða yðar; og sál mín mun hafna yður.'),
(3556, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 31, 'OT', 'Og ég mun gera borgir yðar að rústum og eyða helgidómum yðar, og ég mun ekki finna þægilegan ilm yðar.'),
(3557, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 32, 'OT', 'Og ég mun gera jörð að auðn, og óvinir yðar sem búa í henni munu undrast hana.'),
(3558, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 33, 'OT', 'Og ég mun tvístra yður meðal þjóðum og draga sverð á eftir yður; jörð yðar mun verða auðn, og borgir yðar rústir.'),
(3559, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 34, 'OT', 'Þá mun jörð njóta hvíldardaga sinna alla daga auðnarinnar, meðan þér eruð í landi óvina yðar; þá mun jörð hvílast og njóta hvíldardaga sinna.'),
(3560, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 35, 'OT', 'Alla daga auðnarinnar mun hún hvílast, það sem hún hvíldist ekki á hvíldardögum yðar meðan þér bjugguð á henni.'),
(3561, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 36, 'OT', 'Og þeim sem eftir verða meðal yðar mun ég senda ragmennsku í hjörtu þeirra í löndum óvina þeirra; rödd af fjúkandi laufi mun elta þá, og þeir munu flýja flótta undan sverði og falla, þótt enginn elti.'),
(3562, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 37, 'OT', 'Og þeir munu hrasa hver um bróður sinn, eins og frammi fyrir sverði, án þess að neinn elti; og yður mun ekki verða mótstöðuafl frammi fyrir andliti óvina yðar.'),
(3563, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 38, 'OT', 'Og þér munuð farast meðal þjóðum, og jörð óvina yðar mun eta yður.'),
(3564, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 39, 'OT', 'Og þeir sem eftir verða meðal yðar munu rotna í misgjörð sinni í löndum óvina yðar; og jafnvel í misgjörðum feðra sinna munu þeir rotna með þeim.'),
(3565, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 40, 'OT', 'Og þeir skulu játa misgjörð sína og misgjörð feðra sinna, í ótrúmennsku þeirra við mig, og að þeir gengu einnig í andstöðu við mig.'),
(3566, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 41, 'OT', 'Þá mun ég einnig ganga með þeim í andstöðu og leiða þá í jörð óvina þeirra; eða þá mun óumskorið hjarta þeirra auðmýkjast, og þeir munu þá bæta fyrir misgjörð sína.'),
(3567, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 42, 'OT', 'Og ég mun minnast sáttmála míns við Jakob, og einnig sáttmála míns við Ísak, og einnig sáttmála míns við Abraham mun ég minnast, og ég mun minnast jarðar.'),
(3568, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 43, 'OT', 'Jörð mun verða yfirgefin af þeim og njóta hvíldardaga sinna þegar hún er auðn án þeirra; en þeir munu bæta fyrir misgjörð sína, af því að þeir höfnuðu dóma mína og lagaákvæði mín fyrirlitu, og sál þeirra fyrirleit þau.'),
(3569, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 44, 'OT', 'Og þrátt fyrir þetta, þegar þeir eru í jörð óvina sinna, mun ég ekki hafna þeim né fyrirlíta þá til eyðingar, né rjúfa sáttmála minn við þá, því að ég er Jahve Guð þeirra.'),
(3570, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 45, 'OT', 'Og ég mun minnast sáttmála fyrri feðra, sem ég leiddi út af Egyptalandi fyrir augum þjóðum, til að vera þeirra Guð; ég er Jahve.'),
(3571, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 26, 46, 'OT', 'Þetta eru lög, dómar og lögmál, sem Jahve setti milli sín og sona Ísraels á fjalli Sínaí fyrir hendi Mósesar.'),
(3572, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 1, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(3573, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 2, 'OT', 'Tala við sonu Ísraels og seg við þá: Ef einhver maður fer með sérstakt heit, og metur sálir eftir verði fyrir Jahve.'),
(3574, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 3, 'OT', 'Verð þitt skal vera fimmtíu sikla silfurs, eftir helgum sikli, og verð karlkyns frá tuttugu ára til sextugs.'),
(3575, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 4, 'OT', 'Ef það er kvenkyn, þá skal verð þitt vera þrjátíu sikla.'),
(3576, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 5, 'OT', 'Og ef frá fimm ára til tuttugu ára, þá skal verð karlkyns vera tuttugu sikla, og fyrir kvenkyns tíu sikla.'),
(3577, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 6, 'OT', 'Og ef frá eins mánaðar til fimm ára, þá skal verð karlkyns vera fimm sikla silfurs, og fyrir kvenkyns verð þitt þrjú sikla silfurs.'),
(3578, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 7, 'OT', 'Og ef frá sextugs ára og eldri, og ef karlkyns, þá skal verð þitt vera fimmtán sikla, og fyrir kvenkyns tíu sikla.'),
(3579, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 8, 'OT', 'Og ef hann er fátækari en verð hans, þá skal hann stilla hann frammi fyrir presti, og presturinn skal meta hann eftir munni þess sem heitið gerði; eftir því sem hönd hans nær.'),
(3580, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 9, 'OT', 'Og ef það er skepna sem menn færa af sér sem fórnargjöf handa Jahve, þá skal allt sem gefið er af henni handa Jahve vera helgi.'),
(3581, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 10, 'OT', 'Hann skal ekki skipta henni né skipta á henni góðu fyrir illt eða illu fyrir gott; og ef hann skiptir skepnu fyrir skepnu, þá skulu hún og skipti hennar vera helgi.'),
(3582, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 11, 'OT', 'Og ef hver óhrein skepna, sem menn færa ekki af sér sem fórnargjöf Jahve, þá skal hann stilla skepnu frammi fyrir presti.'),
(3583, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 12, 'OT', 'Og prestur skal meta hana, á milli góðs og ills; eins og verð þitt er, svo skal það vera.'),
(3584, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 13, 'OT', 'Og ef hann vill leysa hana, þá skal hann leggja við fimmtung sinn yfir verð þitt.'),
(3585, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 14, 'OT', 'Og ef maður helgar hús sitt sem helgi Jahve, þá skal prestur meta það á milli góðs og ills; eins og prestur metur það, svo skal það standa.'),
(3586, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 15, 'OT', 'Og ef sá sem helgar leysir hús sitt, þá skal hann bæta fimmtungi af silfri við verð sitt, og það skal vera hans.'),
(3587, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 16, 'OT', 'Og ef maður helgar Jahve hluta af akri eignar sinnar, þá skal verð þitt vera eftir sæði hans; eitt hómer byggs er fimmtíu sikla silfurs.'),
(3588, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 17, 'OT', 'Ef hann helgar akur sinn frá fagnaðarári, þá skal verð þitt standa eins og það er.'),
(3589, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 18, 'OT', 'Ef hann helgar akur sinn eftir fagnaðarár, þá skal prestur reikna honum silfur eftir tölu ára sem eftir eru til fagnaðarárs, og verð hans skal lækka.'),
(3590, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 19, 'OT', 'Og ef sá sem helgar vill leysa akur, þá skal hann bæta fimmtungi silfurs við verð sitt, og það skal standa honum.'),
(3591, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 20, 'OT', 'En ef hann leysir ekki akur, og ef hann selur akur öðrum manni, þá skal hann ekki leystur verða framar.'),
(3592, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 21, 'OT', 'Og þegar akur gengur út á fagnaðarári, skal hann vera helgi Jahve, eins og akur bannfæringar; eign hans skal vera prests.'),
(3593, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 22, 'OT', 'Og ef hann helgar Jahve akur sem er kaup hans, sem er ekki af akri eignar hans.'),
(3594, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 23, 'OT', 'Og prestur skal reikna honum verð eftir tölu ára til fagnaðarárs, og hann skal gefa verð þann dag sem helgi Jahve.'),
(3595, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 24, 'OT', 'Á fagnaðarári skal akur snúa aftur til þess sem keypti hann af honum, til þess sem átti eign jarðar.'),
(3596, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 25, 'OT', 'Og allt verð þitt skal vera eftir helgum sikli; tuttugu gera er sikill.'),
(3597, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 26, 'OT', 'En frumgetinn sem Jahve á af skepnu, enginn maður skal helga; hvort sem það er naut eða lamb, það er Jahve.'),
(3598, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 27, 'OT', 'En ef það er af óhreinni skepnu, þá skal leysa það eftir verði þínu og bæta fimmtungi við; en ef það er ekki leyst, þá skal það seljast eftir verði þínu.'),
(3599, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 28, 'OT', 'Aðeins sérhver bannfæring, sem maður bannfærir Jahve af öllu sem hann á, af mönnum, skepnum eða akri eignar sinnar, skal hvorki seljast né leysast; hver bannfæring er helgi, helgi Jahve.'),
(3600, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 29, 'OT', 'Sérhver bannfæring sem bannfærð er af mönnum skal ekki leysast; hún skal víst deyja.'),
(3601, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 30, 'OT', 'Öll tíund jarðarinnar, af sæði jarðar og af ávexti trésins, er helgi Jahve.'),
(3602, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 31, 'OT', 'Og ef maður vill leysa til sín eitthvað af tíund sinni, skal hann bæta fimmtung ofan á það.'),
(3603, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 32, 'OT', 'Og öll tíund af nautum og sauðfé, allt sem fer undir ættkvíslarstafinn, hvert tíunda dýr, skal vera helgi Jahve.'),
(3604, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 33, 'OT', 'Hann skal ekki gera greinarmun á góðu og illu og ekki skipta því. En ef hann skiptir því, þá skal bæði það og skipti þess vera helgi; það má ekki leysa til sín.'),
(3605, 3, 'GOI_Is', 'GOI_Is', 'is', 'LEV', 27, 34, 'OT', 'Þessi eru boðorðin sem Jahve bauð Mósesi að flytja sonum Ísraels á fjalli Sínaí.'),
(3606, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 1, 'OT', 'Og Jahve talaði við Móses í eyðimörkinni Sínaí, í samfundatjaldinu, fyrsta dag annars mánaðar á öðru ári eftir að þeir fóru af jörð Egyptalands, og sagði:'),
(3607, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 2, 'OT', 'Takið höfuð allrar safnaðar Ísraels sona, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, hvern karl eftir höfuðkúpum hans.'),
(3608, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 3, 'OT', 'Frá sonum tuttugu ára og eldri, allir þeir sem geta farið í her Ísraels, skalt þú telja þá eftir herjum þeirra, þú og Aron.'),
(3609, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 4, 'OT', 'Með ykkur skal vera einn maður úr hverjum staf, sem er höfuð húsi feðra sinna.'),
(3610, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 5, 'OT', 'Þetta eru nöfn mannanna sem standa með ykkur: Af Rúben: Elísúr sonur Sedeúrs.'),
(3611, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 6, 'OT', 'Af Símeon: Selúmíel sonur Súríaddaís.'),
(3612, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 7, 'OT', 'Af Júda: Nakson sonur Amínadabs.'),
(3613, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 8, 'OT', 'Af Íssakar: Netanel sonur Súars.'),
(3614, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 9, 'OT', 'Af Sebúlon: Elíab sonur Helons.'),
(3615, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 10, 'OT', 'Af sonum Jósefs: af Efraím: Elísama sonur Ammíhúds; af Manasse: Gamalíel sonur Pedasúrs.'),
(3616, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 11, 'OT', 'Af Benjamín: Abídan sonur Gídeonís.'),
(3617, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 12, 'OT', 'Af Dan: Akíeser sonur Ammíaddaís.'),
(3618, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 13, 'OT', 'Af Asser: Pagíel sonur Ókrans.'),
(3619, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 14, 'OT', 'Af Gað: Elíasaf sonur Deúels.'),
(3620, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 15, 'OT', 'Af Naftalí: Akíra sonur Enans.'),
(3621, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 16, 'OT', 'Þessir eru þeir sem kallaðir voru af söfnuði, höfðingjar stafa feðra sinna; þeir eru höfuð þúsundanna í Ísrael.'),
(3622, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 17, 'OT', 'Móses og Aron tóku þessa menn, sem voru nefndir með nafni.'),
(3623, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 18, 'OT', 'Og þeir kölluðu saman allan söfnuðinn fyrsta dag annars mánaðar, og þeir skráðu ættir sínar eftir ættum sínum og húsi feðra sinna, með tölu nafna, frá tuttugu ára og eldri, eftir höfuðkúpum þeirra.'),
(3624, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 19, 'OT', 'Eins og Jahve bauð Mósesi, taldi hann þá í eyðimörkinni Sínaí.'),
(3625, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 20, 'OT', 'Synir Rúbens, frumgetins Ísraels, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, hver karl frá tuttugu ára og eldri sem gátu farið í her.'),
(3626, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 21, 'OT', 'Taldir þeirra af staf Rúbens voru sex og fjörutíu þúsund og fimm hundruð.'),
(3627, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 22, 'OT', 'Synir Símeons, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, hver karl frá tuttugu ára og eldri sem gátu farið í her.'),
(3628, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 23, 'OT', 'Taldir þeirra af staf Símeons voru níu og fimmtíu þúsund og þrjú hundruð.'),
(3629, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 24, 'OT', 'Synir Gaðs, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3630, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 25, 'OT', 'Taldir þeirra af staf Gaðs voru fimm og fjörutíu þúsund og sex hundruð og fimmtíu.'),
(3631, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 26, 'OT', 'Synir Júda, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3632, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 27, 'OT', 'Taldir þeirra af staf Júda voru fjögur og sjötíu þúsund og sex hundruð.'),
(3633, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 28, 'OT', 'Synir Íssakars, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3634, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 29, 'OT', 'Taldir þeirra af staf Íssakars voru fjögur og fimmtíu þúsund og fjögur hundruð.'),
(3635, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 30, 'OT', 'Synir Sebúlons, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3636, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 31, 'OT', 'Taldir þeirra af staf Sebúlons voru sjö og fimmtíu þúsund og fjögur hundruð.'),
(3637, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 32, 'OT', 'Synir Jósefs, það er synir Efraíms, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3638, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 33, 'OT', 'Taldir þeirra af staf Efraíms voru fjörutíu þúsund og fimm hundruð.'),
(3639, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 34, 'OT', 'Synir Manasse, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3640, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 35, 'OT', 'Taldir þeirra af staf Manasse voru tvö og þrjátíu þúsund og tvö hundruð.'),
(3641, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 36, 'OT', 'Synir Benjamíns, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3642, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 37, 'OT', 'Taldir þeirra af staf Benjamíns voru fimm og þrjátíu þúsund og fjögur hundruð.'),
(3643, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 38, 'OT', 'Synir Dans, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3644, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 39, 'OT', 'Taldir þeirra af staf Dans voru tvö og sextíu þúsund og sjö hundruð.'),
(3645, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 40, 'OT', 'Synir Assers, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3646, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 41, 'OT', 'Taldir þeirra af staf Assers voru einn og fjörutíu þúsund og fimm hundruð.'),
(3647, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 42, 'OT', 'Synir Naftalís, eftir ættartölum þeirra, eftir ættum þeirra og húsi feðra þeirra, með tölu nafna, frá tuttugu ára og eldri, allir sem gátu farið í her.'),
(3648, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 43, 'OT', 'Taldir þeirra af staf Naftalís voru þrjú og fimmtíu þúsund og fjögur hundruð.'),
(3649, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 44, 'OT', 'Þessar eru talningarnar sem Móses og Aron framkvæmdu, og höfðingjar Ísraels, tólf menn; hver einn maður var fyrir húsi feðra sinna.'),
(3650, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 45, 'OT', 'Og allir sem taldir voru af sonum Ísraels, eftir húsi feðra þeirra, frá tuttugu ára og eldri, allir sem gátu farið í her í Ísrael.'),
(3651, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 46, 'OT', 'Og allir taldir voru sex hundruð þúsund, þrjú þúsund, fimm hundruð og fimmtíu.'),
(3652, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 47, 'OT', 'En Levítarnir voru ekki taldir eftir staf feðra sinna meðal þeirra.'),
(3653, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 48, 'OT', 'Því að Jahve hafði talað við Móses og sagt:'),
(3654, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 49, 'OT', 'Aðeins staf Leví skalt þú ekki telja, og höfuð þeirra skalt þú ekki taka upp með sonum Ísraels.'),
(3655, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 50, 'OT', 'Levítum skalt þú fela umsjón yfir bústaðnum vitnisburðarins og yfir öllum áhöldum hans og öllu sem honum tilheyrir.'),
(3656, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 51, 'OT', 'Þegar bústaðurinn heldur af stað, skulu Levítarnir taka hann niður, og þegar bústaðurinn er reistur, skulu Levítarnir reisa hann; en hver ókunnugur sem nálgast skal deyja.'),
(3657, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 52, 'OT', 'Synir Ísraels skulu setja upp herbúðir, hver maður í sínum herbúðum og undir sínu fána, eftir herjum sínum.'),
(3658, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 53, 'OT', 'Levítarnir skulu setja upp herbúðir umhverfis bústaðinn vitnisburðarins, svo að reiði komi ekki yfir söfnuð Ísraels; og Levítarnir skulu gegna varðstöðu bústaðar vitnisburðarins.'),
(3659, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 1, 54, 'OT', 'Synir Ísraels gerðu allt eins og Jahve bauð Mósesi; þannig gerðu þeir.'),
(3660, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 1, 'OT', 'Og Jahve talaði við Móses og Aron og sagði:'),
(3661, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 2, 'OT', 'Hver maður skal vera undir sínum fána, með táknum eftir húsum feðra sinna; synir Ísraels skulu setja upp herbúðir umhverfis samfundatjaldið.'),
(3662, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 3, 'OT', 'Í austri, til sólarupprásar, skal fáni herbúða Júda vera eftir herjum þeirra; og höfðingi sona Júda er Nakson sonur Amínadabs.'),
(3663, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 4, 'OT', 'Og her hans, fjögur og sjötíu þúsund og sex hundruð.'),
(3664, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 5, 'OT', 'Næst honum skal staf Íssakars vera; og höfðingi sona Íssakars er Netanel sonur Súars.'),
(3665, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 6, 'OT', 'Og her hans, fjögur og fimmtíu þúsund og fjögur hundruð.'),
(3666, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 7, 'OT', 'Og staf Sebúlons skal vera þar; og höfðingi sona Sebúlons er Elíab sonur Helons.'),
(3667, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 8, 'OT', 'Og her hans, sjö og fimmtíu þúsund og fjögur hundruð.'),
(3668, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 9, 'OT', 'Allir taldir í herbúðum Júda, eftir herjum þeirra, eru hundrað áttatíu og sex þúsund og fjögur hundruð. Þeir skulu fyrstir leggja af stað.'),
(3669, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 10, 'OT', 'Fáni herbúða Rúbens skal vera sunnan megin, eftir herjum þeirra; og höfðingi sona Rúbens er Elísúr sonur Sedeúrs.'),
(3670, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 11, 'OT', 'Og her hans, sex og fjörutíu þúsund og fimm hundruð.'),
(3671, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 12, 'OT', 'Staf Símeons skal vera þar næst; og höfðingi sona Símeons er Selúmíel sonur Súríaddaís.'),
(3672, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 13, 'OT', 'Og her hans, níu og fimmtíu þúsund og þrjú hundruð.'),
(3673, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 14, 'OT', 'Og staf Gaðs skal vera þar; og höfðingi sona Gaðs er Elíasaf sonur Regúels.'),
(3674, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 15, 'OT', 'Og her hans, fimm og fjörutíu þúsund og sex hundruð og fimmtíu.'),
(3675, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 16, 'OT', 'Allir taldir í herbúðum Rúbens, eftir herjum þeirra, eru hundrað fimmtíu og eitt þúsund og fjögur hundruð og fimmtíu.'),
(3676, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 17, 'OT', 'Samfundatjaldið skal leggja af stað með herbúðum Levíta í miðjum herbúðunum; eins og þeir setjast að, þannig skal hver maður halda af stað á sinni hendi, eftir fánum sínum.'),
(3677, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 18, 'OT', 'Fáni herbúða Efraíms skal vera til hafs, eftir herjum þeirra; og höfðingi sona Efraíms er Elísama sonur Ammíhúds.'),
(3678, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 19, 'OT', 'Og her hans, fjörutíu þúsund og fimm hundruð.'),
(3679, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 20, 'OT', 'Næst skal staf Manasse vera; og höfðingi sona Manasse er Gamalíel sonur Pedasúrs.'),
(3680, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 21, 'OT', 'Og her hans, tvö og þrjátíu þúsund og tvö hundruð.'),
(3681, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 22, 'OT', 'Og staf Benjamíns; og höfðingi sona Benjamíns er Abídan sonur Gídeonís.'),
(3682, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 23, 'OT', 'Og her hans, fimm og þrjátíu þúsund og fjögur hundruð.'),
(3683, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 24, 'OT', 'Allir taldir í herbúðum Efraíms, eftir herjum þeirra, eru hundrað og átta þúsund og eitt hundrað.'),
(3684, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 25, 'OT', 'Fáni herbúða Dans skal vera norðan megin, eftir herjum þeirra; og höfðingi sona Dans er Akíeser sonur Ammíaddaís.'),
(3685, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 26, 'OT', 'Og her hans, tvö og sextíu þúsund og sjö hundruð.'),
(3686, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 27, 'OT', 'Og staf Assers skal vera þar; og höfðingi sona Assers er Pagíel sonur Ókrans.'),
(3687, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 28, 'OT', 'Og her hans, eitt og fjörutíu þúsund og fimm hundruð.'),
(3688, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 29, 'OT', 'Og staf Naftalís; og höfðingi sona Naftalís er Akíra sonur Enans.'),
(3689, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 30, 'OT', 'Og her hans, þrjú og fimmtíu þúsund og fjögur hundruð.'),
(3690, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 31, 'OT', 'Allir taldir í herbúðum Dans eru hundrað sjö og fimmtíu þúsund og sex hundruð, eftir fánum sínum; þeir skulu síðastir leggja af stað.'),
(3691, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 32, 'OT', 'Þetta eru taldir sona Ísraels eftir húsi feðra sinna; allir taldir í herbúðum eftir herjum þeirra voru sex hundruð þúsund, þrjú þúsund, fimm hundruð og fimmtíu.'),
(3692, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 33, 'OT', 'En Levítarnir voru ekki taldir meðal sona Ísraels, eins og Jahve bauð Mósesi.'),
(3693, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 2, 34, 'OT', 'Og synir Ísraels gerðu allt eins og Jahve bauð Móses; þannig settu þeir upp herbúðir eftir fánum sínum, og þannig lögðu þeir af stað, hver maður eftir sinni ætt og eftir húsi feðra sinna.'),
(3694, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 1, 'OT', 'Þetta eru ættartölur Arons og Móses á þeim degi þegar Jahve talaði við Móses á fjalli Sínaí.'),
(3695, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 2, 'OT', 'Þetta eru nöfn sona Arons: Nadab frumgetinn, Abíhú, Eleasar og Ítamar.'),
(3696, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 3, 'OT', 'Þetta eru nöfn sona Arons, hinna smurðu presta, sem hendur þeirra voru fylltar til að þjóna sem prestar.'),
(3697, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 4, 'OT', 'Nadab og Abíhú dóu fyrir andliti Jahve, þegar þeir báru framandi eld fram fyrir andlit Jahve í eyðimörkinni Sínaí; þeir áttu enga sonu. Eleasar og Ítamar þjónuðu fyrir andliti Arons föður síns.'),
(3698, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 5, 'OT', 'Og Jahve talaði við Móses og sagði:'),
(3699, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 6, 'OT', 'Færðu fram staf Leví og settu hann fyrir Aron prest, svo að þeir þjóni honum.'),
(3700, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 7, 'OT', 'Þeir skulu gegna varðstöðu sinni og varðstöðu allrar safnaðarins fyrir framan samfundatjaldið, og annast þjónustu bústaðarins.'),
(3701, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 8, 'OT', 'Þeir skulu gæta allra áhalda samfundatjaldsins og varðstöðu sona Ísraels, og annast þjónustu bústaðarins.'),
(3702, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 9, 'OT', 'Þú skalt gefa Levítana Aroni og sonum hans; þeir eru gefnir honum af sonum Ísraels.'),
(3703, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 10, 'OT', 'Aron og sonum hans skalt þú skipa, og þeir skulu gegna prestsembætti sínu; en hver ókunnugur sem nálgast skal deyja.'),
(3704, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 11, 'OT', 'Og Jahve talaði aftur við Móses og sagði:'),
(3705, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 12, 'OT', 'Sjá, ég hef tekið Levítana úr meðal sona Ísraels í stað allra frumgetinna, sem opna móðurlíf meðal sona Ísraels; og Levítarnir skulu vera mínir.'),
(3706, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 13, 'OT', 'Því að allir frumgetnir eru mínir; á þeim degi þegar ég laust alla frumgetna á jörð Egyptalands helgaði ég mér alla frumgetna í Ísrael, bæði menn og skepnur; þeir skulu vera mínir: ég er Jahve.'),
(3707, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 14, 'OT', 'Og Jahve talaði við Móses í eyðimörkinni Sínaí og sagði:'),
(3708, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 15, 'OT', 'Teldu sonu Leví eftir húsi feðra þeirra og ættum þeirra; teldu alla karla frá eins mánaðar aldri og eldri.'),
(3709, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 16, 'OT', 'Og Móses taldi þá eftir munni Jahve, eins og honum var boðið.'),
(3710, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 17, 'OT', 'Þessir eru synir Leví með nöfnum sínum: Gerson, Kahat og Merarí.'),
(3711, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 18, 'OT', 'Og þetta eru nöfn sona Gersons eftir ættum þeirra: Libní og Símeí.'),
(3712, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 19, 'OT', 'Synir Kahats eftir ættum þeirra: Amram, Ísehar, Hebron og Ússíel.'),
(3713, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 20, 'OT', 'Synir Merarís eftir ættum þeirra: Mahli og Músí. Þetta eru ættir Levíta eftir húsi feðra þeirra.'),
(3714, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 21, 'OT', 'Til Gersons heyra ættirnar Libníti og Símeíti; þetta eru ættir Gersóníta.'),
(3715, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 22, 'OT', 'Eftir tölu allra karla frá eins mánaðar aldri og eldri voru taldir þeirra sjö þúsund og fimm hundruð.'),
(3716, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 23, 'OT', 'Ættir Gersóníta skulu setja tjöld sín aftan við bústaðinn, til hafs.'),
(3717, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 24, 'OT', 'Og höfðingi húss feðra Gersóníta er Elíasaf sonur Laels.'),
(3718, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 25, 'OT', 'Varðstaða sona Gersons skal vera í samfundatjaldinu og bústaðnum, með tjaldinu og hlíf þess og tjaldi fyrir inngangi samfundatjaldsins.'),
(3719, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 26, 'OT', 'Og slöngvur forgarðsins og tjald inngangs forgarðsins, sem er við bústaðinn og umhverfis altari, með strengjum sínum til allrar þjónustu hans.'),
(3720, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 27, 'OT', 'Til Kahats heyra ættirnar Amramíta, Jisharíta, Hebroníta og Ússíelíta; þetta eru ættir Kahatíta.'),
(3721, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 28, 'OT', 'Eftir tölu allra karla frá eins mánaðar aldri og eldri voru átta þúsund og sex hundruð, sem gegndu varðstöðu helgidómsins.'),
(3722, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 29, 'OT', 'Ættir sona Kahats skulu setja tjöld sín við læri bústaðarins, til suðurs.'),
(3723, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 30, 'OT', 'Og höfðingi húss feðra ættar Kahatíta er Elísafan sonur Ússíels.'),
(3724, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 31, 'OT', 'Og þeir gæta varðstöðu sinnar: örkin, borðið, ljósastika, altari, áhöld helgidómsins sem þeir þjóna með, og tjaldið og allri þjónustu þess.'),
(3725, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 32, 'OT', 'Og höfðingi höfðingja Levíta er Eleasar sonur Arons prests, með umsjón yfir þeim sem gæta varðstöðu helgidómsins.'),
(3726, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 33, 'OT', 'Til Merarís heyra ættirnar Mahlíta og Músíta; þetta eru ættir Merarí.'),
(3727, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 34, 'OT', 'Taldir þeirra eftir tölu allra karla frá eins mánaðar aldri og eldri voru sex þúsund og tvö hundruð.'),
(3728, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 35, 'OT', 'Og höfðingi húss feðra ættar Merarí er Súríel sonur Abíhails; þeir skulu setja tjöld sín við læri bústaðarins, til norðurs.'),
(3729, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 36, 'OT', 'Umsjón varðstöðu sona Merarís: borð bústaðarins, slár hans, súlur og undirstöður, ásamt öllum áhöldum þeirra og allri þjónustu.'),
(3730, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 37, 'OT', 'Og súlur forgarðsins umhverfis, undirstöður þeirra, hælar þeirra og strengir.'),
(3731, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 38, 'OT', 'En þeir sem setja tjöld sín fyrir andliti bústaðarins í austri, fyrir andliti samfundatjaldsins, eru Móses, Aron og synir hans, sem gæta varðstöðu helgidómsins í þágu sona Ísraels; en hver ókunnugur sem nálgast skal deyja.'),
(3732, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 39, 'OT', 'Allir Levítar sem Móses og Aron töldu eftir munni Jahve, eftir ættum þeirra, allir karlar frá eins mánaðar aldri og eldri, voru tuttugu og tvö þúsund.'),
(3733, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 40, 'OT', 'Og Jahve sagði við Móses: Teldu alla frumgetna sona Ísraels frá eins mánaðar aldri og eldri, og tak tölu nafna þeirra.'),
(3734, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 41, 'OT', 'Þú skalt taka Levítana mér í stað allra frumgetinna meðal sona Ísraels, og skepnur Levíta í stað skepna þeirra; ég er Jahve.'),
(3735, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 42, 'OT', 'Og Móses taldi alla frumgetna meðal sona Ísraels, eins og Jahve hafði boðið honum.'),
(3736, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 43, 'OT', 'Og allir frumgetnir eftir tölu nafna, frá eins mánaðar aldri og eldri, voru tuttugu og tvö þúsund, tvö hundruð sjötíu og þrjú.'),
(3737, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 44, 'OT', 'Og Jahve sagði við Móses:'),
(3738, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 45, 'OT', 'Tak Levítana í stað allra frumgetinna meðal sona Ísraels, og skepnu Levíta í stað skepna þeirra; og Levítarnir skulu vera mínir; ég er Jahve.'),
(3739, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 46, 'OT', 'Lausnargjald þeirra sem umfram eru Levítana, hinna frumgetinna sona Ísraels:'),
(3740, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 47, 'OT', 'Fimm sikla skalt þú taka fyrir hverja höfuðkúpu, eftir helgisikli; sikill er tuttugu gera.'),
(3741, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 48, 'OT', 'Silfurið skalt þú gefa Aroni og sonum hans sem lausnargjald þeirra sem umfram eru.'),
(3742, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 49, 'OT', 'Og Móses tók silfur lausnargjaldsins af þeim sem umfram voru meðal Levíta.'),
(3743, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 50, 'OT', 'Af frumgetnum sona Ísraels tók hann silfurið, þúsund þrjú hundruð fimm og sextíu sikla eftir helgisikli.'),
(3744, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 3, 51, 'OT', 'Og Móses gaf silfur lausnargjaldsins Aroni og sonum hans eftir munni Jahve, eins og Jahve bauð Mósesi.'),
(3745, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 1, 'OT', 'Og Jahve sagði enn við Móses og Aron:'),
(3746, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 2, 'OT', 'Taktu höfuð sona Kahats meðal sona Leví, eftir ættum þeirra og húsi feðra þeirra.'),
(3747, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 3, 'OT', 'Frá sonum þrjátíu ára og eldri, til fimmtíu ára, allir sem fara í her til að vinna starf við samfundatjaldið.'),
(3748, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 4, 'OT', 'Þjónusta sona Kahats við samfundatjaldið snýst um helgi helgidómsins.'),
(3749, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 5, 'OT', 'Þegar herbúðirnar halda af stað, skulu Aron og synir hans koma, taka niður fortjaldið og hylja með því örkina vitnisburðarins.'),
(3750, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 6, 'OT', 'Og þeir skulu leggja yfir það hulu af selskinni, breiða yfir hana klæði úr bláma og setja strengi þess á sinn stað.'),
(3751, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 7, 'OT', 'Á borðinu fyrir andlitinu skulu þeir breiða bláma klæði og leggja á það skálarnar, lófana, skeiðarnar og bikarana til dreypifórnar. Brauðið skal vera þar stöðugt.'),
(3752, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 8, 'OT', 'Yfir þau skulu þeir breiða klæði úr skarlati, tvílitu skarlati, og hylja síðan með hlíf úr skinni sela og setja stengurnar í.'),
(3753, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 9, 'OT', 'Þá skulu þeir taka bláma klæði og hylja ljósastikuna og ljósin, lampana, tengurnar, eldpönnurnar og öll áhöld fyrir olíu sem þjóna henni.'),
(3754, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 10, 'OT', 'Þeir skulu setja hana og öll áhöld hennar í hlíf úr skinni sela og leggja hana á slagbrand.'),
(3755, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 11, 'OT', 'Á altarið úr gulli skulu þeir breiða bláma klæði og hylja það með hlíf úr skinni sela og setja stengurnar á.'),
(3756, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 12, 'OT', 'Þeir skulu taka öll áhöld þjónustunnar, þau sem þjóna í helgi, í helgidóminum, og leggja þau í bláma klæði og hylja með hlíf úr skinni sela og setja á slagbrandinn.'),
(3757, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 13, 'OT', 'Þeir skulu hreinsa altarið og breiða yfir það klæði úr purpura.'),
(3758, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 14, 'OT', 'Á það skulu þeir leggja öll áhöld þess, sem notuð eru við það: eldpönnurnar, kjötkrókana, skóflurnar og skálarnar, öll áhöld altarisins. Yfir það skulu þeir breiða hulu úr skinni sela og setja stengurnar á.'),
(3759, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 15, 'OT', 'Þegar Aron og synir hans eru búnir að hylja helgidóminn og öll áhöld helgidómsins, þegar herbúðirnar leggja af stað, þá skulu synir Kahat koma til að bera, en þeir mega ekki snerta hið helga, annars deyja þeir. Þetta er byrði sona Kahat í samfundatjaldinu.'),
(3760, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 16, 'OT', 'Umsjón Eleasars, sonar Arons prestsins, skal vera yfir olíu ljóssins, ilmreykelsinu, daglegu fórninni, olíunni til smurningar, og yfir öllum bústaðnum og öllu sem í honum er, helgidóminum og áhöldum hans.'),
(3761, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 17, 'OT', 'Jahve talaði við Móses og Aron og sagði:'),
(3762, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 18, 'OT', 'Látið ekki ættkvísl Kahatíta upprætast úr hópi Levíta.'),
(3763, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 19, 'OT', 'En þetta skuluð þið gera við þá, svo að þeir lifi en deyi ekki, þegar þeir nálgast hið helgasta og helgi þess: Aron og synir hans skulu fara inn og setja hvern mann í sína þjónustu og sína byrði.'),
(3764, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 20, 'OT', 'Þeir mega þó ekki ganga inn til að líta helgina, svo að þeir deyi ekki.'),
(3765, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 21, 'OT', 'Jahve talaði við Móses og sagði:'),
(3766, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 22, 'OT', 'Teljið einnig höfuð sona Gersons eftir feðrahúsum þeirra og ættum.'),
(3767, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 23, 'OT', 'Frá þrjátíu ára aldri og upp til fimmtíu ára skalt þú telja hvern son sem kemur í herinn til að gegna þjónustu í samfundatjaldinu.'),
(3768, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 24, 'OT', 'Þetta er þjónusta ættar Gersóníta: að þjóna og bera byrði.'),
(3769, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 25, 'OT', 'Þeir skulu bera tjöldin í bústaðnum, samfundatjaldið, yfirbreiðslu þess, hlífina úr skinni sela sem er yfir henni og fortjaldið við innganginn í samfundatjaldinu.'),
(3770, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 26, 'OT', 'Þeir skulu bera slöngvurnar við forgarðinn, fortjaldið við hlið forgarðsins, sem er í kringum bústaðinn og altarið, og strengina þeirra, öll áhöld þjónustunnar; og allt það sem gert verður fyrir þá skulu þeir þjóna.'),
(3771, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 27, 'OT', 'Eftir munni Arons og sona hans skal öll þjónusta Gersóníta verða, allt eftir byrði þeirra og þjónustu; og þú skalt setja þá í varðstöðu yfir öllum byrðum þeirra.'),
(3772, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 28, 'OT', 'Þetta er þjónusta ætta Gersóníta í samfundatjaldinu: þeir skulu hafa varðstöðu undir hendi Ítamars, sonar Arons prestsins.'),
(3773, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 29, 'OT', 'Synir Merarí, eftir ættum þeirra og feðrahúsum, skalt þú telja.'),
(3774, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 30, 'OT', 'Frá þrjátíu ára aldri og upp til fimmtíu ára skalt þú telja hvern son sem kemur í herinn til að gegna þjónustu í samfundatjaldinu.'),
(3775, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 31, 'OT', 'Þetta er varðstaða byrða þeirra í allri þjónustu þeirra í samfundatjaldinu: borðin í bústaðnum, slárnar, súlurnar og undirstöðurnar.'),
(3776, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 32, 'OT', 'Súlurnar í forgarðinum allt um kring og undirstöður þeirra, hælarnir og strengirnir, ásamt öllum áhöldum þeirra og allri þjónustu við þau; og með nafni skulu þeir telja áhöldin sem þeir eiga að gæta og bera.'),
(3777, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 33, 'OT', 'Þetta er þjónusta ætta Merarí í allri þjónustu þeirra í samfundatjaldinu, undir hendi Ítamars, sonar Arons prestsins.'),
(3778, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 34, 'OT', 'Móses og Aron og höfðingjar safnaðarins töldu sonu Kahatíta eftir ættum þeirra og feðrahúsum.'),
(3779, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 35, 'OT', 'Frá þrjátíu ára aldri og upp til fimmtíu ára skalt þú telja hvern son sem kemur í herinn til að vinna þjónustu í samfundatjaldinu.'),
(3780, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 36, 'OT', 'Og tala þeirra eftir ættum var tvö þúsund og sjö hundruð og fimmtíu.'),
(3781, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 37, 'OT', 'Þetta eru tölur ættar Kahatíta, allra sem þjóna í samfundatjaldinu, sem Móses og Aron töldu eftir munni Jahve, fyrir hendi Mósesar.'),
(3782, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 38, 'OT', 'Og tölur sona Gersons eftir ættum þeirra og feðrahúsum.'),
(3783, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 39, 'OT', 'Frá þrjátíu ára aldri og upp til fimmtíu ára skalt þú telja hvern son sem kemur í herinn til að vinna þjónustu í samfundatjaldinu.'),
(3784, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 40, 'OT', 'Og tölur þeirra eftir ættum þeirra og feðrahúsum voru tvö þúsund sex hundruð og þrjátíu.'),
(3785, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 41, 'OT', 'Þetta eru tölur ætta sona Gersons, allra sem þjóna í samfundatjaldinu, sem Móses og Aron töldu eftir munni Jahve.'),
(3786, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 42, 'OT', 'Og tölur ætta sona Merarí eftir ættum þeirra og feðrahúsum.'),
(3787, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 43, 'OT', 'Frá þrjátíu ára aldri og upp til fimmtíu ára skalt þú telja hvern son sem kemur í herinn til að vinna þjónustu í samfundatjaldinu.'),
(3788, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 44, 'OT', 'Og tölur þeirra eftir ættum þeirra voru þrjú þúsund og tvö hundruð.'),
(3789, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 45, 'OT', 'Þetta eru tölur ætta sona Merarí, sem Móses og Aron töldu eftir munni Jahve, fyrir hendi Mósesar.'),
(3790, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 46, 'OT', 'Allar tölur sem Móses og Aron og höfðingjar Ísraels töldu af Levítum, eftir ættum þeirra og feðrahúsum.'),
(3791, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 47, 'OT', 'Frá þrjátíu ára aldri og upp til fimmtíu ára, hvern son sem kemur til að vinna þjónustu og bera byrði í samfundatjaldinu.'),
(3792, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 48, 'OT', 'Og tölur þeirra voru átta þúsund fimm hundruð og áttatíu.'),
(3793, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 4, 49, 'OT', 'Eftir munni Jahve taldi hann þá fyrir hendi Mósesar, hvern mann eftir þjónustu hans og byrði. Þannig voru tölur þeirra sem Jahve bauð Mósesi.'),
(3794, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 1, 'OT', 'Jahve talaði við Móses og sagði:'),
(3795, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 2, 'OT', 'Bjóð Ísraels sonum að senda úr herbúðum hvern holdsveikan, hvern þann sem hefur rennsli og hvern þann sem er óhreinn vegna dauðrar sálar.'),
(3796, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 3, 'OT', 'Hvort sem er karlkyn eða kvenkyn skuluð þér senda þá út fyrir herbúðir; út fyrir herbúðirnar skuluð þér senda þá, svo að þeir saurgi ekki herbúðir sínar, þar sem ég bý meðal þeirra.'),
(3797, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 4, 'OT', 'Synir Ísraels gerðu svo og ráku þá út fyrir herbúðirnar, eins og Jahve hafði talað við Móses; þannig gerðu synir Ísraels.'),
(3798, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 5, 'OT', 'Jahve talaði við Móses og sagði:'),
(3799, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 6, 'OT', 'Tala við sonu Ísraels: Þegar maður eða kona fremur einhverja af öllum syndum manna og sýnir ótrúmennsku við Jahve, þá er sú sál sek.'),
(3800, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 7, 'OT', 'Þá skulu þeir játa synd sína, sem þeir hafa drýgt, og endurgreiða sektarfórn sína með höfuðstólnum og bæta fimmtungi ofan á það; og gefa það þeim sem hann hefur brotið á.'),
(3801, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 8, 'OT', 'Ef enginn er sá nánasti ættingi mannsins sem geti endurgoldið sektarfórnina, skal sú sektarfórn sem endurgoldin er Jahve falla prestinum í skaut, auk hrútsins til friðþægingar, sem með skal friðþægt fyrir hann.'),
(3802, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 9, 'OT', 'Allt framlag af öllu sem helgi er hjá Ísraels sonum, sem þeir færa presti, skal vera hans.'),
(3803, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 10, 'OT', 'Hver maður skal eiga sína helgi, og hver sem gefur presti, hans skal það vera.'),
(3804, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 11, 'OT', 'Jahve talaði við Móses og sagði:'),
(3805, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 12, 'OT', 'Tala við Ísraels sonu og seg við þá: Þegar maður lætur konu sína villast af réttri leið og fremur ótrúmennsku gegn honum,'),
(3806, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 13, 'OT', 'ef einhver hefur samræði við hana og sæði fer, og það er falið augum manns hennar, og hún er leynd og óhrein, og enginn vottur er gegn henni og hún hefur ekki verið tekin:'),
(3807, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 14, 'OT', 'ef andi kemur yfir mann í vandlæti og hann vandlætir konu sinni og hún er óhrein; eða ef andi kemur yfir hann í vandlæti og hann vandlætir konu sinni en hún er ekki óhrein:'),
(3808, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 15, 'OT', 'Þá skal maðurinn færa konu sína til prestsins, og fórnargjöf hennar með henni: tíunda hluta úr efu af byggmjöli. Hann skal ekki hella olíu á það né leggja á reykelsi, því að það er fórn vandlæti, fórn minningar sem minnir á misgjörð.'),
(3809, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 16, 'OT', 'Og presturinn skal leiða hana fram fyrir andlit Jahve.'),
(3810, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 17, 'OT', 'Presturinn skal taka heilagt vatn í áhaldi úr leirkeri, og af moldinni sem er á botni bústaðarins skal presturinn taka og láta í vatnið.'),
(3811, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 18, 'OT', 'Presturinn skal leiða konuna fram fyrir andlit Jahve, og hann skal leysa höfuð konunnar og leggja í lófa hennar fórn minningarinnar, sem er fórn vandlæti. En í hendi prestsins skulu vötnin, hin beisku og bölvuðu, vera.'),
(3812, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 19, 'OT', 'Presturinn skal sverja konuna og segja við konuna: Ef enginn maður hefur legið hjá þér og ef þú hefur ekki villst til óhreinleika í stað manns þíns, þá ver þú hrein frá þessum beisku bölvuðu vötnum.'),
(3813, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 20, 'OT', 'En þú, af því að þú hefur villst í stað manns þíns og ert óhrein, og maður hefur lagt með þér legu sína utan manns þíns:'),
(3814, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 21, 'OT', 'Presturinn skal sverja konuna með eiðnum bölvunarinnar og segja við konuna: Jahve geri þig að bölvun og eið í miðju lýðs þíns, þegar Jahve lætur læri þitt visna og kvið þinn bólgna.'),
(3815, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 22, 'OT', 'Og þessi bölvuðu vötn skulu fara í iður þína, til að kviðurinn bólgni og lærin falli; og konan skal segja: Amen, amen.'),
(3816, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 23, 'OT', 'Presturinn skal rita þessar bölvanir í bók og þvo þær af í beiska vatnið.'),
(3817, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 24, 'OT', 'Og hann skal gefa konunni að drekka beiska vatnið, og bölvuðu vötnin skulu fara í hana til beiskju.'),
(3818, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 25, 'OT', 'Og presturinn skal taka fórnina, sem er af vandlæti, úr hendi konunnar og veifa henni fyrir andlit Jahve og færa hana að altarinu.'),
(3819, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 26, 'OT', 'Og presturinn skal taka af fórninni handfylli, minningarhlutann, og brenna á altarinu; eftir það skal hann láta konuna drekka vatnið.'),
(3820, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 27, 'OT', 'Þegar hún hefur drukkið vatnið: ef hún er óhrein og hefur sýnt ótrúmennsku gegn manni sínum, þá skulu bölvuðu vötnin fara í hana til beiskju, og kviðurinn bólgna og lærið falla, og konan verða bölvun meðal lýðs síns.'),
(3821, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 28, 'OT', 'En ef konan er ekki óhrein og er hrein, þá skal hún ganga laus og getur af sér sæði.'),
(3822, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 29, 'OT', 'Þetta er lögmálið um vandlæti: þegar kona villist í stað manns síns og verður óhrein.'),
(3823, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 30, 'OT', 'Eða ef maður, sem andi vandlætis kemur yfir í vandlæti við konu sína, þá skal hann færa konuna fram fyrir andlit Jahve, og presturinn skal gera við hana allt þetta lögmál.'),
(3824, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 5, 31, 'OT', 'Maðurinn skal vera hreinn af misgjörð, en konan skal bera sína misgjörð.'),
(3825, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 1, 'OT', 'Jahve talaði við Móses og sagði:'),
(3826, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 2, 'OT', 'Tala við Ísraels sonu og seg við þá: Þegar maður eða kona strengir sérstakt heit, heit nasírea, til að helga sig Jahve,'),
(3827, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 3, 'OT', 'skal hann halda sig frá víni og áfengi; edik úr víni og edik úr áfengi skal hann ekki drekka, og engan vökva úr vínberjum skal hann drekka, og hvorki fersk vínber né þurrkuð skal hann eta.'),
(3828, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 4, 'OT', 'Alla daga nasírsheitis síns skal hann ekki eta neitt sem gert er af vínviði, frá vínberjakjarna til hýðis.'),
(3829, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 5, 'OT', 'Allir dagar heits síns sem nasíri skal rakhnífur ekki fara yfir höfuð hans, þar til dagarnir eru fullnaðir sem hann helgar Jahve; hann skal vera heilagur og láta lokka hárs höfuðs síns vaxa.'),
(3830, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 6, 'OT', 'Alla daga þess að hann er helgaður Jahve skal hann ekki koma nálægt dauðri sál.'),
(3831, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 7, 'OT', 'Hann skal ekki gera sig óhreinan vegna föður síns eða móður, bróður síns eða systur, við dauða þeirra; því að nasírsheit Guðs er á höfði hans.'),
(3832, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 8, 'OT', 'Alla daga nasírsheitis síns er hann helgaður Jahve.'),
(3833, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 9, 'OT', 'Ef einhver deyr hjá honum í einu augnabliki og saurgar höfuð nasírsheitis hans, þá skal hann raka höfuð sitt á hreinsunardegi sínum; á sjöunda degi skal hann raka það.'),
(3834, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 10, 'OT', 'Á áttunda degi skal hann koma til prestsins með tvær turtildúfur eða tvo sonu dúfna, að inngangi samfundatjaldsins.'),
(3835, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 11, 'OT', 'Presturinn skal færa annan til syndar og hinn til brennifórnar, og friðþægja fyrir hann vegna sálarinnar sem syndgaði, og helga höfuð hans sama dag.'),
(3836, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 12, 'OT', 'Og hann skal vígja Jahve daga nasírsheitisins og færa ársgamalt lamb til sektarfórnar, en fyrri dagarnir falla, því að nasírsheit hans var óhreint.'),
(3837, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 13, 'OT', 'Þetta er lögmál nasírea: þegar dagar nasírsheits hans eru liðnir, skal hann koma með það að inngangi samfundatjaldsins.'),
(3838, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 14, 'OT', 'Og hann skal færa fórnargjöf sína Jahve: eitt ársgamalt lamb, gallalaust, til brennifórnar, og eina ársgamla lambsgimbur, gallalausa, til syndar, og einn hrút gallalausan til þakkarfórnar.'),
(3839, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 15, 'OT', 'Og körfu ósýrðra brauða: fínt mjöl í kökum hnoðað með olíu, og ósýrðar kökur smurðar með olíu. Fórn þeirra og dreypifórnir eru þar með.'),
(3840, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 16, 'OT', 'Og presturinn skal færa það fram fyrir andlit Jahve og gera þá fórn til syndar og brennifórn hans.'),
(3841, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 17, 'OT', 'Hrútinn skal hann færa sem sláturfórn þakkarfórnar Jahve, ásamt körfu ósýrðra brauða; og presturinn skal færa fórn hans og dreypifórn hans.'),
(3842, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 18, 'OT', 'Og nasírinn skal við inngang samfundatjaldsins raka höfuð nasírsheits síns, og hann skal taka hárið og láta á eldinn, sem er undir sláturfórninni til þakkarfórnar.'),
(3843, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 19, 'OT', 'Og presturinn skal taka arminn af hrútinum, soðinn, og eina köku úr körfu ósýrðs brauðs og eina ósýrða köku, og leggja á lófa nasírsins eftir að hann hefur rakað nasírsheit sitt.'),
(3844, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 20, 'OT', 'Og presturinn skal veifa þeim sem veifufórn fyrir andlit Jahve. Það er helgi, presti heyrir til, ásamt bringu veifufórnarinnar og lærinu, sem er framlag; og eftir það má nasírinn drekka vín.'),
(3845, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 21, 'OT', 'Þetta er lögmál nasírsins: fórnargjöf hans, Jahve skal færa vegna nasírsheits síns, auk þess sem hönd hans nær; eftir munni heitis síns sem hann strengir, þannig skal hann gera eftir lögmáli nasírsheits síns.'),
(3846, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 22, 'OT', 'Jahve talaði við Móses og sagði:'),
(3847, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 23, 'OT', 'Tala við Aron og sonu hans og seg: Svo skuluð þér blessa Ísraels sonu, og segið við þá:'),
(3848, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 24, 'OT', 'Jahve blessi þig og varðveiti þig.'),
(3849, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 25, 'OT', 'Jahve láti andlit sitt lýsa yfir þig og sýni þér náð.'),
(3850, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 26, 'OT', 'Jahve lyfti andlit sitt yfir þig og gefi þér frið.'),
(3851, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 6, 27, 'OT', 'Þeir skulu setja nafn mitt yfir Ísraels sonu, og ég mun blessa þá.'),
(3852, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 1, 'OT', 'Þann dag sem Móses lauk við að reisa bústað smurði hann og helgaði hann, ásamt öllum áhöldum hans, altari og alla áhöld þess; hann smurði þau og helgaði.'),
(3853, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 2, 'OT', 'Höfðingjar Ísraels, höfuð hús feðra, þeir sem voru höfðingjar stafa og stóðu yfir talningunni, færðu fram.'),
(3854, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 3, 'OT', 'Þeir færðu fram fórnargjöf sína fyrir andlit Jahve: sex yfirbyggða vagna og tólf naut, einn vagn fyrir hverja tvo höfðingja og eitt naut fyrir hvern. Þeir færðu þau fram fyrir bústað.'),
(3855, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 4, 'OT', 'Jahve talaði við Móses og sagði:'),
(3856, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 5, 'OT', 'Tak þetta af þeim og lát þá vinna þjónustu í samfundatjaldinu, og gef þau Levítum, hverjum manni eftir munni þjónustu hans.'),
(3857, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 6, 'OT', 'Móses tók vagna og naut og gaf þau Levítum.'),
(3858, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 7, 'OT', 'Tvo vagna og fjögur naut gaf hann sonum Gersons eftir munni þjónustu þeirra.'),
(3859, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 8, 'OT', 'Fjóra vagna og átta naut gaf hann sonum Merarí eftir munni þjónustu þeirra, undir hendi Ítamars, sonar Arons prests.'),
(3860, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 9, 'OT', 'En sonum Kahats gaf hann ekki, því að þjónusta við helgi hvílir á þeim; þeir skulu bera á öxlum.'),
(3861, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 10, 'OT', 'Höfðingjar færðu fram vígslu altaris á þeim degi sem það var smurt; höfðingjar færðu fram fórnargjöf sína fyrir andlit altaris.'),
(3862, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 11, 'OT', 'Jahve talaði við Móses: Einn höfðingi á hverjum degi, einn höfðingi á hverjum degi skal færa fram fórnargjöf sína til vígslu altaris.'),
(3863, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 12, 'OT', 'Á fyrsta degi var það Nakson, sonur Amínadabs, af stafi Júda, sem færði fram fórnargjöf sína.'),
(3864, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 13, 'OT', 'Fórnargjöf hans var ein skál úr silfri, hundrað og þrjátíu sikla vigt, og önnur skál úr silfri, sjötíu sikla eftir helgi sikli; báðar fullar af fínu mjöli blönduðu með olíu sem fórn.'),
(3865, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 14, 'OT', 'Ein lófa úr gulli, tíu sikla, full af reykelsi.'),
(3866, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 15, 'OT', 'Einn ungnaut, sonur nauta, einn hrútur og eitt lamb, sonur ára, til brennifórnar.'),
(3867, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 16, 'OT', 'Einn geithafur af geitum til syndar.'),
(3868, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 17, 'OT', 'Og til sláturfórnar og þakkarfórnar: tvö naut, fimm hrútar, fimm hafrar, fimm lömb eins árs. Þetta var fórnargjöf Nakson, sonar Amínadabs.'),
(3869, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 18, 'OT', 'Á öðrum degi bar fram Netanel, sonur Súars, höfðingi Íssakars.'),
(3870, 4, 'GOI_Is', 'GOI_Is', 'is', 'NUM', 7, 19, 'OT', 'Fórnargjöf hans var ein skál úr silfri, hundrað og þrjátíu sikla vigt, og önnur skál úr silfri, sjötíu sikla eftir helgi sikli; báðar fullar af fínu mjöli blönduðu með olíu sem fórn.'),
